        private static bool TryGetCalendarPersonNotionUrl(
            string person,
            out string url)
        {
            var normalized =
                NormalizeCalendarPerson(
                    person ?? string.Empty);

            if (!string.IsNullOrWhiteSpace(normalized) &&
                CalendarPersonNotionUrls.TryGetValue(
                    normalized,
                    out var mapped) &&
                !string.IsNullOrWhiteSpace(mapped))
            {
                url = mapped;
                return true;
            }

            url = string.Empty;
            return false;
        }

