        // Vista "Proyecto relacionado". Reutiliza el panel lateral ya existente
        // para no crear otra ventana ni duplicar UI.
        private sealed record CalendarProjectGroupCriteria(
            string ProjectType,
            string ProjectLabel,
            string Domain,
            string Person,
            int Year,
            int Month,
            string MonthTag,
            bool IncludeAllProjectTypes = false)
        {
            // Identidad de la vista relacionada. El modo normal conserva
            // tipo + dominio + mes. "Todas" usa * + dominio + mes para
            // incluir SEO/WEB/ADS/etc. sin mezclar otros dominios.
            public string Key =>
                $"{(IncludeAllProjectTypes ? "*" : ProjectType)}|{Domain}|{MonthTag}";
        }

