        private void StartCalendarStartupPipeline()
        {
            if (_calendarStartupPipelineStarted)
                return;

            _calendarStartupPipelineStarted = true;

            // Solo una pestaña ejecuta el mantenimiento global. Las demas
            // reutilizan las caches compartidas y no lanzan procesos pesados.
            if (Interlocked.CompareExchange(
                    ref _sharedDailyCalendarAutomationStarted,
                    1,
                    0) != 0)
            {
                return;
            }

            _calendarStartupPipelineTask =
                RunCalendarStartupPipelineAsync();
        }

        private async Task RunCalendarStartupPipelineAsync()
        {
            try
            {
                // 1) Primero mantenimiento diario. Se mantiene en background y
                // se oculta su overlay global para que no bloquee Buscador,
                // Resultados ni cambios de modulo. El estado inferior continua
                // informando que dia/proceso esta revisando.
                var automationTask =
                    RunDailyCalendarAutomationIfNeededAsync();

                await Task.Delay(80);

                if (StatusText != null &&
                    (StatusText.Text?.IndexOf(
                        "rezagad",
                        StringComparison.OrdinalIgnoreCase) ?? -1) >= 0)
                {
                    ForceHideLoadingState();
                }

                await automationTask;
            }
            catch (Exception ex)
            {
                Debug.WriteLine(
                    $"[CALENDAR_STARTUP_AUTOMATION] {ex.Message}");
            }

            // 2) Despues precarga Hoy + checklist + asociaciones de proyecto.
            // No corre a la vez que el mantenimiento diario, reduciendo picos
            // de solicitudes y evitando que Notion entre en cooldown por varios
            // procesos de ANFETA compitiendo al arrancar.
            StartCalendarStartupCacheWarmup();

            if (_calendarStartupCacheWarmupTask != null)
            {
                try
                {
                    await _calendarStartupCacheWarmupTask;
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_STARTUP_WARMUP] {ex.Message}");
                }
            }
        }

        private void StartCalendarStartupCacheWarmup()
        {
            if (_calendarStartupCacheWarmupStarted)
                return;

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
                return;

            _calendarStartupCacheWarmupStarted = true;
            _calendarStartupCacheWarmupTask =
                WarmCalendarStartupCacheAsync(token);
        }

        private void SetCalendarStartupStatus(
            string value)
        {
            if (_calendarViewActive ||
                StatusText == null)
            {
                return;
            }

            // Si otro flujo cambio el estado desde nuestra ultima escritura
            // (busqueda, drag, etc.), la precarga deja de pisar sus mensajes.
            if (!string.IsNullOrWhiteSpace(
                    _calendarStartupLastStatus) &&
                !string.Equals(
                    StatusText.Text,
                    _calendarStartupLastStatus,
                    StringComparison.Ordinal))
            {
                return;
            }

            _calendarStartupLastStatus =
                value ?? string.Empty;

            StatusText.Text =
                _calendarStartupLastStatus;
        }

        private async Task WarmCalendarStartupCacheAsync(
            string token)
        {
            try
            {
                SetCalendarStartupStatus(
                    "Estado: Preparando calendario y cache de checklist en segundo plano…");

                var progress =
                    new Progress<NotionCalendarProgress>(report =>
                    {
                        var next =
                            report.Total > 0
                                ? $"Estado: {report.Stage} {report.Current}/{report.Total} · {report.Detail}"
                                : $"Estado: {report.Stage} · {report.Detail}";

                        SetCalendarStartupStatus(next);
                    });

                var result =
                    await _notionCalendarService
                        .StartStartupWarmupAsync(
                            token,
                            GetCalendarChangesAnchorUtc(),
                            CancellationToken.None,
                            progress);

                // Con el dia ya preparado, resuelve tambien los grupos de
                // proyecto visibles HOY. No descarga bodies extra aqui: solo
                // deja listas las asociaciones para que el primer clic/hover
                // no tenga que empezar la busqueda desde cero.
                var todayActivities =
                    await _notionCalendarService
                        .TryGetCachedDayAsync(
                            DateTime.Today,
                            CancellationToken.None);

                if (todayActivities != null &&
                    todayActivities.Count > 0)
                {
                    await WarmCalendarProjectCandidatesAtStartupAsync(
                        todayActivities,
                        token);
                }

                SetCalendarStartupStatus(
                    $"Estado: Precarga del calendario lista ✅ · " +
                    $"{result.TodayCount} actividad(es) preparadas");
            }
            catch (Exception ex)
            {
                Debug.WriteLine(
                    $"[CALENDAR_STARTUP_CACHE] {ex.Message}");

                SetCalendarStartupStatus(
                    "Estado: ANFETA lista · la precarga del calendario continuará al abrirlo.");
            }
        }

        private async Task WarmCalendarProjectCandidatesAtStartupAsync(
            IReadOnlyList<NotionCalendarActivity> activities,
            string token)
        {
            var projects =
                new List<(
                    NotionCalendarActivity Activity,
                    CalendarProjectGroupCriteria Criteria)>();

            var seen =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);

            foreach (var activity in
                     activities.Where(activity =>
                         activity != null &&
                         !activity.IsReviewMirror))
            {
                if (!TryBuildCalendarProjectGroupCriteria(
                        activity,
                        out var criteria) ||
                    !seen.Add(criteria.Key))
                {
                    continue;
                }

                projects.Add((activity, criteria));
            }

            for (var index = 0;
                 index < projects.Count;
                 index++)
            {
                var item = projects[index];

                try
                {
                    SetCalendarStartupStatus(
                        $"Estado: Preparando proyectos {index + 1}/{projects.Count} · " +
                        $"{item.Criteria.Domain}");

                    await GetCalendarProjectRelatedActivitiesAsync(
                        item.Activity,
                        item.Criteria,
                        token,
                        CancellationToken.None,
                        forceRefresh: false);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_STARTUP_PROJECT] " +
                        $"{item.Criteria.Key}: {ex.Message}");
                }
            }
        }

        private async Task RestoreLastSearchSubViewAsync()
        {
            var lastView =
                (ApplicationData.Current.LocalSettings.Values[
                    LS_SearchLastSubView] as string ??
                 string.Empty).Trim();

            if (string.Equals(
                    lastView,
                    "calendar",
                    StringComparison.OrdinalIgnoreCase))
            {
                await ShowCalendarAsync(DateTime.Today);
                return;
            }

            if (string.Equals(
                    lastView,
                    "reminders",
                    StringComparison.OrdinalIgnoreCase))
            {
                await ShowRemindersCalendarAsync(DateTime.Today);
            }
        }

        private static void SaveLastSearchSubView(
            string value)
        {
            ApplicationData.Current.LocalSettings.Values[
                LS_SearchLastSubView] =
                (value ?? string.Empty).Trim();
        }

        private async void ToggleCalendarView_Click(
            object sender,
            RoutedEventArgs e)
        {
            if (ToggleCalendarView.IsChecked == true)
            {
                await ShowCalendarAsync(DateTime.Today);
            }
            else
            {
                CloseCalendarView();
            }
        }

        private void ClearSearchForModuleSwitch()
        {
            _calendarSearchQuery = string.Empty;

            if (SearchBox == null)
                return;

            SearchBox.Text = string.Empty;
            SearchBox.IsSuggestionListOpen = false;
        }

        private async Task ShowCalendarAsync(DateTime date)
        {
            // Al cambiar de Buscador/Mensajes/Recordatorios a Calendario no se
            // arrastra el texto anterior ni se dejan vistas superpuestas.
            ClearSearchForModuleSwitch();

            if (_remindersCalendarViewActive)
                CloseRemindersCalendarView();

            if (_messagesViewActive)
                CloseMessagesView();

            LoadCalendarCobrosPreference();
            LoadCalendarPreferences();
            LoadCalendarExtraHoursPreference();
            EnsureCalendarWorkTimerLoaded();
            EnsureCalendarWorkSessionHistoryLoaded();
            EnsureCalendarWorkTimerUiTimer();

            await EnsureCalendarReviewFlowLocalCacheLoadedAsync();

            _calendarViewActive = true;
            _calendarSelectedDate = date.Date;
            _calendarCardChecklistBaselines.Clear();
            SaveLastSearchSubView("calendar");
            NotifyTabModeChanged("calendar");

            // La vista se muestra de inmediato. Si existe cache, el usuario ve
            // el calendario al instante mientras las validaciones pesadas corren
            // en segundo plano. Nunca dejamos el modulo en blanco esperando
            // rezagadas/checklist.
            CalendarHost.Visibility = Visibility.Visible;
            ToggleCalendarView.IsChecked = true;
            CalendarDateTitle.Text = FormatCalendarDate(_calendarSelectedDate);

            if (SearchBox != null)
            {
                _calendarPreviousSearchPlaceholder ??=
                    SearchBox.PlaceholderText;

                SearchBox.PlaceholderText =
                    "Filtrar actividades del calendario...";

                _calendarSearchQuery = string.Empty;
            }

            EnsureCalendarWheelHandler();
            EnsureCalendarSizeHandler();
            ApplyCalendarTheme(_calendarThemeColor);

            if (CalendarPhaseFilterControl != null)
                CalendarPhaseFilterControl.Visibility = Visibility.Visible;

            StartCalendarChangesTimer();

            // Primero muestra la version guardada del dia. LoadCalendarDayAsync
            // ya valida cambios despues sin bloquear la vista cuando hay cache.
            await LoadCalendarDayAsync(
                preferCache: true);

            // La automatizacion diaria ya se inicia desde el ciclo compartido
            // de SearchView y tambien se comprueba por el timer. No se relanza
            // aqui: abrir/cambiar de modulo no debe iniciar otro proceso pesado
            // ni volver a mostrar el overlay de rezagadas.

            DispatcherQueue.TryEnqueue(
                () =>
                    ApplyCalendarResponsiveSizing(
                        CalendarHost.ActualWidth));
        }

        private void StartCalendarChangesTimer()
        {
            if (_calendarChangesTimer == null)
            {
                _calendarChangesTimer = new DispatcherTimer
                {
                    // Menos consultas automáticas y más margen para Notion.
                    // El botón Actualizar sigue disponible en todo momento.
                    Interval = TimeSpan.FromSeconds(180)
                };

                _calendarChangesTimer.Tick += async (_, __) =>
                {
                    await RefreshCalendarChangesSilentlyAsync();
                    RefreshCalendarExternalOverlaysIfNeeded();

                    // Comprobación ligera: si ya se ejecutó hoy, sale de inmediato.
                    // Si ANFETA quedó abierta durante el cambio de día, permite que
                    // las rezagadas se procesen sin reiniciar la aplicación.
                    _ = RunDailyCalendarAutomationIfNeededAsync();
                };
            }

            _calendarChangesTimer.Stop();
            _calendarChangesTimer.Start();
        }

        private void StopCalendarChangesTimer()
        {
            _calendarChangesTimer?.Stop();
        }

        private long BeginCalendarProcess(
            string stage,
            string detail)
        {
            var version = Interlocked.Increment(
                ref _calendarProcessUiVersion);

            _calendarProcessStartedAt = DateTimeOffset.Now;
            _calendarProcessBaseDetail = detail ?? string.Empty;

            if (CalendarProcessPanel == null)
                return version;

            CalendarProcessPanel.Visibility = Visibility.Visible;
            CalendarProcessRing.IsActive = true;
            CalendarProcessStageText.Text = stage;
            CalendarProcessDetailText.Text = _calendarProcessBaseDetail;
            CalendarProcessElapsedText.Text = "00:00";
            CalendarProcessBar.IsIndeterminate = true;
            CalendarProcessBar.Value = 0;

            if (_calendarProcessElapsedTimer == null)
            {
                _calendarProcessElapsedTimer = new DispatcherTimer
                {
                    Interval = TimeSpan.FromMilliseconds(500)
                };

                _calendarProcessElapsedTimer.Tick += (_, __) =>
                {
                    if (CalendarProcessPanel?.Visibility !=
                        Visibility.Visible)
                    {
                        return;
                    }

                    var elapsed =
                        DateTimeOffset.Now - _calendarProcessStartedAt;

                    CalendarProcessElapsedText.Text =
                        elapsed.TotalHours >= 1
                            ? elapsed.ToString(@"hh\:mm\:ss")
                            : elapsed.ToString(@"mm\:ss");

                    if (NotionRequestCoordinator.IsCoolingDown)
                    {
                        var seconds = Math.Max(1,
                            (int)Math.Ceiling(
                                NotionRequestCoordinator
                                    .CooldownRemaining
                                    .TotalSeconds));

                        CalendarProcessDetailText.Text =
                            $"Notion está regulando las solicitudes · " +
                            $"reintento en {seconds}s · " +
                            _calendarProcessBaseDetail;
                    }
                    else
                    {
                        CalendarProcessDetailText.Text =
                            _calendarProcessBaseDetail;
                    }
                };
            }

            _calendarProcessElapsedTimer.Stop();
            _calendarProcessElapsedTimer.Start();

            return version;
        }

        private void UpdateCalendarProcess(
            long version,
            NotionCalendarProgress report)
        {
            if (version != _calendarProcessUiVersion ||
                CalendarProcessPanel == null)
            {
                return;
            }

            CalendarProcessPanel.Visibility = Visibility.Visible;
            CalendarProcessRing.IsActive = true;
            CalendarProcessStageText.Text = report.Stage;
            _calendarProcessBaseDetail = report.Detail ?? string.Empty;
            CalendarProcessDetailText.Text = _calendarProcessBaseDetail;

            var hasTotal = report.Total > 0;
            CalendarProcessBar.IsIndeterminate = !hasTotal;

            if (hasTotal)
                CalendarProcessBar.Value = report.Percentage;

            StatusText.Text = hasTotal
                ? $"Estado: {report.Stage} {report.Percentage}%"
                : $"Estado: {report.Stage}...";
        }

        private void UpdateCalendarReviewProgress(
            long version,
            int current,
            int total)
        {
            if (version <= 0 ||
                version != _calendarProcessUiVersion ||
                CalendarProcessPanel == null)
            {
                return;
            }

            CalendarProcessStageText.Text =
                "Obteniendo datos de revisión";

            _calendarProcessBaseDetail =
                $"Actividad de revisión {current} de {total}";

            CalendarProcessDetailText.Text =
                _calendarProcessBaseDetail;

            CalendarProcessBar.IsIndeterminate = total <= 0;

            if (total > 0)
            {
                CalendarProcessBar.Value =
                    Math.Clamp(
                        current * 100d / total,
                        0,
                        100);
            }
        }

        private void CompleteCalendarProcess(
            long version,
            string stage,
            string detail,
            bool success = true)
        {
            if (version != _calendarProcessUiVersion ||
                CalendarProcessPanel == null)
            {
                return;
            }

            _calendarProcessElapsedTimer?.Stop();
            CalendarProcessRing.IsActive = false;
            CalendarProcessStageText.Text = stage;
            _calendarProcessBaseDetail = detail ?? string.Empty;
            CalendarProcessDetailText.Text = _calendarProcessBaseDetail;
            CalendarProcessBar.IsIndeterminate = false;
            CalendarProcessBar.Value = success ? 100 : 0;

            DispatcherQueue.TryEnqueue(
                async () =>
                {
                    await Task.Delay(
                        success
                            ? TimeSpan.FromSeconds(2.5)
                            : TimeSpan.FromSeconds(5));

                    if (version == _calendarProcessUiVersion &&
                        CalendarProcessPanel != null)
                    {
                        CalendarProcessPanel.Visibility =
                            Visibility.Collapsed;
                    }
                });
        }

        private DateTimeOffset GetCalendarChangesAnchorUtc()
        {
            var raw =
                ApplicationData.Current.LocalSettings.Values[
                    LS_CalendarLastSyncUtc] as string;

            if (DateTimeOffset.TryParse(
                    raw,
                    out var saved))
            {
                return saved
                    .ToUniversalTime()
                    .Subtract(TimeSpan.FromSeconds(20));
            }

            return _calendarLastChangesCheckUtc
                .Subtract(TimeSpan.FromSeconds(20));
        }

        private void SaveCalendarChangesCheckpoint()
        {
            _calendarLastChangesCheckUtc =
                DateTimeOffset.UtcNow;

            ApplicationData.Current.LocalSettings.Values[
                LS_CalendarLastSyncUtc] =
                _calendarLastChangesCheckUtc.ToString("O");
        }

        private async Task RefreshCalendarChangesSilentlyAsync()
        {
            if (!_calendarViewActive ||
                _calendarChangesRefreshRunning)
            {
                return;
            }

            await RefreshCalendarDaySilentlyAsync(
                _calendarSelectedDate.Date,
                _calendarLoadVersion,
                userInitiated: false);

            // Recordatorios y cobros se refrescan aparte únicamente si cambió
            // App.LocalIndex. No fuerzan un DrawCalendar completo.
            RefreshCalendarExternalOverlaysIfNeeded();
        }

        private void EnsureCalendarSizeHandler()
        {
            if (_calendarSizeHandlerHooked ||
                CalendarScrollViewer == null)
            {
                return;
            }

            CalendarScrollViewer.SizeChanged +=
                CalendarScrollViewer_SizeChanged;

            _calendarSizeHandlerHooked = true;
        }

        private void CalendarScrollViewer_SizeChanged(
            object sender,
            SizeChangedEventArgs e)
        {
            if (!_calendarViewActive)
                return;

            var width =
                e.NewSize.Width;

            if (width <= 0 ||
                Math.Abs(
                    width -
                    _calendarLastViewportWidth) < 8)
            {
                return;
            }

            _calendarLastViewportWidth = width;

            DispatcherQueue.TryEnqueue(() =>
            {
                if (_calendarViewActive)
                    DrawCalendar(_calendarActivities);
            });
        }

        private void ApplyCalendarResponsiveSizing(
            double width)
        {
            if (width <= 0)
                return;

            if (CalendarPersonPreviewPanel != null)
            {
                var desired =
                    width >= 3000
                        ? 520d
                        : width >= 2200
                            ? 460d
                            : width >= 1500
                                ? 420d
                                : 360d;

                var maximum =
                    Math.Max(
                        300,
                        width * 0.34);

                CalendarPersonPreviewPanel.Width =
                    Math.Clamp(
                        desired,
                        300,
                        maximum);
            }

            if (_calendarActivityPreviewPopup?.IsOpen == true &&
                _calendarHoveredActivityButton != null)
            {
                DispatcherQueue.TryEnqueue(
                    () =>
                        PositionCalendarActivityPreviewPopup(
                            _calendarHoveredActivityButton));
            }
        }

        private void CalendarHost_SizeChanged(
            object sender,
            SizeChangedEventArgs e)
        {
            ApplyCalendarResponsiveSizing(
                e.NewSize.Width);
        }

        private void CloseCalendarView()
        {
            _calendarViewActive = false;
            NotifyTabModeChanged("results");
            ClearSearchForModuleSwitch();
            SaveLastSearchSubView("results");
            StopCalendarChangesTimer();
            _calendarProcessElapsedTimer?.Stop();
            Interlocked.Increment(ref _calendarProcessUiVersion);

            if (CalendarProcessPanel != null)
                CalendarProcessPanel.Visibility = Visibility.Collapsed;

            CloseCalendarPersonPreviewPanel(redrawCalendar: false);

            try
            {
                _calendarCts?.Cancel();
                _calendarHoverPreviewCts?.Cancel();
                _calendarIncrementalChecklistCts?.Cancel();
                _calendarReviewFlowBackgroundCts?.Cancel();

                // PROY sí se cancela al salir del calendario. Es una precarga
                // visual de estas cards y no tiene sentido seguir consultando
                // proyectos a escondidas cuando el usuario ya cambió de módulo.
                _calendarProjectWarmupCts?.Cancel();

                // El precalentado de checklist general puede continuar aunque el
                // usuario vuelva a Resultados. Así se conserva ACT en caché.
                // PROY se reconstruirá cuando vuelva a abrir el calendario.
                HideCalendarActivityPreviewFlyout();
            }
            catch
            {
            }

            _calendarHoveredActivityButton = null;

            CalendarHost.Visibility = Visibility.Collapsed;
            ToggleCalendarView.IsChecked = false;

            if (CalendarPhaseFilterControl != null)
                CalendarPhaseFilterControl.Visibility = Visibility.Collapsed;

            if (SearchBox != null &&
                _calendarPreviousSearchPlaceholder != null)
            {
                SearchBox.PlaceholderText =
                    _calendarPreviousSearchPlaceholder;
            }

            ModeText.Text = $"Modo: Buscar ({GetSourceScopeLabel()})";
            CountText.Text = $"{Results.Count} resultados";
        }

