        private async Task NavigateCalendarToDateAsync(
            DateTime date)
        {
            _calendarSelectedDate = date.Date;
            _calendarCardChecklistBaselines.Clear();

            // Cancela cualquier consulta del día anterior para impedir que
            // una respuesta atrasada sobrescriba el día que ya está visible.
            try
            {
                _calendarCts?.Cancel();
            }
            catch
            {
            }

            CalendarDateTitle.Text =
                FormatCalendarDate(_calendarSelectedDate);

            // Una sola ruta de carga: muestra caché y programa la validación
            // incremental sin hacer un segundo DrawCalendar inmediato.
            await LoadCalendarDayAsync(
                preferCache: true);
        }

        private async void CalendarRefresh_Click(
            object sender,
            RoutedEventArgs e)
        {
            _calendarCobroOverlayCache.Clear();

            // El botón manual siempre reconstruye el día directamente desde
            // Notion. La actualización automática conserva la ruta incremental.
            // Esto evita que una caché incompleta deje actividades ocultas.
            await LoadCalendarDayAsync(
                preferCache: false,
                forceRefresh: true);
        }

        private async Task LoadCalendarDayAsync(
            bool preferCache = true,
            bool forceRefresh = false)
        {
            var requestedDate =
                _calendarSelectedDate.Date;

            var loadVersion =
                Interlocked.Increment(
                    ref _calendarLoadVersion);

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            CalendarDateTitle.Text =
                FormatCalendarDate(requestedDate);

            CalendarEmptyState.Visibility =
                Visibility.Collapsed;

            if (string.IsNullOrWhiteSpace(token))
            {
                CalendarEmptyText.Text =
                    "Configura primero el token de Notion.";
                CalendarEmptyState.Visibility =
                    Visibility.Visible;
                return;
            }

            if (preferCache && !forceRefresh)
            {
                var cached =
                    await _notionCalendarService.TryGetCachedDayAsync(
                        requestedDate);

                if (cached != null)
                {
                    if (loadVersion != _calendarLoadVersion ||
                        requestedDate != _calendarSelectedDate.Date)
                    {
                        return;
                    }

                    _calendarActivities = cached;
                    EnsureCalendarRtuzObservationBaseline(
                        _calendarActivities);
                    ApplyCachedCalendarReviewFlow(
                        _calendarActivities);
                    DrawCalendar(_calendarActivities);
                    StartCalendarChecklistHydration(
                        requestedDate,
                        loadVersion);

                    ModeText.Text =
                        "Modo: Calendario (Revisiones)";
                    StatusText.Text =
                        "Estado: Calendario cargado desde caché ✅ · comprobando cambios...";

                    // Ya no se descarga toda la base al mostrar la caché.
                    // Solo se solicitan páginas modificadas desde el último sync.
                    _ = RefreshCalendarDaySilentlyAsync(
                        requestedDate,
                        loadVersion,
                        userInitiated: false);

                    return;
                }
            }

            try
            {
                _calendarCts?.Cancel();
                _calendarCts?.Dispose();
            }
            catch
            {
            }

            _calendarCts =
                new CancellationTokenSource(
                    TimeSpan.FromMinutes(10));

            var cancellationToken =
                _calendarCts.Token;

            var processVersion =
                BeginCalendarProcess(
                    forceRefresh
                        ? "Recarga completa del calendario"
                        : "Preparando calendario",
                    "Esperando turno para consultar Notion...");

            try
            {
                ShowLoadingState(
                    "Estado: Cargando calendario de Revisiones...",
                    FormatCalendarDate(requestedDate));

                var progress =
                    new Progress<NotionCalendarProgress>(
                        report =>
                        {
                            if (loadVersion != _calendarLoadVersion ||
                                requestedDate != _calendarSelectedDate.Date)
                            {
                                return;
                            }

                            UpdateCalendarProcess(
                                processVersion,
                                report);

                            var percentText =
                                report.Total > 0
                                    ? $" {report.Percentage}%"
                                    : string.Empty;

                            UpdateLoadingState(
                                $"Estado: {report.Stage}{percentText}",
                                report.Detail);

                            CountText.Text =
                                report.Total > 0
                                    ? $"{report.Current} de {report.Total}"
                                    : "Consultando...";
                        });

                var activities =
                    await _notionCalendarService.GetDayAsync(
                        token,
                        requestedDate,
                        progress,
                        cancellationToken,
                        forceRefresh);

                // El botón Actualizar debe reparar zREVISION antiguas EN ESTA
                // MISMA CARGA, no depender únicamente de la hidratación
                // secundaria. Esto permite que una actividad que todavía tenga
                // Assignee=Genaro/John vuelva a su responsable original antes
                // de dibujar las columnas.
                if (forceRefresh)
                {
                    await RepairCompletedReviewAssigneesAsync(
                        token,
                        activities,
                        cancellationToken);
                }

                if (!_calendarViewActive ||
                    loadVersion != _calendarLoadVersion ||
                    requestedDate != _calendarSelectedDate.Date)
                {
                    return;
                }

                // También se detecta aquí. El botón “Actualizar” usa esta
                // recarga completa y antes omitía por completo la transición
                // automática hacia RTUZ.
                await ProcessAutomaticCalendarReviewTransitionsAsync(
                    activities,
                    activities
                        .Where(item =>
                            item != null &&
                            !item.IsReviewMirror &&
                            !string.IsNullOrWhiteSpace(item.PageId))
                        .Select(item => item.PageId)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList());

                _calendarActivities = activities;

                // La metadata de revisión jamás debe impedir que el usuario vea
                // y use el calendario. Se aplica lo local y se dibuja primero;
                // cualquier lectura faltante se hace después en segundo plano.
                await EnsureCalendarReviewFlowLocalCacheLoadedAsync(
                    cancellationToken);
                ApplyCachedCalendarReviewFlow(_calendarActivities);

                DrawCalendar(_calendarActivities);
                StartCalendarChecklistHydration(
                    requestedDate,
                    loadVersion);
                SaveCalendarChangesCheckpoint();

                ModeText.Text =
                    "Modo: Calendario (Revisiones)";
                StatusText.Text =
                    activities.Count > 0
                        ? $"Estado: Calendario actualizado ✅ ({activities.Count})"
                        : "Estado: Calendario sin coincidencias";

                CompleteCalendarProcess(
                    processVersion,
                    "Calendario actualizado",
                    $"{activities.Count} actividades listas.");

                StartCalendarReviewFlowHydrationBackground(
                    _calendarActivities,
                    requestedDate,
                    loadVersion);
            }
            catch (OperationCanceledException)
            {
                if (loadVersion != _calendarLoadVersion ||
                    requestedDate != _calendarSelectedDate.Date)
                {
                    return;
                }

                var cached =
                    await _notionCalendarService.TryGetCachedDayAsync(
                        requestedDate);

                if (cached != null)
                {
                    _calendarActivities = cached;
                    DrawCalendar(_calendarActivities);
                    StatusText.Text =
                        "Estado: Se conservó la información guardada del calendario ✅";

                    CompleteCalendarProcess(
                        processVersion,
                        "Consulta cancelada",
                        "Se conserva la caché visible.",
                        success: false);
                    return;
                }

                _calendarActivities =
                    Array.Empty<NotionCalendarActivity>();
                DrawCalendar(_calendarActivities);

                CalendarEmptyText.Text =
                    "La consulta tardó demasiado y fue cancelada. " +
                    "Pulsa Actualizar para intentarlo de nuevo.";
                CalendarEmptyState.Visibility =
                    Visibility.Visible;
                StatusText.Text =
                    "Estado: Carga del calendario cancelada por tiempo de espera.";

                CompleteCalendarProcess(
                    processVersion,
                    "Carga cancelada",
                    "Notion tardó demasiado en responder.",
                    success: false);
            }
            catch (Exception ex)
            {
                if (loadVersion != _calendarLoadVersion ||
                    requestedDate != _calendarSelectedDate.Date)
                {
                    return;
                }

                var cached =
                    await _notionCalendarService.TryGetCachedDayAsync(
                        requestedDate);

                if (cached != null)
                {
                    _calendarActivities = cached;
                    DrawCalendar(_calendarActivities);
                    StatusText.Text =
                        "Estado: No se pudo actualizar; se conserva la caché del calendario.";

                    CompleteCalendarProcess(
                        processVersion,
                        "No se pudo actualizar",
                        "La información guardada sigue visible.",
                        success: false);
                    return;
                }

                _calendarActivities =
                    Array.Empty<NotionCalendarActivity>();
                DrawCalendar(_calendarActivities);
                CalendarEmptyText.Text =
                    $"No se pudo cargar el calendario.\n{ex.Message}";
                CalendarEmptyState.Visibility =
                    Visibility.Visible;
                StatusText.Text =
                    $"Estado: Error en calendario → {ex.Message}";

                CompleteCalendarProcess(
                    processVersion,
                    "Error en calendario",
                    ex.Message,
                    success: false);
            }
            finally
            {
                if (loadVersion == _calendarLoadVersion)
                    HideLoadingState();
            }
        }

        private async Task RefreshCalendarDaySilentlyAsync(
            DateTime requestedDate,
            long loadVersion,
            bool userInitiated = false)
        {
            if (_calendarChangesRefreshRunning)
            {
                if (userInitiated)
                {
                    StatusText.Text =
                        "Estado: El calendario ya se está actualizando...";
                }

                return;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
                return;

            _calendarChangesRefreshRunning = true;

            var processVersion =
                BeginCalendarProcess(
                    userInitiated
                        ? "Actualizando calendario"
                        : "Mostrando caché",
                    "Esperando turno para comprobar cambios recientes...");

            try
            {
                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(4));

                var progress =
                    new Progress<NotionCalendarProgress>(
                        report =>
                            UpdateCalendarProcess(
                                processVersion,
                                report));

                var changed =
                    await _notionCalendarService.RefreshChangedSinceAsync(
                        token,
                        GetCalendarChangesAnchorUtc(),
                        cts.Token,
                        progress);

                var reconcile =
                    await _notionCalendarService.ReconcileDayAsync(
                        token,
                        requestedDate,
                        cts.Token,
                        progress);

                var anyChanges =
                    changed ||
                    reconcile.HasChanges;

                if (reconcile.DeletedOrTrashedPageIds.Count > 0)
                {
                    // También desaparecen de Resultados/App.LocalIndex; no solo
                    // del Canvas del calendario.
                    await RemoveNotionRowsFromIndexAsync(
                        reconcile.DeletedOrTrashedPageIds
                            .ToHashSet(
                                StringComparer.OrdinalIgnoreCase));
                }

                SaveCalendarChangesCheckpoint();

                if (!_calendarViewActive ||
                    requestedDate != _calendarSelectedDate.Date ||
                    loadVersion != _calendarLoadVersion)
                {
                    return;
                }

                var activities =
                    await _notionCalendarService.TryGetCachedDayAsync(
                        requestedDate,
                        cts.Token);

                if (activities != null &&
                    userInitiated)
                {
                    await RepairCompletedReviewAssigneesAsync(
                        token,
                        activities,
                        cts.Token);
                }

                if (activities == null)
                {
                    CompleteCalendarProcess(
                        processVersion,
                        "Sin caché disponible",
                        "Pulsa Actualizar para realizar una recarga completa del día.",
                        success: false);
                    return;
                }

                if (anyChanges)
                {
                    var changedPageIds =
                        _notionCalendarService
                            .LastChangedPageIds
                            .Concat(
                                reconcile.AffectedPageIds)
                            .Where(id =>
                                !string.IsNullOrWhiteSpace(id))
                            .Distinct(
                                StringComparer.OrdinalIgnoreCase)
                            .ToList();

                    // Conserva calientes los proyectos que no tienen relación con
                    // las PageId modificadas. Antes cualquier refresh incremental
                    // vaciaba TODO el cache de proyecto.
                    InvalidateCalendarProjectMemoryForChangedPages(
                        changedPageIds);

                    // Solo una página realmente modificada vuelve a ser elegible
                    // para consultar metadata de revisión. Los "sin metadata" de
                    // las demás páginas permanecen cacheados y no gastan requests.
                    if (InvalidateCalendarReviewFlowForChangedPages(
                            changedPageIds))
                    {
                        await PersistCalendarReviewFlowLocalCacheAsync(
                            cts.Token);
                    }

                    ApplyCachedCalendarReviewFlow(activities);

                    var incomingFingerprint =
                        BuildCalendarVisualFingerprint(activities);

                    var currentFingerprint =
                        BuildCalendarVisualFingerprint(
                            _calendarActivities);

                    // Detecta transiciones reales hacia rtuzREVISION usando un
                    // estado independiente por PageId. Así no se pierde el cambio
                    // aunque otra sincronización ya haya actualizado la caché.
                    // No agrega consultas de lectura.
                    await ProcessAutomaticCalendarReviewTransitionsAsync(
                        activities,
                        changedPageIds);

                    _calendarActivities = activities;

                    if (!string.Equals(
                            incomingFingerprint,
                            currentFingerprint,
                            StringComparison.Ordinal))
                    {
                        DrawCalendarPreservingView(
                            _calendarActivities);
                    }

                    // Incluso si solo cambió un bloque to_do y las propiedades
                    // visibles son idénticas, se refresca SOLO ese PageId.
                    var liveChangedPageIds =
                        changedPageIds
                            .Where(id =>
                                activities.Any(activity =>
                                    string.Equals(
                                        activity.PageId,
                                        id,
                                        StringComparison.OrdinalIgnoreCase)))
                            .ToList();

                    StartCalendarIncrementalChecklistRefresh(
                        liveChangedPageIds,
                        requestedDate,
                        loadVersion);
                }

                var reconcileSummary =
                    reconcile.HasChanges
                        ? $" · {reconcile.DeletedOrTrashed} eliminada(s)" +
                          $" · {reconcile.MovedOrRemovedFromDay} movida(s)" +
                          $" · {reconcile.Added} nueva(s)"
                        : string.Empty;

                StatusText.Text = anyChanges
                    ? $"Estado: Calendario actualizado ✅ ({activities.Count}){reconcileSummary}"
                    : $"Estado: Calendario al día ✅ ({activities.Count})";

                CompleteCalendarProcess(
                    processVersion,
                    anyChanges
                        ? "Cambios reconciliados"
                        : "Calendario al día",
                    anyChanges
                        ? $"{activities.Count} actividades listas{reconcileSummary}."
                        : "No se encontraron cambios ni páginas ausentes en Notion.");

                // Revisión es enriquecimiento secundario: empieza SOLO cuando la
                // comprobación principal terminó y nunca mantiene abierto el panel
                // de proceso. Si hay cooldown, espera/cancela de fondo.
                StartCalendarReviewFlowHydrationBackground(
                    activities,
                    requestedDate,
                    loadVersion);
            }
            catch (OperationCanceledException)
            {
                CompleteCalendarProcess(
                    processVersion,
                    "Comprobación cancelada",
                    "La caché continúa visible.",
                    success: false);
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    "Estado: No se pudo comprobar Notion; se conserva la caché.";

                CompleteCalendarProcess(
                    processVersion,
                    "No se pudo comprobar Notion",
                    ex.Message,
                    success: false);
            }
            finally
            {
                _calendarChangesRefreshRunning = false;
            }
        }

        private static List<DateTime> NormalizeCalendarMovementRoute(
            CalendarMoveHistoryEntry entry)
        {
            var route =
                (entry.RouteDates ??
                 new List<DateTime>())
                    .Where(date =>
                        date != default)
                    .Select(date =>
                        date.Date)
                    .ToList();

            if (route.Count == 0)
            {
                if (entry.SourceDate != default)
                    route.Add(entry.SourceDate.Date);

                if (entry.TargetDate != default &&
                    (route.Count == 0 ||
                     route[^1] != entry.TargetDate.Date))
                {
                    route.Add(entry.TargetDate.Date);
                }
            }

            if (entry.SourceDate != default &&
                (route.Count == 0 ||
                 route[0] != entry.SourceDate.Date))
            {
                route.Insert(
                    0,
                    entry.SourceDate.Date);
            }

            if (entry.TargetDate != default &&
                (route.Count == 0 ||
                 route[^1] != entry.TargetDate.Date))
            {
                route.Add(
                    entry.TargetDate.Date);
            }

            var normalized =
                new List<DateTime>();

            foreach (var date in route)
            {
                if (normalized.Count == 0 ||
                    normalized[^1] != date.Date)
                {
                    normalized.Add(
                        date.Date);
                }
            }

            return normalized;
        }

        private void EnsureCalendarMoveHistoryLoaded()
        {
            lock (_calendarMoveHistorySync)
            {
                try
                {
                    var path = Path.Combine(
                        ApplicationData.Current.LocalFolder.Path,
                        CalendarMoveHistoryFileName);

                    var lastWriteUtc =
                        File.Exists(path)
                            ? File.GetLastWriteTimeUtc(path)
                            : DateTime.MinValue;

                    // Avance Diario también puede registrar "Mover mañana".
                    // Si el archivo cambió fuera de SearchView, recargamos sin
                    // reiniciar ANFETA.
                    if (_calendarMoveHistoryLoaded &&
                        lastWriteUtc ==
                            _calendarMoveHistoryLastWriteUtc)
                    {
                        return;
                    }

                    _calendarMoveHistoryLoaded = true;
                    _calendarMoveHistoryLastWriteUtc =
                        lastWriteUtc;

                    _calendarMoveHistory.Clear();

                    if (!File.Exists(path))
                        return;

                    var raw = File.ReadAllText(path);

                    if (string.IsNullOrWhiteSpace(raw))
                        return;

                    var restored =
                        JsonSerializer.Deserialize<
                            Dictionary<string, CalendarMoveHistoryEntry>>(raw);

                    if (restored == null)
                        return;

                    foreach (var item in restored)
                    {
                        if (string.IsNullOrWhiteSpace(item.Key) ||
                            item.Value == null)
                        {
                            continue;
                        }

                        var restoredEntry =
                            item.Value;

                        restoredEntry.PageId =
                            item.Key;

                        restoredEntry.SourceDate =
                            restoredEntry.SourceDate.Date;

                        restoredEntry.TargetDate =
                            restoredEntry.TargetDate.Date;

                        restoredEntry.LastSourceDate =
                            restoredEntry.LastSourceDate == default
                                ? restoredEntry.SourceDate
                                : restoredEntry.LastSourceDate.Date;

                        restoredEntry.RouteDates =
                            NormalizeCalendarMovementRoute(
                                restoredEntry);

                        if (restoredEntry.MoveCount <= 0)
                        {
                            restoredEntry.MoveCount =
                                Math.Max(
                                    1,
                                    restoredEntry.RouteDates.Count - 1);
                        }

                        _calendarMoveHistory[item.Key] =
                            restoredEntry;
                    }
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_MOVE_HISTORY_LOAD] {ex.Message}");
                }
            }
        }

        private void SaveCalendarMoveHistory()
        {
            lock (_calendarMoveHistorySync)
            {
                try
                {
                    var path = Path.Combine(
                        ApplicationData.Current.LocalFolder.Path,
                        CalendarMoveHistoryFileName);

                    var json = JsonSerializer.Serialize(
                        _calendarMoveHistory,
                        new JsonSerializerOptions
                        {
                            WriteIndented = true
                        });

                    File.WriteAllText(path, json);

                    _calendarMoveHistoryLastWriteUtc =
                        File.Exists(path)
                            ? File.GetLastWriteTimeUtc(path)
                            : DateTime.UtcNow;
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_MOVE_HISTORY_SAVE] {ex.Message}");
                }
            }
        }

        private void RegisterCalendarDayMovement(
            NotionCalendarActivity activity,
            DateTime sourceDate,
            DateTime targetDate,
            string reason)
        {
            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return;
            }

            var source = sourceDate.Date;
            var target = targetDate.Date;

            // El indicador describe arrastre hacia días posteriores.
            // Movimientos hacia atrás reinician la cadena anterior.
            if (target <= source)
            {
                ClearCalendarDayMovement(activity.PageId);
                return;
            }

            EnsureCalendarMoveHistoryLoaded();

            lock (_calendarMoveHistorySync)
            {
                _calendarMoveHistory.TryGetValue(
                    activity.PageId,
                    out var previous);

                var continuesExistingRoute =
                    previous != null &&
                    previous.TargetDate.Date == source &&
                    previous.SourceDate.Date < source;

                if (continuesExistingRoute)
                {
                    var route =
                        NormalizeCalendarMovementRoute(
                            previous!);

                    if (route.Count == 0 ||
                        route[^1] != source)
                    {
                        route.Add(
                            source);
                    }

                    if (route[^1] != target)
                    {
                        route.Add(
                            target);
                    }

                    previous!.LastSourceDate =
                        source;

                    previous.TargetDate =
                        target;

                    previous.MovedAt =
                        DateTimeOffset.Now;

                    previous.Reason =
                        (reason ?? string.Empty).Trim();

                    previous.RouteDates =
                        route;

                    previous.MoveCount =
                        Math.Max(
                            previous.MoveCount + 1,
                            route.Count - 1);

                    _calendarMoveHistory[
                        activity.PageId] =
                            previous;
                }
                else
                {
                    _calendarMoveHistory[
                        activity.PageId] =
                            new CalendarMoveHistoryEntry
                            {
                                PageId =
                                    activity.PageId,
                                SourceDate =
                                    source,
                                LastSourceDate =
                                    source,
                                TargetDate =
                                    target,
                                MovedAt =
                                    DateTimeOffset.Now,
                                Reason =
                                    (reason ?? string.Empty).Trim(),
                                MoveCount =
                                    1,
                                RouteDates =
                                    new List<DateTime>
                                    {
                                        source,
                                        target
                                    }
                            };
                }
            }

            SaveCalendarMoveHistory();
        }

        private void ClearCalendarDayMovement(string pageId)
        {
            var clean = (pageId ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(clean))
                return;

            EnsureCalendarMoveHistoryLoaded();

            var removed = false;

            lock (_calendarMoveHistorySync)
            {
                removed = _calendarMoveHistory.Remove(clean);
            }

            if (removed)
                SaveCalendarMoveHistory();
        }

        private bool TryGetCalendarDayMovement(
            NotionCalendarActivity activity,
            out CalendarMoveHistoryEntry movement)
        {
            movement = null!;

            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return false;
            }

            EnsureCalendarMoveHistoryLoaded();

            CalendarMoveHistoryEntry? stored;

            lock (_calendarMoveHistorySync)
            {
                _calendarMoveHistory.TryGetValue(
                    activity.PageId,
                    out stored);
            }

            if (stored == null)
                return false;

            // Si Notion cambió luego la fecha manualmente, la marca anterior
            // deja de ser válida. No mostramos una ruta vieja.
            if (stored.TargetDate.Date != activity.Start.Date)
            {
                ClearCalendarDayMovement(activity.PageId);
                return false;
            }

            if (stored.TargetDate.Date <= stored.SourceDate.Date)
            {
                ClearCalendarDayMovement(activity.PageId);
                return false;
            }

            stored.RouteDates =
                NormalizeCalendarMovementRoute(
                    stored);

            if (stored.MoveCount <= 0)
            {
                stored.MoveCount =
                    Math.Max(
                        1,
                        stored.RouteDates.Count - 1);
            }

            movement = stored;
            return true;
        }

        private string GetCalendarDayMovementBadge(
            NotionCalendarActivity activity)
        {
            if (!TryGetCalendarDayMovement(activity, out var movement))
                return string.Empty;

            var days = Math.Max(
                1,
                (movement.TargetDate.Date -
                 movement.SourceDate.Date).Days);

            return days == 1
                ? "↪ De ayer"
                : $"↪ De hace {days} días";
        }

        private string GetCalendarDayMovementCompactBadge(
            NotionCalendarActivity activity)
        {
            if (!TryGetCalendarDayMovement(activity, out var movement))
                return string.Empty;

            var days = Math.Max(
                1,
                (movement.TargetDate.Date -
                 movement.SourceDate.Date).Days);

            return days == 1
                ? "↪ Ayer"
                : $"↪ {days}d";
        }

        private string GetCalendarDayMovementDetail(
            NotionCalendarActivity activity)
        {
            if (!TryGetCalendarDayMovement(activity, out var movement))
                return string.Empty;

            var days = Math.Max(
                1,
                (movement.TargetDate.Date -
                 movement.SourceDate.Date).Days);

            var relative = days == 1
                ? "desde ayer"
                : $"desde hace {days} días";

            var reason = string.IsNullOrWhiteSpace(movement.Reason)
                ? string.Empty
                : $" · {movement.Reason}";

            var route =
                NormalizeCalendarMovementRoute(
                    movement);

            var routeText =
                route.Count > 2
                    ? $" · ruta {string.Join(
                        " → ",
                        route.Select(date =>
                            date.ToString(
                                "dd/MM",
                                CultureInfo.InvariantCulture)))}"
                    : string.Empty;

            var moveCount =
                Math.Max(
                    movement.MoveCount,
                    route.Count - 1);

            var countText =
                moveCount > 1
                    ? $" · {moveCount} movimientos"
                    : string.Empty;

            return
                $"Movida por ANFETA {relative} " +
                $"({movement.SourceDate:dd/MM/yyyy} → " +
                $"{movement.TargetDate:dd/MM/yyyy})" +
                $"{countText}{routeText}{reason}";
        }

        private static string BuildCalendarVisualFingerprint(
            IReadOnlyList<NotionCalendarActivity> activities)
        {
            if (activities == null || activities.Count == 0)
                return string.Empty;

            return string.Join(
                "\n",
                activities
                    .OrderBy(item => item.PageId)
                    .ThenBy(item => item.Person)
                    .Select(item =>
                        string.Join(
                            "|",
                            item.PageId,
                            item.Title,
                            item.Person,
                            item.OriginalPerson,
                            item.ReviewAssignee,
                            item.ReviewState,
                            item.Start.ToString("O"),
                            item.End.ToString("O"),
                            item.Status,
                            item.StatusColor,
                            item.UpdateText,
                            item.IsAutomationLocked,
                            item.ChecklistScanned,
                            item.ChecklistTotal,
                            item.ChecklistCompleted,
                            item.EstimatedWorkMinutes,
                            item.WorkedMinutes,
                            item.WorkLogDetail,
                            item.ActivityCreatedDate?.ToString("yyyy-MM-dd") ?? string.Empty,
                            item.InternalDeadlineDate?.ToString("yyyy-MM-dd") ?? string.Empty)));
        }

        private void DrawCalendarPreservingView(
            IReadOnlyList<NotionCalendarActivity> activities,
            bool force = false)
        {
            var fingerprint =
                BuildCalendarVisualFingerprint(activities);

            if (!force &&
                string.Equals(
                    fingerprint,
                    _calendarLastVisualFingerprint,
                    StringComparison.Ordinal))
            {
                return;
            }

            var horizontalOffset =
                CalendarScrollViewer?.HorizontalOffset ?? 0;

            var verticalOffset =
                CalendarScrollViewer?.VerticalOffset ?? 0;

            DrawCalendar(activities);

            _calendarLastVisualFingerprint = fingerprint;

            DispatcherQueue.TryEnqueue(() =>
            {
                CalendarScrollViewer?.ChangeView(
                    horizontalOffset,
                    verticalOffset,
                    null,
                    disableAnimation: true);
            });
        }

        private void DrawCalendar(
            IReadOnlyList<NotionCalendarActivity> activities)
        {
            ApplyCachedCalendarReviewFlow(activities);

            var expandedActivities =
                ExpandCalendarReviewActivities(activities);

            var phaseActivities =
                string.IsNullOrWhiteSpace(
                    _calendarPhaseFilter)
                    ? expandedActivities
                    : expandedActivities
                        .Where(activity =>
                            ContainsExactCalendarPart(
                                BuildCalendarActivitySearchableText(
                                    activity),
                                _calendarPhaseFilter))
                        .ToList();

            var visibleActivities =
                FilterCalendarActivities(
                    phaseActivities,
                    _calendarSearchQuery);

            CalendarCanvas.Children.Clear();
            _calendarActivityVisuals.Clear();
            _calendarPinnedOverlapActivityButton = null;
            _calendarActivityBaseZIndexes.Clear();
            _calendarStickyHeaders.Clear();
            _calendarStickyHours.Clear();
            _calendarStickyCorner = null;

            var hasCobroOverlayEvents =
                _calendarShowCobros &&
                GetCalendarCobroItems(
                    _calendarSelectedDate).Count > 0;

            CalendarEmptyState.Visibility =
                visibleActivities.Count == 0 &&
                !hasCobroOverlayEvents
                    ? Visibility.Visible
                    : Visibility.Collapsed;

            CalendarEmptyText.Text =
                string.IsNullOrWhiteSpace(_calendarSearchQuery)
                    ? (string.IsNullOrWhiteSpace(_calendarPhaseFilter)
                        ? "No hay actividades programadas para este día."
                        : $"No hay actividades con la fase exacta {_calendarPhaseFilter}.") +
                      (string.IsNullOrWhiteSpace(
                          _notionCalendarService.LastDiagnostics)
                          ? string.Empty
                          : $"\n\n{_notionCalendarService.LastDiagnostics}")
                    : $"No se encontraron actividades que coincidan con “{_calendarSearchQuery}”.";

            var persons =
                _calendarPeopleOrder
                    .Where(person =>
                        _calendarSelectedPeople.Contains(person))
                    .ToList();

            if (persons.Count == 0)
            {
                CalendarEmptyText.Text =
                    "Selecciona al menos una persona en el filtro.";
                CalendarEmptyState.Visibility = Visibility.Visible;
            }

            var visibleEndHour =
                CalendarVisibleEndHour;

            var totalHours =
                visibleEndHour - CalendarStartHour;

            var headerHeight = CalendarHeaderHeight;
            var bodyHeight = totalHours * CalendarHourHeight;

            var viewportWidth =
                CalendarScrollViewer?.ActualWidth > 0
                    ? CalendarScrollViewer.ActualWidth
                    : CalendarHost.ActualWidth;

            ResolveCalendarColumnLayout(
                persons,
                viewportWidth);

            var totalWidth =
                CalendarTimeColumnWidth +
                persons.Sum(GetResolvedCalendarColumnWidth) +
                GetResolvedCalendarCobroRailWidth();

            CalendarCanvas.Width =
                Math.Max(
                    Math.Max(900, viewportWidth),
                    totalWidth);

            // Banda inferior persistente: incluso si no hay actividades
            // después de las 9:00 PM, el usuario siempre ve cómo desplegar
            // 9:00–10:00 PM.
            var extraHoursToggleBandHeight =
                Math.Max(
                    34,
                    38 * _calendarZoom);

            CalendarCanvas.Height =
                headerHeight +
                bodyHeight +
                extraHoursToggleBandHeight +
                18;

            CalendarCanvas.Background =
                new SolidColorBrush(Darken(_calendarThemeColor, 0.12));

            var headerBackground = AddCalendarRectangle(
                0,
                0,
                CalendarCanvas.Width,
                headerHeight,
                Darken(_calendarThemeColor, 0.02),
                Lighten(_calendarThemeColor, 0.18));

            Canvas.SetZIndex(headerBackground, 100);

            var corner = AddCalendarText(
                "Hora",
                10,
                17 * _calendarZoom,
                CalendarTimeColumnWidth - 20,
                24 * _calendarZoom,
                12 * CalendarFontScale,
