                    });

                // 📅 Calendario Notion
                headerContainer.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                // ⚡ One Click
                headerContainer.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                // ⋯ Más opciones
