                var notionCalendarButton = new Button
                {
                    Content = "📅",
                    Width = 28,
                    Height = Math.Max(26, headerHeight - 14),
                    Margin = new Thickness(0, 5, 3, 5),
                    Padding = new Thickness(0),
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Center,
                    HorizontalContentAlignment = HorizontalAlignment.Center,
                    VerticalContentAlignment = VerticalAlignment.Center,
                    FontSize = 11.5 * CalendarFontScale,
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(48, 56, 189, 248)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(150, 56, 189, 248)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6),
                    Tag = person,
                    Visibility =
                        hasPersonNotionCalendar
                            ? Visibility.Visible
                            : Visibility.Collapsed
                };

                ToolTipService.SetToolTip(
                    notionCalendarButton,
                    $"Abrir calendario de {person} en Notion");

                notionCalendarButton.Click +=
                    CalendarOpenPersonNotion_Click;

                var optimizeButton = new Button
                {
                    Content = "⚡",
                    Width = 28,
                    Height = Math.Max(26, headerHeight - 14),
                    Margin = new Thickness(0, 5, 3, 5),
                    Padding = new Thickness(0),
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Center,
                    HorizontalContentAlignment = HorizontalAlignment.Center,
                    VerticalContentAlignment = VerticalAlignment.Center,
                    FontSize = 12.5 * CalendarFontScale,
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(55, 250, 204, 21)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(155, 250, 204, 21)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6),
                    Tag = person
                };

                ToolTipService.SetToolTip(
                    optimizeButton,
                    $"Generar vista previa de One Click Schedule para {person}");

                optimizeButton.Click +=
