                    BorderBrush = new SolidColorBrush(
                        Color.FromArgb(115, 192, 132, 252)),
                    BorderThickness = new Thickness(1),
                    Child = cobroHeader
                };

                Canvas.SetLeft(
                    cobroHeaderBorder,
                    GetResolvedCalendarCobroRailLeft() + 3);

                Canvas.SetTop(cobroHeaderBorder, 4);
                Canvas.SetZIndex(cobroHeaderBorder, 305);
                CalendarCanvas.Children.Add(cobroHeaderBorder);
                _calendarStickyHeaders.Add(cobroHeaderBorder);

                AddVerticalLine(
                    GetResolvedCalendarCobroRailLeft(),
                    0,
                    headerHeight + bodyHeight,
                    Color.FromArgb(145, 168, 85, 247));

                AddVerticalLine(
                    GetResolvedCalendarCobroRailLeft() + globalCobroRailWidth,
                    0,
                    headerHeight + bodyHeight,
                    Color.FromArgb(100, 168, 85, 247));
            }

            AddVerticalLine(
                CalendarCanvas.Width - 1,
                0,
                headerHeight + bodyHeight,
                Lighten(_calendarThemeColor, 0.20));

            for (var hour = CalendarStartHour;
                 hour <= visibleEndHour;
                 hour++)
            {
                var top =
                    headerHeight +
                    (hour - CalendarStartHour) *
                    CalendarHourHeight;

                AddHorizontalLine(
                    0,
                    top,
                    CalendarCanvas.Width,
                    Lighten(_calendarThemeColor, 0.15));

                // También dibuja la etiqueta del LÍMITE inferior.
                // Contraído: aparece 9:00 PM al final.
                // Expandido: aparece 10:00 PM al final.
                var isTerminalHour =
                    hour == visibleEndHour;

                var hourLabel = AddCalendarText(
                    FormatHour(hour),
                    8,
                    top + (isTerminalHour ? -9 : 5),
                    CalendarTimeColumnWidth - 14,
                    22 * _calendarZoom,
                    11 * CalendarFontScale,
                    false);

                hourLabel.Opacity =
                    isTerminalHour
                        ? 0.82
                        : 1.0;

                _calendarStickyHours.Add(hourLabel);
                Canvas.SetZIndex(hourLabel, 210);
            }

            // ---------------------------------------------------------
            // HORARIO EXTRA · DESPLEGABLE EN EL PROPIO CALENDARIO
            // ---------------------------------------------------------
            // Siempre visible, aunque no exista ninguna actividad 21:00–22:00.
            // Así se entiende claramente que el calendario principal llega
            // hasta las 9:00 PM y que hay una hora adicional disponible.
            var extraHourCount =
                GetCalendarExtraHourItemCount();

            var extraBandTop =
                headerHeight +
                bodyHeight +
                Math.Max(
                    14,
                    16 * _calendarZoom);

            var extraBandLeft =
                CalendarTimeColumnWidth +
                6;

            var extraBandWidth =
                Math.Max(
                    180,
                    CalendarCanvas.Width -
                    CalendarTimeColumnWidth -
                    12);

            var extraBandButton =
                new Button
                {
                    Width = extraBandWidth,
                    Height =
                        Math.Max(
                            28,
                            31 * _calendarZoom),
                    Padding =
                        new Thickness(
                            12,
                            3,
                            12,
                            3),
                    HorizontalContentAlignment =
                        HorizontalAlignment.Center,
                    VerticalContentAlignment =
                        VerticalAlignment.Center,
                    Background =
                        new SolidColorBrush(
                            _calendarShowExtraHours
                                ? Color.FromArgb(
                                    52, 56, 189, 248)
                                : Color.FromArgb(
                                    30, 148, 163, 184)),
                    BorderBrush =
                        new SolidColorBrush(
                            _calendarShowExtraHours
                                ? Color.FromArgb(
                                    155, 56, 189, 248)
                                : Color.FromArgb(
                                    90, 148, 163, 184)),
                    BorderThickness =
                        new Thickness(1),
                    CornerRadius =
                        new CornerRadius(8),
                    Content =
                        new TextBlock
                        {
                            Text =
                                _calendarShowExtraHours
                                    ? "⌃ Ocultar horario extra · 9:00–10:00 PM"
                                    : extraHourCount > 0
                                        ? $"⌄ Mostrar horario extra · 9:00–10:00 PM · {extraHourCount} elemento(s)"
                                        : "⌄ Mostrar horario extra · 9:00–10:00 PM",
                            FontSize =
                                Math.Max(
                                    9.5,
                                    10.2 * CalendarFontScale),
                            FontWeight =
                                Microsoft.UI.Text.FontWeights.SemiBold,
                            HorizontalAlignment =
                                HorizontalAlignment.Center,
                            TextAlignment =
                                TextAlignment.Center,
                            TextTrimming =
                                TextTrimming.CharacterEllipsis,
                            MaxLines = 1
                        },
                    Tag = "CalendarExtraHoursInlineToggle"
                };

            extraBandButton.Click +=
                CalendarExtraHoursToggle_Click;

            ToolTipService.SetToolTip(
                extraBandButton,
                _calendarShowExtraHours
                    ? "Contraer el calendario y volver a terminar visualmente a las 9:00 PM."
                    : extraHourCount > 0
                        ? $"Desplegar 9:00–10:00 PM. Hay {extraHourCount} elemento(s) en esa hora."
                        : "Desplegar 9:00–10:00 PM aunque actualmente no haya actividades.");

            Canvas.SetLeft(
                extraBandButton,
                extraBandLeft);

            Canvas.SetTop(
                extraBandButton,
                extraBandTop);

            Canvas.SetZIndex(
                extraBandButton,
                260);

            CalendarCanvas.Children.Add(
                extraBandButton);

            var filteredActivities =
                visibleActivities
                    .SelectMany(activity =>
                        SplitPersons(activity.Person)
                            .Select(person =>
                                (Activity: activity,
                                 Person: NormalizeCalendarPerson(person))))
                    .Where(x =>
                        !string.IsNullOrWhiteSpace(x.Person) &&
                        _calendarSelectedPeople.Contains(x.Person))
                    .ToList();


            foreach (var person in persons)
            {
                var personIndex =
                    persons.FindIndex(x =>
                        string.Equals(
                            x,
                            person,
                            StringComparison.OrdinalIgnoreCase));

                var items = filteredActivities
                    .Where(x =>
                        string.Equals(
                            x.Person,
                            person,
                            StringComparison.OrdinalIgnoreCase))
                    .Select(x => x.Activity)
                    .OrderBy(x => x.Start)
                    .ThenBy(x => x.End)
                    .ToList();

                DrawPersonActivities(
                    items,
                    person,
                    headerHeight);
            }

            // Los recordatorios se dibujan como eventos especiales sobre el
            // calendario normal sin formar parte de One Click ni de la carga
            // de actividades de Notion.
            DrawCalendarReminderOverlays(
                headerHeight,
                persons);

            // Capa visual independiente de BD COBRAR Y PAGAR.
            DrawCalendarCobroOverlays(
                headerHeight,
                persons);

            _calendarExternalOverlayIndexVersion =
                App.LocalIndex.Version;

            DrawCurrentTimeLine(headerHeight);
            UpdateCalendarStickyElements();

            CalendarZoomText.Text =
                $"{Math.Round(_calendarZoom * 100):0}%";

            if (_calendarViewActive)
            {
                var drawnActivityCount =
                    filteredActivities
                        .Select(item =>
                            string.Join(
                                "|",
                                item.Activity.PageId,
                                item.Person,
                                item.Activity.IsReviewMirror,
                                item.Activity.Start.ToString("O")))
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .Count();

                var visibleCobros =
                    _calendarShowCobros
                        ? GetCalendarCobroItems(
                            _calendarSelectedDate).Count
                        : 0;

                CountText.Text =
                    $"{drawnActivityCount} visibles · {activities.Count} cargadas" +
                    (_calendarShowCobros
                        ? $" · {visibleCobros} cobro(s)"
                        : string.Empty);

                var phaseLabel =
                    string.IsNullOrWhiteSpace(_calendarPhaseFilter)
                        ? "Todas"
                        : _calendarPhaseFilter;

                var cobrosMode =
                    _calendarShowCobros
                        ? " · 💰 Cobros"
                        : string.Empty;

                ModeText.Text =
                    (string.IsNullOrWhiteSpace(_calendarSearchQuery)
                        ? $"Modo: Calendario · {phaseLabel}"
                        : $"Modo: Calendario · {phaseLabel} · {_calendarSearchQuery}") +
                    cobrosMode;
            }

            _calendarLastVisualFingerprint =
                BuildCalendarVisualFingerprint(activities);

            // Refresca texto/contador del botón cada vez que cambia el día,
            // filtros, personas, cobros o actividades.
            UpdateCalendarExtraHoursToggleVisual();

            RefreshCalendarPersonPreviewIfOpen();
        }

        private sealed record CalendarCobroOverlayItem(
            SearchResultRow Row,
            DateTime Start,
            DateTime End,
            string Person,
            string Title);

        private ToggleButton? CalendarCobrosToggleControl =>
            FindName("CalendarCobrosToggle") as ToggleButton;

        private ToggleButton? CalendarExtraHoursToggleControl =>
            FindName("CalendarExtraHoursToggle") as ToggleButton;

        private void LoadCalendarExtraHoursPreference()
        {
            if (!_calendarExtraHoursPreferenceLoaded)
            {
                _calendarExtraHoursPreferenceLoaded = true;

                var stored =
                    ApplicationData.Current.LocalSettings.Values[
                        LS_CalendarShowExtraHours];

                // Contraído por defecto. Solo se restaura expandido cuando el
                // propio usuario lo dejó así anteriormente.
                _calendarShowExtraHours =
                    stored is bool enabled && enabled;
            }

            UpdateCalendarExtraHoursToggleVisual();
        }

        private int GetCalendarExtraHourItemCount()
        {
            if (_calendarActivities == null)
                return 0;

            var extraStart =
                _calendarSelectedDate.Date
                    .AddHours(CalendarPrimaryEndHour);

            var extraEnd =
                _calendarSelectedDate.Date
                    .AddHours(CalendarEndHour);

            var expanded =
                ExpandCalendarReviewActivities(
                    _calendarActivities);

            var phaseFiltered =
                string.IsNullOrWhiteSpace(_calendarPhaseFilter)
                    ? expanded
                    : expanded
                        .Where(activity =>
                            ContainsExactCalendarPart(
                                BuildCalendarActivitySearchableText(
                                    activity),
                                _calendarPhaseFilter))
                        .ToList();

            var filtered =
                FilterCalendarActivities(
                    phaseFiltered,
                    _calendarSearchQuery);

            var activityCount =
                filtered
                    .Where(activity =>
                        activity != null &&
                        activity.End > extraStart &&
                        activity.Start < extraEnd &&
                        SplitPersons(activity.Person)
                            .Select(NormalizeCalendarPerson)
                            .Any(person =>
                                _calendarSelectedPeople.Contains(
                                    person)))
                    .Select(activity =>
                        string.Join(
                            "|",
                            activity.PageId,
                            activity.IsReviewMirror,
                            activity.Start.ToString("O")))
                    .Distinct(
                        StringComparer.OrdinalIgnoreCase)
                    .Count();

            // Si Cobros está visible también advertimos de eventos de esa
            // columna en la hora extra, para que no parezca que desaparecieron.
            var cobroCount =
                _calendarShowCobros
                    ? GetCalendarCobroItems(
                            _calendarSelectedDate)
                        .Count(item =>
                            item.End > extraStart &&
                            item.Start < extraEnd)
                    : 0;

            return activityCount + cobroCount;
        }

        private void UpdateCalendarExtraHoursToggleVisual()
        {
            if (CalendarExtraHoursToggleControl == null)
                return;

            var extraCount =
                GetCalendarExtraHourItemCount();

            CalendarExtraHoursToggleControl.IsChecked =
                _calendarShowExtraHours;

            CalendarExtraHoursToggleControl.Content =
                _calendarShowExtraHours
                    ? "🕙 Ocultar 9–10 PM ↑"
                    : extraCount > 0
                        ? $"🕘 9–10 PM ({extraCount}) ↓"
                        : "🕘 9–10 PM ↓";

            ToolTipService.SetToolTip(
                CalendarExtraHoursToggleControl,
                _calendarShowExtraHours
                    ? "Ocultar el tramo extra de 9:00 PM a 10:00 PM y volver al horario principal."
                    : extraCount > 0
                        ? $"Mostrar 9:00–10:00 PM · hay {extraCount} elemento(s) en ese tramo."
                        : "Mostrar el horario extra de 9:00 PM a 10:00 PM.");
        }

        private void CalendarExtraHoursToggle_Click(
            object sender,
            RoutedEventArgs e)
        {
            _calendarShowExtraHours =
                sender is ToggleButton toggle
                    ? toggle.IsChecked == true
                    : !_calendarShowExtraHours;

            ApplicationData.Current.LocalSettings.Values[
                LS_CalendarShowExtraHours] =
                _calendarShowExtraHours;

            UpdateCalendarExtraHoursToggleVisual();

            if (_calendarViewActive)
            {
                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);

                if (_calendarShowExtraHours)
                {
                    // Mostrar horario extra debe ser visible inmediatamente.
                    // Se lleva la vista cerca de las 20:00 para que aparezcan
                    // 21:00–22:00 sin mandar al usuario al fondo manualmente.
                    DispatcherQueue.TryEnqueue(() =>
                    {
                        var targetOffset =
                            Math.Max(
                                0,
                                CalendarHeaderHeight +
                                (CalendarPrimaryEndHour -
                                 CalendarStartHour - 1) *
                                CalendarHourHeight);

                        CalendarScrollViewer?.ChangeView(
                            null,
                            targetOffset,
                            null,
                            disableAnimation: false);
                    });
                }
            }

            StatusText.Text =
                _calendarShowExtraHours
                    ? "Estado: Horario extra 9:00–10:00 PM visible ✅"
                    : "Estado: Calendario principal hasta 9:00 PM · tramo 9:00–10:00 PM oculto ✅";
        }

        private void LoadCalendarCobrosPreference()
        {
            if (!_calendarCobrosPreferenceLoaded)
            {
                _calendarCobrosPreferenceLoaded = true;

                var stored =
                    ApplicationData.Current.LocalSettings.Values[
                        LS_CalendarShowCobros];

                _calendarShowCobros =
                    stored is bool enabled && enabled;

                var storedSlot =
                    ApplicationData.Current.LocalSettings.Values[
                        LS_CalendarCobrosColumnSlot];

                if (storedSlot is int intSlot)
                {
                    _calendarCobroColumnSlot =
                        Math.Max(0, intSlot);
                }
                else if (int.TryParse(
                             storedSlot?.ToString(),
                             NumberStyles.Integer,
                             CultureInfo.InvariantCulture,
                             out var parsedSlot))
                {
                    _calendarCobroColumnSlot =
                        Math.Max(0, parsedSlot);
                }
            }

            UpdateCalendarCobrosToggleVisual();
        }

        private void UpdateCalendarCobrosToggleVisual()
        {
            if (CalendarCobrosToggleControl == null)
                return;

            CalendarCobrosToggleControl.IsChecked = _calendarShowCobros;
            CalendarCobrosToggleControl.Content =
                _calendarShowCobros ? "💰 Cobros ✓" : "💰 Cobros";

            ToolTipService.SetToolTip(
                CalendarCobrosToggleControl,
                _calendarShowCobros
                    ? "Ocultar eventos de BD COBRAR Y PAGAR"
                    : "Mostrar eventos con Due Fecha Recordatorio de BD COBRAR Y PAGAR");
        }

        private void SaveCalendarCobrosColumnSlot()
        {
            ApplicationData.Current.LocalSettings.Values[
                LS_CalendarCobrosColumnSlot] =
                Math.Max(0, _calendarCobroColumnSlot);
        }

        private void MoveCalendarCobrosColumn(
            int delta)
        {
            if (!_calendarShowCobros || delta == 0)
                return;

            var visiblePeopleCount =
                _calendarPeopleOrder.Count(person =>
                    _calendarSelectedPeople.Contains(person));

            var current = Math.Clamp(
                _calendarCobroColumnSlot,
                0,
                Math.Max(0, visiblePeopleCount));

            var next = Math.Clamp(
                current + delta,
                0,
                Math.Max(0, visiblePeopleCount));

            if (next == current)
                return;

            _calendarCobroColumnSlot = next;
            SaveCalendarCobrosColumnSlot();

            if (_calendarViewActive)
            {
                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);
            }

            StatusText.Text =
                $"Estado: Columna Cobros movida · posición {_calendarCobroColumnSlot + 1} ✅";
        }

        private void HideCalendarCobrosColumn()
        {
            _calendarShowCobros = false;

            ApplicationData.Current.LocalSettings.Values[
                LS_CalendarShowCobros] = false;

            _calendarCobroOverlayCache.Clear();
            UpdateCalendarCobrosToggleVisual();

            if (_calendarViewActive)
            {
                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);
            }

            StatusText.Text =
                "Estado: Columna Cobros oculta ✅ · usa 💰 Cobros para mostrarla de nuevo";
        }

        private async void CalendarCobrosToggle_Click(
            object sender,
            RoutedEventArgs e)
        {
            _calendarShowCobros =
                sender is ToggleButton toggle
                    ? toggle.IsChecked == true
                    : !_calendarShowCobros;

            ApplicationData.Current.LocalSettings.Values[
                LS_CalendarShowCobros] = _calendarShowCobros;

            _calendarCobroOverlayCache.Clear();
            _calendarCobroCacheIndexVersion =
                App.LocalIndex.Version;

            UpdateCalendarCobrosToggleVisual();

            if (_calendarShowCobros)
            {
                // Primera activación después de actualizar ANFETA: reconstruye
                // únicamente la base Cobrar y pagar para corregir filas viejas
                // que todavía conserven una fecha anterior en el índice.
                await EnsureCobrosCalendarIndexMappingAsync();

                _calendarCobroOverlayCache.Clear();
                _calendarCobroCacheIndexVersion =
                    App.LocalIndex.Version;
            }

            if (_calendarViewActive)
            {
                RefreshCalendarExternalOverlaysIfNeeded(
                    force: true);

                StatusText.Text =
                    _calendarShowCobros
                        ? $"Estado: BdCOBRAR visible ✅ ({GetCalendarCobroItems(_calendarSelectedDate).Count} evento(s) con hora)"
                        : "Estado: BdCOBRAR oculto ✅";
            }
        }

