        private void CalendarQuickTemplate_Click(
            object sender,
            RoutedEventArgs e)
        {
            if (sender is not FrameworkElement anchor)
                return;

            var flyout = new MenuFlyout();

            foreach (var template in CalendarQuickTemplates)
            {
                var item = new MenuFlyoutItem
                {
                    Text = $"⚡ {template.Label}",
                    Tag = template
                };

                item.Click += async (_, __) =>
                {
                    await ShowCalendarQuickTemplateCatalogAsync(
                        template,
                        forceRefresh: false);
                };

                flyout.Items.Add(item);
            }

            flyout.Items.Add(new MenuFlyoutSeparator());

            var sourceItem = new MenuFlyoutItem
            {
                Text = "↗ Abrir Asignación PLANTILLAS"
            };

            sourceItem.Click += async (_, __) =>
            {
                await OpenNotionPageWithFallbackAsync(
                    CalendarTemplateHubUrl,
                    desktopSuccessStatus: "Plantillas abiertas en Notion Desktop",
                    browserSuccessStatus: "Plantillas abiertas en el navegador",
                    failureStatus: "No se pudo abrir Asignación PLANTILLAS",
                    invalidUrlStatus: "La vista de plantillas no tiene una URL válida");
            };

            flyout.Items.Add(sourceItem);
            flyout.ShowAt(anchor);
        }

        private static bool CalendarQuickTemplateTitleMatchesCategory(
            string title,
            CalendarQuickTemplateDefinition template)
        {
            if (template == null ||
                string.IsNullOrWhiteSpace(title))
            {
                return false;
            }

            var normalized =
                $" {Regex.Replace(
                    title.ToLowerInvariant(),
                    @"\s+",
                    " ")} ";

            return template.ProjectToken.ToLowerInvariant() switch
            {
                "wwebs" =>
                    Regex.IsMatch(
                        normalized,
                        @"(?<![\p{L}\p{Nd}_])(?:wwebs|webs|web)(?![\p{L}\p{Nd}_])",
                        RegexOptions.IgnoreCase |
                        RegexOptions.CultureInvariant),

                "sseo" =>
                    Regex.IsMatch(
                        normalized,
                        @"(?<![\p{L}\p{Nd}_])(?:sseo|seo)(?![\p{L}\p{Nd}_])",
                        RegexOptions.IgnoreCase |
                        RegexOptions.CultureInvariant),

                "aads" =>
                    Regex.IsMatch(
                        normalized,
                        @"(?<![\p{L}\p{Nd}_])(?:aads|ads)(?![\p{L}\p{Nd}_])",
                        RegexOptions.IgnoreCase |
                        RegexOptions.CultureInvariant),

                "ccobr" =>
                    Regex.IsMatch(
                        normalized,
                        @"(?<![\p{L}\p{Nd}_])(?:ccobr|cobro|cobros)(?![\p{L}\p{Nd}_])",
                        RegexOptions.IgnoreCase |
                        RegexOptions.CultureInvariant),

                "bbibl" =>
                    Regex.IsMatch(
                        normalized,
                        @"(?<![\p{L}\p{Nd}_])(?:bbibl|bibl|biblioteca|bibliotecas)(?![\p{L}\p{Nd}_])",
                        RegexOptions.IgnoreCase |
                        RegexOptions.CultureInvariant),

                _ =>
                    normalized.Contains(
                        template.ProjectToken,
                        StringComparison.OrdinalIgnoreCase)
            };
        }

        private async Task ShowCalendarQuickTemplateCatalogAsync(
            CalendarQuickTemplateDefinition template,
            bool forceRefresh,
            CalendarQuickCreationSeed? seed = null)
        {
            if (template == null)
                return;

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return;
            }

            IReadOnlyList<NotionQuickTemplateItem> templates;

            var progress =
                new Progress<string>(
                    message =>
                    {
                        StatusText.Text =
                            $"Estado: {template.Label} · {message}";
                    });

            try
            {
                ShowLoadingState(
                    forceRefresh
                        ? $"Estado: Actualizando view {template.Label}…"
                        : $"Estado: Abriendo view {template.Label}…",
                    "Catálogo Plantilla Fase1 · solo la view elegida");

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromSeconds(24));

                templates =
                    await _calendarTemplateCatalogService
                        .GetTemplatesForViewAsync(
                            token,
                            template.SourceUrl,
                            template.ProjectToken,
                            forceRefresh,
                            progress,
                            cts.Token);
            }
            catch (OperationCanceledException)
            {
                var cached =
                    await _calendarTemplateCatalogService
                        .TryGetCachedForViewAsync(
                            template.SourceUrl);

                if (cached.Count == 0)
                {
                    StatusText.Text =
                        $"Estado: {template.Label} tardó demasiado. " +
                        "Se canceló sin consultar Revisiones completa.";
                    return;
                }

                templates = cached;

                StatusText.Text =
                    $"Estado: Notion tardó · usando catálogo local {template.Label} ✅";
            }
            catch (Exception ex)
            {
                var cached =
                    await _calendarTemplateCatalogService
                        .TryGetCachedForViewAsync(
                            template.SourceUrl);

                if (cached.Count == 0)
                {
                    StatusText.Text =
                        $"Estado: {template.Label} → {ex.Message}";
                    return;
                }

                templates = cached;

                StatusText.Text =
                    $"Estado: No se pudo refrescar {template.Label} · usando caché ✅";
            }
            finally
            {
                HideLoadingState();
            }

            if (templates.Count == 0)
            {
                var emptyDialog =
                    new ContentDialog
                    {
                        XamlRoot = XamlRoot,
                        Title =
                            $"Plantillas · {template.Label}",
                        Content =
                            $"La view {template.Label} respondió correctamente, " +
                            "pero su filtro no devolvió páginas.",
                        CloseButtonText = "Cerrar"
                    };

                await emptyDialog.ShowAsync();
                return;
            }

            // Orden visual estable por 0.30 / 1.00 / 2.03...
            var orderedTemplates =
                templates
                    .OrderBy(item =>
                    {
                        var raw =
                            ExtractCalendarQuickTemplateOrder(
                                item.Title);

                        return decimal.TryParse(
                            raw,
                            NumberStyles.AllowDecimalPoint,
                            CultureInfo.InvariantCulture,
                            out var parsed)
                                ? parsed
                                : decimal.MaxValue;
                    })
                    .ThenBy(item =>
                        item.Title,
                        StringComparer.OrdinalIgnoreCase)
                    .ToList();

            StatusText.Text =
                $"Estado: Plantillas {template.Label} listas ✅ · {orderedTemplates.Count}";

            var rootWidth =
                XamlRoot == null
                    ? 1200d
                    : XamlRoot.Size.Width;

            var rootHeight =
                XamlRoot == null
                    ? 800d
                    : XamlRoot.Size.Height;

            // El ContentDialog de WinUI conserva un máximo interno relativamente
            // angosto aunque MinWidth/MaxWidth se asignen directamente. Calculamos
            // primero el ancho REAL que queremos usar y más abajo sobrescribimos
            // también ContentDialogMinWidth/ContentDialogMaxWidth.
            var dialogWidth =
                Math.Max(
                    560d,
                    Math.Min(
                        1100d,
                        rootWidth - 64d));

            var contentWidth =
                Math.Max(
                    500d,
                    dialogWidth - 44d);

            var list =
                new ListView
                {
                    SelectionMode =
                        ListViewSelectionMode.Multiple,
                    MaxHeight =
                        Math.Clamp(
                            rootHeight - 330d,
                            300d,
                            520d),
                    MinHeight = 260,
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            foreach (var sourceTemplate in orderedTemplates)
            {
                var order =
                    ExtractCalendarQuickTemplateOrder(
                        sourceTemplate.Title);

                var cleanTitle =
                    CleanCalendarQuickTemplateActivityTitle(
                        sourceTemplate.Title,
                        template.ProjectToken);

                var displayTitle =
                    string.IsNullOrWhiteSpace(order)
                        ? cleanTitle
                        : $"{order} · {cleanTitle}";

                var itemContent =
                    new StackPanel
                    {
                        Spacing = 2,
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch,
                        Width =
                            Math.Max(
                                440d,
                                contentWidth - 58d),
                        MaxWidth =
                            Math.Max(
                                440d,
                                contentWidth - 58d),
                        Children =
                        {
                            new TextBlock
                            {
                                Text = displayTitle,
                                FontWeight =
                                    Microsoft.UI.Text
                                        .FontWeights.SemiBold,
                                TextWrapping =
                                    TextWrapping.Wrap,
                                TextTrimming =
                                    TextTrimming.CharacterEllipsis,
                                MaxLines = 2,
                                MinWidth = 0
                            },
                            new TextBlock
                            {
                                Text = sourceTemplate.Title,
                                FontSize = 10.5,
                                Opacity = 0.55,
                                TextWrapping =
                                    TextWrapping.NoWrap,
                                TextTrimming =
                                    TextTrimming.CharacterEllipsis,
                                MaxLines = 1,
                                MinWidth = 0
                            }
                        }
                    };

                list.Items.Add(
                    new ListViewItem
                    {
                        Content = itemContent,
                        Tag = sourceTemplate,
                        HorizontalContentAlignment =
                            HorizontalAlignment.Stretch
                    });
            }

            var selectedCountText =
                new TextBlock
                {
                    Text = "0 seleccionadas",
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    Opacity = 0.84
                };

            var selectAllButton =
                new Button
                {
                    Content = "☑ Seleccionar todas",
                    Padding =
                        new Thickness(
                            10, 5, 10, 5)
                };

            var clearButton =
                new Button
                {
                    Content = "☐ Limpiar",
                    Padding =
                        new Thickness(
                            10, 5, 10, 5)
                };

            var individualButton =
                new Button
                {
                    Content = "Crear solo esta",
                    IsEnabled = false,
                    Padding =
                        new Thickness(
                            10, 5, 10, 5)
                };

            ContentDialog? dialog =
                null;

            void UpdateSelectionUi()
            {
                var count =
                    list.SelectedItems.Count;

                selectedCountText.Text =
                    count == 1
                        ? "1 seleccionada"
                        : $"{count} seleccionadas";

                individualButton.IsEnabled =
                    count == 1;

                if (dialog != null)
                {
                    dialog.IsPrimaryButtonEnabled =
                        count > 0;

                    dialog.PrimaryButtonText =
                        count > 0
                            ? $"Continuar con {count}"
                            : "Selecciona plantillas";
                }
            }

            list.SelectionChanged +=
                (_, __) =>
                    UpdateSelectionUi();

            selectAllButton.Click +=
                (_, __) =>
                {
                    list.SelectAll();
                    UpdateSelectionUi();
                };

            clearButton.Click +=
                (_, __) =>
                {
                    list.SelectedItems.Clear();
                    UpdateSelectionUi();
                };

            var sourceButton =
                new Button
                {
                    Content =
                        $"↗ Abrir view {template.Label}",
                    HorizontalAlignment =
                        HorizontalAlignment.Left
                };

            sourceButton.Click += async (_, __) =>
            {
                await OpenNotionPageWithFallbackAsync(
                    template.SourceUrl,
                    desktopSuccessStatus:
                        $"Vista {template.Label} abierta en Notion Desktop",
                    browserSuccessStatus:
                        $"Vista {template.Label} abierta en navegador",
                    failureStatus:
                        $"No se pudo abrir la vista {template.Label}",
                    invalidUrlStatus:
                        "La vista no tiene URL válida");
            };

            individualButton.Click += async (_, __) =>
            {
                if (list.SelectedItems.Count != 1 ||
                    list.SelectedItems[0] is not
                        ListViewItem selectedItem ||
                    selectedItem.Tag is not
                        NotionQuickTemplateItem selectedTemplate)
                {
                    return;
                }

                dialog?.Hide();

                await ShowCalendarQuickTemplateDialogAsync(
                    template,
                    selectedTemplate,
                    seed);
            };

            var selectionBar =
                new Grid
                {
                    ColumnSpacing = 8
                };

            selectionBar.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            selectionBar.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            selectionBar.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });

            selectionBar.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            Grid.SetColumn(
                selectAllButton,
                0);

            Grid.SetColumn(
                clearButton,
                1);

            Grid.SetColumn(
                selectedCountText,
                2);

            Grid.SetColumn(
                individualButton,
                3);

            selectionBar.Children.Add(
                selectAllButton);

            selectionBar.Children.Add(
                clearButton);

            selectionBar.Children.Add(
                selectedCountText);

            selectionBar.Children.Add(
                individualButton);

            ScrollViewer.SetHorizontalScrollBarVisibility(
                list,
                ScrollBarVisibility.Disabled);

            var panel =
                new StackPanel
                {
                    Width = contentWidth,
                    MinWidth =
                        Math.Min(
                            500d,
                            contentWidth),
                    MaxWidth = contentWidth,
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch,
                    Spacing = 10,
                    Children =
                    {
                        new Border
                        {
                            Padding =
                                new Thickness(
                                    10, 8, 10, 8),
                            CornerRadius =
                                new CornerRadius(7),
                            Background =
                                new SolidColorBrush(
                                    Color.FromArgb(
                                        26, 56, 189, 248)),
                            BorderBrush =
                                new SolidColorBrush(
                                    Color.FromArgb(
                                        70, 56, 189, 248)),
                            BorderThickness =
                                new Thickness(1),
                            Child =
                                new TextBlock
                                {
                                    Text =
                                        $"Plantilla Fase1 · {template.Label}. " +
                                        "Selecciona todo el proyecto o quita únicamente " +
                                        "las actividades que no apliquen. Cada copia conserva SU BODY.",
                                    TextWrapping =
                                        TextWrapping.Wrap
                                }
                        },
                        selectionBar,
                        list,
                        sourceButton
                    }
                };

            dialog =
                new ContentDialog
                {
                    XamlRoot = XamlRoot,
                    Title =
                        $"⚡ Plantillas masivas · {template.Label}",
                    Content = panel,
                    MinWidth = dialogWidth,
                    MaxWidth = dialogWidth,
                    PrimaryButtonText =
                        "Selecciona plantillas",
                    SecondaryButtonText =
                        "↻ Actualizar esta view",
                    CloseButtonText =
                        "Cancelar",
                    IsPrimaryButtonEnabled = false,
                    DefaultButton =
                        ContentDialogButton.Primary
                };

            // IMPORTANTE: MinWidth/MaxWidth del ContentDialog no bastan por sí
            // solos en WinUI. Estos recursos locales eliminan el tope visual
            // interno que estaba comprimiendo la barra y cortando los textos.
            dialog.Resources["ContentDialogMinWidth"] =
                dialogWidth;

            dialog.Resources["ContentDialogMaxWidth"] =
                dialogWidth;

            // John pidió poder seleccionar todo y luego quitar excepciones.
            // Dejamos TODO seleccionado al abrir para que el flujo masivo sea
            // de "quitar lo que no aplica", no de marcar 30 filas una por una.
            list.SelectAll();
            UpdateSelectionUi();

            var result =
                await dialog.ShowAsync();

            if (result ==
                ContentDialogResult.Secondary)
            {
                await ShowCalendarQuickTemplateCatalogAsync(
                    template,
                    forceRefresh: true,
                    seed);

                return;
            }

            if (result !=
                    ContentDialogResult.Primary)
            {
                return;
            }

            var selectedTemplates =
                list.SelectedItems
                    .OfType<ListViewItem>()
                    .Select(item =>
                        item.Tag as NotionQuickTemplateItem)
                    .Where(item =>
                        item != null)
                    .Cast<NotionQuickTemplateItem>()
                    .GroupBy(
                        item => item.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group =>
                        group.First())
                    .OrderBy(item =>
                    {
                        var raw =
                            ExtractCalendarQuickTemplateOrder(
                                item.Title);

                        return decimal.TryParse(
                            raw,
                            NumberStyles.AllowDecimalPoint,
                            CultureInfo.InvariantCulture,
                            out var parsed)
                                ? parsed
                                : decimal.MaxValue;
                    })
                    .ThenBy(item =>
                        item.Title,
                        StringComparer.OrdinalIgnoreCase)
                    .ToList();

            if (selectedTemplates.Count == 0)
                return;

            // Una plantilla conserva exactamente el flujo individual conocido.
            if (selectedTemplates.Count == 1)
            {
                await ShowCalendarQuickTemplateDialogAsync(
                    template,
                    selectedTemplates[0],
                    seed);

                return;
            }

            await ShowCalendarQuickTemplateBatchDialogAsync(
                template,
                selectedTemplates,
                seed);
        }

        private static string ExtractCalendarQuickTemplateOrder(
            string title)
        {
            var match = Regex.Match(
                title ?? string.Empty,
                @"(?<!\d)(?<order>\d{1,3}\.\d{1,3})(?!\d)",
                RegexOptions.CultureInvariant);

            return match.Success
                ? match.Groups["order"].Value
                : string.Empty;
        }

        private static string CleanCalendarQuickTemplateActivityTitle(
            string rawTitle,
            string projectToken)
        {
            var value = Regex.Replace(
                (rawTitle ?? string.Empty).Trim(),
                @"\s+",
                " ");

            if (string.IsNullOrWhiteSpace(value))
                return "Actividad desde plantilla";

            value = Regex.Replace(
                value,
                @"(?<![\p{L}\p{Nd}_])(?:a?prtuzrevision|sprtuzrevision|rtuzrevision|zrevision)(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            if (!string.IsNullOrWhiteSpace(projectToken))
            {
                value = Regex.Replace(
                    value,
                    $@"(?<![\p{{L}}\p{{Nd}}_]){Regex.Escape(projectToken)}(?![\p{{L}}\p{{Nd}}_])",
                    " ",
                    RegexOptions.IgnoreCase |
                    RegexOptions.CultureInvariant);
            }

            value = Regex.Replace(
                value,
                @"\(\s*\d{2,4}[A-ZÁÉÍÓÚÑ]{0,12}\s*\)",
                " ",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            value = Regex.Replace(
                value,
                @"(?<!\d)\d{1,3}\.\d{1,3}(?!\d)",
                " ",
                RegexOptions.CultureInvariant);

            value = Regex.Replace(
                value,
                @"(?<![\p{L}\p{Nd}_])(?:n-neft|e-emma|a-andr|k-karl|b-bria|g-gena|j-john|i-isai|s-sote|a-acal|nneft|eemma|aandr|kkarl|bbria|ggena|jjohn|iisaia|iisai|eedua|aacal)(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            value = Regex.Replace(
                value,
                @"(?<![\w@])(?:https?://)?(?:www\.)?(?:[a-z0-9-]+\.)+(?:com\.mx|org\.mx|gob\.mx|edu\.mx|net\.mx|com|mx|org|net|io|co|app|dev)(?![\w])",
                " ",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            value = Regex.Replace(
                value,
                @"(?<![\p{L}\p{Nd}_])(?:ENER|FEBR|MARZ|ABRI|MAYO|JUNI|JULI|AGOS|SEPT|OCTU|NOVI|DICI)(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            value = Regex.Replace(
                value,
                @"\s+",
                " ").Trim(' ', '-', '·', '|');

            return string.IsNullOrWhiteSpace(value)
                ? "Actividad desde plantilla"
                : value;
        }

        private string BuildCalendarQuickTemplateFinalTitle(
            CalendarQuickTemplateDefinition template,
            DateTime selectedDate,
            string orderToken,
            string description,
            string domain,
            string personTag)
        {
            var monthTag =
                BuildCalendarProjectMonthKey(
                    selectedDate.Date);

            var titleParts = new[]
            {
                "prtuzREVISION",
                template.ProjectToken,
                $"({monthTag})",
                orderToken,
                description,
                domain,
                personTag
            };

            return Regex.Replace(
                string.Join(
                    " ",
                    titleParts.Where(value =>
                        !string.IsNullOrWhiteSpace(value))),
                @"\s+",
                " ").Trim();
        }


        private async Task ShowCalendarQuickTemplateBatchDialogAsync(
            CalendarQuickTemplateDefinition template,
            IReadOnlyList<NotionQuickTemplateItem> selectedTemplates,
            CalendarQuickCreationSeed? seed = null)
        {
            if (template == null ||
                selectedTemplates == null ||
                selectedTemplates.Count == 0)
            {
                return;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return;
            }

            var rootWidth =
                XamlRoot == null
                    ? 1200d
                    : XamlRoot.Size.Width;

            var rootHeight =
                XamlRoot == null
                    ? 800d
                    : XamlRoot.Size.Height;

            var dialogWidth =
                Math.Max(
                    620d,
                    Math.Min(
                        1040d,
                        rootWidth - 64d));

            var contentWidth =
                Math.Max(
                    560d,
                    dialogWidth - 44d);

            var contentMaxHeight =
                Math.Clamp(
                    rootHeight - 230d,
                    440d,
                    700d);

            var criteria =
                _calendarActivityPreviewLastCriteria ??
                _calendarProjectPreviewCriteria;

            var domainBox =
                new TextBox
                {
                    Header = "Dominio / proyecto",
                    PlaceholderText = "ej. proyecto.com",
                    Text = criteria?.Domain ?? string.Empty,
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            // IMPORTANTE: responsable EN BLANCO por defecto.
            // No se hereda usuario actual.
            var personCombo =
                new ComboBox
                {
                    Header = "Responsable (opcional)",
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            personCombo.Items.Add(
                new ComboBoxItem
                {
                    Content =
                        "— Sin asignar —",
                    Tag =
                        string.Empty
                });

            foreach (var candidatePerson in
                     ActiveCalendarPeople.Where(person =>
                         !string.Equals(
                             person,
                             "Sin asignar",
                             StringComparison.OrdinalIgnoreCase)))
            {
                personCombo.Items.Add(
                    new ComboBoxItem
                    {
                        Content =
                            candidatePerson,
                        Tag =
                            candidatePerson
                    });
            }

            if (seed != null)
            {
                SelectCalendarQuickCreationPerson(
                    personCombo,
                    seed.Person);
            }
            else
            {
                personCombo.SelectedIndex = 0;
            }

            var datePicker =
                new DatePicker
                {
                    Header = "Fecha",
                    Date =
                        new DateTimeOffset(
                            DateTime.SpecifyKind(
                                seed?.Start.Date ??
                                    _calendarSelectedDate.Date,
                                DateTimeKind.Local)),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            var defaultStart =
                seed?.Start ??
                _calendarSelectedDate.Date.AddHours(10);

            if (seed == null &&
                _calendarSelectedDate.Date ==
                    DateTime.Today)
            {
                var now =
                    RoundOneClickStartUpToQuarterHour(
                        DateTime.Now);

                if (now.Hour >= CalendarStartHour &&
                    now.Hour < CalendarEndHour)
                {
                    defaultStart = now;
                }
            }

            var timePicker =
                new TimePicker
                {
                    Header = "Hora base",
                    ClockIdentifier =
                        "24HourClock",
                    MinuteIncrement = 5,
                    Time =
                        defaultStart.TimeOfDay,
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            var durationCombo =
                new ComboBox
                {
                    Header =
                        "Duración por actividad",
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            var durations =
                new[]
                {
                    15, 30, 45, 60, 90, 120
                };

            foreach (var minutes in durations)
            {
                durationCombo.Items.Add(
                    new ComboBoxItem
                    {
                        Content =
                            minutes < 60
                                ? $"{minutes} min"
                                : minutes % 60 == 0
                                    ? $"{minutes / 60} h"
                                    : $"{minutes / 60} h {minutes % 60} min",
                        Tag = minutes
                    });
            }

            var defaultDurationIndex =
                Array.IndexOf(
                    durations,
                    template.DefaultDurationMinutes);

            durationCombo.SelectedIndex =
                defaultDurationIndex >= 0
                    ? defaultDurationIndex
                    : 3;

            var sequentialCheck =
                new CheckBox
                {
                    Content =
                        "Distribuir una detrás de otra desde la hora base",
                    IsChecked = false
                };

            ToolTipService.SetToolTip(
                sequentialCheck,
                "Desactivado: todas nacen con el mismo horario base para poder acomodarlas después con One Click.");

            var summaryText =
                new TextBlock
                {
                    Text =
                        $"{selectedTemplates.Count} actividades seleccionadas",
                    FontSize = 14,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold
                };

            var previewText =
                new TextBlock
                {
                    TextWrapping =
                        TextWrapping.Wrap,
                    TextTrimming =
                        TextTrimming.CharacterEllipsis,
                    MaxLines = 9,
                    MinWidth = 0,
                    FontSize = 11.5
                };

            string GetSelectedPersonTag()
            {
                if (personCombo.SelectedItem is not
                        ComboBoxItem personItem)
                {
                    return string.Empty;
                }

                var raw =
                    (personItem.Tag?.ToString() ??
                     string.Empty).Trim();

                if (string.IsNullOrWhiteSpace(raw))
                    return string.Empty;

                return GetCalendarMessageRecipientTag(
                    NormalizeCalendarPerson(raw));
            }

            void UpdateBatchPreview()
            {
                var domain =
                    NormalizeCalendarProjectDomain(
                        domainBox.Text);

                var selectedDate =
                    datePicker.Date
                        .LocalDateTime
                        .Date;

                var personTag =
                    GetSelectedPersonTag();

                var lines =
                    selectedTemplates
                        .Take(7)
                        .Select(source =>
                        {
                            var order =
                                ExtractCalendarQuickTemplateOrder(
                                    source.Title);

                            var activity =
                                CleanCalendarQuickTemplateActivityTitle(
                                    source.Title,
                                    template.ProjectToken);

                            return BuildCalendarQuickTemplateFinalTitle(
                                template,
                                selectedDate,
                                order,
                                activity,
                                domain,
                                personTag);
                        })
                        .ToList();

                if (selectedTemplates.Count > lines.Count)
                {
                    lines.Add(
                        $"… +{selectedTemplates.Count - lines.Count} actividad(es)");
                }

                previewText.Text =
                    string.Join(
                        "\n",
                        lines);
            }

            domainBox.TextChanged +=
                (_, __) =>
                    UpdateBatchPreview();

            personCombo.SelectionChanged +=
                (_, __) =>
                    UpdateBatchPreview();

            datePicker.DateChanged +=
                (_, __) =>
                    UpdateBatchPreview();

            var fields =
                new Grid
                {
                    ColumnSpacing = 10
                };

            fields.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1.4,
                            GridUnitType.Star)
                });

            fields.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            Grid.SetColumn(
                domainBox,
                0);

            Grid.SetColumn(
                personCombo,
                1);

            fields.Children.Add(
                domainBox);

            fields.Children.Add(
                personCombo);

            var scheduleRow =
                new Grid
                {
                    ColumnSpacing = 10
                };

            scheduleRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            scheduleRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            scheduleRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            Grid.SetColumn(
                datePicker,
                0);

            Grid.SetColumn(
                timePicker,
                1);

            Grid.SetColumn(
                durationCombo,
                2);

            scheduleRow.Children.Add(
                datePicker);

            scheduleRow.Children.Add(
                timePicker);

            scheduleRow.Children.Add(
                durationCombo);

            var previewBorder =
                new Border
                {
                    Padding =
                        new Thickness(
                            10, 8, 10, 8),
                    CornerRadius =
                        new CornerRadius(7),
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                24, 56, 189, 248)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                68, 56, 189, 248)),
                    BorderThickness =
                        new Thickness(1),
                    Child =
                        new StackPanel
                        {
                            Spacing = 5,
                            Children =
                            {
                                new TextBlock
                                {
                                    Text =
                                        "Vista previa · primeras actividades",
                                    FontSize = 10.5,
                                    Opacity = 0.70
                                },
                                previewText
                            }
                        }
                };

            var notice =
                new Border
                {
                    Padding =
                        new Thickness(
                            10, 8, 10, 8),
                    CornerRadius =
                        new CornerRadius(7),
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                34, 34, 197, 94)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                80, 34, 197, 94)),
                    BorderThickness =
                        new Thickness(1),
                    Child =
                        new TextBlock
                        {
                            Text =
                                "📋 Cada actividad se crea desde SU Plantilla Fase1 real. " +
                                "Se conserva BODY, checklist, toggles y bloques del template. " +
                                "El responsable queda vacío si no eliges uno.",
                            TextWrapping =
                                TextWrapping.Wrap,
                            FontSize = 11,
                            Opacity = 0.92
                        }
                };

            var panel =
                new StackPanel
                {
                    Width = contentWidth,
                    MinWidth =
                        Math.Min(
                            560d,
                            contentWidth),
                    MaxWidth =
                        contentWidth,
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch,
                    Spacing = 10,
                    Children =
                    {
                        summaryText,
                        notice,
                        fields,
                        scheduleRow,
                        sequentialCheck,
                        previewBorder
                    }
                };

            UpdateBatchPreview();

            var contentScroll =
                new ScrollViewer
                {
                    Content = panel,
                    MaxHeight =
                        contentMaxHeight,
                    HorizontalScrollBarVisibility =
                        ScrollBarVisibility.Disabled,
                    HorizontalScrollMode =
                        ScrollMode.Disabled,
                    VerticalScrollBarVisibility =
                        ScrollBarVisibility.Auto,
                    VerticalScrollMode =
                        ScrollMode.Auto
                };

            var dialog =
                new ContentDialog
                {
                    XamlRoot = XamlRoot,
                    Title =
                        $"Crear proyecto desde Plantilla Fase1 · {template.Label}",
                    Content =
                        contentScroll,
                    MinWidth = dialogWidth,
                    MaxWidth = dialogWidth,
                    PrimaryButtonText =
                        $"Crear {selectedTemplates.Count} actividades",
                    CloseButtonText =
                        "Cancelar",
                    DefaultButton =
                        ContentDialogButton.Primary
                };

            dialog.Resources["ContentDialogMinWidth"] =
                dialogWidth;

            dialog.Resources["ContentDialogMaxWidth"] =
                dialogWidth;

            var result =
                await dialog.ShowAsync();

            if (result !=
                ContentDialogResult.Primary)
            {
                return;
            }

            var domain =
                NormalizeCalendarProjectDomain(
                    domainBox.Text);

            if (string.IsNullOrWhiteSpace(domain))
            {
                StatusText.Text =
                    "Estado: Falta el dominio/proyecto para crear el lote.";
                return;
            }

            var selectedDate =
                datePicker.Date
                    .LocalDateTime
                    .Date;

            var baseStart =
                selectedDate.Add(
                    timePicker.Time);

            var duration =
                durationCombo.SelectedItem is
                    ComboBoxItem durationItem &&
                durationItem.Tag is int selectedMinutes
                    ? selectedMinutes
                    : template.DefaultDurationMinutes;

            duration =
                Math.Max(
                    15,
                    duration);

            var personTag =
                GetSelectedPersonTag();

            var distributeSequentially =
                sequentialCheck.IsChecked == true;

            var requests =
                new List<NotionQuickTemplateBatchRequest>(
                    selectedTemplates.Count);

            var runningStart =
                baseStart;

            foreach (var source in selectedTemplates)
            {
                var order =
                    ExtractCalendarQuickTemplateOrder(
                        source.Title);

                var activity =
                    CleanCalendarQuickTemplateActivityTitle(
                        source.Title,
                        template.ProjectToken);

                var start =
                    distributeSequentially
                        ? runningStart
                        : baseStart;

                var end =
                    start.AddMinutes(
                        duration);

                var title =
                    BuildCalendarQuickTemplateFinalTitle(
                        template,
                        selectedDate,
                        order,
                        activity,
                        domain,
                        personTag);

                requests.Add(
                    new NotionQuickTemplateBatchRequest(
                        source.PageId,
                        title,
                        start,
                        end));

                if (distributeSequentially)
                {
                    runningStart =
                        end;
                }
            }

            var refreshAnchor =
                DateTimeOffset.UtcNow
                    .AddSeconds(-10);

            try
            {
                ShowLoadingState(
                    $"Estado: Creando proyecto {template.Label}…",
                    $"0/{requests.Count} · cada actividad conserva su BODY");

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(
                            Math.Max(
                                5,
                                requests.Count)));

                var batchProgress =
                    new Progress<NotionQuickTemplateBatchProgress>(
                        report =>
                        {
                            var clean =
                                Regex.Replace(
                                    report.Title ?? string.Empty,
                                    @"\s+",
                                    " ").Trim();

                            if (clean.Length > 72)
                            {
                                clean =
                                    clean.Substring(
                                        0,
                                        69) +
                                    "…";
                            }

                            StatusText.Text =
                                $"Estado: Plantillas {template.Label} · " +
                                $"creando {report.Current}/{report.Total}";

                            UpdateLoadingState(
                                $"Estado: Creando {report.Current}/{report.Total}",
                                clean);
                        });

                var batchResults =
                    await _calendarQuickActivityService
                        .CreateBatchFromTemplatesAsync(
                            token,
                            NotionFilePageService.RevisionesDataSourceId,
                            requests,
                            batchProgress,
                            cts.Token);

                var succeeded =
                    batchResults
                        .Where(item =>
                            item.Success)
                        .ToList();

                var failed =
                    batchResults
                        .Where(item =>
                            !item.Success)
                        .ToList();

                var bodyPending =
                    succeeded.Count(item =>
                        !item.BodyApplied);

                // REFRESH UNA SOLA VEZ AL FINAL.
                try
                {
                    await _notionCalendarService
                        .RefreshChangedSinceAsync(
                            token,
                            refreshAnchor,
                            cts.Token);

                    if (selectedDate ==
                        _calendarSelectedDate.Date)
                    {
                        var current =
                            await _notionCalendarService
                                .TryGetCachedDayAsync(
                                    _calendarSelectedDate,
                                    cts.Token);

                        if (current != null)
                        {
                            _calendarActivities =
                                current;

                            ApplyCachedCalendarReviewFlow(
                                _calendarActivities);

                            DrawCalendarPreservingView(
                                _calendarActivities,
                                force: true);
                        }
                    }
                }
                catch (Exception refreshException)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_BATCH_TEMPLATE_REFRESH] {refreshException}");
                }

                StatusText.Text =
                    failed.Count == 0
                        ? $"Estado: Proyecto {template.Label} creado ✅ · " +
                          $"{succeeded.Count} actividades"
                        : $"Estado: Lote terminado · " +
                          $"{succeeded.Count} creadas · " +
                          $"{failed.Count} con error";

                var resultLines =
                    new List<string>
                    {
                        $"✅ Creadas: {succeeded.Count}",
                        $"❌ Fallidas: {failed.Count}"
                    };

                if (bodyPending > 0)
                {
                    resultLines.Add(
                        $"⏳ BODY aún aplicándose al cerrar la espera: {bodyPending}");
                }

                if (failed.Count > 0)
                {
                    resultLines.Add(string.Empty);
                    resultLines.Add("Fallos:");

                    foreach (var item in failed.Take(8))
                    {
                        var cleanError =
                            Regex.Replace(
                                item.Error ?? string.Empty,
                                @"\s+",
                                " ").Trim();

                        if (cleanError.Length > 150)
                        {
                            cleanError =
                                cleanError.Substring(
                                    0,
                                    147) +
                                "…";
                        }

                        resultLines.Add(
                            $"• {item.Title}\n  {cleanError}");
                    }

                    if (failed.Count > 8)
                    {
                        resultLines.Add(
                            $"• … y {failed.Count - 8} más");
                    }
                }

                var resultDialog =
                    new ContentDialog
                    {
                        XamlRoot = XamlRoot,
                        Title =
                            failed.Count == 0
                                ? "Proyecto creado"
                                : "Lote terminado con incidencias",
                        Content =
                            new ScrollViewer
                            {
                                MaxHeight = 430,
                                VerticalScrollBarVisibility =
                                    ScrollBarVisibility.Auto,
                                Content =
                                    new TextBlock
                                    {
                                        Text =
                                            string.Join(
                                                "\n",
                                                resultLines),
                                        TextWrapping =
                                            TextWrapping.Wrap
                                    }
                            },
                        CloseButtonText =
                            "Cerrar"
                    };

                await resultDialog.ShowAsync();
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: El lote se canceló por tiempo. " +
                    "Revisa Notion antes de volver a crear para no duplicar páginas ya creadas.";
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo completar el lote → {ex.Message}";
            }
            finally
            {
                HideLoadingState();
            }
        }

        private async Task ShowCalendarQuickTemplateDialogAsync(
            CalendarQuickTemplateDefinition template,
            NotionQuickTemplateItem sourceTemplate,
            CalendarQuickCreationSeed? seed = null)
        {
            if (template == null || sourceTemplate == null)
                return;

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return;
            }

            var rootWidth =
                XamlRoot == null
                    ? 1200d
                    : XamlRoot.Size.Width;

            var rootHeight =
                XamlRoot == null
                    ? 800d
                    : XamlRoot.Size.Height;

            var contentWidth =
                Math.Clamp(
                    rootWidth - 300d,
                    500d,
                    660d);

            var contentMaxHeight =
                Math.Clamp(
                    rootHeight - 250d,
                    420d,
                    680d);

            var criteria =
                _calendarActivityPreviewLastCriteria ??
                _calendarProjectPreviewCriteria;

            var parsedOrder =
                ExtractCalendarQuickTemplateOrder(
                    sourceTemplate.Title);

            var parsedActivity =
                CleanCalendarQuickTemplateActivityTitle(
                    sourceTemplate.Title,
                    template.ProjectToken);

            var domainBox = new TextBox
            {
                Header = "Dominio / proyecto",
                PlaceholderText = "ej. anfeta.com",
                Text = criteria?.Domain ?? string.Empty,
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            var orderBox = new TextBox
            {
                Header = "Orden",
                PlaceholderText = "ej. 2.03",
                Text = parsedOrder,
                MaxLength = 12,
                Width = 150,
                HorizontalAlignment = HorizontalAlignment.Left
            };

            var descriptionBox = new TextBox
            {
                Header = "Actividad",
                PlaceholderText = "Nombre de la actividad…",
                Text = parsedActivity,
                AcceptsReturn = true,
                TextWrapping = TextWrapping.Wrap,
                MinHeight = 72,
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            var personCombo = new ComboBox
            {
                Header = "Responsable (opcional)",
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            personCombo.Items.Add(
                new ComboBoxItem
                {
                    Content = "— Sin asignar —",
                    Tag = string.Empty
                });

            foreach (var candidatePerson in ActiveCalendarPeople
                         .Where(candidatePerson =>
                             !string.Equals(
                                 candidatePerson,
                                 "Sin asignar",
                                 StringComparison.OrdinalIgnoreCase)))
            {
                personCombo.Items.Add(
                    new ComboBoxItem
                    {
                        Content = candidatePerson,
                        Tag = candidatePerson
                    });
            }

            // Desde el botón general sigue sin asignarse automáticamente.
            // Desde un hueco sí conserva la columna/persona detectada.
            if (seed != null)
            {
                SelectCalendarQuickCreationPerson(
                    personCombo,
                    seed.Person);
            }
            else
            {
                personCombo.SelectedIndex = 0;
            }

            var datePicker = new DatePicker
            {
                Header = "Fecha",
                Date = new DateTimeOffset(
                    DateTime.SpecifyKind(
                        seed?.Start.Date ??
                            _calendarSelectedDate.Date,
                        DateTimeKind.Local)),
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            var defaultStart =
                seed?.Start ??
                _calendarSelectedDate.Date.AddHours(10);

            if (seed == null &&
                _calendarSelectedDate.Date == DateTime.Today)
            {
                var now = RoundOneClickStartUpToQuarterHour(DateTime.Now);

                if (now.Hour >= CalendarStartHour &&
                    now.Hour < CalendarEndHour)
                {
                    defaultStart = now;
                }
            }

            var timePicker = new TimePicker
            {
                Header = "Hora",
                ClockIdentifier = "24HourClock",
                MinuteIncrement = 5,
                Time = defaultStart.TimeOfDay,
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            var durationCombo = new ComboBox
            {
                Header = "Duración",
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            var durations = new[]
            {
                15, 30, 45, 60, 90, 120, 180
            };

            foreach (var minutes in durations)
            {
                durationCombo.Items.Add(
                    new ComboBoxItem
                    {
                        Content = minutes < 60
                            ? $"{minutes} min"
                            : minutes % 60 == 0
                                ? $"{minutes / 60} h"
                                : $"{minutes / 60} h {minutes % 60} min",
                        Tag = minutes
                    });
            }

            var defaultDurationIndex =
                Array.IndexOf(
                    durations,
                    template.DefaultDurationMinutes);

            durationCombo.SelectedIndex =
                defaultDurationIndex >= 0
                    ? defaultDurationIndex
                    : 3;

            var previewText = new TextBlock
            {
                TextWrapping = TextWrapping.Wrap,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                MaxLines = 4,
                MinWidth = 0,
                FontWeight = Microsoft.UI.Text.FontWeights.SemiBold,
                FontSize = 12
            };

            var previewBorder = new Border
            {
                Padding = new Thickness(10),
                CornerRadius = new CornerRadius(7),
                Background = new SolidColorBrush(
                    Color.FromArgb(26, 56, 189, 248)),
                BorderBrush = new SolidColorBrush(
                    Color.FromArgb(70, 56, 189, 248)),
                BorderThickness = new Thickness(1),
                Child = new StackPanel
                {
                    Spacing = 4,
                    Children =
                    {
                        new TextBlock
                        {
                            Text = "Vista previa del título final",
                            FontSize = 10.5,
                            Opacity = 0.70
                        },
                        previewText
                    }
                }
            };

            void UpdatePreview()
            {
                var previewRawPerson =
                    personCombo.SelectedItem is ComboBoxItem previewPersonItem
                        ? (previewPersonItem.Tag?.ToString() ?? string.Empty)
                        : (personCombo.SelectedItem?.ToString() ?? string.Empty);

                var previewPerson =
                    NormalizeCalendarPerson(
                        previewRawPerson);

                var previewPersonTag =
                    string.IsNullOrWhiteSpace(previewRawPerson)
                        ? string.Empty
                        : GetCalendarMessageRecipientTag(
                            previewPerson);

                var previewDomain =
                    NormalizeCalendarProjectDomain(
                        domainBox.Text);

                var previewDescription = Regex.Replace(
                    (descriptionBox.Text ?? string.Empty).Trim(),
                    @"\s+",
                    " ");

                var previewOrder = Regex.Replace(
                    (orderBox.Text ?? string.Empty).Trim(),
                    @"[^0-9.]",
                    string.Empty);

                previewText.Text =
                    BuildCalendarQuickTemplateFinalTitle(
                        template,
                        datePicker.Date.LocalDateTime.Date,
                        previewOrder,
                        previewDescription,
                        previewDomain,
                        previewPersonTag);
            }

            domainBox.TextChanged += (_, __) => UpdatePreview();
            orderBox.TextChanged += (_, __) => UpdatePreview();
            descriptionBox.TextChanged += (_, __) => UpdatePreview();
            personCombo.SelectionChanged += (_, __) => UpdatePreview();
            datePicker.DateChanged += (_, __) => UpdatePreview();

            var selectedTemplateButton = new Button
            {
                Content = "↗ Abrir plantilla elegida",
                HorizontalAlignment = HorizontalAlignment.Left
            };

            selectedTemplateButton.Click += async (_, __) =>
            {
                var sourceUrl =
                    !string.IsNullOrWhiteSpace(sourceTemplate.PageUrl)
                        ? sourceTemplate.PageUrl
                        : template.SourceUrl;

                await OpenNotionPageWithFallbackAsync(
                    sourceUrl,
                    desktopSuccessStatus: "Plantilla abierta en Notion Desktop",
                    browserSuccessStatus: "Plantilla abierta en el navegador",
                    failureStatus: "No se pudo abrir la plantilla elegida",
                    invalidUrlStatus: "La plantilla no tiene una URL válida");
            };

            var notice = new Border
            {
                Padding = new Thickness(10, 8, 10, 8),
                CornerRadius = new CornerRadius(7),
                Background = new SolidColorBrush(
                    Color.FromArgb(34, 34, 197, 94)),
                BorderBrush = new SolidColorBrush(
                    Color.FromArgb(80, 34, 197, 94)),
                BorderThickness = new Thickness(1),
                Child = new TextBlock
                {
                    Text =
                        "📋 BODY: se copiará siempre desde la plantilla elegida. " +
                        "Notion conservará su checklist, toggles, bloques y contenido; " +
                        "ANFETA solo cambia los datos variables de la nueva copia.",
                    TextWrapping = TextWrapping.Wrap,
                    TextTrimming =
                        TextTrimming.CharacterEllipsis,
                    MaxLines = 4,
                    FontSize = 11,
                    MinWidth = 0,
                    Opacity = 0.90
                }
            };

            var originalTitle = new Border
            {
                Padding = new Thickness(10, 7, 10, 7),
                CornerRadius = new CornerRadius(6),
                Background = new SolidColorBrush(
                    Color.FromArgb(20, 255, 255, 255)),
                Child = new StackPanel
                {
                    Spacing = 3,
                    Children =
                    {
                        new TextBlock
                        {
                            Text = "Plantilla fuente",
                            FontSize = 10.5,
                            Opacity = 0.65
                        },
                        new TextBlock
                        {
                            Text = sourceTemplate.Title,
                            TextWrapping = TextWrapping.Wrap,
                            TextTrimming =
                                TextTrimming.CharacterEllipsis,
                            MaxLines = 3,
                            FontSize = 11.5,
                            MinWidth = 0
                        }
                    }
                }
            };

            var row = new Grid
            {
                ColumnSpacing = 10
            };

            row.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(1, GridUnitType.Star)
                });
            row.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(1, GridUnitType.Star)
                });
            row.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(1, GridUnitType.Star)
                });

            Grid.SetColumn(datePicker, 0);
            Grid.SetColumn(timePicker, 1);
            Grid.SetColumn(durationCombo, 2);

            row.Children.Add(datePicker);
            row.Children.Add(timePicker);
            row.Children.Add(durationCombo);

            var identityRow = new Grid
            {
                ColumnSpacing = 10
            };

            identityRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(1, GridUnitType.Star)
                });
            identityRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            Grid.SetColumn(domainBox, 0);
            Grid.SetColumn(orderBox, 1);

            identityRow.Children.Add(domainBox);
            identityRow.Children.Add(orderBox);

            var panel = new StackPanel
            {
                MinWidth =
                    Math.Min(
                        500d,
                        contentWidth),
                MaxWidth = contentWidth,
                HorizontalAlignment =
                    HorizontalAlignment.Stretch,
                Spacing = 10,
                Children =
                {
                    new TextBlock
                    {
                        Text = $"⚡ {template.Label} · {template.Hint}",
                        FontSize = 15,
                        FontWeight = Microsoft.UI.Text.FontWeights.SemiBold,
                        TextWrapping = TextWrapping.Wrap
                    },
                    originalTitle,
                    notice,
                    identityRow,
                    descriptionBox,
                    personCombo,
                    row,
                    previewBorder,
                    selectedTemplateButton
                }
            };

            UpdatePreview();

            var contentScroll =
                new ScrollViewer
                {
                    Content = panel,
                    MaxHeight = contentMaxHeight,
                    HorizontalScrollBarVisibility =
                        ScrollBarVisibility.Disabled,
                    HorizontalScrollMode =
                        ScrollMode.Disabled,
                    VerticalScrollBarVisibility =
                        ScrollBarVisibility.Auto,
                    VerticalScrollMode =
                        ScrollMode.Auto
                };

            var dialog = new ContentDialog
            {
                XamlRoot = XamlRoot,
                Title = $"Crear desde plantilla · {template.Label}",
                Content = contentScroll,
                MinWidth =
                    Math.Min(
                        540d,
                        contentWidth + 24d),
                MaxWidth =
                    contentWidth + 48d,
                PrimaryButtonText = "Crear copia",
                CloseButtonText = "Cancelar",
                DefaultButton = ContentDialogButton.Primary
            };

            var result = await dialog.ShowAsync();

            if (result != ContentDialogResult.Primary)
                return;

            var domain =
                NormalizeCalendarProjectDomain(
                    domainBox.Text);

            var description = Regex.Replace(
                (descriptionBox.Text ?? string.Empty).Trim(),
                @"\s+",
                " ");

            var rawPerson =
                personCombo.SelectedItem is ComboBoxItem selectedPersonItem
                    ? (selectedPersonItem.Tag?.ToString() ?? string.Empty)
                    : (personCombo.SelectedItem?.ToString() ?? string.Empty);

            var person =
                NormalizeCalendarPerson(
                    rawPerson);

            var personTag =
                string.IsNullOrWhiteSpace(rawPerson)
                    ? string.Empty
                    : GetCalendarMessageRecipientTag(
                        person);

            if (string.IsNullOrWhiteSpace(domain))
            {
                StatusText.Text =
                    "Estado: Falta el dominio/proyecto para crear la actividad.";
                return;
            }

            if (string.IsNullOrWhiteSpace(description))
            {
                StatusText.Text =
                    "Estado: La actividad no puede quedar vacía.";
                return;
            }

            var selectedDate =
                datePicker.Date.LocalDateTime.Date;

            var start =
                selectedDate.Add(
                    timePicker.Time);

            var duration =
                durationCombo.SelectedItem is ComboBoxItem durationItem &&
                durationItem.Tag is int selectedMinutes
                    ? selectedMinutes
                    : template.DefaultDurationMinutes;

            var end =
                start.AddMinutes(
                    Math.Max(15, duration));

            var orderToken = Regex.Replace(
                (orderBox.Text ?? string.Empty).Trim(),
                @"[^0-9.]",
                string.Empty);

            var title =
                BuildCalendarQuickTemplateFinalTitle(
                    template,
                    selectedDate,
                    orderToken,
                    description,
                    domain,
                    personTag);

            try
            {
                ShowLoadingState(
                    $"Estado: Copiando plantilla {template.Label}…",
                    "Notion está aplicando el BODY y los datos finales");

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(3));

                var refreshAnchor =
                    DateTimeOffset.UtcNow.AddSeconds(-8);

                var created =
                    await _calendarQuickActivityService
                        .CreateFromTemplateAsync(
                            token,
                            NotionFilePageService.RevisionesDataSourceId,
                            sourceTemplate.PageId,
                            title,
                            start,
                            end,
                            cts.Token);

                var refreshed = false;

                try
                {
                    refreshed =
                        await _notionCalendarService
                            .RefreshChangedSinceAsync(
                                token,
                                refreshAnchor,
                                cts.Token);

                    if (refreshed &&
                        selectedDate == _calendarSelectedDate.Date)
                    {
                        var current =
                            await _notionCalendarService
                                .TryGetCachedDayAsync(
                                    _calendarSelectedDate,
                                    cts.Token);

                        if (current != null)
                        {
                            _calendarActivities = current;
                            ApplyCachedCalendarReviewFlow(
                                _calendarActivities);
                            DrawCalendarPreservingView(
                                _calendarActivities,
                                force: true);
                        }
                    }
                }
                catch (Exception refreshException)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_QUICK_TEMPLATE_REFRESH] {refreshException}");
                }

                StatusText.Text =
                    created.BodyApplied
                        ? $"Estado: Actividad {template.Label} creada desde plantilla ✅ · BODY copiado"
                        : $"Estado: Actividad {template.Label} creada ✅ · Notion todavía puede estar terminando de aplicar el BODY" +
                          (refreshed
                              ? string.Empty
                              : " · pulsa Actualizar si todavía no aparece");
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: La copia de la plantilla tardó demasiado. " +
                    "Revisa Notion antes de volver a crear para evitar duplicados.";
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo crear desde plantilla → {ex.Message}";
            }
            finally
            {
                HideLoadingState();
            }
        }

        private static bool IsCobrarPagarIndexRow(
            SearchResultRow row)
        {
            if (row == null || row.Source != SearchSource.Notion)
                return false;

            var source =
                NormalizeCalendarSearchText(
                    row.ExternalSourceName);

            var isCobrarPagarSource =
                source.Contains("cobrar", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("pagar", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("cobro", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("pago", StringComparison.OrdinalIgnoreCase);

            if (!isCobrarPagarSource)
                return false;

            return Regex.IsMatch(
                row.DisplayName ?? string.Empty,
                @"(?<![\p{L}\p{Nd}_])(?:sprtuz|prtuz|rtuz|z)?cobrar(?![\p{L}\p{Nd}_])",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static bool TryParseCobroScheduledRange(
            SearchResultRow row,
            out DateTime start,
            out DateTime end)
        {
            start = default;
            end = default;

            var raw = (row?.ScheduledDate ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(raw))
                return false;

            // Solo eventos con hora explícita. Las fechas sin hora no se dibujan.
            if (!Regex.IsMatch(
                    raw,
                    @"(?:T|\s)\d{1,2}:\d{2}",
                    RegexOptions.CultureInvariant))
            {
                return false;
            }

            var separatorIndex = raw.IndexOf(" - ", StringComparison.Ordinal);
            var startRaw = separatorIndex > 0
                ? raw.Substring(0, separatorIndex).Trim()
                : raw;
            var endRaw = separatorIndex > 0
                ? raw.Substring(separatorIndex + 3).Trim()
                : string.Empty;

            if (DateTimeOffset.TryParse(
                    startRaw,
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.AssumeLocal,
                    out var startOffset))
            {
                start = startOffset.LocalDateTime;
            }
            else if (!DateTime.TryParse(
                         startRaw,
                         CultureInfo.InvariantCulture,
                         DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.AssumeLocal,
                         out start))
            {
                return false;
            }

            if (!string.IsNullOrWhiteSpace(endRaw) &&
                DateTimeOffset.TryParse(
                    endRaw,
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.AssumeLocal,
                    out var endOffset))
            {
                end = endOffset.LocalDateTime;
            }
            else if (!string.IsNullOrWhiteSpace(endRaw) &&
                     DateTime.TryParse(
                         endRaw,
                         CultureInfo.InvariantCulture,
                         DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.AssumeLocal,
                         out var endDate))
            {
                end = endDate;
            }
            else
            {
                end = start.AddHours(1);
            }

            if (end <= start)
                end = start.AddHours(1);

            return true;
        }

        private IReadOnlyList<CalendarCobroOverlayItem> GetCalendarCobroItems(
            DateTime day)
        {
            if (!_calendarShowCobros)
                return Array.Empty<CalendarCobroOverlayItem>();

            var indexVersion =
                App.LocalIndex.Version;

            if (_calendarCobroCacheIndexVersion != indexVersion)
            {
                _calendarCobroOverlayCache.Clear();
                _calendarCobroCacheIndexVersion = indexVersion;
            }

            var key = day.Date.ToString(
                "yyyy-MM-dd",
                CultureInfo.InvariantCulture);

            if (_calendarCobroOverlayCache.TryGetValue(key, out var cached))
                return cached;

            var dayStart = day.Date;
            var dayEnd = dayStart.AddDays(1);

            var items =
                App.LocalIndex
                    .GetAll()
                    .Where(IsCobrarPagarIndexRow)
                    .Select(row =>
                    {
                        if (!TryParseCobroScheduledRange(
                                row,
                                out var start,
                                out var end) ||
                            start >= dayEnd || end <= dayStart)
                        {
                            return null;
                        }

                        var title = row.DisplayName?.Trim() ?? string.Empty;
                        var person = GetActiveCalendarPersonFromTitle(title);
                        if (string.IsNullOrWhiteSpace(person))
                            person = "Sin asignar";

                        return new CalendarCobroOverlayItem(
                            row, start, end, person, title);
                    })
                    .Where(item => item != null)
                    .Cast<CalendarCobroOverlayItem>()
                    .OrderBy(item => item.Start)
                    .ThenBy(item => item.Title)
                    .ToList();

            _calendarCobroOverlayCache[key] = items;
            return items;
        }

        private void RefreshCalendarExternalOverlaysIfNeeded(
            bool force = false)
        {
            if (!_calendarViewActive ||
                CalendarCanvas == null)
            {
                return;
            }

            var indexVersion =
                App.LocalIndex.Version;

            if (!force &&
                _calendarExternalOverlayIndexVersion ==
                    indexVersion)
            {
                return;
            }

            // Cobros 2.0 modifica el ancho lógico de las columnas que tienen
            // cobros porque agrega un carril independiente. Por eso, al
            // activar/desactivar Cobros o cambiar el índice, hace falta
            // recalcular el layout completo una sola vez. No es una consulta a
            // Notion: usa los datos/caché ya cargados en memoria.
            if (force || _calendarShowCobros)
            {
                _calendarCobroOverlayCache.Clear();
                _calendarCobroCacheIndexVersion =
                    indexVersion;

                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);

                _calendarExternalOverlayIndexVersion =
                    indexVersion;
                return;
            }

            var removable =
                CalendarCanvas.Children
                    .OfType<FrameworkElement>()
                    .Where(element =>
                        (element is Button button &&
                         button.Tag is MessageViewItem) ||
                        (element.Tag is SearchResultRow row &&
                         IsCobrarPagarIndexRow(row)))
                    .ToList();

            foreach (var element in removable)
                CalendarCanvas.Children.Remove(element);

            _calendarCobroOverlayCache.Clear();
            _calendarCobroCacheIndexVersion = indexVersion;

            var persons =
                _calendarPeopleOrder
                    .Where(person =>
                        _calendarSelectedPeople.Contains(person))
                    .ToList();

            DrawCalendarReminderOverlays(
                CalendarHeaderHeight,
                persons);

            _calendarExternalOverlayIndexVersion =
                indexVersion;
        }

        private async Task OpenCalendarCobroAsync(
            SearchResultRow row)
        {
            if (row == null)
                return;

            await OpenNotionPageWithFallbackAsync(
                !string.IsNullOrWhiteSpace(row.ExternalUrl)
                    ? row.ExternalUrl
                    : row.Target,
                desktopSuccessStatus: "Cobro abierto en Notion Desktop",
                browserSuccessStatus: "Cobro abierto en el navegador",
                failureStatus: "No se pudo abrir el cobro",
                invalidUrlStatus: "El cobro no tiene una URL válida de Notion");
        }

        private sealed record CalendarCobroDisplayInfo(
            string Domain,
            string Concept,
            string Status);

        private static string ExtractCalendarCobroDomainFromText(
            string value)
        {
            var text = (value ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(text))
                return string.Empty;

            var match = Regex.Match(
                text,
                @"(?<![\p{L}\p{Nd}_@])(?:https?://)?(?:www\.)?(?<domain>[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?)+)(?![\p{L}\p{Nd}_])",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            return match.Success
                ? match.Groups["domain"].Value.Trim().ToLowerInvariant()
                : string.Empty;
        }

        private CalendarCobroDisplayInfo BuildCalendarCobroDisplayInfo(
            CalendarCobroOverlayItem cobro)
        {
            var row = cobro.Row;

            var rawTitle =
                (row?.DisplayName ?? cobro.Title ?? string.Empty)
                .Trim();

            // Prioriza el nombre visible y la descripción para no tomar
            // accidentalmente app.notion.com de alguna URL indexada.
            var domain =
                NormalizeCalendarProjectDomain(
                    ExtractCalendarCobroDomainFromText(rawTitle));

            if (string.IsNullOrWhiteSpace(domain))
            {
                domain =
                    NormalizeCalendarProjectDomain(
                        ExtractCalendarCobroDomainFromText(
                            row?.Description ?? string.Empty));
            }

            if (string.IsNullOrWhiteSpace(domain))
            {
                domain =
                    NormalizeCalendarProjectDomain(
                        ExtractCalendarCobroDomainFromText(
                            row?.SearchText ?? string.Empty));
            }

            if (domain.EndsWith(
                    "notion.com",
                    StringComparison.OrdinalIgnoreCase) ||
                domain.EndsWith(
                    "notion.site",
                    StringComparison.OrdinalIgnoreCase))
            {
                domain = string.Empty;
            }

            var concept = rawTitle;

            // Quita únicamente nomenclatura técnica de BdCOBRAR. El título
            // original permanece intacto en Notion y en el tooltip completo.
            concept = Regex.Replace(
                concept,
                @"^\s*\[[^\]]{1,45}\]\s*",
                string.Empty,
                RegexOptions.CultureInvariant);

            concept = Regex.Replace(
                concept,
                @"(?<![\p{L}\p{Nd}_])(?:sprtuz|prtuz|rtuz|z)?cobrar(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            concept = Regex.Replace(
                concept,
                @"(?<!\d)20\d{2}[-/.](?:0?[1-9]|1[0-2])[-/.](?:0?[1-9]|[12]\d|3[01])(?!\d)",
                " ",
                RegexOptions.CultureInvariant);

            concept = Regex.Replace(
                concept,
                @"(?<![\p{L}\p{Nd}_])(?:jjohn|kkarl|iisai|iisaia|ssote|eedua|aacal|aandr|eemma|bbria|ggena|nneft)\d*(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);

            if (!string.IsNullOrWhiteSpace(domain))
            {
                concept = Regex.Replace(
                    concept,
                    $@"(?<![\p{{L}}\p{{Nd}}_])(?:www\.)?{Regex.Escape(domain)}(?![\p{{L}}\p{{Nd}}_])",
                    " ",
                    RegexOptions.IgnoreCase |
                    RegexOptions.CultureInvariant);
            }

            concept = Regex.Replace(
                    concept,
                    @"\s{2,}",
                    " ",
                    RegexOptions.CultureInvariant)
                .Trim(' ', '-', '–', '—', '·', '|', ':');

            // Si el nombre quedó puramente técnico, usa la descripción indexada
            // antes de caer en un texto genérico.
            if (concept.Length < 3)
            {
                concept =
                    (row?.Description ?? string.Empty)
                    .Trim();

                concept = Regex.Replace(
                    concept,
                    @"^\s*\[[^\]]{1,45}\]\s*",
                    string.Empty,
                    RegexOptions.CultureInvariant);

                if (!string.IsNullOrWhiteSpace(domain))
                {
                    concept = Regex.Replace(
                        concept,
                        $@"(?<![\p{{L}}\p{{Nd}}_])(?:www\.)?{Regex.Escape(domain)}(?![\p{{L}}\p{{Nd}}_])",
                        " ",
                        RegexOptions.IgnoreCase |
                        RegexOptions.CultureInvariant);
                }

                concept = Regex.Replace(
                        concept,
                        @"\s{2,}",
                        " ",
                        RegexOptions.CultureInvariant)
                    .Trim(' ', '-', '–', '—', '·', '|', ':');
            }

            if (string.IsNullOrWhiteSpace(concept) ||
                concept.StartsWith(
                    "http",
                    StringComparison.OrdinalIgnoreCase))
            {
                concept = "Pendiente de cobro";
            }

            var status =
                (row?.ProjectUpdateStatus ?? string.Empty)
                .Trim();

            return new CalendarCobroDisplayInfo(
                domain,
                concept,
                status);
        }

        private static string BuildCalendarCobroTooltip(
            CalendarCobroOverlayItem cobro,
            CalendarCobroDisplayInfo display)
        {
            var lines =
                new List<string>
                {
                    $"💰 COBRO · {cobro.Start:dd/MM/yyyy HH:mm}–{cobro.End:HH:mm}"
                };

            if (!string.IsNullOrWhiteSpace(display.Domain))
                lines.Add($"Cliente / dominio: {display.Domain}");

            if (!string.IsNullOrWhiteSpace(display.Concept))
                lines.Add($"Concepto: {display.Concept}");

            if (!string.IsNullOrWhiteSpace(display.Status))
                lines.Add($"Estado: {display.Status}");

            lines.Add("Clic para abrir en Notion");

            return string.Join("\n", lines);
        }

        private void DrawCalendarCobroOverlays(
            double headerHeight,
            IReadOnlyList<string> visiblePersons)
        {
            if (!_calendarShowCobros || !_calendarViewActive ||
                CalendarCanvas == null || visiblePersons == null ||
                visiblePersons.Count == 0)
            {
                return;
            }

            var cobros = GetCalendarCobroItems(_calendarSelectedDate);
            if (cobros.Count == 0)
                return;

            var dayStart =
                _calendarSelectedDate.Date
                    .AddHours(CalendarStartHour);

            var dayEnd =
                _calendarSelectedDate.Date
                    .AddHours(CalendarVisibleEndHour);

            // Cobros usa una columna GLOBAL y movible. Ya no depende de
            // la persona para decidir dónde dibujarse.
            var resolved =
                cobros
                    .Where(cobro =>
                        cobro.End > dayStart &&
                        cobro.Start < dayEnd)
                    .OrderBy(cobro => cobro.Start)
                    .ThenBy(cobro => cobro.Title)
                    .ToList();

            var railWidth =
                GetResolvedCalendarCobroRailWidth();

            var railLeft =
                GetResolvedCalendarCobroRailLeft();

            if (railWidth <= 0 || resolved.Count == 0)
                return;

            var width =
                Math.Max(
                    120,
                    railWidth - 10);

            var nextAvailableTop =
                headerHeight + 4;

            var globalSequence = 0;

            foreach (var cobro in resolved)
            {
                var localStart = cobro.Start;
                var localEnd = cobro.End;

                var visibleStart =
                    localStart < dayStart
                        ? dayStart
                        : localStart;

                var minutesFromStart =
                    (visibleStart - dayStart)
                    .TotalMinutes;

                var desiredTop =
                    headerHeight +
                    minutesFromStart / 60d *
                    CalendarHourHeight +
                    4;

                var durationMinutes =
                    Math.Max(
                        15,
                        (localEnd - localStart)
                        .TotalMinutes);

                var height =
                    Math.Clamp(
                        durationMinutes / 60d *
                        CalendarHourHeight - 6,
                        48,
                        70);

                var top =
                    Math.Max(
                        desiredTop,
                        nextAvailableTop);

                nextAvailableTop =
                    top + height + 4;

                var display =
                    BuildCalendarCobroDisplayInfo(
                        cobro);

                var cardGrid =
                    new Grid
                    {
                        RowSpacing = 1,
                        IsHitTestVisible = false
                    };

                cardGrid.RowDefinitions.Add(
                    new RowDefinition
                    {
                        Height = GridLength.Auto
                    });

                cardGrid.RowDefinitions.Add(
                    new RowDefinition
                    {
                        Height = GridLength.Auto
                    });

                cardGrid.RowDefinitions.Add(
                    new RowDefinition
                    {
                        Height = new GridLength(
                            1,
                            GridUnitType.Star)
                    });

                var headerGrid =
                    new Grid
                    {
                        ColumnSpacing = 4,
                        IsHitTestVisible = false
                    };

                headerGrid.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(
                            1,
                            GridUnitType.Star)
                    });

                headerGrid.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                var headerText =
                    new TextBlock
                    {
                        Text =
                            $"💰 COBRO · {localStart:HH:mm}",
                        FontSize =
                            Math.Max(
                                8.5,
                                9.2 * CalendarFontScale),
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.Bold,
                        MaxLines = 1,
                        TextTrimming =
                            TextTrimming.CharacterEllipsis,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    255,
                                    237,
                                    220,
                                    255)),
                        IsHitTestVisible = false
                    };

                Grid.SetColumn(
                    headerText,
                    0);

                headerGrid.Children.Add(
                    headerText);

                if (!string.IsNullOrWhiteSpace(
                        display.Status))
                {
                    var statusBadge =
                        new Border
                        {
                            MaxWidth =
                                Math.Max(
                                    46,
                                    width * 0.38),
                            Padding =
                                new Thickness(
                                    5,
                                    0,
                                    5,
                                    0),
                            CornerRadius =
                                new CornerRadius(7),
                            Background =
                                new SolidColorBrush(
                                    Color.FromArgb(
                                        105,
                                        192,
                                        132,
                                        252)),
                            BorderBrush =
                                new SolidColorBrush(
                                    Color.FromArgb(
                                        170,
                                        216,
                                        180,
                                        254)),
                            BorderThickness =
                                new Thickness(0.8),
                            Child =
                                new TextBlock
                                {
                                    Text =
                                        display.Status,
                                    FontSize =
                                        Math.Max(
                                            7.1,
                                            7.5 *
                                            CalendarFontScale),
                                    FontWeight =
                                        Microsoft.UI.Text.FontWeights.SemiBold,
                                    Foreground =
                                        new SolidColorBrush(
                                            Color.FromArgb(
                                                255,
                                                245,
                                                238,
                                                255)),
                                    MaxLines = 1,
                                    TextTrimming =
                                        TextTrimming.CharacterEllipsis,
                                    IsHitTestVisible = false
                                },
                            IsHitTestVisible = false
                        };

                    Grid.SetColumn(
                        statusBadge,
                        1);

                    headerGrid.Children.Add(
                        statusBadge);
                }

                Grid.SetRow(
                    headerGrid,
                    0);

                cardGrid.Children.Add(
                    headerGrid);

                var domainText =
                    new TextBlock
                    {
                        Text =
                            string.IsNullOrWhiteSpace(
                                display.Domain)
                                ? "Cobro programado"
                                : display.Domain,
                        FontSize =
                            Math.Max(
                                8.4,
                                9.0 * CalendarFontScale),
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    255,
                                    255,
                                    255,
                                    255)),
                        MaxLines = 1,
                        TextTrimming =
                            TextTrimming.CharacterEllipsis,
                        IsHitTestVisible = false
                    };

                Grid.SetRow(
                    domainText,
                    1);

                cardGrid.Children.Add(
                    domainText);

                var conceptText =
                    new TextBlock
                    {
                        Text =
                            display.Concept,
                        FontSize =
                            Math.Max(
                                7.8,
                                8.4 * CalendarFontScale),
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    225,
                                    233,
                                    213,
                                    255)),
                        Opacity = 0.94,
                        MaxLines =
                            height >= 62
                                ? 2
                                : 1,
                        TextWrapping =
                            height >= 62
                                ? TextWrapping.Wrap
                                : TextWrapping.NoWrap,
                        TextTrimming =
                            TextTrimming.CharacterEllipsis,
                        IsHitTestVisible = false
                    };

                Grid.SetRow(
                    conceptText,
                    2);

                cardGrid.Children.Add(
                    conceptText);

                var button =
                    new Button
                    {
                        Width = width,
                        Height = height,
                        Padding =
                            new Thickness(
                                8,
                                4,
                                8,
                                4),
                        HorizontalContentAlignment =
                            HorizontalAlignment.Stretch,
                        VerticalContentAlignment =
                            VerticalAlignment.Stretch,

                        // Morado profundo + acento eléctrico. Se conserva
                        // el lenguaje visual de Cobros pero con más contraste
                        // y menos efecto de "tarjetas apiladas".
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    252,
                                    42,
                                    18,
                                    70)),

                        BorderBrush =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    255,
                                    192,
                                    132,
                                    252)),

                        BorderThickness =
                            new Thickness(
                                4,
                                1.25,
                                1.25,
                                1.25),

                        CornerRadius =
                            new CornerRadius(8),

                        Content = cardGrid,
                        Tag = cobro.Row
                    };

                button.Resources[
                    "ButtonBackgroundPointerOver"] =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255,
                                58,
                                25,
                                96));

                button.Resources[
                    "ButtonBorderBrushPointerOver"] =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255,
                                216,
                                180,
                                254));

                button.Resources[
                    "ButtonBackgroundPressed"] =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255,
                                72,
                                33,
                                116));

                button.Resources[
                    "ButtonBorderBrushPressed"] =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255,
                                233,
                                213,
                                255));

                ToolTipService.SetToolTip(
                    button,
                    BuildCalendarCobroTooltip(
                        cobro,
                        display));

                button.Click += async (_, __) =>
                    await OpenCalendarCobroAsync(
                        cobro.Row);

                var cobroLeft =
                    railLeft + 5;

                // Glow mucho más sutil: da presencia sin simular otra
                // tarjeta debajo ni generar el efecto de solapamiento.
                var cobroGlow =
                    new Border
                    {
                        Width = width + 4,
                        Height = height + 4,
                        CornerRadius =
                            new CornerRadius(10),
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    28,
                                    168,
                                    85,
                                    247)),
                        BorderBrush =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    74,
                                    216,
                                    180,
                                    254)),
                        BorderThickness =
                            new Thickness(1),
                        IsHitTestVisible = false,
                        Tag = cobro.Row
                    };

                Canvas.SetLeft(
                    cobroGlow,
                    cobroLeft - 2);

                Canvas.SetTop(
                    cobroGlow,
                    top - 2);

                Canvas.SetZIndex(
                    cobroGlow,
                    430 + globalSequence * 2);

                CalendarCanvas.Children.Add(
                    cobroGlow);

                Canvas.SetLeft(
                    button,
                    cobroLeft);

                Canvas.SetTop(
                    button,
                    top);

                Canvas.SetZIndex(
                    button,
                    431 + globalSequence * 2);

                CalendarCanvas.Children.Add(
                    button);

                globalSequence++;
            }
        }

        private static bool HasExactCalendarPhase(
            NotionCalendarActivity activity,
            string phase)
        {
            if (activity == null ||
                string.IsNullOrWhiteSpace(phase))
            {
                return false;
            }

            return Regex.IsMatch(
                activity.Title ?? string.Empty,
                $@"(?<![\p{{L}}\p{{Nd}}_]){Regex.Escape(phase)}(?![\p{{L}}\p{{Nd}}_])",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);
        }

        private static bool HasCurrentReviewMirrorPhase(
            NotionCalendarActivity activity)
        {
            // La copia visual existe exclusivamente durante rtuzREVISION.
            // zREVISION ya representa una revisión aprobada y debe mostrarse
            // como una sola actividad normal del responsable original.
            return HasExactCalendarPhase(
                activity,
                "rtuzREVISION");
        }

        private static bool IsReviewEligibleActivity(
            NotionCalendarActivity activity)
        {
            // Estas fases contienen o conservan metadata del flujo.
            // prtuzREVISION no se hidrata como revisión para evitar consultas
            // innecesarias y nunca genera copia visual.
            return HasExactCalendarPhase(
                       activity,
                       "rtuzREVISION") ||
                   HasExactCalendarPhase(
                       activity,
                       "zREVISION");
        }

        private static bool CanSendCalendarActivityToReview(
            NotionCalendarActivity activity)
        {
            if (activity == null || activity.IsReviewMirror)
                return false;

            // Una actividad vuelve a estar lista para revisión cuando está
            // en prtuzREVISION, o puede reenviarse desde zREVISION.
            // sprtuzREVISION queda excluido por coincidencia exacta.
            return HasExactCalendarPhase(
                       activity,
                       "prtuzREVISION") ||
                   HasExactCalendarPhase(
                       activity,
                       "zREVISION") ||
                   (HasExactCalendarPhase(
                        activity,
                        "rtuzREVISION") &&
                    (!activity.IsPendingReview ||
                     activity.IsReturnedForCorrections));
        }

        private static bool IsPendingReviewActivity(
            NotionCalendarActivity activity)
        {
            return HasExactCalendarPhase(
                       activity,
                       "rtuzREVISION") &&
                   activity.IsPendingReview;
        }

        private static string BuildCalendarActivitySearchableText(
            NotionCalendarActivity activity)
        {
            return string.Join(
                " ",
                new[]
                {
                    activity.Title,
                    activity.Person,
                    activity.OriginalPerson,
                    activity.Project,
                    activity.Status,
                    activity.UpdateText,
                    activity.Description,
                    activity.IsAutomationLocked
                        ? "bloqueada automatizacion"
                        : string.Empty,
                    activity.ChecklistScanned
                        ? $"checklist {activity.ChecklistCompleted} de {activity.ChecklistTotal} {activity.ChecklistPercentage} porcentaje"
                        : string.Empty
                }.Where(value =>
                    !string.IsNullOrWhiteSpace(value)));
        }


        private sealed class MeetBrowserOption
        {
            public string Name { get; init; } = string.Empty;
            public string ExecutablePath { get; init; } = string.Empty;

            public bool IsSystemDefault =>
                string.IsNullOrWhiteSpace(ExecutablePath);

            public override string ToString() => Name;
        }

        private static string ReadMeetBrowserExecutable(
            string command)
        {
            command =
                Environment.ExpandEnvironmentVariables(
                    command ?? string.Empty)
                .Trim();

            if (string.IsNullOrWhiteSpace(command))
                return string.Empty;

            if (command.StartsWith('"'))
            {
                var closingQuote =
                    command.IndexOf('"', 1);

                if (closingQuote > 1)
                {
                    return command
                        .Substring(1, closingQuote - 1)
                        .Trim();
                }
            }

            var executableEnd =
                command.IndexOf(
                    ".exe",
                    StringComparison.OrdinalIgnoreCase);

            return executableEnd >= 0
                ? command
                    .Substring(0, executableEnd + 4)
                    .Trim()
                    .Trim('"')
                : string.Empty;
        }

        private static string NormalizeMeetBrowserDisplayName(
            string name,
            string executablePath)
        {
            var searchable =
                $"{name} {Path.GetFileNameWithoutExtension(executablePath)}";

            if (searchable.Contains(
                    "msedge",
                    StringComparison.OrdinalIgnoreCase) ||
                searchable.Contains(
                    "edge",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Microsoft Edge";
            }

            if (searchable.Contains(
                    "chrome",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Google Chrome";
            }

            if (searchable.Contains(
                    "firefox",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Mozilla Firefox";
            }

            if (searchable.Contains(
                    "brave",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Brave";
            }

            if (searchable.Contains(
                    "opera gx",
                    StringComparison.OrdinalIgnoreCase) ||
                searchable.Contains(
                    "operagx",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Opera GX";
            }

            if (searchable.Contains(
                    "opera",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Opera";
            }

            if (searchable.Contains(
                    "vivaldi",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Vivaldi";
            }

            if (searchable.Contains(
                    "arc",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Arc";
            }

            if (searchable.Contains(
                    "helium",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "Helium";
            }

            return string.IsNullOrWhiteSpace(name)
                ? Path.GetFileNameWithoutExtension(executablePath)
                : name.Trim();
        }

        private static void AddMeetBrowserCandidate(
            IDictionary<string, MeetBrowserOption> browsers,
            string name,
            string executablePath)
        {
            executablePath =
                Environment.ExpandEnvironmentVariables(
                    executablePath ?? string.Empty)
                .Trim()
                .Trim('"');

            if (string.IsNullOrWhiteSpace(executablePath) ||
                !File.Exists(executablePath))
            {
                return;
            }

            try
            {
                executablePath =
                    Path.GetFullPath(executablePath);
            }
            catch
            {
                return;
            }

            if (browsers.ContainsKey(executablePath))
                return;

            browsers[executablePath] =
                new MeetBrowserOption
                {
                    Name = NormalizeMeetBrowserDisplayName(
                        name,
                        executablePath),
                    ExecutablePath = executablePath
                };
        }

        private static void ReadRegisteredMeetBrowsers(
            IDictionary<string, MeetBrowserOption> browsers,
            RegistryHive hive,
            RegistryView view)
        {
            try
            {
                using var baseKey =
                    RegistryKey.OpenBaseKey(hive, view);

                using var clients =
                    baseKey.OpenSubKey(
                        @"SOFTWARE\Clients\StartMenuInternet");

                if (clients == null)
                    return;

                foreach (var browserKeyName in
                         clients.GetSubKeyNames())
                {
                    using var browserKey =
                        clients.OpenSubKey(browserKeyName);

                    using var commandKey =
                        browserKey?.OpenSubKey(
                            @"shell\open\command");

                    var command =
                        commandKey?.GetValue(null)?.ToString() ??
                        string.Empty;

                    var executablePath =
                        ReadMeetBrowserExecutable(command);

                    var displayName =
                        browserKey?.GetValue(null)?.ToString() ??
                        browserKeyName;

                    AddMeetBrowserCandidate(
                        browsers,
                        displayName,
                        executablePath);
                }
            }
            catch
            {
                // Algunos equipos restringen ciertas vistas del registro.
                // La detección continúa con rutas conocidas y el navegador
                // predeterminado de Windows siempre permanece disponible.
            }
        }

        private static IReadOnlyList<MeetBrowserOption>
            DetectInstalledMeetBrowsers()
        {
            var discovered =
                new Dictionary<string, MeetBrowserOption>(
                    StringComparer.OrdinalIgnoreCase);

            foreach (var hive in new[]
                     {
                         RegistryHive.CurrentUser,
                         RegistryHive.LocalMachine
                     })
            {
                foreach (var view in new[]
                         {
                             RegistryView.Registry64,
                             RegistryView.Registry32
                         })
                {
                    ReadRegisteredMeetBrowsers(
                        discovered,
                        hive,
                        view);
                }
            }

            var programFiles =
                Environment.GetFolderPath(
                    Environment.SpecialFolder.ProgramFiles);

            var programFilesX86 =
                Environment.GetFolderPath(
                    Environment.SpecialFolder.ProgramFilesX86);

            var localAppData =
                Environment.GetFolderPath(
                    Environment.SpecialFolder.LocalApplicationData);

            var knownBrowsers = new[]
            {
                ("Microsoft Edge", Path.Combine(programFilesX86, "Microsoft", "Edge", "Application", "msedge.exe")),
                ("Microsoft Edge", Path.Combine(programFiles, "Microsoft", "Edge", "Application", "msedge.exe")),
                ("Google Chrome", Path.Combine(programFiles, "Google", "Chrome", "Application", "chrome.exe")),
                ("Google Chrome", Path.Combine(programFilesX86, "Google", "Chrome", "Application", "chrome.exe")),
                ("Google Chrome", Path.Combine(localAppData, "Google", "Chrome", "Application", "chrome.exe")),
                ("Mozilla Firefox", Path.Combine(programFiles, "Mozilla Firefox", "firefox.exe")),
                ("Mozilla Firefox", Path.Combine(programFilesX86, "Mozilla Firefox", "firefox.exe")),
                ("Brave", Path.Combine(programFiles, "BraveSoftware", "Brave-Browser", "Application", "brave.exe")),
                ("Brave", Path.Combine(programFilesX86, "BraveSoftware", "Brave-Browser", "Application", "brave.exe")),
                ("Brave", Path.Combine(localAppData, "BraveSoftware", "Brave-Browser", "Application", "brave.exe")),
                ("Opera", Path.Combine(localAppData, "Programs", "Opera", "launcher.exe")),
                ("Opera GX", Path.Combine(localAppData, "Programs", "Opera GX", "launcher.exe")),
                ("Vivaldi", Path.Combine(programFiles, "Vivaldi", "Application", "vivaldi.exe")),
                ("Vivaldi", Path.Combine(localAppData, "Vivaldi", "Application", "vivaldi.exe")),
                ("Arc", Path.Combine(localAppData, "Programs", "Arc", "Arc.exe")),
                ("Helium", Path.Combine(localAppData, "Programs", "Helium", "helium.exe")),
                ("Helium", Path.Combine(programFiles, "Helium", "helium.exe"))
            };

            foreach (var browser in knownBrowsers)
            {
                AddMeetBrowserCandidate(
                    discovered,
                    browser.Item1,
                    browser.Item2);
            }

            return new[]
                {
                    new MeetBrowserOption
                    {
                        Name = "Predeterminado de Windows"
                    }
                }
                .Concat(
                    discovered.Values
                        .OrderBy(browser => browser.Name)
                        .ThenBy(browser => browser.ExecutablePath))
                .ToList();
        }

        private static void ClearSavedMeetBrowser()
        {
            var values =
                ApplicationData.Current.LocalSettings.Values;

            values.Remove(LS_MeetBrowserName);
            values.Remove(LS_MeetBrowserPath);
        }

        private async Task<MeetBrowserOption?>
            SelectMeetBrowserAsync(
                bool alwaysShowDialog)
        {
            var values =
                ApplicationData.Current.LocalSettings.Values;

            var hasSavedSelection =
                values.ContainsKey(LS_MeetBrowserName) ||
                values.ContainsKey(LS_MeetBrowserPath);

            var savedName =
                values[LS_MeetBrowserName] as string ??
                string.Empty;

            var savedPath =
                values[LS_MeetBrowserPath] as string ??
                string.Empty;

            if (!alwaysShowDialog && hasSavedSelection)
            {
                if (string.IsNullOrWhiteSpace(savedPath))
                {
                    return new MeetBrowserOption
                    {
                        Name = string.IsNullOrWhiteSpace(savedName)
                            ? "Predeterminado de Windows"
                            : savedName
                    };
                }

                if (File.Exists(savedPath))
                {
                    return new MeetBrowserOption
                    {
                        Name = string.IsNullOrWhiteSpace(savedName)
                            ? NormalizeMeetBrowserDisplayName(
                                string.Empty,
                                savedPath)
                            : savedName,
                        ExecutablePath = savedPath
                    };
                }

                ClearSavedMeetBrowser();
                StatusText.Text =
                    "Estado: El navegador guardado ya no está instalado. Elige otro para Meet.";
            }

            var browsers =
                DetectInstalledMeetBrowsers();

            var browserCombo = new ComboBox
            {
                Width = 360,
                MaxDropDownHeight = 320,
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            foreach (var browser in browsers)
            {
                browserCombo.Items.Add(
                    new ComboBoxItem
                    {
                        Content = browser.Name,
                        Tag = browser
                    });
            }

            var selectedIndex = 0;

            if (!string.IsNullOrWhiteSpace(savedPath))
            {
                for (var index = 0;
                     index < browserCombo.Items.Count;
                     index++)
                {
                    if (browserCombo.Items[index] is not
                            ComboBoxItem item ||
                        item.Tag is not MeetBrowserOption browser)
                    {
                        continue;
                    }

                    if (string.Equals(
                            browser.ExecutablePath,
                            savedPath,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        selectedIndex = index;
                        break;
                    }
                }
            }

            browserCombo.SelectedIndex = selectedIndex;

            var content = new StackPanel
            {
                Spacing = 10,
                MinWidth = 370
            };

            content.Children.Add(
                new TextBlock
                {
                    Text =
                        "Selecciona dónde abrir los tres enlaces de Google Meet. " +
                        "ANFETA guardará esta elección para las siguientes reuniones.",
                    TextWrapping = TextWrapping.Wrap,
                    Opacity = 0.78
                });

            content.Children.Add(browserCombo);

            content.Children.Add(
                new TextBlock
                {
                    Text =
                        browsers.Count > 1
                            ? "Puedes cambiarlo después desde Meet → Cambiar navegador."
                            : "No se detectaron otros navegadores; se usará el predeterminado de Windows.",
                    FontSize = 11,
                    TextWrapping = TextWrapping.Wrap,
                    Opacity = 0.60
                });

            var dialog = new ContentDialog
            {
                XamlRoot = XamlRoot,
                Title = "Elegir navegador para Meet",
                PrimaryButtonText = "Guardar",
                CloseButtonText = "Cancelar",
                DefaultButton = ContentDialogButton.Primary,
                Content = content
            };

            var result =
                await dialog.ShowAsync();

            if (result != ContentDialogResult.Primary)
                return null;

            var selected =
                (browserCombo.SelectedItem as ComboBoxItem)?
                    .Tag as MeetBrowserOption ??
                browsers[0];

            values[LS_MeetBrowserName] = selected.Name;
            values[LS_MeetBrowserPath] = selected.ExecutablePath;

            return selected;
        }

        private static bool LaunchMeetWithExecutable(
            MeetBrowserOption browser,
            Uri uri)
        {
            if (browser.IsSystemDefault ||
                !File.Exists(browser.ExecutablePath))
            {
                return false;
            }

            var startInfo = new ProcessStartInfo
            {
                FileName = browser.ExecutablePath,
                UseShellExecute = false
            };

            startInfo.ArgumentList.Add(uri.AbsoluteUri);

            return Process.Start(startInfo) != null;
        }

        private async void ConfigureMeetBrowser_Click(
            object sender,
            RoutedEventArgs e)
        {
            try
            {
                var selected =
                    await SelectMeetBrowserAsync(
                        alwaysShowDialog: true);

                StatusText.Text = selected == null
                    ? "Estado: No se cambió el navegador de Meet."
                    : $"Estado: Meet se abrirá con {selected.Name} ✅";
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo configurar el navegador → {ex.Message}";
            }
        }

        private async void OpenMeetQuickLink_Click(
            object sender,
            RoutedEventArgs e)
        {
            if (sender is not FrameworkElement element)
                return;

            var url =
                (element.Tag?.ToString() ?? string.Empty).Trim();

            var label =
                sender is MenuFlyoutItem menuItem &&
                !string.IsNullOrWhiteSpace(menuItem.Text)
                    ? menuItem.Text
                    : "Google Meet";

            if (!Uri.TryCreate(
                    url,
                    UriKind.Absolute,
                    out var uri) ||
                !string.Equals(
                    uri.Scheme,
                    Uri.UriSchemeHttps,
                    StringComparison.OrdinalIgnoreCase))
            {
                StatusText.Text =
                    "Estado: El enlace de Meet no es válido.";
                return;
            }

            try
            {
                var browser =
                    await SelectMeetBrowserAsync(
                        alwaysShowDialog: false);

                if (browser == null)
                {
                    StatusText.Text =
                        "Estado: Apertura de Meet cancelada.";
                    return;
                }

                var opened = browser.IsSystemDefault
                    ? await Launcher.LaunchUriAsync(uri)
                    : LaunchMeetWithExecutable(browser, uri);

                if (!opened && !browser.IsSystemDefault)
                {
                    // Si el ejecutable dejó de funcionar, se elimina la
                    // preferencia y se intenta con el navegador predeterminado.
                    ClearSavedMeetBrowser();
                    opened = await Launcher.LaunchUriAsync(uri);

                    StatusText.Text = opened
                        ? $"Estado: {label} abierto con el navegador predeterminado; vuelve a elegir tu navegador de Meet."
                        : $"Estado: Windows no pudo abrir {label}.";
                    return;
                }

                StatusText.Text = opened
                    ? $"Estado: {label} abierto con {browser.Name} ✅"
                    : $"Estado: Windows no pudo abrir {label}.";
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo abrir {label} → {ex.Message}";
            }
        }

        private void CalendarPhaseFilterCombo_SelectionChanged(
