        private static IReadOnlyList<NotionCalendarActivity>
            FilterCalendarActivities(
                IReadOnlyList<NotionCalendarActivity> activities,
                string query)
        {
            var parts =
                ParseCalendarSearchParts(query);

            if (parts.Count == 0)
                return activities;

            return activities
                .Where(activity =>
                {
                    var searchable = string.Join(
                        " ",
                        new[]
                        {
                            activity.Title,
                            activity.Person,
                            activity.OriginalPerson,
                            activity.Project,
                            activity.Status,
                            activity.UpdateText,
                            activity.Description,
                            activity.PageUrl,
                            activity.TimeLabel,
                            activity.Start.ToString(
                                "dd/MM/yyyy HH:mm",
                                CultureInfo.InvariantCulture),
                            activity.End.ToString(
                                "dd/MM/yyyy HH:mm",
                                CultureInfo.InvariantCulture)
                        });

                    return parts.All(part =>
                    {
                        // Los estados de revisión siempre son tokens exactos.
                        // Así rtuzREVISION no coincide dentro de prtuzREVISION
                        // ni sprtuzREVISION aunque se escriba sin comillas.
                        if (IsCalendarPhaseSearchToken(part.Value))
                        {
                            return ContainsExactCalendarPart(
                                searchable,
                                part.Value);
                        }

                        return part.IsExact
                            ? ContainsExactCalendarPart(
                                searchable,
                                part.Value)
                            : searchable.Contains(
                                part.Value,
                                StringComparison.OrdinalIgnoreCase);
                    });
                })
                .ToList();
        }

        private sealed record CalendarSearchPart(
            string Value,
            bool IsExact);

        private static IReadOnlyList<CalendarSearchPart>
            ParseCalendarSearchParts(string query)
        {
            var result =
                new List<CalendarSearchPart>();

            foreach (Match match in Regex.Matches(
                query ?? string.Empty,
                "\\\"(?<exact>[^\\\"]+)\\\"|(?<normal>\\S+)",
                RegexOptions.CultureInvariant))
            {
                var exact =
                    match.Groups["exact"].Success;

                var value = exact
                    ? match.Groups["exact"].Value
                    : match.Groups["normal"].Value;

                value = value.Trim();

                if (!string.IsNullOrWhiteSpace(value))
                {
                    result.Add(
                        new CalendarSearchPart(
                            value,
                            exact));
                }
            }

            return result;
        }

        private static bool IsCalendarPhaseSearchToken(
            string value)
        {
            return Regex.IsMatch(
                (value ?? string.Empty).Trim(),
                @"^(?:sprtuz|prtuz|rtuz|z)REVISION$",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);
        }

        private static bool ContainsExactCalendarPart(
            string searchable,
            string value)
        {
            value =
                (value ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(value))
                return true;

            if (value.Any(char.IsWhiteSpace) ||
                value.Contains('.') ||
                value.Contains('/'))
            {
                return searchable.Contains(
                    value,
                    StringComparison.OrdinalIgnoreCase);
            }

            return Regex.IsMatch(
                searchable,
                $@"(?<![\p{{L}}\p{{Nd}}_]){Regex.Escape(value)}(?![\p{{L}}\p{{Nd}}_])",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);
        }

        private static string NormalizeCalendarSearchText(
            string value)
        {
            var normalized =
                (value ?? string.Empty)
                .Trim()
                .ToLowerInvariant()
                .Normalize(NormalizationForm.FormD);

            var result =
                new StringBuilder(
                    normalized.Length);

            foreach (var character in normalized)
            {
                var category =
                    CharUnicodeInfo.GetUnicodeCategory(
                        character);

                if (category ==
                    UnicodeCategory.NonSpacingMark)
                {
                    continue;
                }

                result.Append(
                    char.IsLetterOrDigit(character)
                        ? character
                        : ' ');
            }

            return string.Join(
                " ",
                result.ToString()
                    .Split(
                        ' ',
                        StringSplitOptions.RemoveEmptyEntries));
        }

        private void DrawPersonActivities(
            IReadOnlyList<NotionCalendarActivity> items,
            string person,
            double headerHeight)
        {
            var ordered =
                (items ?? Array.Empty<NotionCalendarActivity>())
                    .OrderBy(activity => activity.Start)
                    .ThenBy(activity => activity.End)
                    .ThenBy(activity => activity.Title)
                    .ToList();

            if (ordered.Count == 0)
                return;

            var overlapGroup =
                new List<NotionCalendarActivity>();

            var overlapGroupEnd =
                DateTime.MinValue;

            void DrawOverlapGroup()
            {
                if (overlapGroup.Count == 0)
                    return;

                var laneEnds =
                    new List<DateTime>();

                var layouts =
                    new List<(
                        NotionCalendarActivity Activity,
                        int Lane,
                        int Sequence)>();

                for (var sequence = 0;
                     sequence < overlapGroup.Count;
                     sequence++)
                {
                    var activity =
                        overlapGroup[sequence];

                    var lane = 0;

                    while (lane < laneEnds.Count &&
                           activity.Start < laneEnds[lane])
                    {
                        lane++;
                    }

                    if (lane == laneEnds.Count)
                        laneEnds.Add(activity.End);
                    else
                        laneEnds[lane] = activity.End;

                    layouts.Add(
                        (activity, lane, sequence));
                }

                var maxConcurrency =
                    Math.Max(
                        1,
                        laneEnds.Count);

                foreach (var layout in layouts)
                {
                    var directOverlapCount =
                        Math.Max(
                            1,
                            overlapGroup.Count(other =>
                                other.Start <
                                    layout.Activity.End &&
                                other.End >
                                    layout.Activity.Start));

                    var directOverlapItems =
                        overlapGroup
                            .Where(other =>
                                other.Start < layout.Activity.End &&
                                other.End > layout.Activity.Start)
                            .OrderBy(other => other.Start)
                            .ThenBy(other => other.End)
                            .ThenBy(other => other.Title)
                            .ToList();

                    AddActivityButton(
                        layout.Activity,
                        person,
                        headerHeight,
                        layout.Lane,
                        maxConcurrency,
                        directOverlapCount,
                        layout.Sequence,
                        directOverlapItems);
                }

                overlapGroup.Clear();
                overlapGroupEnd =
                    DateTime.MinValue;
            }

            foreach (var activity in ordered)
            {
                if (overlapGroup.Count == 0)
                {
                    overlapGroup.Add(activity);
                    overlapGroupEnd = activity.End;
                    continue;
                }

                // Agrupa cadenas completas de empalmes. Aunque una actividad
                // no se cruce directamente con la primera, permanece en el
                // mismo grupo cuando se conecta por otra actividad intermedia.
                if (activity.Start < overlapGroupEnd)
                {
                    overlapGroup.Add(activity);

                    if (activity.End > overlapGroupEnd)
                        overlapGroupEnd = activity.End;

                    continue;
                }

                DrawOverlapGroup();

                overlapGroup.Add(activity);
                overlapGroupEnd = activity.End;
            }

            DrawOverlapGroup();
        }

        private static string BuildActivityDayRangeTooltip(
            NotionCalendarActivity activity)
        {
            if (activity == null ||
                !activity.HasActivityDayRange)
            {
                return string.Empty;
            }

            var start =
                activity.ActivityCreatedDate!.Value.Date;

            var deadline =
                activity.InternalDeadlineDate!.Value.Date;

            var elapsed =
                activity.ActivityElapsedDays;

            var budget =
                activity.ActivityBudgetDays;

            var overdueDays =
                Math.Max(0, elapsed - budget);

            var budgetText =
                overdueDays > 0
                    ? $"vencida +{overdueDays}d"
                    : $"resta {Math.Max(0, budget - elapsed)}d";

            // Tooltip compacto: conserva la información útil sin cubrir
            // media columna del calendario.
            return
                $"📅 {start:dd/MM} → {deadline:dd/MM} · " +
                $"día {elapsed}/{budget} · {budgetText}";
        }

        private FrameworkElement? BuildActivityDayRangeIndicator(
            NotionCalendarActivity activity,
            double cardWidth,
            double cardHeight,
            bool compact)
        {
            if (activity == null ||
                !activity.HasActivityDayRange ||
                activity.ActivityBudgetDays <= 0)
            {
                return null;
            }

            var elapsed =
                activity.ActivityElapsedDays;

            var budget =
                activity.ActivityBudgetDays;

            var overdue =
                activity.IsActivityOverdue;

            // Cada bloque representa un día siempre que el rango sea razonable.
            // En rangos muy largos se comprime para no destruir el ancho de la
            // tarjeta, pero el texto conserva siempre el valor real X/Y días.
            const int MaxExactDaySegments = 16;

            var maxSegmentsByWidth =
                Math.Clamp(
                    (int)Math.Floor(
                        Math.Max(36, cardWidth - 12) /
                        Math.Max(6, 9 * _calendarZoom)),
                    3,
                    MaxExactDaySegments);

            var segmentCount =
                budget <= MaxExactDaySegments
                    ? Math.Max(1, budget)
                    : Math.Max(
                        1,
                        Math.Min(
                            budget,
                            maxSegmentsByWidth));

            var completedSegments =
                budget <= 0
                    ? 0
                    : Math.Clamp(
                        budget <= MaxExactDaySegments
                            ? Math.Min(elapsed, budget)
                            : (int)Math.Ceiling(
                                Math.Min(elapsed, budget) *
                                segmentCount /
                                (double)budget),
                        0,
                        segmentCount);

            var root = new Grid
            {
                Height = compact
                    ? Math.Max(12, 13 * _calendarZoom)
                    : Math.Max(14, 16 * _calendarZoom),
                Margin = new Thickness(
                    0,
                    2,
                    0,
                    0),
                HorizontalAlignment =
                    HorizontalAlignment.Stretch,
                VerticalAlignment =
                    VerticalAlignment.Bottom,
                IsHitTestVisible = false
            };

            root.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });

            root.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            var segments = new Grid
            {
                Height = compact
                    ? Math.Max(5, 5.5 * _calendarZoom)
                    : Math.Max(6, 6.5 * _calendarZoom),
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 5, 0)
            };

            for (var index = 0;
                 index < segmentCount;
                 index++)
            {
                segments.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(
                            1,
                            GridUnitType.Star)
                    });

                var filled =
                    index < completedSegments;

                var segment = new Border
                {
                    // Separación visible entre días. La línea oscura hace que
                    // incluso dos días (1/2d) se perciban como dos bloques y
                    // no como una sola barra continua partida por color.
                    Margin = new Thickness(
                        index == 0 ? 0 : 1.35,
                        0,
                        index == segmentCount - 1 ? 0 : 1.35,
                        0),
                    CornerRadius = new CornerRadius(2),
                    BorderBrush = new SolidColorBrush(
                        Color.FromArgb(185, 17, 24, 39)),
                    BorderThickness = new Thickness(0.8),
                    Background =
                        new SolidColorBrush(
                            filled
                                ? Color.FromArgb(255, 255, 153, 0)
                                : Color.FromArgb(255, 47, 128, 237))
                };

                Grid.SetColumn(segment, index);
                segments.Children.Add(segment);
            }

            Grid.SetColumn(segments, 0);
            root.Children.Add(segments);

            var label = new TextBlock
            {
                Text = overdue
                    ? $"{elapsed}/{budget}d ⚠"
                    : $"{elapsed}/{budget}d",
                FontSize = Math.Max(
                    7.6,
                    (compact ? 7.7 : 8.2) *
                    CalendarFontScale),
                FontWeight =
                    Microsoft.UI.Text.FontWeights.SemiBold,
                Foreground = new SolidColorBrush(
                    overdue
                        ? Color.FromArgb(255, 248, 113, 113)
                        : Color.FromArgb(235, 229, 231, 235)),
                VerticalAlignment =
                    VerticalAlignment.Center,
                MaxLines = 1,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                IsHitTestVisible = false
            };

            Grid.SetColumn(label, 1);
            root.Children.Add(label);

            // El detalle de días se conserva en el preview/detalle de la
            // actividad. No se coloca ToolTip sobre este indicador porque en
            // tarjetas empalmadas tapa justo las tarjetas que el usuario
            // intenta inspeccionar con el cursor.

            return root;
        }

        private string BuildCalendarChecklistBadgeText(
            NotionCalendarActivity activity,
            bool compactBadge,
            bool ultraCompact = false)
        {
            var stats =
                GetCalendarChecklistStats(
                    activity);

            var prefix =
                ultraCompact
                    ? "A"
                    : compactBadge
                        ? "A "
                        : "ACT ";

            if (!activity.ChecklistScanned)
                return prefix + "…";

            if (!stats.HasChecklist)
                return ultraCompact
                    ? "A0"
                    : prefix + "0/0";

            if (ultraCompact)
            {
                return
                    $"A{GetChecklistPercentage(stats)}";
            }

            // ACT conserva el dato que ya usaban (2/59, 13/15, etc.).
            return
                $"{prefix}{stats.Completed}/{stats.Total}";
        }

        private string BuildCalendarTodayProgressBadgeText(
            NotionCalendarActivity activity,
            bool ultraCompact,
            out string tooltip)
        {
            var dayLabel =
                _calendarSelectedDate.Date == DateTime.Today
                    ? "HOY"
                    : "DÍA";

            var shortPrefix =
                _calendarSelectedDate.Date == DateTime.Today
                    ? "H"
                    : "D";

            tooltip =
                $"{dayLabel}: todavía no existe un baseline comparable.";

            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                tooltip =
                    $"{dayLabel}: actividad sin identidad comparable.";

                return ultraCompact
                    ? $"{shortPrefix}—"
                    : $"{shortPrefix} —";
            }

            if (!activity.ChecklistScanned)
            {
                tooltip =
                    $"{dayLabel}: esperando la lectura del checklist de esta actividad.";

                return ultraCompact
                    ? $"{shortPrefix}…"
                    : $"{shortPrefix} …";
            }

            if (activity.ChecklistTotal <= 0)
            {
                tooltip =
                    $"{dayLabel}: esta actividad no tiene checklist activo; " +
                    "no hay avance diario que calcular.";

                return ultraCompact
                    ? $"{shortPrefix}—"
                    : $"{shortPrefix} —";
            }

            if (!_calendarCardChecklistBaselines.TryGetValue(
                    activity.PageId,
                    out var baseline))
            {
                tooltip =
                    $"{dayLabel}: todavía no existe un baseline comparable " +
                    "para esta actividad.";

                return ultraCompact
                    ? $"{shortPrefix}—"
                    : $"{shortPrefix} —";
            }

            // Si cambió el total del body, no inventamos avance del día.
            if (baseline.Total > 0 &&
                baseline.Total != activity.ChecklistTotal)
            {
                tooltip =
                    $"{dayLabel}: cambió la estructura del checklist " +
                    $"({baseline.Total} → {activity.ChecklistTotal}); " +
                    "se espera un nuevo baseline comparable.";

                return ultraCompact
                    ? $"{shortPrefix}↻"
                    : $"{shortPrefix} ↻";
            }

            var delta =
                Math.Max(
                    0,
                    activity.ChecklistCompleted -
                    baseline.Completed);

            // REGLA 20/08: el indicador diario arranca en 0%.
            // El porcentaje histórico de la checklist pertenece a A/P, no a H.
            // Hasta que ANFETA observe un delta posterior al baseline, H = 0%.
            if (!baseline.EstablishedBeforeThisRead &&
                delta == 0)
            {
                tooltip =
                    $"{dayLabel}: seguimiento iniciado " +
                    $"{baseline.TrackingStartedAt:HH:mm}. " +
                    "0% observado hoy; el progreso anterior no se suma a H.";

                return ultraCompact
                    ? $"{shortPrefix}0"
                    : $"{shortPrefix} 0%";
            }

            var percentage =
                Math.Clamp(
                    (int)Math.Round(
                        delta * 100d /
                        Math.Max(
                            1,
                            activity.ChecklistTotal)),
                    0,
                    100);

            tooltip =
                $"{dayLabel}: +{delta} check(s) desde el baseline " +
                $"{baseline.TrackingStartedAt:HH:mm} · " +
                $"{percentage}% del checklist total.";

            return ultraCompact
                ? $"{shortPrefix}{percentage}"
                : $"{shortPrefix} {percentage}%";
        }

        private bool TryGetCalendarProjectProgress(
            NotionCalendarActivity activity,
            out NotionChecklistStats stats,
            out string projectLabel,
            out bool isPartial,
            out int scannedActivities,
            out int totalActivities)
        {
            stats =
                new NotionChecklistStats(
                    0,
                    0);

            projectLabel =
                "Proyecto";

            isPartial =
                false;

            scannedActivities =
                0;

            totalActivities =
                0;

            if (activity == null ||
                !TryBuildCalendarProjectGroupCriteria(
                    activity,
                    out var criteria))
            {
                return false;
            }

            projectLabel =
                $"{criteria.ProjectLabel} · {criteria.Domain} · {criteria.MonthTag}";

            if (!_calendarProjectActivitiesCache.TryGetValue(
                    criteria.Key,
                    out var cached) ||
                DateTimeOffset.UtcNow - cached.StoredAt >
                    CalendarProjectActivitiesCacheLifetime)
            {
                return false;
            }

            var related =
                NormalizeCalendarProjectActivityList(
                    cached.Activities,
                    activity,
                    criteria);

            var unique =
                related
                    .Where(item =>
                        item != null &&
                        !item.IsReviewMirror &&
                        !string.IsNullOrWhiteSpace(
                            item.PageId))
                    .GroupBy(
                        item => item.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();

            totalActivities =
                unique.Count;

            if (totalActivities == 0)
                return false;

            var scanned =
                unique
                    .Where(item =>
                        item.ChecklistScanned)
                    .ToList();

            scannedActivities =
                scanned.Count;

            // Si todavía no existe ni una actividad escaneada, sí continúa
            // siendo una carga real de PROY.
            if (scannedActivities == 0)
                return false;

            // Si algunas ya están y otras no, mostramos un porcentaje PARCIAL
            // (~) para no dejar la card indefinidamente en P…
            isPartial =
                scannedActivities <
                totalActivities;

            stats =
                GetCalendarProjectChecklistStats(
                    scanned);

            return true;
        }

        private string BuildCalendarProjectProgressBadgeText(
            NotionCalendarActivity activity,
            bool ultraCompact,
            out string tooltip)
        {
            // Si ni siquiera existe identidad de proyecto, el morado no aporta
            // nada y en cards pequeñas solo roba espacio.
            if (activity == null ||
                !TryBuildCalendarProjectGroupCriteria(
                    activity,
                    out _))
            {
                tooltip =
                    "PROY: esta actividad no tiene un proyecto comparable.";

                return string.Empty;
            }

            if (!TryGetCalendarProjectProgress(
                    activity,
                    out var stats,
                    out var projectLabel,
                    out var isPartial,
                    out var scannedActivities,
                    out var totalActivities))
            {
                tooltip =
                    "PROY: preparando el avance total desde la caché del proyecto. " +
                    "No se hace una consulta por tarjeta.";

                return ultraCompact
                    ? "P…"
                    : "P …";
            }

            // Si todavía faltan páginas y lo leído hasta ahora no tiene checks,
            // se conserva el indicador de carga. Si YA terminó el proyecto y el
            // total real es 0, se oculta por completo.
            if (stats.Total <= 0)
            {
                if (isPartial)
                {
                    tooltip =
                        $"PROY: {projectLabel} · todavía faltan " +
                        $"{Math.Max(0, totalActivities - scannedActivities)} actividad(es) por revisar.";

                    return ultraCompact
                        ? "P…"
                        : "P …";
                }

                tooltip =
                    $"PROY: {projectLabel} · sin checklist de proyecto.";

                return string.Empty;
            }

            var percentage =
                GetChecklistPercentage(
                    stats);

            if (isPartial)
            {
                tooltip =
                    $"PROY: {projectLabel} · cálculo parcial con " +
                    $"{scannedActivities}/{totalActivities} actividad(es) ya leídas · " +
                    $"{stats.Completed}/{stats.Total} checks disponibles · " +
                    $"{percentage}%. El símbolo ~ indica que todavía faltan actividades.";

                return ultraCompact
                    ? $"P~{percentage}"
                    : $"P ~{percentage}%";
            }

            tooltip =
                $"PROY: {projectLabel} · " +
                $"{stats.Completed}/{stats.Total} checks · " +
                $"{percentage}%.";

            return ultraCompact
                ? $"P{percentage}"
                : $"P {percentage}%";
        }

        private void UpdateCalendarProgressVisual(
            CalendarActivityVisual visual,
            NotionCalendarActivity activity)
        {
            if (visual == null ||
                activity == null)
            {
                return;
            }

            var stats =
                GetCalendarChecklistStats(
                    activity);

            visual.Button.Tag =
                activity;

            visual.ChecklistText.Text =
                BuildCalendarChecklistBadgeText(
                    activity,
                    visual.CompactChecklistBadge,
                    visual.UltraCompactProgress);

            visual.ChecklistBadge.Visibility =
                Visibility.Visible;

            visual.ChecklistBadge.BorderBrush =
                new SolidColorBrush(
                    !activity.ChecklistScanned
                        ? Color.FromArgb(
                            255, 125, 211, 252)
                        : stats.HasChecklist
                            ? Color.FromArgb(
                                255, 74, 222, 128)
                            : Color.FromArgb(
                                150, 148, 163, 184));

            visual.ChecklistText.Foreground =
                new SolidColorBrush(
                    !activity.ChecklistScanned
                        ? Color.FromArgb(
                            255, 186, 230, 253)
                        : stats.HasChecklist
                            ? Color.FromArgb(
                                255, 134, 239, 172)
                            : Color.FromArgb(
                                220, 203, 225, 235));

            ToolTipService.SetToolTip(
                visual.ChecklistBadge,
                activity.ChecklistScanned
                    ? stats.HasChecklist
                        ? $"ACT: checklist de esta actividad · " +
                          $"{stats.Completed}/{stats.Total} · " +
                          $"{GetChecklistPercentage(stats)}%"
                        : "ACT: checklist revisado · sin tareas activas"
                    : "ACT: calculando checklist de la actividad…");

            var todayText =
                BuildCalendarTodayProgressBadgeText(
                    activity,
                    visual.UltraCompactProgress,
                    out var todayTooltip);

            visual.TodayProgressText.Text =
                todayText;

            ToolTipService.SetToolTip(
                visual.TodayProgressBadge,
                todayTooltip);

            var projectText =
                BuildCalendarProjectProgressBadgeText(
                    activity,
                    visual.UltraCompactProgress,
                    out var projectTooltip);

            visual.ProjectProgressText.Text =
                projectText;

            visual.ProjectProgressBadge.Visibility =
                string.IsNullOrWhiteSpace(projectText)
                    ? Visibility.Collapsed
                    : Visibility.Visible;

            ToolTipService.SetToolTip(
                visual.ProjectProgressBadge,
                projectTooltip);

            // La fase/tipo/progresos viven en una fila propia.
            visual.TitleText.Margin =
                new Thickness(0);
        }

        private void RefreshCalendarProjectProgressVisuals(
            string criteriaKey)
        {
            if (string.IsNullOrWhiteSpace(criteriaKey))
                return;

            foreach (var visualList in
                     _calendarActivityVisuals.Values)
            {
                foreach (var visual in visualList)
                {
                    if (visual.Button.Tag is not
                        NotionCalendarActivity activity ||
                        !TryBuildCalendarProjectGroupCriteria(
                            activity,
                            out var criteria) ||
                        !string.Equals(
                            criteria.Key,
                            criteriaKey,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    UpdateCalendarProgressVisual(
                        visual,
                        activity);
                }
            }
        }

        private async Task RefreshCalendarCardTodayBaselinesAsync(
            DateTime requestedDate,
            long loadVersion,
            CancellationToken cancellationToken)
        {
            try
            {
                var unique =
                    _calendarActivities
                        .Where(activity =>
                            activity != null &&
                            !activity.IsReviewMirror &&
                            !string.IsNullOrWhiteSpace(
                                activity.PageId))
                        .GroupBy(
                            activity => activity.PageId,
                            StringComparer.OrdinalIgnoreCase)
                        .Select(group => group.First())
                        .ToList();

                var baselines =
                    await NotionDailyProgressService
                        .GetCalendarCardChecklistBaselinesAsync(
                            requestedDate.Date,
                            unique,
                            cancellationToken);

                cancellationToken.ThrowIfCancellationRequested();

                if (requestedDate.Date !=
                        _calendarSelectedDate.Date ||
                    loadVersion !=
                        _calendarLoadVersion)
                {
                    return;
                }

                DispatcherQueue.TryEnqueue(
                    () =>
                    {
                        if (requestedDate.Date !=
                                _calendarSelectedDate.Date ||
                            loadVersion !=
                                _calendarLoadVersion)
                        {
                            return;
                        }

                        _calendarCardChecklistBaselines.Clear();

                        foreach (var item in baselines)
                        {
                            _calendarCardChecklistBaselines[
                                item.Key] =
                                    item.Value;
                        }

                        UpdateCalendarChecklistVisuals(
                            unique.Select(activity =>
                                activity.PageId));
                    });
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                Debug.WriteLine(
                    $"[CALENDAR_PROGRESS_BASELINE] {ex.Message}");
            }
        }

        private double GetCalendarChecklistReservedWidth(
            bool compactBadge)
        {
            return compactBadge
                ? Math.Max(48, 54 * _calendarZoom)
                : Math.Max(72, 84 * _calendarZoom);
        }

        private void UpdateCalendarChecklistVisuals(
            IEnumerable<string> pageIds)
        {
            if (pageIds == null)
                return;

            foreach (var pageId in
                     pageIds
                         .Where(id =>
                             !string.IsNullOrWhiteSpace(id))
                         .Distinct(
                             StringComparer.OrdinalIgnoreCase))
            {
                if (!_calendarActivityVisuals.TryGetValue(
                        pageId,
                        out var visuals))
                {
                    continue;
                }

                var activity =
                    _calendarActivities
                        .FirstOrDefault(item =>
                            string.Equals(
                                item.PageId,
                                pageId,
                                StringComparison.OrdinalIgnoreCase));

                if (activity == null)
                    continue;

                foreach (var visual in visuals)
                {
                    UpdateCalendarProgressVisual(
                        visual,
                        activity);
                }
            }
        }

        private static string GetCalendarPhaseBadgeLabel(
            NotionCalendarActivity activity)
        {
            if (activity == null)
                return string.Empty;

            if (HasExactCalendarPhase(activity, "sprtuzREVISION"))
                return "SP";

            if (HasExactCalendarPhase(activity, "aprtuzREVISION"))
                return "AP";

            if (HasExactCalendarPhase(activity, "prtuzREVISION"))
                return "P";

            if (HasExactCalendarPhase(activity, "rtuzREVISION"))
                return "R";

            if (HasExactCalendarPhase(activity, "zREVISION"))
                return "Z";

            return string.Empty;
        }

        private static (Color Background, Color Border, Color Foreground)
            GetCalendarPhaseBadgeColors(string label)
        {
            return (label ?? string.Empty).ToUpperInvariant() switch
            {
                "P" => (
                    Color.FromArgb(235, 69, 48, 8),
                    Color.FromArgb(255, 245, 158, 11),
                    Color.FromArgb(255, 253, 230, 138)),
                "R" => (
                    Color.FromArgb(235, 6, 78, 59),
                    Color.FromArgb(255, 52, 211, 153),
                    Color.FromArgb(255, 167, 243, 208)),
                "Z" => (
                    Color.FromArgb(235, 8, 47, 73),
                    Color.FromArgb(255, 56, 189, 248),
                    Color.FromArgb(255, 186, 230, 253)),
                "SP" => (
                    Color.FromArgb(235, 59, 7, 100),
                    Color.FromArgb(255, 192, 132, 252),
                    Color.FromArgb(255, 233, 213, 255)),
                "AP" => (
                    Color.FromArgb(235, 30, 41, 59),
                    Color.FromArgb(255, 148, 163, 184),
                    Color.FromArgb(255, 226, 232, 240)),
                _ => (
                    Color.FromArgb(220, 30, 41, 59),
                    Color.FromArgb(255, 100, 116, 139),
                    Color.FromArgb(255, 226, 232, 240))
            };
        }

        private string GetCalendarCardDisplayTitle(
            NotionCalendarActivity activity)
        {
            if (activity == null)
                return "Actividad sin título";

            var parts = new List<string>();

            if (TryGetWhatsAppCalendarProjectType(
                    activity,
                    out _,
                    out var projectLabel) &&
                !string.IsNullOrWhiteSpace(projectLabel))
            {
                parts.Add(projectLabel.Trim());
            }

            var domain =
                NormalizeCalendarProjectDomain(
                    TryExtractFirstDomain(
                        BuildCalendarSearchRow(activity)));

            if (!string.IsNullOrWhiteSpace(domain))
                parts.Add(domain);

            var compactTitle =
                GetCalendarCompactActivityTitle(activity);

            if (!string.IsNullOrWhiteSpace(compactTitle))
                parts.Add(compactTitle);

            return string.Join(
                " · ",
                parts
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .Distinct(StringComparer.OrdinalIgnoreCase));
        }

        private void AddActivityButton(
            NotionCalendarActivity activity,
            string person,
            double headerHeight,
            int lane,
            int laneCount,
            int overlapCount,
            int sequenceIndex,
            IReadOnlyList<NotionCalendarActivity>? overlapItems = null)
        {
            var dayStart =
                _calendarSelectedDate.Date.AddHours(CalendarStartHour);

            var dayEnd =
                _calendarSelectedDate.Date.AddHours(
                    CalendarVisibleEndHour);

            var visibleStart =
                activity.Start < dayStart ? dayStart : activity.Start;

            var visibleEnd =
                activity.End > dayEnd ? dayEnd : activity.End;

            if (visibleEnd <= dayStart ||
                visibleStart >= dayEnd)
            {
                return;
            }

            var minutesFromStart =
                (visibleStart - dayStart).TotalMinutes;

            var durationMinutes =
                Math.Max(
                    30,
                    (visibleEnd - visibleStart).TotalMinutes);

            var columnWidth =
                GetResolvedCalendarColumnWidth(person);

            var columnLeft =
                GetResolvedCalendarColumnLeft(person);

            var usableWidth =
                Math.Max(20, columnWidth - 10);

            var safeLaneCount =
                Math.Max(1, laneCount);

            var safeLane =
                Math.Clamp(
                    lane,
                    0,
                    safeLaneCount - 1);

            // Identidad visible dentro de un empalme. El antiguo +1/+2
            // indicaba cuántas tarjetas había detrás, pero no permitía saber
            // cuál se estaba inspeccionando. Ahora cada tarjeta conoce su
            // posición real (1/3, 2/3, 3/3) dentro del grupo que comparte hora.
            var orderedOverlapItems =
                (overlapItems ?? Array.Empty<NotionCalendarActivity>())
                    .Where(item => item != null)
                    .GroupBy(
                        item => string.IsNullOrWhiteSpace(item.PageId)
                            ? $"{item.Title}|{item.Start:O}|{item.End:O}"
                            : item.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .OrderBy(item => item.Start)
                    .ThenBy(item => item.End)
                    .ThenBy(item => item.Title)
                    .ToList();

            var overlapTotal =
                Math.Max(
                    Math.Max(1, overlapCount),
                    orderedOverlapItems.Count);

            var overlapPosition = 1;

            if (overlapTotal > 1)
            {
                var foundIndex =
                    orderedOverlapItems.FindIndex(item =>
                        string.Equals(
                            item.PageId,
                            activity.PageId,
                            StringComparison.OrdinalIgnoreCase) ||
                        (string.IsNullOrWhiteSpace(item.PageId) &&
                         string.Equals(
                             item.Title,
                             activity.Title,
                             StringComparison.OrdinalIgnoreCase) &&
                         item.Start == activity.Start &&
                         item.End == activity.End));

                overlapPosition =
                    foundIndex >= 0
                        ? foundIndex + 1
                        : Math.Clamp(
                            sequenceIndex + 1,
                            1,
                            overlapTotal);
            }

            // Empalmes adaptativos. Dos actividades solo se dividen lado a
            // lado cuando cada una conserva ancho legible. En zoom panorámico
            // (70–80%) o columnas estrechas se usa el mismo abanico de 3+ para
            // evitar dos tarjetas diminutas peleando por badges/texto.
            var prospectiveTwoLaneWidth =
                safeLaneCount == 2
                    ? usableWidth / 2d - 4
                    : double.MaxValue;

            var minimumTwoLaneReadableWidth =
                _calendarZoom <= 0.80
                    ? 112d
                    : 104d;

            var useStackedLayout =
                safeLaneCount >= 3 ||
                (safeLaneCount == 2 &&
                 prospectiveTwoLaneWidth <
                    minimumTwoLaneReadableWidth);

            double cardWidth;
            double left;

            if (!useStackedLayout)
            {
                var laneWidth =
                    usableWidth / safeLaneCount;

                cardWidth =
                    Math.Max(
                        8,
                        laneWidth - 4);

                left =
                    columnLeft +
                    5 +
                    safeLane * laneWidth;
            }
            else
            {
                // Abanico más visible: deja una franja suficiente de cada
                // tarjeta para poder apuntarla con el cursor aunque otra esté
                // por encima. Hover la trae al frente y clic la fija.
                var desiredOffset =
                    Math.Clamp(
                        20 * _calendarZoom,
                        14,
                        24);

                var minimumReadableWidth =
                    safeLaneCount == 2
                        ? Math.Min(
                            Math.Max(
                                82,
                                92 * _calendarZoom),
                            usableWidth * 0.82)
                        : Math.Min(
                            Math.Max(
                                58,
                                66 * _calendarZoom),
                            usableWidth * 0.62);

                var maximumOffset =
                    safeLaneCount <= 1
                        ? 0
                        : Math.Max(
                            2,
                            (usableWidth -
                             minimumReadableWidth -
                             4) /
                            (safeLaneCount - 1));

                var stackOffset =
                    Math.Min(
                        desiredOffset,
                        maximumOffset);

                cardWidth =
                    Math.Max(
                        34,
                        usableWidth -
                        stackOffset *
                        (safeLaneCount - 1) -
                        4);

                left =
                    columnLeft +
                    5 +
                    safeLane * stackOffset;
            }

            var top =
                headerHeight +
                minutesFromStart / 60d *
                CalendarHourHeight +
                3;

            var height =
                Math.Max(
                    34 * _calendarZoom,
                    durationMinutes / 60d *
                    CalendarHourHeight -
                    5);

            var phaseBadgeLabel =
                GetCalendarPhaseBadgeLabel(activity);

            // La tarjeta cambia de densidad según SU espacio real. Además,
            // 70–80% se trata deliberadamente como vista panorámica: muestra
            // identificación/progreso y deja el detalle completo para clic.
            var overviewMode =
                _calendarZoom <= 0.80;

            var ultraMiniCard =
                cardWidth < 78 ||
                height < 40;

            var miniCard =
                overviewMode ||
                useStackedLayout ||
                cardWidth < 105 ||
                height < 50;

            var mediumCard =
                !miniCard &&
                (cardWidth < 150 ||
                 height < 88);

            var fullCard =
                !miniCard &&
                !mediumCard;

            var phaseBadgeWidth =
                string.IsNullOrWhiteSpace(phaseBadgeLabel)
                    ? 0
                    : miniCard
                        ? phaseBadgeLabel.Length > 1
                            ? Math.Max(19, 20 * _calendarZoom)
                            : Math.Max(14, 15 * _calendarZoom)
                        : phaseBadgeLabel.Length > 1
                            ? Math.Max(22, 23 * _calendarZoom)
                            : Math.Max(17, 18 * _calendarZoom);

            // Se conserva por compatibilidad con la actualización incremental,
            // pero ya no hay overlays que obliguen a desplazar el título.
            var phaseTitleReserve = 0d;

            TryGetWhatsAppCalendarProjectType(
                activity,
                out _,
                out var projectTypeLabel);

            projectTypeLabel =
                (projectTypeLabel ?? string.Empty)
                .Trim()
                .ToUpperInvariant();

            var domainLabel =
                NormalizeCalendarProjectDomain(
                    TryExtractFirstDomain(
                        BuildCalendarSearchRow(activity)));

            if (string.IsNullOrWhiteSpace(domainLabel))
            {
                domainLabel =
                    (activity.Project ?? string.Empty)
                    .Trim();
            }

            var descriptionLabel =
                GetCalendarCompactActivityTitle(activity);

            // Si la limpieza técnica deja un título pobre, usa primero textos
            // realmente útiles de la actividad antes de volver al título crudo.
            if (string.IsNullOrWhiteSpace(descriptionLabel) ||
                descriptionLabel.Length < 4 ||
                string.Equals(
                    descriptionLabel,
                    domainLabel,
                    StringComparison.OrdinalIgnoreCase))
            {
                descriptionLabel =
                    !string.IsNullOrWhiteSpace(activity.UpdateText)
                        ? activity.UpdateText.Trim()
                        : !string.IsNullOrWhiteSpace(activity.Description)
                            ? activity.Description.Trim()
                            : (activity.Title ?? "Actividad").Trim();
            }

            var calendarChecklist =
                GetCalendarChecklistStats(activity);

            var hasCalendarChecklist =
                activity.ChecklistScanned &&
                calendarChecklist.HasChecklist;

            // En mini/medium el porcentaje completo se omite para preservar el
            // dominio y la actividad. El popup conserva siempre el dato completo.
            var compactBadge =
                miniCard ||
                mediumCard ||
                cardWidth < 165;

            var checklistBadgeText =
                BuildCalendarChecklistBadgeText(
                    activity,
                    compactBadge,
                    ultraMiniCard);

            var checklistText =
                new TextBlock
                {
                    Text = checklistBadgeText,
                    FontSize = Math.Max(
                        7.6,
                        (compactBadge ? 8.0 : 8.5) *
                        CalendarFontScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.Bold,
                    Foreground = new SolidColorBrush(
                        !activity.ChecklistScanned
                            ? Color.FromArgb(255, 186, 230, 253)
                            : hasCalendarChecklist
                                ? Color.FromArgb(255, 134, 239, 172)
                                : Color.FromArgb(220, 203, 213, 225)),
                    HorizontalAlignment =
                        HorizontalAlignment.Center,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    TextAlignment = TextAlignment.Center,
                    MaxLines = 1,
                    TextWrapping = TextWrapping.NoWrap,
                    TextTrimming =
                        TextTrimming.CharacterEllipsis,
                    IsHitTestVisible = false
                };

            var checklistBadge = new Border
            {
                MinWidth =
                    miniCard
                        ? Math.Max(30, 34 * _calendarZoom)
                        : compactBadge
                            ? Math.Max(34, 38 * _calendarZoom)
                            : Math.Max(52, 58 * _calendarZoom),
                Height =
                    miniCard
                        ? Math.Max(15, 17 * _calendarZoom)
                        : Math.Max(17, 19 * _calendarZoom),
                Padding =
                    miniCard
                        ? new Thickness(3, 0, 3, 0)
                        : compactBadge
                            ? new Thickness(4, 0, 4, 0)
                            : new Thickness(5, 0, 5, 0),
                HorizontalAlignment =
                    HorizontalAlignment.Right,
                VerticalAlignment =
                    VerticalAlignment.Center,
                CornerRadius = new CornerRadius(7),
                Background = new SolidColorBrush(
                    !activity.ChecklistScanned
                        ? Color.FromArgb(205, 15, 31, 45)
                        : hasCalendarChecklist
                            ? Color.FromArgb(205, 11, 38, 31)
                            : Color.FromArgb(95, 51, 65, 85)),
                BorderBrush = new SolidColorBrush(
                    !activity.ChecklistScanned
                        ? Color.FromArgb(255, 125, 211, 252)
                        : hasCalendarChecklist
                            ? Color.FromArgb(255, 74, 222, 128)
                            : Color.FromArgb(150, 148, 163, 184)),
                BorderThickness = new Thickness(1),
                Child = checklistText,
                Visibility =
                    string.IsNullOrWhiteSpace(checklistBadgeText)
                        ? Visibility.Collapsed
                        : Visibility.Visible,
                IsHitTestVisible = false
            };

            ToolTipService.SetToolTip(
                checklistBadge,
                activity.ChecklistScanned
                    ? calendarChecklist.HasChecklist
                        ? $"ACT: {calendarChecklist.Completed}/{calendarChecklist.Total} · {GetChecklistPercentage(calendarChecklist)}%"
                        : "ACT: checklist revisado · sin tareas activas"
                    : "ACT: calculando checklist…");

            // HOY: el más importante visualmente.
            var todayProgressText =
                new TextBlock
                {
                    Text =
                        BuildCalendarTodayProgressBadgeText(
                            activity,
                            ultraMiniCard,
                            out var todayProgressTooltip),
                    FontSize = Math.Max(
                        6.8,
                        (ultraMiniCard ? 6.9 : 7.6) *
                        CalendarFontScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.Bold,
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255, 186, 230, 253)),
                    HorizontalAlignment =
                        HorizontalAlignment.Center,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    TextAlignment =
                        TextAlignment.Center,
                    MaxLines = 1,
                    TextWrapping =
                        TextWrapping.NoWrap,
                    IsHitTestVisible = false
                };

            var todayProgressBadge =
                new Border
                {
                    MinWidth = 0,
                    Height =
                        ultraMiniCard
                            ? Math.Max(
                                10,
                                11.5 * _calendarZoom)
                            : miniCard
                                ? Math.Max(
                                    11,
                                    13 * _calendarZoom)
                                : Math.Max(
                                    14,
                                    16 * _calendarZoom),
                    Padding =
                        ultraMiniCard
                            ? new Thickness(
                                1, 0, 1, 0)
                            : miniCard
                                ? new Thickness(
                                    1.5, 0, 1.5, 0)
                                : new Thickness(
                                    2, 0, 2, 0),
                    Margin =
                        new Thickness(
                            0, 0, 1, 0),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    CornerRadius =
                        new CornerRadius(6),
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                225, 7, 45, 66)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255, 56, 189, 248)),
                    BorderThickness =
                        new Thickness(1),
                    Child =
                        todayProgressText,
                    IsHitTestVisible = false
                };

            ToolTipService.SetToolTip(
                todayProgressBadge,
                todayProgressTooltip);

            var projectProgressText =
                new TextBlock
                {
                    Text =
                        BuildCalendarProjectProgressBadgeText(
                            activity,
                            ultraMiniCard,
                            out var projectProgressTooltip),
                    FontSize = Math.Max(
                        6.0,
                        (ultraMiniCard ? 6.1 : miniCard ? 6.5 : 7.1) *
                        CalendarFontScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.Bold,
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255, 221, 214, 254)),
                    HorizontalAlignment =
                        HorizontalAlignment.Center,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    TextAlignment =
                        TextAlignment.Center,
                    MaxLines = 1,
                    TextWrapping =
                        TextWrapping.NoWrap,
                    IsHitTestVisible = false
                };

            var projectProgressBadge =
                new Border
                {
                    MinWidth = 0,
                    Height =
                        miniCard
                            ? Math.Max(
                                14,
                                16 * _calendarZoom)
                            : Math.Max(
                                16,
                                18 * _calendarZoom),
                    Padding =
                        ultraMiniCard
                            ? new Thickness(
                                1, 0, 1, 0)
                            : new Thickness(
                                3, 0, 3, 0),
                    Margin =
                        new Thickness(
                            1, 0, 0, 0),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    CornerRadius =
                        new CornerRadius(6),
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                205, 38, 23, 61)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                235, 168, 85, 247)),
                    BorderThickness =
                        new Thickness(1),
                    Child =
                        projectProgressText,
                    Visibility =
                        string.IsNullOrWhiteSpace(
                            projectProgressText.Text)
                            ? Visibility.Collapsed
                            : Visibility.Visible,
                    IsHitTestVisible = false
                };

            ToolTipService.SetToolTip(
                projectProgressBadge,
                projectProgressTooltip);

            // ACT debe compartir el mismo ancho que HOY/PROY.
            checklistBadge.MinWidth = 0;
            checklistBadge.HorizontalAlignment =
                HorizontalAlignment.Stretch;

            // Calculamos el ancho NATURAL de cada indicador.
            // No se reparten 1/3-1/3-1/3 porque A 23/23 necesita más espacio
            // que H 0%, y eso era lo que provocaba textos como "A 23...".
            static double EstimateProgressBadgeWidth(
                string? value,
                bool ultra)
            {
                var text =
                    value ??
                    string.Empty;

                var charWidth =
                    ultra
                        ? 4.4d
                        : 5.1d;

                return Math.Max(
                    ultra
                        ? 21d
                        : 27d,
                    text.Length * charWidth +
                    (ultra
                        ? 6d
                        : 10d));
            }

            var todayNaturalWidth =
                EstimateProgressBadgeWidth(
                    todayProgressText.Text,
                    ultraMiniCard);

            var activityNaturalWidth =
                EstimateProgressBadgeWidth(
                    checklistText.Text,
                    ultraMiniCard);

            var hasProjectProgress =
                !string.IsNullOrWhiteSpace(
                    projectProgressText.Text);

            var projectNaturalWidth =
                hasProjectProgress
                    ? EstimateProgressBadgeWidth(
                        projectProgressText.Text,
                        ultraMiniCard)
                    : 0d;

            var oneRowNaturalWidth =
                todayNaturalWidth +
                activityNaturalWidth +
                (hasProjectProgress
                    ? projectNaturalWidth + 4d
                    : 2d);

            var oneRowAvailableWidth =
                Math.Clamp(
                    cardWidth *
                    (ultraMiniCard
                        ? 0.72
                        : miniCard
                            ? 0.68
                            : 0.62),
                    ultraMiniCard
                        ? 42d
                        : 86d,
                    ultraMiniCard
                        ? 94d
                        : 150d);

            // Si el texto real no entra, P baja. También se baja antes en cards
            // medianas para conservar dominio/título sin apretarlos.
            var wrapProgressStrip =
                oneRowNaturalWidth >
                    oneRowAvailableWidth ||
                cardWidth <
                    (ultraMiniCard
                        ? 112d
                        : miniCard
                            ? 178d
                            : 188d);

            var topRowNaturalWidth =
                todayNaturalWidth +
                activityNaturalWidth +
                2d;

            var wrappedNaturalWidth =
                Math.Max(
                    topRowNaturalWidth,
                    projectNaturalWidth);

            var progressStrip =
                new Grid
                {
                    Width =
                        wrapProgressStrip
                            ? Math.Min(
                                Math.Max(
                                    ultraMiniCard
                                        ? 38d
                                        : 62d,
                                    wrappedNaturalWidth),
                                Math.Max(
                                    ultraMiniCard
                                        ? 42d
                                        : 70d,
                                    cardWidth *
                                    (ultraMiniCard
                                        ? 0.72
                                        : 0.62)))
                            : Math.Min(
                                oneRowNaturalWidth,
                                oneRowAvailableWidth),
                    ColumnSpacing = 1,
                    RowSpacing =
                        wrapProgressStrip
                            ? 1
                            : 0,
                    HorizontalAlignment =
                        HorizontalAlignment.Right,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    IsHitTestVisible = false
                };

            if (wrapProgressStrip)
            {
                // Auto/Auto: cada badge recibe el ancho que realmente necesita.
                progressStrip.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            GridLength.Auto
                    });

                progressStrip.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            GridLength.Auto
                    });

                progressStrip.RowDefinitions.Add(
                    new RowDefinition
                    {
                        Height = GridLength.Auto
                    });

                progressStrip.RowDefinitions.Add(
                    new RowDefinition
                    {
                        Height = GridLength.Auto
                    });

                var wrappedBadgeHeight =
                    ultraMiniCard
                        ? Math.Max(
                            10,
                            11.5 * _calendarZoom)
                        : Math.Max(
                            12,
                            14 * _calendarZoom);

                todayProgressBadge.Height =
                    wrappedBadgeHeight;

                checklistBadge.Height =
                    wrappedBadgeHeight;

                projectProgressBadge.Height =
                    wrappedBadgeHeight;

                todayProgressBadge.Margin =
                    new Thickness(
                        0, 0, 1, 0);

                checklistBadge.Margin =
                    new Thickness(
                        1, 0, 0, 0);

                projectProgressBadge.Margin =
                    new Thickness(
                        0, 0, 0, 0);

                Grid.SetColumn(
                    todayProgressBadge,
                    0);

                Grid.SetRow(
                    todayProgressBadge,
                    0);

                progressStrip.Children.Add(
                    todayProgressBadge);

                Grid.SetColumn(
                    checklistBadge,
                    1);

                Grid.SetRow(
                    checklistBadge,
                    0);

                progressStrip.Children.Add(
                    checklistBadge);

                Grid.SetColumn(
                    projectProgressBadge,
                    0);

                Grid.SetColumnSpan(
                    projectProgressBadge,
                    2);

                Grid.SetRow(
                    projectProgressBadge,
                    1);

                projectProgressBadge.HorizontalAlignment =
                    HorizontalAlignment.Stretch;

                progressStrip.Children.Add(
                    projectProgressBadge);
            }
            else
            {
                checklistBadge.Margin =
                    new Thickness(
                        1, 0, 1, 0);

                // Auto/Auto/Auto evita truncar ACT cuando el conteo tiene
                // más dígitos que HOY o PROY.
                progressStrip.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            GridLength.Auto
                    });

                progressStrip.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            GridLength.Auto
                    });

                progressStrip.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            GridLength.Auto
                    });

                Grid.SetColumn(
                    todayProgressBadge,
                    0);

                progressStrip.Children.Add(
                    todayProgressBadge);

                Grid.SetColumn(
                    checklistBadge,
                    1);

                progressStrip.Children.Add(
                    checklistBadge);

                Grid.SetColumn(
                    projectProgressBadge,
                    2);

                progressStrip.Children.Add(
                    projectProgressBadge);
            }

            var phaseBadge = new Border
            {
                MinWidth = phaseBadgeWidth,
                Height = miniCard
                    ? Math.Max(14, 15.5 * _calendarZoom)
                    : Math.Max(16, 18 * _calendarZoom),
                Padding = new Thickness(
                    miniCard
                        ? phaseBadgeLabel.Length > 1 ? 3 : 1
                        : phaseBadgeLabel.Length > 1 ? 4 : 2,
                    0,
                    miniCard
                        ? phaseBadgeLabel.Length > 1 ? 3 : 1
                        : phaseBadgeLabel.Length > 1 ? 4 : 2,
                    0),
                HorizontalAlignment =
                    HorizontalAlignment.Left,
                VerticalAlignment =
                    VerticalAlignment.Center,
                CornerRadius = new CornerRadius(5),
                Visibility =
                    string.IsNullOrWhiteSpace(phaseBadgeLabel)
                        ? Visibility.Collapsed
                        : Visibility.Visible,
                IsHitTestVisible = false
            };

            if (!string.IsNullOrWhiteSpace(phaseBadgeLabel))
            {
                var phaseColors =
                    GetCalendarPhaseBadgeColors(phaseBadgeLabel);

                phaseBadge.Background =
                    new SolidColorBrush(phaseColors.Background);
                phaseBadge.BorderBrush =
                    new SolidColorBrush(phaseColors.Border);
                phaseBadge.BorderThickness =
                    new Thickness(1);
                phaseBadge.Child =
                    new TextBlock
                    {
                        Text = phaseBadgeLabel,
                        FontSize = Math.Max(
                            miniCard ? 6.8 : 7.4,
                            (miniCard ? 7.1 : 7.8) *
                            CalendarFontScale),
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.Bold,
                        Foreground =
                            new SolidColorBrush(
                                phaseColors.Foreground),
                        HorizontalAlignment =
                            HorizontalAlignment.Center,
                        VerticalAlignment =
                            VerticalAlignment.Center,
                        TextAlignment = TextAlignment.Center,
                        MaxLines = 1,
                        IsHitTestVisible = false
                    };
            }

            var typeText = new TextBlock
            {
                Text = projectTypeLabel,
                FontSize = Math.Max(
                    miniCard ? 7.0 : 7.7,
                    (miniCard ? 7.3 : 8.5) *
                    CalendarFontScale),
                FontWeight =
                    Microsoft.UI.Text.FontWeights.SemiBold,
                Opacity = 0.88,
                MaxLines = 1,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                VerticalAlignment =
                    VerticalAlignment.Center,
                IsHitTestVisible = false
            };

            var headerRow = new Grid
            {
                ColumnSpacing = miniCard
                    ? Math.Max(2, 2.5 * _calendarZoom)
                    : Math.Max(3, 4 * _calendarZoom),
                HorizontalAlignment = HorizontalAlignment.Stretch,
                IsHitTestVisible = false
            };

            headerRow.ColumnDefinitions.Add(
                new ColumnDefinition { Width = GridLength.Auto });
            headerRow.ColumnDefinitions.Add(
                new ColumnDefinition { Width = GridLength.Auto });
            headerRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });
            headerRow.ColumnDefinitions.Add(
                new ColumnDefinition { Width = GridLength.Auto });


            var domainText = new TextBlock
            {
                Text = domainLabel,
                FontSize = Math.Max(
                    8.1,
                    (miniCard ? 8.5 : 9.2) *
                    CalendarFontScale),
                FontWeight =
                    Microsoft.UI.Text.FontWeights.SemiBold,
                Opacity = 0.96,
                MaxLines = 1,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                TextWrapping = TextWrapping.NoWrap,
                Visibility =
                    string.IsNullOrWhiteSpace(domainLabel)
                        ? Visibility.Collapsed
                        : Visibility.Visible,
                IsHitTestVisible = false
            };

            // TitleText continúa siendo la referencia del render incremental.
            // Ahora representa la descripción útil, no una mezcla de badges.
            var titleText = new TextBlock
            {
                Text = descriptionLabel,
                FontSize = Math.Max(
                    7.6,
                    (miniCard
                        ? 8.0
                        : mediumCard
                            ? 8.6
                            : 9.2) *
                    CalendarFontScale),
                FontWeight =
                    Microsoft.UI.Text.FontWeights.Normal,
                Opacity = 0.84,
                MaxLines = fullCard ? 2 : 1,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                TextWrapping =
                    fullCard
                        ? TextWrapping.Wrap
                        : TextWrapping.NoWrap,
                Visibility =
                    miniCard ||
                    ultraMiniCard ||
                    (!fullCard && height < 62) ||
                    string.IsNullOrWhiteSpace(descriptionLabel)
                        ? Visibility.Collapsed
                        : Visibility.Visible,
                IsHitTestVisible = false
            };

            var movementBadge =
                GetCalendarDayMovementBadge(
                    activity);

            var movementCompactBadge =
                GetCalendarDayMovementCompactBadge(
                    activity);

            var timeText = new TextBlock
            {
                Text =
                    !string.IsNullOrWhiteSpace(
                        movementBadge) &&
                    height < 82
                        ? $"{activity.TimeLabel} · {movementBadge}"
                        : activity.TimeLabel,
                FontSize = Math.Max(
                    7.5,
                    (miniCard ? 7.8 : 8.3) *
                    CalendarFontScale),
                Opacity = 0.76,
                MaxLines = 1,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                VerticalAlignment =
                    VerticalAlignment.Center,
                IsHitTestVisible = false
            };

            var overdueMinutes =
                GetCalendarOverdueMinutes(activity);

            var overdueText = new TextBlock
            {
                Text = overdueMinutes > 0
                    ? $"⚠ {FormatCalendarDelayMinutes(overdueMinutes)}"
                    : string.Empty,
                FontSize = Math.Max(
                    7.2,
                    7.7 * CalendarFontScale),
                FontWeight =
                    Microsoft.UI.Text.FontWeights.SemiBold,
                Foreground = new SolidColorBrush(
                    Color.FromArgb(255, 248, 113, 113)),
                Opacity = 0.96,
                MaxLines = 1,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                HorizontalAlignment =
                    HorizontalAlignment.Right,
                VerticalAlignment =
                    VerticalAlignment.Center,
                Visibility =
                    !miniCard &&
                    overdueMinutes > 0 &&
                    cardWidth >= 105
                        ? Visibility.Visible
                        : Visibility.Collapsed,
                IsHitTestVisible = false
            };

            var metaRow = new Grid
            {
                ColumnSpacing = 5,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                IsHitTestVisible = false
            };

            metaRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });
            metaRow.ColumnDefinitions.Add(
                new ColumnDefinition { Width = GridLength.Auto });

            Grid.SetColumn(timeText, 0);
            metaRow.Children.Add(timeText);
            Grid.SetColumn(overdueText, 1);
            metaRow.Children.Add(overdueText);

            var content = new StackPanel
            {
                Spacing = miniCard
                    ? Math.Max(0, 0.5 * _calendarZoom)
                    : Math.Max(1, 1.5 * _calendarZoom),
                IsHitTestVisible = false
            };

            if (ultraMiniCard)
            {
                // Actividades de 15–30 min no tienen altura suficiente para
                // tres filas. Antes se recortaban y parecían una simple línea.
                // En este modo se usa UNA sola fila informativa: fase +
                // tipo/dominio + checklist. La posición vertical ya comunica
                // la hora y el detalle completo sigue disponible al hacer clic.
                var shortRow = new Grid
                {
                    ColumnSpacing = Math.Max(2, 2.5 * _calendarZoom),
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    VerticalAlignment = VerticalAlignment.Center,
                    IsHitTestVisible = false
                };

                shortRow.ColumnDefinitions.Add(
                    new ColumnDefinition { Width = GridLength.Auto });
                shortRow.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(1, GridUnitType.Star)
                    });
                shortRow.ColumnDefinitions.Add(
                    new ColumnDefinition { Width = GridLength.Auto });

                var shortIdentity =
                    string.Join(
                        " · ",
                        new[]
                        {
                            projectTypeLabel,
                            domainLabel
                        }.Where(value =>
                            !string.IsNullOrWhiteSpace(value)));

                if (string.IsNullOrWhiteSpace(shortIdentity))
                {
                    shortIdentity =
                        string.IsNullOrWhiteSpace(descriptionLabel)
                            ? "Actividad"
                            : descriptionLabel;
                }

                var shortIdentityDisplay =
                    string.IsNullOrWhiteSpace(
                        movementCompactBadge)
                        ? shortIdentity
                        : $"{movementCompactBadge} · {shortIdentity}";

                var shortIdentityText = new TextBlock
                {
                    Text = shortIdentityDisplay,
                    FontSize = Math.Max(
                        7.2,
                        7.7 * CalendarFontScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    Opacity = 0.94,
                    MaxLines = 1,
                    TextWrapping = TextWrapping.NoWrap,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    VerticalAlignment = VerticalAlignment.Center,
                    IsHitTestVisible = false
                };

                Grid.SetColumn(phaseBadge, 0);
                shortRow.Children.Add(phaseBadge);

                Grid.SetColumn(shortIdentityText, 1);
                shortRow.Children.Add(shortIdentityText);

                // PRIORIDAD DE MEET: incluso en 15–30 min deben verse los
                // tres avances. El indicador de empalme pasa al texto central.
                if (overlapTotal > 1)
                {
                    shortIdentityText.Text =
                        $"{shortIdentityDisplay} · {overlapPosition}/{overlapTotal}";
                }

                if (cardWidth < 112)
                {
                    // En cards extremadamente angostas H/A/P usan todo el ancho
                    // INTERNO disponible. Nunca alteran cardWidth.
                    progressStrip.Width =
                        Math.Max(
                            30,
                            cardWidth -
                            8);

                    progressStrip.HorizontalAlignment =
                        HorizontalAlignment.Stretch;

                    Grid.SetColumn(
                        progressStrip,
                        0);

                    Grid.SetColumnSpan(
                        progressStrip,
                        3);

                    shortRow.Children.Add(
                        progressStrip);
                }
                else
                {
                    Grid.SetColumn(
                        progressStrip,
                        2);

                    shortRow.Children.Add(
                        progressStrip);
                }

                content.Children.Add(shortRow);
            }
            else
            {
                Grid.SetColumn(phaseBadge, 0);
                headerRow.Children.Add(phaseBadge);

                Grid.SetColumn(typeText, 1);
                headerRow.Children.Add(typeText);

                Grid.SetColumn(progressStrip, 3);
                headerRow.Children.Add(progressStrip);

                content.Children.Add(headerRow);
                content.Children.Add(domainText);
                content.Children.Add(titleText);
                content.Children.Add(metaRow);
            }

            if (!miniCard &&
                !string.IsNullOrWhiteSpace(movementBadge) &&
                height >= 82)
            {
                content.Children.Add(
                    new TextBlock
                    {
                        Text = movementBadge,
                        FontSize = 7.7 * CalendarFontScale,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    255, 125, 211, 252)),
                        Opacity = 0.92,
                        MaxLines = 1,
                        TextTrimming =
                            TextTrimming.CharacterEllipsis,
                        IsHitTestVisible = false
                    });
            }

            if (activity.IsAutomationLocked &&
                !miniCard &&
                height >= 92)
            {
                content.Children.Add(
                    new TextBlock
                    {
                        Text = "🔒 Bloqueada",
                        FontSize = 7.7 * CalendarFontScale,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Foreground = new SolidColorBrush(
                            Color.FromArgb(255, 216, 180, 254)),
                        Opacity = 0.90,
                        MaxLines = 1,
                        TextTrimming =
                            TextTrimming.CharacterEllipsis,
                        IsHitTestVisible = false
                    });
            }

            if (string.Equals(
                    person,
                    "Sin asignar",
                    StringComparison.OrdinalIgnoreCase) &&
                ContainsAnyCalendarPersonTag(activity.Title) &&
                fullCard)
            {
                content.Children.Add(
                    new TextBlock
                    {
                        Text = "Tag activo no reconocido",
                        FontSize = 7.6 * CalendarFontScale,
                        Opacity = 0.82,
                        MaxLines = 1,
                        TextTrimming =
                            TextTrimming.CharacterEllipsis,
                        IsHitTestVisible = false
                    });
            }

            if (fullCard &&
                !string.IsNullOrWhiteSpace(
                    activity.ReviewBadgeLabel) &&
                height >= 110)
            {
                content.Children.Add(
                    new TextBlock
                    {
                        Text = activity.ReviewBadgeLabel,
                        FontSize = 7.7 * CalendarFontScale,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Opacity = 0.84,
                        MaxLines = 1,
                        TextTrimming =
                            TextTrimming.CharacterEllipsis,
                        IsHitTestVisible = false
                    });
            }

            var workTimerBadgeText =
                BuildCalendarWorkTimerBadgeText(activity);

            var workTimerText =
                new TextBlock
                {
                    Text = workTimerBadgeText,
                    FontSize = Math.Max(
                        7.3,
                        7.8 * CalendarFontScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.Bold,
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255, 224, 242, 254)),
                    HorizontalAlignment =
                        HorizontalAlignment.Center,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    TextAlignment = TextAlignment.Center,
                    MaxLines = 1,
                    IsHitTestVisible = false
                };

            var workTimerBadge = new Border
            {
                MinWidth = Math.Max(42, 48 * _calendarZoom),
                Height = Math.Max(16, 18 * _calendarZoom),
                Padding = new Thickness(4, 0, 4, 0),
                HorizontalAlignment = HorizontalAlignment.Left,
                VerticalAlignment = VerticalAlignment.Center,
                CornerRadius = new CornerRadius(7),
                Background =
                    new SolidColorBrush(
                        GetCalendarWorkBadgeColors(activity).Background),
                BorderBrush =
                    new SolidColorBrush(
                        GetCalendarWorkBadgeColors(activity).Border),
                BorderThickness = new Thickness(1),
                Child = workTimerText,
                Visibility =
                    string.IsNullOrWhiteSpace(workTimerBadgeText)
                        ? Visibility.Collapsed
                        : Visibility.Visible,
                IsHitTestVisible = false
            };

            var activityDayRange =
                !miniCard &&
                height >= 80
                    ? BuildActivityDayRangeIndicator(
                        activity,
                        cardWidth,
                        height,
                        mediumCard || cardWidth < 125)
                    : null;

            if (activityDayRange != null ||
                workTimerBadge.Visibility == Visibility.Visible)
            {
                var progressFooter = new Grid
                {
                    ColumnSpacing = 5,
                    Margin = new Thickness(0, 1, 0, 0),
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    VerticalAlignment = VerticalAlignment.Bottom,
                    IsHitTestVisible = false
                };

                progressFooter.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });
                progressFooter.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(
                            1,
                            GridUnitType.Star)
                    });

                Grid.SetColumn(workTimerBadge, 0);
                progressFooter.Children.Add(workTimerBadge);

                if (activityDayRange != null)
                {
                    activityDayRange.Margin = new Thickness(0);
                    activityDayRange.VerticalAlignment =
                        VerticalAlignment.Center;
                    Grid.SetColumn(activityDayRange, 1);
                    progressFooter.Children.Add(activityDayRange);
                }

                content.Children.Add(progressFooter);
            }

            // rtuzREVISION conserva el microbadge R, pero además recupera un
            // fondo verde oscuro para poder localizar visualmente las revisiones
            // con un vistazo, tal como se pidió en Meet.
            var isRtuzCalendarActivity =
                HasExactCalendarPhase(
                    activity,
                    "rtuzREVISION");

            var cardContent = new Grid
            {
                IsHitTestVisible = false
            };

            cardContent.Children.Add(content);

            if (useStackedLayout &&
                overlapTotal > 1 &&
                !ultraMiniCard)
            {
                // 1/3, 2/3, 3/3 es mucho más útil que +2: permite saber qué
                // tarjeta del empalme está al frente y cuántas hay en total.
                var overlapBadge = new Border
                {
                    MinWidth = miniCard ? 25 : 29,
                    Height = Math.Max(15, 17 * _calendarZoom),
                    Padding = new Thickness(4, 0, 4, 0),
                    Margin = new Thickness(0, 0, 1, 1),
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Bottom,
                    CornerRadius = new CornerRadius(8),
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(228, 88, 28, 135)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(255, 192, 132, 252)),
                    BorderThickness = new Thickness(1),
                    Child = new TextBlock
                    {
                        Text = $"{overlapPosition}/{overlapTotal}",
                        FontSize = Math.Max(7.0, 7.5 * CalendarFontScale),
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.Bold,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(255, 233, 213, 255)),
                        HorizontalAlignment = HorizontalAlignment.Center,
                        VerticalAlignment = VerticalAlignment.Center,
                        TextAlignment = TextAlignment.Center,
                        MaxLines = 1,
                        IsHitTestVisible = false
                    },
                    IsHitTestVisible = false
                };

                cardContent.Children.Add(overlapBadge);
            }

            var activityPriority =
                GetOneClickPriorityInfo(
                    activity,
                    person);

            var baseZIndex =
                useStackedLayout
                    ? 20 +
                      Math.Min(
                          90,
                          safeLane * 6 +
                          sequenceIndex)
                    : 10;

            var button = new Button
            {
                Content = cardContent,
                Width = cardWidth,
                Height = height,
                Padding = new Thickness(
                    6 * _calendarZoom,
                    4 * _calendarZoom,
                    6 * _calendarZoom,
                    4 * _calendarZoom),
                HorizontalContentAlignment =
                    HorizontalAlignment.Stretch,
                VerticalContentAlignment =
                    VerticalAlignment.Top,
                Background =
                    isRtuzCalendarActivity
                        ? new SolidColorBrush(
                            Color.FromArgb(
                                235,
                                20,
                                70,
                                50))
                        : GetNeutralCalendarActivityBrush(
                            activity.Status,
                            activity.StatusColor),
                // rtuzREVISION usa fondo verde oscuro; el resto conserva el
                // fondo neutro. La franja izquierda sigue indicando prioridad.
                BorderBrush =
                    new SolidColorBrush(
                        activityPriority.Color),
                BorderThickness = new Thickness(4, 1, 1, 1),
                CornerRadius =
                    new CornerRadius(6 * _calendarZoom),
                Tag = activity
            };

            // Tooltip deliberadamente compacto: la información completa
            // sigue disponible, pero sin ocultar varias tarjetas vecinas.
            var activityTooltipParts =
                new List<string>();

            if (activity.HasActivityDayRange)
            {
                activityTooltipParts.Add(
                    BuildActivityDayRangeTooltip(activity));
            }

            if (activity.HasWorkLog)
            {
                activityTooltipParts.Add(
                    $"⏱ {activity.WorkProgressLabel}" +
                    (string.IsNullOrWhiteSpace(activity.WorkLogDetail)
                        ? string.Empty
                        : $"\nSesiones: {activity.WorkLogDetail}"));
            }

            activityTooltipParts.Add(
                "H = avance observado en el día · " +
                "A = checklist de esta actividad · " +
                "P = avance total del proyecto");

            // En un grupo empalmado el hover se usa exclusivamente para
            // traer tarjetas al frente. Un ToolTip estándar de WinUI tapa el
            // grupo y hace difícil seleccionar la tarjeta inferior.
            ToolTipService.SetToolTip(
                button,
                overlapCount > 1
                    ? null
                    : activityTooltipParts.Count > 0
                        ? string.Join(
                            "\n",
                            activityTooltipParts)
                        : null);

            // 19/08: el tooltip informativo se ancla ARRIBA de la tarjeta.
            // Antes WinUI lo posicionaba alrededor del puntero y podía caer
            // sobre las actividades inferiores. Al usar la propia tarjeta
            // como PlacementTarget, el tooltip queda por encima del bloque
            // que se está inspeccionando y libera el calendario de abajo.
            if (overlapCount <= 1 &&
                activityTooltipParts.Count > 0)
            {
                ToolTipService.SetPlacementTarget(
                    button,
                    button);

                ToolTipService.SetPlacement(
                    button,
                    PlacementMode.Top);
            }

            // WinUI aplica un visual PointerOver semitransparente a Button.
            // En tarjetas empalmadas se conserva exactamente el fondo/borde
            // real para que la tarjeta que sube al frente no parezca apagada.
            if (overlapCount > 1)
            {
                button.Resources["ButtonBackgroundPointerOver"] =
                    button.Background;
                button.Resources["ButtonBorderBrushPointerOver"] =
                    button.BorderBrush;
                button.Resources["ButtonForegroundPointerOver"] =
                    button.Foreground;
            }

            button.KeyboardAccelerators.Clear();
            button.KeyboardAcceleratorPlacementMode =
                KeyboardAcceleratorPlacementMode.Hidden;

            _calendarActivityBaseZIndexes[button] =
                baseZIndex;

            button.PointerEntered +=
                (sender, args) =>
                {
                    if (overlapCount > 1)
                    {
                        // En empalmes, hover = inspección visual inmediata.
                        // IMPORTANTE: una checklist fijada con clic NO se cierra
                        // al mover/scrollar el calendario. Al desplazarse, una
                        // tarjeta empalmada puede quedar debajo del cursor y
                        // disparar PointerEntered sin que el usuario la haya
                        // seleccionado. La checklist fijada solo se sustituye
                        // después de cerrarla explícitamente con la X.
                        if (!_calendarActivityPreviewPinned)
                            HideCalendarActivityPreviewFlyout();

                        Canvas.SetZIndex(
                            button,
                            1500);

                        var overlapIdentity =
                            string.Join(
                                " · ",
                                new[]
                                {
                                    projectTypeLabel,
                                    domainLabel,
                                    descriptionLabel
                                }.Where(value =>
                                    !string.IsNullOrWhiteSpace(value)));

                        StatusText.Text =
                            $"Estado: Empalme {overlapPosition}/{overlapTotal} · " +
                            $"{overlapIdentity} · {activity.TimeLabel}";

                        return;
                    }

                    CalendarActivity_PointerEntered(
                        sender,
                        args);
                };

            button.PointerExited +=
                (sender, args) =>
                {
                    if (overlapCount > 1)
                    {
                        if (!ReferenceEquals(
                                _calendarDraggingButton,
                                button))
                        {
                            Canvas.SetZIndex(
                                button,
                                ReferenceEquals(
                                    _calendarPinnedOverlapActivityButton,
                                    button)
                                    ? 1400
                                    : baseZIndex);
                        }

                        return;
                    }

                    CalendarActivity_PointerExited(
                        sender,
                        args);
                };

            button.PointerPressed +=
                (_, args) =>
                {
                    if (overlapCount <= 1)
                        return;

                    var point =
                        args.GetCurrentPoint(button);

                    if (!point.Properties.IsLeftButtonPressed)
                        return;

                    if (_calendarPinnedOverlapActivityButton != null &&
                        !ReferenceEquals(
                            _calendarPinnedOverlapActivityButton,
                            button) &&
                        _calendarActivityBaseZIndexes.TryGetValue(
                            _calendarPinnedOverlapActivityButton,
                            out var previousZ))
                    {
                        Canvas.SetZIndex(
                            _calendarPinnedOverlapActivityButton,
                            previousZ);
                    }

                    _calendarPinnedOverlapActivityButton =
                        button;

                    Canvas.SetZIndex(
                        button,
                        1400);

                    var pinnedIdentity =
                        string.Join(
                            " · ",
                            new[]
                            {
                                projectTypeLabel,
                                domainLabel,
                                descriptionLabel
                            }.Where(value =>
                                !string.IsNullOrWhiteSpace(value)));

                    StatusText.Text =
                        $"Estado: Actividad empalmada {overlapPosition}/{overlapTotal} seleccionada · " +
                        $"{pinnedIdentity}";
                };

            button.AddHandler(
                UIElement.PointerPressedEvent,
                new PointerEventHandler(
                    CalendarActivityDrag_PointerPressed),
                handledEventsToo: true);

            button.AddHandler(
                UIElement.PointerMovedEvent,
                new PointerEventHandler(
                    CalendarActivityDrag_PointerMoved),
                handledEventsToo: true);

            button.AddHandler(
                UIElement.PointerReleasedEvent,
                new PointerEventHandler(
                    CalendarActivityDrag_PointerReleased),
                handledEventsToo: true);

            button.AddHandler(
                UIElement.PointerCanceledEvent,
                new PointerEventHandler(
                    CalendarActivityDrag_PointerCanceled),
                handledEventsToo: true);

            button.ContextFlyout =
                BuildCalendarActivityContextFlyout(
                    activity);

            // Clic simple = proyecto relacionado.
            // Doble clic conserva la apertura directa de Notion.
            button.Click +=
                CalendarActivity_Click;

            button.DoubleTapped +=
                CalendarActivity_DoubleTapped;

            Canvas.SetLeft(button, left);
            Canvas.SetTop(button, top);
            Canvas.SetZIndex(
                button,
                baseZIndex);
            CalendarCanvas.Children.Add(button);

            if (!string.IsNullOrWhiteSpace(
                    activity.PageId))
            {
                if (!_calendarActivityVisuals.TryGetValue(
                        activity.PageId,
                        out var visuals))
                {
                    visuals =
                        new List<CalendarActivityVisual>();

                    _calendarActivityVisuals[
                        activity.PageId] = visuals;
                }

                visuals.Add(
                    new CalendarActivityVisual
                    {
                        Button = button,
                        TitleText = titleText,
                        ChecklistBadge = checklistBadge,
                        ChecklistText = checklistText,
                        TodayProgressBadge =
                            todayProgressBadge,
                        TodayProgressText =
                            todayProgressText,
                        ProjectProgressBadge =
                            projectProgressBadge,
                        ProjectProgressText =
                            projectProgressText,
                        CompactChecklistBadge =
                            compactBadge,
                        UltraCompactProgress =
                            ultraMiniCard,
                        TitleLeftReserve =
                            phaseTitleReserve,
                        TimerBadge = workTimerBadge,
                        TimerText = workTimerText
                    });
            }
        }

        private void CalendarActivityDrag_PointerPressed(
            object sender,
            PointerRoutedEventArgs e)
        {
            if (sender is not Button button ||
                button.Tag is not NotionCalendarActivity activity)
            {
                return;
            }

            if (activity.IsReviewMirror)
            {
                StatusText.Text =
                    "Estado: Esta es una tarjeta de seguimiento. Ábrela con doble clic; no se puede mover.";
                return;
            }

            if (!CanCurrentUserReorderCalendarActivity(
                    activity))
            {
                StatusText.Text =
                    GetCalendarReorderAccessMessage(
                        activity);
                return;
            }

            if (activity.IsAutomationLocked)
            {
                StatusText.Text =
                    "Estado: La actividad está bloqueada para automatizaciones. Desbloquéala para moverla.";
                return;
            }

            var point =
                e.GetCurrentPoint(CalendarCanvas);

            if (!point.Properties.IsLeftButtonPressed)
                return;

            _calendarDraggingButton = button;
            _calendarDraggingActivity = activity;
            _calendarDragPointerId = e.Pointer.PointerId;
            _calendarDragStartPointerY = point.Position.Y;
            _calendarDragStartTop = Canvas.GetTop(button);
            _calendarDragActive = false;

            _calendarDragTimeText =
                (button.Content as StackPanel)?
                    .Children
                    .OfType<TextBlock>()
                    .FirstOrDefault(item =>
                        string.Equals(
                            item.Text,
                            activity.TimeLabel,
                            StringComparison.Ordinal));

            _calendarDragOriginalTimeLabel =
                _calendarDragTimeText?.Text ??
                activity.TimeLabel;

            button.CapturePointer(e.Pointer);
        }

        private void CalendarActivityDrag_PointerMoved(
            object sender,
            PointerRoutedEventArgs e)
        {
            if (_calendarDraggingButton == null ||
                _calendarDraggingActivity == null ||
                e.Pointer.PointerId !=
                    _calendarDragPointerId)
            {
                return;
            }

            var point =
                e.GetCurrentPoint(CalendarCanvas);

            if (!point.Properties.IsLeftButtonPressed)
                return;

            var delta =
                point.Position.Y -
                _calendarDragStartPointerY;

            if (!_calendarDragActive &&
                Math.Abs(delta) < 5)
            {
                return;
            }

            _calendarDragActive = true;
            HideCalendarActivityPreviewFlyout();

            var minTop =
                CalendarHeaderHeight + 3;

            var maxTop =
                CalendarHeaderHeight +
                (CalendarVisibleEndHour - CalendarStartHour) *
                CalendarHourHeight -
                _calendarDraggingButton.Height;

            var top =
                Math.Clamp(
                    _calendarDragStartTop + delta,
                    minTop,
                    Math.Max(minTop, maxTop));

            Canvas.SetTop(
                _calendarDraggingButton,
                top);

            _calendarDraggingButton.Opacity = 0.78;
            Canvas.SetZIndex(
                _calendarDraggingButton,
                900);

            var minutes =
                Math.Round(
                    ((top - CalendarHeaderHeight - 3) /
                     CalendarHourHeight * 60d) / 15d) * 15d;

            var previewStart =
                _calendarSelectedDate.Date
                    .AddHours(CalendarStartHour)
                    .AddMinutes(minutes);

            var duration =
                _calendarDraggingActivity.End >
                _calendarDraggingActivity.Start
                    ? _calendarDraggingActivity.End -
                      _calendarDraggingActivity.Start
                    : TimeSpan.FromHours(1);

            var previewEnd =
                previewStart.Add(duration);

            if (_calendarDragTimeText != null)
            {
                _calendarDragTimeText.Text =
                    $"Mover a {previewStart:HH:mm} – {previewEnd:HH:mm}";
                _calendarDragTimeText.FontWeight =
                    Microsoft.UI.Text.FontWeights.SemiBold;
                _calendarDragTimeText.Opacity = 1;
            }

            StatusText.Text =
                $"Estado: Mover a {previewStart:HH:mm}–" +
                $"{previewEnd:HH:mm}";

            e.Handled = true;
        }

        private async void CalendarActivityDrag_PointerReleased(
            object sender,
            PointerRoutedEventArgs e)
        {
            if (_calendarDraggingButton == null ||
                _calendarDraggingActivity == null ||
                e.Pointer.PointerId !=
                    _calendarDragPointerId)
            {
                return;
            }

            var button =
                _calendarDraggingButton;

            var activity =
                _calendarDraggingActivity;

            button.ReleasePointerCapture(e.Pointer);
            button.Opacity = 1;

            var wasDragging =
                _calendarDragActive;

            if (!wasDragging &&
                _calendarDragTimeText != null)
            {
                _calendarDragTimeText.Text =
                    _calendarDragOriginalTimeLabel;
            }

            _calendarDraggingButton = null;
            _calendarDraggingActivity = null;
            _calendarDragPointerId = 0;
            _calendarDragActive = false;
            _calendarDragTimeText = null;
            _calendarDragOriginalTimeLabel = string.Empty;

            if (!wasDragging)
                return;

            _calendarSuppressNextActivityClick = true;
            _calendarSuppressActivityClickUntil =
                DateTimeOffset.UtcNow.AddMilliseconds(900);
            _calendarSuppressedActivityPageId =
                activity.PageId ?? string.Empty;
            e.Handled = true;

            var top =
                Canvas.GetTop(button);

            var minutes =
                Math.Round(
                    ((top - CalendarHeaderHeight - 3) /
                     CalendarHourHeight * 60d) / 15d) * 15d;

            var duration =
                activity.End > activity.Start
                    ? activity.End - activity.Start
                    : TimeSpan.FromHours(1);

            var totalMinutes =
                (CalendarVisibleEndHour - CalendarStartHour) * 60d;

            minutes = Math.Clamp(
                minutes,
                0,
                Math.Max(
                    0,
                    totalMinutes -
                    duration.TotalMinutes));

            var targetStart =
                _calendarSelectedDate.Date
                    .AddHours(CalendarStartHour)
                    .AddMinutes(minutes);

            await MoveCalendarActivityToTimeAsync(
                activity,
                targetStart);
        }

        private void CalendarActivityDrag_PointerCanceled(
            object sender,
            PointerRoutedEventArgs e)
        {
            if (_calendarDraggingButton != null)
            {
                _calendarDraggingButton.Opacity = 1;
                _calendarDraggingButton.ReleasePointerCapture(
                    e.Pointer);
            }

            var shouldRedraw =
                _calendarDragActive;

            _calendarDraggingButton = null;
            _calendarDraggingActivity = null;
            _calendarDragPointerId = 0;
            _calendarDragActive = false;
            _calendarDragTimeText = null;
            _calendarDragOriginalTimeLabel = string.Empty;
            _calendarSuppressNextActivityClick = false;
            _calendarSuppressActivityClickUntil = DateTimeOffset.MinValue;
            _calendarSuppressedActivityPageId = string.Empty;

            if (shouldRedraw)
                DrawCalendar(_calendarActivities);
        }

        private async Task MoveCalendarActivityToTimeAsync(
            NotionCalendarActivity activity,
            DateTime targetStart)
        {
            if (activity == null)
                return;

            if (!CanCurrentUserReorderCalendarActivity(
                    activity))
            {
                DrawCalendar(_calendarActivities);
                StatusText.Text =
                    GetCalendarReorderAccessMessage(
                        activity);
                return;
            }

            if (activity.IsAutomationLocked)
            {
                DrawCalendar(_calendarActivities);
                StatusText.Text =
                    "Estado: La actividad está bloqueada. Desbloquéala antes de cambiar su horario.";
                return;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                DrawCalendar(_calendarActivities);
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return;
            }

            var oldStart =
                activity.Start;

            var oldEnd =
                activity.End;

            try
            {
                StatusText.Text =
                    $"Estado: Guardando nueva hora {targetStart:HH:mm}...";

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(2));

                var updated =
                    await _notionCalendarService
                        .UpdateActivityScheduleAsync(
                            token,
                            activity,
                            targetStart,
                            cts.Token);

                activity.Start = updated.Start;
                activity.End = updated.End;
                activity.DatePropertyName =
                    updated.DatePropertyName;

                var currentDay =
                    await _notionCalendarService
                        .TryGetCachedDayAsync(
                            _calendarSelectedDate,
                            cts.Token);

                _calendarActivities =
                    currentDay ??
                    Array.Empty<NotionCalendarActivity>();

                DrawCalendar(_calendarActivities);

                StatusText.Text =
                    $"Estado: Actividad movida a " +
                    $"{updated.Start:HH:mm}–{updated.End:HH:mm} ✅";
            }
            catch (Exception ex)
            {
                activity.Start = oldStart;
                activity.End = oldEnd;
                DrawCalendar(_calendarActivities);

                StatusText.Text =
                    $"Estado: No se pudo cambiar la hora → {ex.Message}";
            }
        }

        private MenuFlyout BuildCalendarActivityContextFlyout(
            NotionCalendarActivity activity)
        {
            var flyout = new MenuFlyout();

            MenuFlyoutItem AddItem(
                string text,
                RoutedEventHandler handler)
            {
                var item = new MenuFlyoutItem
                {
                    Text = text,
                    Tag = activity
                };

                item.Click += handler;
                flyout.Items.Add(item);
                return item;
            }

            AddItem(
                "Abrir en Notion",
                CalendarContextOpen_Click);

            AddItem(
                "📊 Ver proyecto relacionado",
                CalendarContextProjectPreview_Click);

            AddItem(
                "🎯 Resaltar en calendario",
                CalendarContextHighlightActivity_Click);

            AddItem(
                "Enviar mensaje…",
                CalendarContextSendMessage_Click);

            AddItem(
                "💬 WhatsApp…",
                CalendarContextWhatsApp_Click);

            AddItem(
                "Copiar nombre",
                CalendarContextCopyName_Click);

            AddItem(
                "Copiar URL de Notion",
                CalendarContextCopyUrl_Click);

            flyout.Items.Add(
                new MenuFlyoutSeparator());

            AddItem(
                "Copiar dominio",
                CalendarContextCopyDomain_Click);

            AddItem(
                "Ir al dominio",
                CalendarContextOpenDomain_Click);

            // La tarjeta espejo conserva el historial visual, pero no
            // puede modificar la actividad real.
            if (activity.IsReviewMirror)
                return flyout;

            flyout.Items.Add(
                new MenuFlyoutSeparator());

            AddItem(
                "Renombrar página…",
                CalendarContextRename_Click);

            AddItem(
                "Duplicar actividad…",
                CalendarContextDuplicate_Click);

            flyout.Items.Add(
                new MenuFlyoutSeparator());

            if (IsCalendarWorkTimerFor(activity))
            {
                if (_calendarWorkTimerState?.IsRunning == true)
                {
                    AddItem(
                        $"⏸ Pausar cronómetro · " +
                        $"{FormatCalendarWorkTimer(GetCalendarWorkTimerElapsedSeconds())}",
                        CalendarContextPauseWorkTimer_Click);
                }
                else
                {
                    AddItem(
                        $"▶ Continuar cronómetro · " +
                        $"{FormatCalendarWorkTimer(GetCalendarWorkTimerElapsedSeconds())}",
                        CalendarContextResumeWorkTimer_Click);
                }

                AddItem(
                    "■ Terminar y guardar tiempo",
                    CalendarContextFinishWorkTimer_Click);

                AddItem(
                    "✕ Cancelar cronómetro",
                    CalendarContextCancelWorkTimer_Click);
            }
            else
            {
                AddItem(
                    "▶ Iniciar cronómetro",
                    CalendarContextStartWorkTimer_Click);
            }

            AddItem(
                "⏱ Registrar tiempo manualmente…",
                CalendarContextRegisterWork_Click);

            AddItem(
                activity.IsAutomationLocked
                    ? "🔓 Desbloquear automatización"
                    : "🔒 Bloquear automatización",
                CalendarContextToggleAutomationLock_Click);

            flyout.Items.Add(
                new MenuFlyoutSeparator());

            if (HasExactCalendarPhase(
                    activity,
                    "rtuzREVISION") &&
                activity.IsPendingReview &&
                !activity.IsReviewMirror &&
                CanCurrentUserResolveReview(activity))
            {
                AddItem(
                    "Aprobar revisión",
                    CalendarContextApproveReview_Click);

                AddItem(
                    "Regresar con correcciones…",
                    CalendarContextReturnReview_Click);
            }
            else if (CanSendCalendarActivityToReview(activity))
            {
                AddItem(
                    "Enviar a revisión…",
                    CalendarContextSendToReview_Click);
            }

            if (HasExactCalendarPhase(
                    activity,
                    "zREVISION"))
            {
                AddItem(
                    "Reasignar y pasar a prtuzREVISION…",
                    CalendarContextReassignApproved_Click);
            }

            AddItem(
                "Mover a papelera…",
                CalendarContextTrash_Click);

            flyout.Items.Add(
                new MenuFlyoutSeparator());

            AddItem(
                "Agregar / quitar Favoritos",
                CalendarContextBookmark_Click);

            return flyout;
        }

        private async void CalendarContextHighlightActivity_Click(
            object sender,
            RoutedEventArgs e)
        {
