        private static NotionCalendarActivity?
            GetCalendarActivityFromMenuSender(
                object sender)
        {
            return sender is FrameworkElement element
                ? element.Tag as NotionCalendarActivity
                : null;
        }


        private static readonly (string Token, string Label)[]
            WhatsAppCalendarProjectTypes =
            {
                ("sseo", "SEO"),
                ("wwebs", "WEB"),
                ("aads", "ADS"),
                ("aapli", "APLICACIÓN"),
                ("pprog", "PROGRAMACIÓN"),
                ("ddise", "DISEÑO"),
                ("rrede", "REDES")
            };

        private static bool TryGetWhatsAppCalendarProjectType(
            NotionCalendarActivity activity,
            out string projectType,
            out string projectLabel)
        {
            projectType = string.Empty;
            projectLabel = string.Empty;

            if (activity == null)
                return false;

            var searchable = string.Join(
                " ",
                activity.Title ?? string.Empty,
                activity.Project ?? string.Empty);

            foreach (var candidate in WhatsAppCalendarProjectTypes)
            {
                if (!Regex.IsMatch(
                        searchable,
                        $@"(?<![\p{{L}}\p{{Nd}}_]){Regex.Escape(candidate.Token)}(?![\p{{L}}\p{{Nd}}_])",
                        RegexOptions.IgnoreCase |
                        RegexOptions.CultureInvariant))
                {
                    continue;
                }

                projectType = candidate.Token;
                projectLabel = candidate.Label;
                return true;
            }

            return false;
        }

        private static readonly string[]
            CalendarProjectMonthAbbreviations =
            {
                "ENER",
                "FEBR",
                "MARZ",
                "ABRI",
                "MAYO",
                "JUNI",
                "JULI",
                "AGOS",
                "SEPT",
                "OCTU",
                "NOVI",
                "DICI"
            };

        private static string BuildCalendarProjectMonthKey(
            DateTime date)
        {
            var month =
                Math.Clamp(
                    date.Month,
                    1,
                    12);

            return
                $"{date.Year % 100:00}" +
                $"{month:00}" +
                CalendarProjectMonthAbbreviations[
                    month - 1];
        }

        private static bool TryReadCalendarProjectMonthKey(
            string text,
            out int year,
            out int month,
            out string monthKey)
        {
            year = 0;
            month = 0;
            monthKey = string.Empty;

            var match =
                Regex.Match(
                    text ?? string.Empty,
                    @"(?<!\d)(?<yy>\d{2})(?<mm>0[1-9]|1[0-2])" +
                    @"(?<abbr>ENER|FEBR|MARZ|ABRI|MAYO|JUNI|JULI|AGOS|SEPT|OCTU|NOVI|DICI)(?![\p{L}\p{Nd}_])",
                    RegexOptions.IgnoreCase |
                    RegexOptions.CultureInvariant);

            if (!match.Success ||
                !int.TryParse(
                    match.Groups["yy"].Value,
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var shortYear) ||
                !int.TryParse(
                    match.Groups["mm"].Value,
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out month))
            {
                return false;
            }

            year =
                2000 + shortYear;

            monthKey =
                $"{shortYear:00}" +
                $"{month:00}" +
                CalendarProjectMonthAbbreviations[
                    month - 1];

            return true;
        }

        private static bool TryGetCalendarProjectMonth(
            NotionCalendarActivity activity,
            out int year,
            out int month,
            out string monthTag)
        {
            year =
                activity?.Start.Year ??
                DateTime.Today.Year;

            month =
                activity?.Start.Month ??
                DateTime.Today.Month;

            monthTag =
                BuildCalendarProjectMonthKey(
                    new DateTime(
                        year,
                        month,
                        1));

            if (activity == null)
                return false;

            // El token ya escrito en el título/proyecto manda.
            // Ejemplo: (2608AGOS). Así una actividad que se mueva a septiembre
            // sigue perteneciendo al proyecto de agosto.
            var searchable =
                $"{activity.Title} {activity.Project}";

            if (TryReadCalendarProjectMonthKey(
                    searchable,
                    out var parsedYear,
                    out var parsedMonth,
                    out var parsedKey))
            {
                year = parsedYear;
                month = parsedMonth;
                monthTag = parsedKey;
                return true;
            }

            // Respaldo para páginas antiguas que todavía no llevan token:
            // se calcula automáticamente con Fecha POR Hacer.
            return true;
        }

        private static string NormalizeCalendarProjectDomain(
            string value)
        {
            var clean =
                (value ?? string.Empty)
                .Trim()
                .ToLowerInvariant()
                .TrimEnd('.');

            if (clean.StartsWith(
                    "www.",
                    StringComparison.OrdinalIgnoreCase))
            {
                clean = clean.Substring(4);
            }

            return clean;
        }

        // Título visual compacto para cards/popup. NO modifica el título real
        // en Notion: únicamente elimina tokens técnicos que ya están
        // representados por la fase, proyecto, dominio o persona en la UI.
        private string GetCalendarCompactActivityTitle(
            NotionCalendarActivity activity)
        {
            if (activity == null)
                return string.Empty;

            var original =
                (activity.Title ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(original))
                return "Actividad sin título";

            var clean = original;

            // Fases técnicas. Se quitan solo como tokens completos para no
            // afectar palabras que casualmente contengan esas letras.
            clean = Regex.Replace(
                clean,
                @"(?<![\p{L}\p{Nd}_])(?:sprtuz|aprtuz|prtuz|rtuz|z)REVISION(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

            // Tipo de proyecto técnico (sseo, aads, wwebs, etc.).
            clean = Regex.Replace(
                clean,
                @"(?<![\p{L}\p{Nd}_])(?:sseo|wwebs|aads|aapli|pprog|ddise|rrede)(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

            // Token de mes, con o sin paréntesis: (2608AGOS) / 2608AGOS.
            clean = Regex.Replace(
                clean,
                @"\(?\b\d{2}(?:0[1-9]|1[0-2])(?:ENER|FEBR|MARZ|ABRI|MAYO|JUNI|JULI|AGOS|SEPT|OCTU|NOVI|DICI)\b\)?",
                " ",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

            // Tags cortos de persona usados en títulos de Notion.
            clean = Regex.Replace(
                clean,
                @"(?<![\p{L}\p{Nd}_])(?:jjohn|kkarl|iisai|iisaia|ssote|eedua|aacal|aandr|eemma|bbria|ggena|nneft)(?![\p{L}\p{Nd}_])",
                " ",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

            // El dominio ya aparece en el encabezado del proyecto.
            var domain =
                NormalizeCalendarProjectDomain(
                    TryExtractFirstDomain(
                        BuildCalendarSearchRow(activity)));

            if (!string.IsNullOrWhiteSpace(domain))
            {
                clean = Regex.Replace(
                    clean,
                    $@"(?<![\p{{L}}\p{{Nd}}_])(?:www\.)?{Regex.Escape(domain)}(?![\p{{L}}\p{{Nd}}_])",
                    " ",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            }

            clean = Regex.Replace(
                clean,
                @"\s*[·|—–-]{2,}\s*",
                " · ",
                RegexOptions.CultureInvariant);

            clean = Regex.Replace(
                clean,
                @"\s{2,}",
                " ",
                RegexOptions.CultureInvariant)
                .Trim(' ', '·', '-', '—', '–', '|');

            // Si el título quedó demasiado corto, conserva el original para no
            // ocultar información útil por una nomenclatura inesperada.
            return clean.Length >= 4
                ? clean
                : original;
        }

        // Vista limpia para el listado de proyecto: conserva el número de orden
        // como dato visual separado (1.00 / 1.10 / 2.03...) y deja el texto
        // principal sin nomenclatura técnica. El título REAL de Notion no cambia.
        private string GetCalendarProjectPreviewTitle(
            NotionCalendarActivity activity,
            out string orderToken)
        {
            orderToken = string.Empty;

            var compact =
                GetCalendarCompactActivityTitle(activity);

            if (string.IsNullOrWhiteSpace(compact))
                return "Actividad sin título";

            var match = Regex.Match(
                compact,
                @"(?<!\d)(?<order>\d{1,3}\.\d{1,3})(?!\d)",
                RegexOptions.CultureInvariant);

            if (!match.Success)
                return compact;

            orderToken =
                match.Groups["order"].Value;

            var clean =
                compact
                    .Remove(
                        match.Index,
                        match.Length);

            clean = Regex.Replace(
                clean,
                @"\s{2,}",
                " ",
                RegexOptions.CultureInvariant)
                .Trim(' ', '·', '-', '—', '–', '|', ':');

            return string.IsNullOrWhiteSpace(clean)
                ? compact
                : clean;
        }

        private bool TryBuildCalendarProjectGroupCriteria(
            NotionCalendarActivity activity,
            out CalendarProjectGroupCriteria criteria)
        {
            criteria = null!;

            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return false;
            }

            if (!TryGetWhatsAppCalendarProjectType(
                    activity,
                    out var projectType,
                    out var projectLabel))
            {
                return false;
            }

            var domain =
                TryExtractFirstDomain(
                    BuildCalendarSearchRow(activity));

            domain =
                NormalizeCalendarProjectDomain(domain);

            if (string.IsNullOrWhiteSpace(domain))
                return false;

            TryGetCalendarProjectMonth(
                activity,
                out var year,
                out var month,
                out var monthTag);

            criteria =
                new CalendarProjectGroupCriteria(
                    projectType,
                    projectLabel,
                    domain,
                    "Todas las personas",
                    year,
                    month,
                    monthTag);

            return true;
        }

        private static CalendarProjectGroupCriteria
            BuildCalendarAllProjectTypesCriteria(
                CalendarProjectGroupCriteria baseCriteria)
        {
            return baseCriteria with
            {
                ProjectType = string.Empty,
                ProjectLabel = "TODAS",
                IncludeAllProjectTypes = true
            };
        }

        private async Task SwitchCalendarProjectScopeAsync(
            NotionCalendarActivity sourceActivity,
            bool includeAllProjectTypes)
        {
            if (sourceActivity == null ||
                !TryBuildCalendarProjectGroupCriteria(
                    sourceActivity,
                    out var baseCriteria))
            {
                return;
            }

            var targetCriteria =
                includeAllProjectTypes
                    ? BuildCalendarAllProjectTypesCriteria(
                        baseCriteria)
                    : baseCriteria;

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return;
            }

            SetCalendarActivityPreviewPinned(
                sourceActivity.PageId,
                true);

            UpdateCalendarActivityPreviewContent(
                BuildCalendarProjectHoverLoading(
                    sourceActivity,
                    targetCriteria));

            try
            {
                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromSeconds(90));

                var related =
                    await GetCalendarProjectRelatedActivitiesAsync(
                        sourceActivity,
                        targetCriteria,
                        token,
                        cts.Token,
                        forceRefresh: false);

                if (!_calendarActivityPreviewPinned ||
                    !string.Equals(
                        _calendarActivityPreviewPinnedPageId,
                        sourceActivity.PageId,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                UpdateCalendarActivityPreviewContent(
                    BuildCalendarProjectHoverChecklist(
                        sourceActivity,
                        targetCriteria,
                        related));

                _ = WarmOpenCalendarProjectChecklistAsync(
                    sourceActivity,
                    targetCriteria,
                    related,
                    sourceActivity.PageId,
                    cts.Token);

                StatusText.Text =
                    includeAllProjectTypes
                        ? $"Estado: Todas las áreas de {targetCriteria.Domain} · {targetCriteria.MonthTag} ✅"
                        : $"Estado: Solo {baseCriteria.ProjectLabel} · {baseCriteria.Domain} · {baseCriteria.MonthTag} ✅";
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: Cambio de alcance cancelado.";
            }
            catch (Exception ex)
            {
                UpdateCalendarActivityPreviewContent(
                    BuildCalendarActivityErrorPreview(
                        sourceActivity,
                        ex.Message));

                StatusText.Text =
                    $"Estado: No se pudo cambiar el alcance del proyecto → {ex.Message}";
            }
        }

        private bool MatchesCalendarProjectGroup(
            NotionCalendarActivity activity,
            CalendarProjectGroupCriteria criteria)
        {
            if (activity == null ||
                criteria == null ||
                activity.IsReviewMirror ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return false;
            }

            // Estados que forman parte de la checklist de actividades.
            var hasValidPhase =
                HasExactCalendarPhase(
                    activity,
                    "prtuzREVISION") ||
                HasExactCalendarPhase(
                    activity,
                    "rtuzREVISION") ||
                HasExactCalendarPhase(
                    activity,
                    "zREVISION") ||
                HasExactCalendarPhase(
                    activity,
                    "sprtuzREVISION") ||
                HasExactCalendarPhase(
                    activity,
                    "aprtuzREVISION");

            if (!hasValidPhase)
                return false;

            if (!criteria.IncludeAllProjectTypes)
            {
                if (!TryGetWhatsAppCalendarProjectType(
                        activity,
                        out var projectType,
                        out _) ||
                    !string.Equals(
                        projectType,
                        criteria.ProjectType,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }
            }

            var domain =
                NormalizeCalendarProjectDomain(
                    TryExtractFirstDomain(
                        BuildCalendarSearchRow(activity)));

            if (!string.Equals(
                    domain,
                    criteria.Domain,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            // La persona NO forma parte de la asociación del proyecto.
            // Puede haber actividades de distintas personas dentro del mismo
            // tipo + dominio + mes.

            TryGetCalendarProjectMonth(
                activity,
                out var year,
                out var month,
                out var monthTag);

            return year == criteria.Year &&
                   month == criteria.Month &&
                   string.Equals(
                       monthTag,
                       criteria.MonthTag,
                       StringComparison.OrdinalIgnoreCase);
        }

        private static string GetCalendarProjectMonthLabel(
            CalendarProjectGroupCriteria criteria)
        {
            if (criteria == null)
                return string.Empty;

            var date =
                new DateTime(
                    criteria.Year,
                    criteria.Month,
                    1);

            var label =
                date.ToString(
                    "MMMM yyyy",
                    new CultureInfo("es-MX"));

            return CultureInfo
                .CurrentCulture
                .TextInfo
                .ToTitleCase(label);
        }

        private static readonly string[]
            WhatsAppCalendarMonthTags =
            {
                "jjane",
                "ffebr",
                "mmarz",
                "aabri",
                "mmayo",
                "jjuni",
                "jjuli",
                "aagos",
                "ssept",
                "ooctu",
                "nnovi",
                "ddici"
            };

        private static string GetWhatsAppCalendarMonthTag(
            DateTime date)
        {
            var month =
                Math.Clamp(
                    date.Month,
                    1,
                    12);

            return WhatsAppCalendarMonthTags[
                month - 1];
        }

        private static string BuildWhatsAppDomainStutterTag(
            string domain)
        {
            var clean =
                (domain ?? string.Empty)
                .Trim()
                .ToLowerInvariant();

            if (clean.StartsWith(
                    "www.",
                    StringComparison.OrdinalIgnoreCase))
            {
                clean =
                    clean.Substring(4);
            }

            var firstLabel =
                clean.Split(
                        '.',
                        StringSplitOptions.RemoveEmptyEntries)
                    .FirstOrDefault() ??
                string.Empty;

            firstLabel =
                Regex.Replace(
                    firstLabel,
                    @"[^a-z0-9]",
                    string.Empty,
                    RegexOptions.IgnoreCase |
                    RegexOptions.CultureInvariant)
                .ToLowerInvariant();

            if (string.IsNullOrWhiteSpace(firstLabel))
                return string.Empty;

            // Tag tartamudo de cinco caracteres:
            // fortelite -> ffort
            // gami      -> ggami
            // abc       -> aaabc
            var body =
                firstLabel.Substring(
                    0,
                    Math.Min(
                        4,
                        firstLabel.Length));

            var result =
                firstLabel[0] + body;

            while (result.Length < 5)
                result = firstLabel[0] + result;

            return result.Length > 5
                ? result.Substring(0, 5)
                : result;
        }

        private static string BuildWhatsAppCalendarGroupName(
            string domain,
            string projectType,
            DateTime date)
        {
            var domainTag =
                BuildWhatsAppDomainStutterTag(
                    domain);

            var monthTag =
                GetWhatsAppCalendarMonthTag(
                    date);

            return
                $"TzPROY [{projectType}] {domain} " +
                $"[{domainTag}] [{monthTag}] E00F00";
        }

        private async void CalendarContextWhatsApp_Click(
            object sender,
            RoutedEventArgs e)
        {
            var activity =
                GetCalendarActivityFromMenuSender(sender);

            if (activity == null)
                return;

            HideCalendarActivityPreviewFlyout();

            var domain =
                TryExtractFirstDomain(
                    BuildCalendarSearchRow(activity));

            if (string.IsNullOrWhiteSpace(domain))
            {
                StatusText.Text =
                    "Estado: No se encontró un dominio para relacionar con WhatsApp.";
                return;
            }

            if (!TryGetWhatsAppCalendarProjectType(
                    activity,
                    out var projectType,
                    out var projectLabel))
            {
                StatusText.Text =
                    "Estado: No se detectó el tipo de proyecto (sseo, wwebs, aads, aapli, pprog, ddise o rrede).";
                return;
            }

            var bridge =
                new WhatsAppBridgeService();

            if (!bridge.IsConfigured)
            {
                var setupDialog = new ContentDialog
                {
                    XamlRoot = XamlRoot,
                    Title = "Configurar WhatsApp",
                    Content =
                        "Falta configurar la URL o API key del WhatsApp Bridge. " +
                        "Puedes hacerlo visualmente desde Configuración → WhatsApp Web.",
                    PrimaryButtonText = "Abrir Configuración",
                    CloseButtonText = "Cancelar",
                    DefaultButton = ContentDialogButton.Primary
                };

                if (await setupDialog.ShowAsync() ==
                    ContentDialogResult.Primary)
                {
                    Frame.Navigate(typeof(SettingsView));
                }

                return;
            }

            try
            {
                StatusText.Text =
                    $"Estado: Buscando grupo de {domain} · {projectLabel}…";

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromSeconds(85));

                var status =
                    await bridge.GetStatusAsync(cts.Token);

                if (!status.Connected)
                {
                    await bridge.StartAsync(cts.Token);

                    for (var attempt = 0;
                         attempt < 10 && !status.Connected;
                         attempt++)
                    {
                        await Task.Delay(
                            TimeSpan.FromSeconds(1.5),
                            cts.Token);

                        status =
                            await bridge.GetStatusAsync(
                                cts.Token);

                        if (status.QrAvailable ||
                            string.Equals(
                                status.Status,
                                "QR_REQUIRED",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            break;
                        }
                    }
                }

                if (!status.Connected)
                {
                    var connectDialog = new ContentDialog
                    {
                        XamlRoot = XamlRoot,
                        Title = "WhatsApp necesita atención",
                        Content =
                            status.QrAvailable ||
                            string.Equals(
                                status.Status,
                                "QR_REQUIRED",
                                StringComparison.OrdinalIgnoreCase)
                                ? "La cuenta necesita escanear un QR. Ábrela desde Configuración → WhatsApp Web."
                                : $"WhatsApp todavía no está conectado ({status.Status}). Puedes revisarlo desde Configuración.",
                        PrimaryButtonText = "Abrir Configuración",
                        CloseButtonText = "Cerrar"
                    };

                    if (await connectDialog.ShowAsync() ==
                        ContentDialogResult.Primary)
                    {
                        Frame.Navigate(typeof(SettingsView));
                    }

                    return;
                }

                var resolved =
                    await bridge.ResolveGroupAsync(
                        domain,
                        projectType,
                        cts.Token);

                if (resolved.Exists &&
                    resolved.Group != null)
                {
                    await ShowExistingWhatsAppGroupAsync(
                        resolved.Group,
                        domain,
                        projectLabel);
                    return;
                }

                await CreateWhatsAppGroupFromCalendarAsync(
                    bridge,
                    activity,
                    domain,
                    projectType,
                    projectLabel,
                    cts.Token);
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: WhatsApp tardó demasiado en responder. Intenta nuevamente.";
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: Error WhatsApp → {ex.Message}";
            }
        }

        private async Task ShowExistingWhatsAppGroupAsync(
            WhatsAppGroupInfo group,
            string domain,
            string projectLabel)
        {
            var panel = new StackPanel
            {
                Width = 430,
                Spacing = 8
            };

            panel.Children.Add(
                new TextBlock
                {
                    Text = group.Name,
                    FontSize = 15,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    TextWrapping = TextWrapping.Wrap
                });

            panel.Children.Add(
                new TextBlock
                {
                    Text =
                        $"{domain} · {projectLabel}\n" +
                        $"ID: {group.GroupId}\n\n" +
                        "ANFETA encontró el grupo guardado. No se creará un duplicado.",
                    TextWrapping = TextWrapping.Wrap,
                    Opacity = 0.76
                });

            var dialog = new ContentDialog
            {
                XamlRoot = XamlRoot,
                Title = "💬 Grupo WhatsApp encontrado",
                Content = panel,
                PrimaryButtonText = "Abrir grupo",
                SecondaryButtonText = "Copiar enlace",
                CloseButtonText = "Cerrar",
                DefaultButton = ContentDialogButton.Primary
            };

            var result =
                await dialog.ShowAsync();

            if (result == ContentDialogResult.Primary)
            {
                await OpenWhatsAppInviteLinkAsync(
                    group.InviteLink,
                    group.Name);
            }
            else if (result == ContentDialogResult.Secondary)
            {
                CopyCalendarText(
                    group.InviteLink,
                    "Estado: Enlace del grupo WhatsApp copiado ✅");
            }
        }

        private async Task CreateWhatsAppGroupFromCalendarAsync(
            WhatsAppBridgeService bridge,
            NotionCalendarActivity activity,
            string domain,
            string projectType,
            string projectLabel,
            CancellationToken cancellationToken)
        {
            var defaultName =
                BuildWhatsAppCalendarGroupName(
                    domain,
                    projectType,
                    activity.Start);

            var nameBox = new TextBox
            {
                Header = "Nombre del grupo",
                Text = defaultName,
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            var seedBox = new TextBox
            {
                Header = "Número interno inicial",
                Text = WhatsAppBridgeService.GetSavedSeedParticipant(),
                PlaceholderText = "Ej. 524831191441",
                HorizontalAlignment = HorizontalAlignment.Stretch
            };

            var panel = new StackPanel
            {
                Width = 450,
                Spacing = 10
            };

            panel.Children.Add(
                new TextBlock
                {
                    Text =
                        $"Servicio: {projectLabel} ({projectType})\n" +
                        $"Dominio: {domain}\n" +
                        $"Tag dominio: {BuildWhatsAppDomainStutterTag(domain)}\n" +
                        $"Mes: {GetWhatsAppCalendarMonthTag(activity.Start)}",
                    TextWrapping = TextWrapping.Wrap,
                    Opacity = 0.78
                });

            panel.Children.Add(
                new TextBlock
                {
                    Text =
                        "Estructura automática: " +
                        "TzPROY [servicio] dominio [tag dominio] [mes] E00F00. " +
                        "El nombre sigue siendo editable antes de crear.",
                    FontSize = 10.5,
                    TextWrapping = TextWrapping.Wrap,
                    Opacity = 0.68
                });

            panel.Children.Add(nameBox);
            panel.Children.Add(seedBox);

            panel.Children.Add(
                new TextBlock
                {
                    Text =
                        "El número inicial sirve para que WhatsApp permita crear el grupo. " +
                        "El cliente NO se agrega automáticamente: ANFETA devolverá un enlace de invitación.",
                    FontSize = 11,
                    TextWrapping = TextWrapping.Wrap,
                    Opacity = 0.68
                });

            var dialog = new ContentDialog
            {
                XamlRoot = XamlRoot,
                Title = "Crear grupo WhatsApp",
                Content = panel,
                PrimaryButtonText = "Crear grupo",
                CloseButtonText = "Cancelar",
                DefaultButton = ContentDialogButton.Primary
            };

            if (await dialog.ShowAsync() !=
                ContentDialogResult.Primary)
            {
                StatusText.Text =
                    "Estado: Creación de grupo cancelada.";
                return;
            }

            var name =
                (nameBox.Text ?? string.Empty).Trim();

            var seedParticipant =
                (seedBox.Text ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(name))
            {
                StatusText.Text =
                    "Estado: Escribe un nombre para el grupo WhatsApp.";
                return;
            }

            if (string.IsNullOrWhiteSpace(seedParticipant))
            {
                StatusText.Text =
                    "Estado: Configura un número interno inicial para crear grupos.";
                return;
            }

            ApplicationData.Current.LocalSettings.Values[
                LS_WhatsAppSeedParticipant] = seedParticipant;

            StatusText.Text =
                $"Estado: Creando grupo {name}…";

            var created =
                await bridge.CreateGroupAsync(
                    name,
                    domain,
                    projectType,
                    seedParticipant,
                    cancellationToken);

            if (!created.Created ||
                created.Group == null)
            {
                throw new InvalidOperationException(
                    "El Bridge no devolvió el grupo creado.");
            }

            StatusText.Text =
                $"Estado: Grupo WhatsApp creado ✅ {created.Group.Name}";

            var successDialog = new ContentDialog
            {
                XamlRoot = XamlRoot,
                Title = "Grupo creado ✅",
                Content =
                    $"{created.Group.Name}\n\n" +
                    $"Dominio: {domain}\n" +
                    $"Servicio: {projectLabel}\n\n" +
                    "El enlace está listo para compartir con el cliente.",
                PrimaryButtonText = "Abrir grupo",
                SecondaryButtonText = "Copiar enlace",
                CloseButtonText = "Cerrar",
                DefaultButton = ContentDialogButton.Primary
            };

            var successResult =
                await successDialog.ShowAsync();

            if (successResult == ContentDialogResult.Primary)
            {
                await OpenWhatsAppInviteLinkAsync(
                    created.Group.InviteLink,
                    created.Group.Name);
            }
            else if (successResult == ContentDialogResult.Secondary)
            {
                CopyCalendarText(
                    created.Group.InviteLink,
                    "Estado: Enlace de invitación copiado ✅");
            }
        }

        private async Task OpenWhatsAppInviteLinkAsync(
            string inviteLink,
            string groupName)
        {
            if (!Uri.TryCreate(
                    inviteLink,
                    UriKind.Absolute,
                    out var uri))
            {
                StatusText.Text =
                    "Estado: El grupo no tiene un enlace de invitación válido.";
                return;
            }

            var opened =
                await Launcher.LaunchUriAsync(uri);

            StatusText.Text = opened
                ? $"Estado: WhatsApp abierto ✅ {groupName}"
                : "Estado: Windows no pudo abrir el enlace de WhatsApp.";
        }

        private void EnsureCalendarWorkTimerLoaded()
        {
            lock (_calendarWorkTimerSync)
            {
                if (_calendarWorkTimerLoaded)
                    return;

                _calendarWorkTimerLoaded = true;

                try
                {
                    var path = Path.Combine(
                        ApplicationData.Current.LocalFolder.Path,
                        CalendarWorkTimerFileName);

                    if (!File.Exists(path))
                        return;

                    var raw = File.ReadAllText(path);

                    if (string.IsNullOrWhiteSpace(raw))
                        return;

                    var restored =
                        JsonSerializer.Deserialize<
                            CalendarWorkTimerState>(raw);

                    if (restored == null ||
                        string.IsNullOrWhiteSpace(restored.PageId))
                    {
                        return;
                    }

                    // Si ANFETA se cerró mientras corría el cronómetro, solo
                    // recuperamos hasta el último heartbeat persistido.
                    // El tiempo con la app cerrada NO se cuenta por seguridad.
                    if (restored.IsRunning &&
                        restored.SegmentStartedAt.HasValue)
                    {
                        var end =
                            restored.LastHeartbeatAt ??
                            restored.SegmentStartedAt.Value;

                        if (end > restored.SegmentStartedAt.Value)
                        {
                            restored.AccumulatedSeconds +=
                                Math.Max(
                                    0,
                                    (long)Math.Floor(
                                        (end -
                                         restored.SegmentStartedAt.Value)
                                        .TotalSeconds));
                        }

                        restored.IsRunning = false;
                        restored.SegmentStartedAt = null;
                    }

                    _calendarWorkTimerState = restored;
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_WORK_TIMER_LOAD] {ex.Message}");
                }
            }
        }

        private void SaveCalendarWorkTimer()
        {
            lock (_calendarWorkTimerSync)
            {
                try
                {
                    var path = Path.Combine(
                        ApplicationData.Current.LocalFolder.Path,
                        CalendarWorkTimerFileName);

                    if (_calendarWorkTimerState == null)
                    {
                        if (File.Exists(path))
                            File.Delete(path);

                        return;
                    }

                    var snapshot =
                        new CalendarWorkTimerState
                        {
                            PageId =
                                _calendarWorkTimerState.PageId,
                            Title =
                                _calendarWorkTimerState.Title,
                            WorkDate =
                                _calendarWorkTimerState.WorkDate,
                            AccumulatedSeconds =
                                _calendarWorkTimerState.AccumulatedSeconds,
                            SegmentStartedAt =
                                _calendarWorkTimerState.SegmentStartedAt,
                            LastHeartbeatAt =
                                _calendarWorkTimerState.IsRunning
                                    ? DateTimeOffset.Now
                                    : _calendarWorkTimerState.LastHeartbeatAt,
                            IsRunning =
                                _calendarWorkTimerState.IsRunning
                        };

                    var json =
                        JsonSerializer.Serialize(
                            snapshot,
                            new JsonSerializerOptions
                            {
                                WriteIndented = true
                            });

                    File.WriteAllText(path, json);
                    _calendarWorkTimerLastPersistence =
                        DateTimeOffset.Now;
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_WORK_TIMER_SAVE] {ex.Message}");
                }
            }
        }

        private void EnsureCalendarWorkSessionHistoryLoaded()
        {
            lock (_calendarWorkSessionsSync)
            {
                if (_calendarWorkSessionsLoaded)
                    return;

                _calendarWorkSessionsLoaded = true;
                _calendarWorkSessions.Clear();

                try
                {
                    var path = Path.Combine(
                        ApplicationData.Current.LocalFolder.Path,
                        CalendarWorkSessionHistoryFileName);

                    if (!File.Exists(path))
                        return;

                    var raw = File.ReadAllText(path);

                    if (string.IsNullOrWhiteSpace(raw))
                        return;

                    var restored =
                        JsonSerializer.Deserialize<
                            List<CalendarWorkSessionEntry>>(raw);

                    if (restored == null)
                        return;

                    foreach (var entry in restored)
                    {
                        if (entry == null ||
                            string.IsNullOrWhiteSpace(entry.PageId) ||
                            entry.Minutes <= 0)
                        {
                            continue;
                        }

                        if (string.IsNullOrWhiteSpace(entry.Id))
                            entry.Id = Guid.NewGuid().ToString("N");

                        _calendarWorkSessions.Add(entry);
                    }
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_WORK_SESSIONS_LOAD] {ex.Message}");
                }
            }
        }

        private void SaveCalendarWorkSessionHistory()
        {
            lock (_calendarWorkSessionsSync)
            {
                try
                {
                    var path = Path.Combine(
                        ApplicationData.Current.LocalFolder.Path,
                        CalendarWorkSessionHistoryFileName);

                    // Se conserva un historial amplio, pero acotado, para que
                    // el archivo local no crezca indefinidamente.
                    var snapshot =
                        _calendarWorkSessions
                            .OrderBy(entry => entry.RecordedAt)
                            .TakeLast(5000)
                            .ToList();

                    var json =
                        JsonSerializer.Serialize(
                            snapshot,
                            new JsonSerializerOptions
                            {
                                WriteIndented = true
                            });

                    File.WriteAllText(path, json);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine(
                        $"[CALENDAR_WORK_SESSIONS_SAVE] {ex.Message}");
                }
            }
        }

        private void RegisterCalendarWorkSession(
            NotionCalendarActivity activity,
            DateTime workDate,
            int minutes,
            string source)
        {
            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId) ||
                minutes <= 0)
            {
                return;
            }

            EnsureCalendarWorkSessionHistoryLoaded();

            lock (_calendarWorkSessionsSync)
            {
                _calendarWorkSessions.Add(
                    new CalendarWorkSessionEntry
                    {
                        Id = Guid.NewGuid().ToString("N"),
                        PageId = activity.PageId,
                        Title =
                            string.IsNullOrWhiteSpace(activity.Title)
                                ? "Actividad"
                                : activity.Title.Trim(),
                        WorkDate = workDate.Date,
                        Minutes = Math.Max(1, minutes),
                        Source =
                            string.IsNullOrWhiteSpace(source)
                                ? "ANFETA"
                                : source.Trim(),
                        RecordedAt = DateTimeOffset.Now
                    });
            }

            SaveCalendarWorkSessionHistory();
        }

        private int GetCalendarWorkedMinutesForDay(
            NotionCalendarActivity activity,
            DateTime day)
        {
            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return 0;
            }

            EnsureCalendarWorkSessionHistoryLoaded();

            lock (_calendarWorkSessionsSync)
            {
                return _calendarWorkSessions
                    .Where(entry =>
                        entry.WorkDate.Date == day.Date &&
                        string.Equals(
                            entry.PageId,
                            activity.PageId,
                            StringComparison.OrdinalIgnoreCase))
                    .Sum(entry => Math.Max(0, entry.Minutes));
            }
        }

        private int GetCalendarWorkedMinutesForDay(
            IEnumerable<NotionCalendarActivity> activities,
            DateTime day)
        {
            if (activities == null)
                return 0;

            var pageIds =
                activities
                    .Where(activity =>
                        activity != null &&
                        !string.IsNullOrWhiteSpace(activity.PageId))
                    .Select(activity => activity.PageId)
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);

            if (pageIds.Count == 0)
                return 0;

            EnsureCalendarWorkSessionHistoryLoaded();

            lock (_calendarWorkSessionsSync)
            {
                return _calendarWorkSessions
                    .Where(entry =>
                        entry.WorkDate.Date == day.Date &&
                        pageIds.Contains(entry.PageId))
                    .Sum(entry => Math.Max(0, entry.Minutes));
            }
        }

        private static int GetCalendarScheduledMinutes(
            IEnumerable<NotionCalendarActivity> activities)
        {
            if (activities == null)
                return 0;

            return activities
                .Where(activity => activity != null)
                .GroupBy(
                    activity => activity.PageId,
                    StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .Sum(activity =>
                {
                    if (activity.End <= activity.Start)
                        return 0;

                    return Math.Max(
                        0,
                        (int)Math.Round(
                            (activity.End - activity.Start)
                            .TotalMinutes));
                });
        }

        private int GetCalendarPersonWorkedMinutesToday(
            string person)
        {
            var activities =
                GetCalendarDailySummaryActivities(person);

            return GetCalendarWorkedMinutesForDay(
                activities,
                _calendarSelectedDate.Date);
        }

        private long GetCalendarWorkTimerElapsedSeconds()
        {
            EnsureCalendarWorkTimerLoaded();

            var state = _calendarWorkTimerState;
            if (state == null)
                return 0;

            var total =
                Math.Max(
                    0,
                    state.AccumulatedSeconds);

            if (state.IsRunning &&
                state.SegmentStartedAt.HasValue)
            {
                total += Math.Max(
                    0,
                    (long)Math.Floor(
                        (DateTimeOffset.Now -
                         state.SegmentStartedAt.Value)
                        .TotalSeconds));
            }

            return total;
        }

        private static string FormatCalendarWorkTimer(
            long totalSeconds)
        {
            totalSeconds =
                Math.Max(
                    0,
                    totalSeconds);

            var elapsed =
                TimeSpan.FromSeconds(totalSeconds);

            return elapsed.TotalHours >= 1
                ? elapsed.ToString(@"hh\:mm\:ss")
                : elapsed.ToString(@"mm\:ss");
        }

        private bool IsCalendarWorkTimerFor(
            NotionCalendarActivity activity)
        {
            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return false;
            }

            EnsureCalendarWorkTimerLoaded();

            return _calendarWorkTimerState != null &&
                   string.Equals(
                       _calendarWorkTimerState.PageId,
                       activity.PageId,
                       StringComparison.OrdinalIgnoreCase);
        }

        private string BuildCalendarWorkTimerBadgeText(
            NotionCalendarActivity activity)
        {
            if (activity == null)
                return string.Empty;

            if (IsCalendarWorkTimerFor(activity))
            {
                var icon =
                    _calendarWorkTimerState?.IsRunning == true
                        ? "▶"
                        : "⏸";

                return
                    $"{icon} " +
                    FormatCalendarWorkTimer(
                        GetCalendarWorkTimerElapsedSeconds());
            }

            // Aunque el cronómetro ya terminó, el tiempo trabajado queda
            // visible permanentemente en la tarjeta.
            if (activity.WorkedMinutes > 0)
            {
                return
                    $"⏱ " +
                    FormatCalendarWorkMinutes(
                        activity.WorkedMinutes);
            }

            return string.Empty;
        }

        private (Color Background, Color Border)
            GetCalendarWorkBadgeColors(
                NotionCalendarActivity activity)
        {
            var isCurrent =
                IsCalendarWorkTimerFor(activity);

            if (isCurrent &&
                _calendarWorkTimerState?.IsRunning == true)
            {
                return (
                    Color.FromArgb(238, 8, 47, 73),
                    Color.FromArgb(255, 56, 189, 248));
            }

            if (isCurrent)
            {
                return (
                    Color.FromArgb(238, 61, 38, 8),
                    Color.FromArgb(255, 251, 191, 36));
            }

            // Verde = tiempo ya guardado en Notion.
            return (
                Color.FromArgb(238, 6, 55, 45),
                Color.FromArgb(255, 52, 211, 153));
        }

        private void EnsureCalendarWorkTimerUiTimer()
        {
            if (_calendarWorkTimerUiTimer != null)
            {
                if (!_calendarWorkTimerUiTimer.IsEnabled)
                    _calendarWorkTimerUiTimer.Start();

                return;
            }

            _calendarWorkTimerUiTimer =
                new DispatcherTimer
                {
                    Interval =
                        TimeSpan.FromSeconds(1)
                };

            _calendarWorkTimerUiTimer.Tick +=
                (_, __) =>
                {
                    var state =
                        _calendarWorkTimerState;

                    if (state == null)
                        return;

                    UpdateCalendarWorkTimerVisuals(
                        state.PageId);

                    if (state.IsRunning &&
                        DateTimeOffset.Now -
                        _calendarWorkTimerLastPersistence >=
                        TimeSpan.FromSeconds(15))
                    {
                        SaveCalendarWorkTimer();
                    }
                };

            _calendarWorkTimerUiTimer.Start();
        }

        private void UpdateCalendarWorkTimerVisuals(
            string pageId)
        {
            if (string.IsNullOrWhiteSpace(pageId) ||
                !_calendarActivityVisuals.TryGetValue(
                    pageId,
                    out var visuals))
            {
                return;
            }

            var activity =
                _calendarActivities
                    .FirstOrDefault(item =>
                        string.Equals(
                            item.PageId,
                            pageId,
                            StringComparison.OrdinalIgnoreCase));

            if (activity == null)
                return;

            var timerText =
                BuildCalendarWorkTimerBadgeText(
                    activity);

            foreach (var visual in visuals)
            {
                visual.TimerText.Text = timerText;
                visual.TimerBadge.Visibility =
                    string.IsNullOrWhiteSpace(timerText)
                        ? Visibility.Collapsed
                        : Visibility.Visible;

                var colors =
                    GetCalendarWorkBadgeColors(
                        activity);

                visual.TimerBadge.Background =
                    new SolidColorBrush(
                        colors.Background);

                visual.TimerBadge.BorderBrush =
                    new SolidColorBrush(
                        colors.Border);
            }
        }

        private void RefreshCalendarWorkTimerUi(
            string? previousPageId = null)
        {
            if (!string.IsNullOrWhiteSpace(previousPageId))
            {
                UpdateCalendarWorkTimerVisuals(
                    previousPageId);
            }

            if (!string.IsNullOrWhiteSpace(
                    _calendarWorkTimerState?.PageId))
            {
                UpdateCalendarWorkTimerVisuals(
                    _calendarWorkTimerState.PageId);
            }

            if (CalendarPersonPreviewPanel?.Visibility ==
                    Visibility.Visible &&
                !string.IsNullOrWhiteSpace(
                    _calendarPersonPreviewPerson))
            {
                RenderCalendarPersonPreviewItems(
                    _calendarPersonPreviewPerson);
            }
        }

        private async Task StartCalendarWorkTimerAsync(
            NotionCalendarActivity activity)
        {
            if (activity == null ||
                activity.IsReviewMirror ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return;
            }

            EnsureCalendarWorkTimerLoaded();
            EnsureCalendarWorkTimerUiTimer();

            if (_calendarWorkTimerState != null &&
                !string.Equals(
                    _calendarWorkTimerState.PageId,
                    activity.PageId,
                    StringComparison.OrdinalIgnoreCase))
            {
                var dialog =
                    new ContentDialog
                    {
                        XamlRoot = XamlRoot,
                        Title =
                            "Ya hay un cronómetro pendiente",
                        Content =
                            $"Primero termina o cancela el cronómetro de:\n\n" +
                            $"{_calendarWorkTimerState.Title}\n\n" +
                            $"Tiempo actual: " +
                            $"{FormatCalendarWorkTimer(GetCalendarWorkTimerElapsedSeconds())}",
                        CloseButtonText = "Entendido"
                    };

                await dialog.ShowAsync();
                return;
            }

            if (_calendarWorkTimerState == null)
            {
                _calendarWorkTimerState =
                    new CalendarWorkTimerState
                    {
                        PageId = activity.PageId,
                        Title =
                            string.IsNullOrWhiteSpace(
                                activity.Title)
                                ? "Actividad"
                                : activity.Title.Trim(),
                        WorkDate = DateTime.Today,
                        AccumulatedSeconds = 0,
                        SegmentStartedAt =
                            DateTimeOffset.Now,
                        LastHeartbeatAt =
                            DateTimeOffset.Now,
                        IsRunning = true
                    };
            }
            else
            {
                if (_calendarWorkTimerState.IsRunning)
                {
                    StatusText.Text =
                        "Estado: El cronómetro ya está corriendo.";
                    return;
                }

                _calendarWorkTimerState.SegmentStartedAt =
                    DateTimeOffset.Now;
                _calendarWorkTimerState.LastHeartbeatAt =
                    DateTimeOffset.Now;
                _calendarWorkTimerState.IsRunning = true;
            }

            SaveCalendarWorkTimer();
            RefreshCalendarWorkTimerUi();

            StatusText.Text =
                $"Estado: ▶ Cronómetro iniciado · " +
                $"{activity.Title}";
        }

        private void PauseCalendarWorkTimer(
            NotionCalendarActivity activity)
        {
            if (!IsCalendarWorkTimerFor(activity) ||
                _calendarWorkTimerState == null ||
                !_calendarWorkTimerState.IsRunning)
            {
                return;
            }

            if (_calendarWorkTimerState
                .SegmentStartedAt.HasValue)
            {
                _calendarWorkTimerState
                    .AccumulatedSeconds +=
                    Math.Max(
                        0,
                        (long)Math.Floor(
                            (DateTimeOffset.Now -
                             _calendarWorkTimerState
                                 .SegmentStartedAt.Value)
                            .TotalSeconds));
            }

            _calendarWorkTimerState.IsRunning = false;
            _calendarWorkTimerState.SegmentStartedAt = null;
            _calendarWorkTimerState.LastHeartbeatAt =
                DateTimeOffset.Now;

            SaveCalendarWorkTimer();
            RefreshCalendarWorkTimerUi();

            StatusText.Text =
                $"Estado: ⏸ Cronómetro pausado · " +
                $"{FormatCalendarWorkTimer(GetCalendarWorkTimerElapsedSeconds())}";
        }

        private async Task FinishCalendarWorkTimerAsync(
            NotionCalendarActivity activity)
        {
            if (!IsCalendarWorkTimerFor(activity) ||
                _calendarWorkTimerState == null)
            {
                return;
            }

            if (_calendarWorkTimerState.IsRunning &&
                _calendarWorkTimerState
                    .SegmentStartedAt.HasValue)
            {
                _calendarWorkTimerState
                    .AccumulatedSeconds +=
                    Math.Max(
                        0,
                        (long)Math.Floor(
                            (DateTimeOffset.Now -
                             _calendarWorkTimerState
                                 .SegmentStartedAt.Value)
                            .TotalSeconds));

                _calendarWorkTimerState.IsRunning = false;
                _calendarWorkTimerState.SegmentStartedAt =
                    null;
            }

            var totalSeconds =
                Math.Max(
                    0,
                    _calendarWorkTimerState
                        .AccumulatedSeconds);

            if (totalSeconds <= 0)
            {
                StatusText.Text =
                    "Estado: El cronómetro todavía no tiene tiempo para guardar.";
                return;
            }

            var workedMinutes =
                Math.Max(
                    1,
                    (int)Math.Round(
                        totalSeconds / 60d,
                        MidpointRounding.AwayFromZero));

            var workDate =
                _calendarWorkTimerState.WorkDate.Date;

            var confirmation =
                new ContentDialog
                {
                    XamlRoot = XamlRoot,
                    Title =
                        "Guardar tiempo trabajado",
                    Content =
                        $"{activity.Title}\n\n" +
                        $"Cronómetro: " +
                        $"{FormatCalendarWorkTimer(totalSeconds)}\n" +
                        $"Se registrará en Notion: " +
                        $"{FormatCalendarWorkMinutes(workedMinutes)}\n\n" +
                        "El registro queda acumulado con el tiempo trabajado existente.",
                    PrimaryButtonText =
                        "Guardar y terminar",
                    CloseButtonText =
                        "Cancelar",
                    DefaultButton =
                        ContentDialogButton.Primary
                };

            if (await confirmation.ShowAsync() !=
                ContentDialogResult.Primary)
            {
                // Permanece pausado para que el usuario pueda continuar.
                SaveCalendarWorkTimer();
                RefreshCalendarWorkTimerUi();
                return;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return;
            }

            try
            {
                StatusText.Text =
                    "Estado: Guardando cronómetro en Notion...";

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(2));

                var result =
                    await _notionCalendarService
                        .RegisterActivityWorkAsync(
                            token,
                            activity,
                            workDate,
                            workedMinutes,
                            cts.Token);

                activity.EstimatedWorkMinutes =
                    result.Activity.EstimatedWorkMinutes;
                activity.WorkedMinutes =
                    result.Activity.WorkedMinutes;
                activity.WorkLogDetail =
                    result.Activity.WorkLogDetail;

                RegisterCalendarWorkSession(
                    activity,
                    workDate,
                    workedMinutes,
                    "Cronómetro");

                var previousPageId =
                    _calendarWorkTimerState.PageId;

                _calendarWorkTimerState = null;
                SaveCalendarWorkTimer();

                var currentDay =
                    await _notionCalendarService
                        .TryGetCachedDayAsync(
                            _calendarSelectedDate,
                            cts.Token);

                _calendarActivities =
                    currentDay ??
                    _calendarActivities;

                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);

                RefreshCalendarWorkTimerUi(
                    previousPageId);

                StatusText.Text =
                    $"Estado: ⏱ Tiempo guardado ✅ · " +
                    $"{FormatCalendarWorkMinutes(workedMinutes)} · " +
                    $"{activity.WorkProgressLabel}";
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: Notion tardó demasiado en guardar el cronómetro.";
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo guardar el cronómetro → {ex.Message}";
            }
        }

        private async Task CancelCalendarWorkTimerAsync(
            NotionCalendarActivity activity)
        {
            if (!IsCalendarWorkTimerFor(activity) ||
                _calendarWorkTimerState == null)
            {
                return;
            }

            var elapsed =
                FormatCalendarWorkTimer(
                    GetCalendarWorkTimerElapsedSeconds());

            var dialog =
                new ContentDialog
                {
                    XamlRoot = XamlRoot,
                    Title =
                        "Cancelar cronómetro",
                    Content =
                        $"Se descartarán {elapsed} de esta sesión.\n\n" +
                        "No se modificará el tiempo ya guardado en Notion.",
                    PrimaryButtonText =
                        "Descartar",
                    CloseButtonText =
                        "Conservar",
                    DefaultButton =
                        ContentDialogButton.Close
                };

            if (await dialog.ShowAsync() !=
                ContentDialogResult.Primary)
            {
                return;
            }

            var previousPageId =
                _calendarWorkTimerState.PageId;

            _calendarWorkTimerState = null;
            SaveCalendarWorkTimer();
            RefreshCalendarWorkTimerUi(
                previousPageId);

            StatusText.Text =
                "Estado: Cronómetro descartado.";
        }

