        private void CopyCalendarText(
            string text,
            string status)
        {
            if (string.IsNullOrWhiteSpace(text))
                return;

            var package =
                new Windows.ApplicationModel.DataTransfer
                    .DataPackage();

            package.SetText(text);

            Windows.ApplicationModel.DataTransfer
                .Clipboard.SetContent(package);

            StatusText.Text = status;
        }

        private void CalendarPeopleButton_Click(
            object sender,
            RoutedEventArgs e)
        {
            var flyout = new MenuFlyout();

            var all = new MenuFlyoutItem
            {
                Text = "Seleccionar todas"
            };
            all.Click += (_, __) =>
            {
                _calendarSelectedPeople.Clear();

                foreach (var person in ActiveCalendarPeople)
                    _calendarSelectedPeople.Add(person);

                SaveCalendarPreferences();
                DrawCalendar(_calendarActivities);
            };
            flyout.Items.Add(all);

            var clear = new MenuFlyoutItem
            {
                Text = "Limpiar selección"
            };
            clear.Click += (_, __) =>
            {
                _calendarSelectedPeople.Clear();
                SaveCalendarPreferences();
                DrawCalendar(_calendarActivities);
            };
            flyout.Items.Add(clear);
            flyout.Items.Add(new MenuFlyoutSeparator());

            foreach (var person in _calendarPeopleOrder)
            {
                var item = new ToggleMenuFlyoutItem
                {
                    Text = person,
                    IsChecked =
                        _calendarSelectedPeople.Contains(person),
                    Tag = person
                };

                item.Click += (_, __) =>
                {
                    if (item.IsChecked)
                        _calendarSelectedPeople.Add(person);
                    else
                        _calendarSelectedPeople.Remove(person);

                    SaveCalendarPreferences();
                    DrawCalendar(_calendarActivities);
                };

                flyout.Items.Add(item);
            }

            flyout.ShowAt(CalendarPeopleButton);
        }

        private void CalendarZoomIn_Click(
            object sender,
            RoutedEventArgs e)
            => ChangeCalendarZoom(0.10);

        private void CalendarZoomOut_Click(
            object sender,
            RoutedEventArgs e)
            => ChangeCalendarZoom(-0.10);

        private void ChangeCalendarZoom(double delta)
        {
            var nextZoom =
                Math.Clamp(
                    Math.Round(
                        _calendarZoom + delta,
                        2),
                    0.70,
                    1.40);

            if (Math.Abs(
                    nextZoom -
                    _calendarZoom) < 0.001)
            {
                return;
            }

            _calendarZoom = nextZoom;

            SaveCalendarPreferences();
            DrawCalendar(_calendarActivities);
        }

        private void QueueCalendarWheelZoom(
            double delta)
        {
            _calendarPendingZoomDelta += delta;

            if (_calendarZoomDebounceTimer == null)
            {
                _calendarZoomDebounceTimer =
                    new DispatcherTimer
                    {
                        Interval =
                            TimeSpan.FromMilliseconds(140)
                    };

                _calendarZoomDebounceTimer.Tick +=
                    (_, __) =>
                    {
                        _calendarZoomDebounceTimer.Stop();

                        var pending =
                            _calendarPendingZoomDelta;

                        _calendarPendingZoomDelta = 0;

                        if (Math.Abs(pending) < 0.001)
                            return;

                        ChangeCalendarZoom(
                            pending > 0
                                ? 0.10
                                : -0.10);
                    };
            }

            _calendarZoomDebounceTimer.Stop();
            _calendarZoomDebounceTimer.Start();
        }

        private void EnsureCalendarWheelHandler()
        {
            if (_calendarWheelHandlerHooked ||
                CalendarCanvas == null)
            {
                return;
            }

            // Se engancha al contenido interno para interceptar la rueda
            // antes de que el ScrollViewer aplique desplazamiento vertical.
            CalendarCanvas.AddHandler(
                UIElement.PointerWheelChangedEvent,
                new PointerEventHandler(
                    CalendarScrollViewer_PointerWheelChanged),
                handledEventsToo: true);

            _calendarWheelHandlerHooked = true;

            if (!_calendarEmptySlotHandlerHooked)
            {
                CalendarCanvas.AddHandler(
                    UIElement.PointerPressedEvent,
                    new PointerEventHandler(
                        CalendarCanvas_EmptySlotPointerPressed),
                    handledEventsToo: true);

                CalendarCanvas.AddHandler(
                    UIElement.PointerReleasedEvent,
                    new PointerEventHandler(
                        CalendarCanvas_EmptySlotPointerReleased),
                    handledEventsToo: true);

                _calendarEmptySlotHandlerHooked = true;
            }
        }

        private void CalendarCanvas_EmptySlotPointerPressed(
            object sender,
            PointerRoutedEventArgs e)
        {
            _calendarEmptySlotPointerArmed = false;

            if (!_calendarViewActive ||
                CalendarCanvas == null ||
                _calendarEmptySlotDialogOpen ||
                _calendarDragActive)
            {
                return;
            }

            // Clics sobre cards, botones, pickers, etc. pertenecen a esos
            // controles y nunca deben iniciar la creación desde hueco.
            // One Click lateral NO bloquea el resto del calendario: la idea
            // del panel lateral es precisamente conservar interacción con los huecos.
            if (IsCalendarInteractiveTapSource(
                    e.OriginalSource as DependencyObject))
            {
                return;
            }

            var current = e.GetCurrentPoint(CalendarCanvas);

            // En escritorio solo se arma con clic izquierdo. No marcamos el
            // evento como Handled para que el ScrollViewer conserve su lógica.
            if (!current.Properties.IsLeftButtonPressed)
                return;

            var point = current.Position;

            if (!TryResolveCalendarEmptySlotSeed(
                    point,
                    out _))
            {
                return;
            }

            _calendarEmptySlotPointerArmed = true;
            _calendarEmptySlotPointerId = e.Pointer.PointerId;
            _calendarEmptySlotPointerStart = point;
        }

        private async void CalendarCanvas_EmptySlotPointerReleased(
            object sender,
            PointerRoutedEventArgs e)
        {
            if (!_calendarEmptySlotPointerArmed ||
                e.Pointer.PointerId != _calendarEmptySlotPointerId)
            {
                return;
            }

            _calendarEmptySlotPointerArmed = false;

            if (!_calendarViewActive ||
                CalendarCanvas == null ||
                _calendarEmptySlotDialogOpen ||
                _calendarDragActive)
            {
                return;
            }

            if (IsCalendarInteractiveTapSource(
                    e.OriginalSource as DependencyObject))
            {
                return;
            }

            var point =
                e.GetCurrentPoint(CalendarCanvas).Position;

            var deltaX =
                point.X - _calendarEmptySlotPointerStart.X;

            var deltaY =
                point.Y - _calendarEmptySlotPointerStart.Y;

            // Si el usuario realmente estaba desplazando el calendario, no
            // se abre nada. Un clic normal tiene prácticamente cero recorrido.
            if ((deltaX * deltaX) + (deltaY * deltaY) > 100d)
                return;

            if (!TryResolveCalendarEmptySlotSeed(
                    point,
                    out var seed))
            {
                return;
            }

            try
            {
                _calendarEmptySlotDialogOpen = true;
                await ShowCalendarCreateFromEmptySlotDialogAsync(seed);
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo abrir la creación rápida → {ex.Message}";
            }
            finally
            {
                _calendarEmptySlotDialogOpen = false;
            }
        }

        private static bool IsCalendarInteractiveTapSource(
            DependencyObject? source)
        {
            var current = source;

            while (current != null)
            {
                if (current is ButtonBase ||
                    current is TextBox ||
                    current is RichEditBox ||
                    current is ComboBox ||
                    current is DatePicker ||
                    current is TimePicker ||
                    current is ListView ||
                    current is ListViewItem ||
                    current is ScrollBar ||
                    current is Slider ||
                    current is ToggleSwitch)
                {
                    return true;
                }

                current = VisualTreeHelper.GetParent(current);
            }

            return false;
        }

        private bool TryResolveCalendarEmptySlotSeed(
            Windows.Foundation.Point point,
            out CalendarQuickCreationSeed seed)
        {
            seed = null!;

            var headerHeight = CalendarHeaderHeight;
            var bodyHeight =
                (CalendarVisibleEndHour - CalendarStartHour) *
                CalendarHourHeight;

            if (point.Y < headerHeight ||
                point.Y >= headerHeight + bodyHeight ||
                point.X < CalendarTimeColumnWidth)
            {
                return false;
            }

            string? person = null;

            foreach (var candidate in
                     _calendarPeopleOrder.Where(value =>
                         _calendarSelectedPeople.Contains(value)))
            {
                var left =
                    GetResolvedCalendarColumnLeft(candidate);

                var width =
                    GetResolvedCalendarColumnWidth(candidate);

                if (point.X >= left &&
                    point.X < left + width)
                {
                    person = candidate;
                    break;
                }
            }

            if (string.IsNullOrWhiteSpace(person))
                return false;

            var rawMinutes =
                (point.Y - headerHeight) /
                CalendarHourHeight * 60d;

            var snappedMinutes =
                (int)(Math.Round(
                    rawMinutes / 15d,
                    MidpointRounding.AwayFromZero) * 15d);

            var visibleMinutes =
                Math.Max(
                    15,
                    (CalendarVisibleEndHour - CalendarStartHour) * 60);

            snappedMinutes =
                Math.Clamp(
                    snappedMinutes,
                    0,
                    Math.Max(0, visibleMinutes - 15));

            var start =
                _calendarSelectedDate.Date
                    .AddHours(CalendarStartHour)
                    .AddMinutes(snappedMinutes);

            // Una creación cerca del final del día nunca nace fuera del
            // límite real de ANFETA (22:00).
            var absoluteEnd =
                _calendarSelectedDate.Date
                    .AddHours(CalendarEndHour);

            var availableMinutes =
                Math.Max(
                    15,
                    (int)Math.Floor(
                        (absoluteEnd - start).TotalMinutes));

            var duration =
                Math.Clamp(
                    Math.Min(60, availableMinutes),
                    15,
                    60);

            seed =
                new CalendarQuickCreationSeed(
                    person,
                    start,
                    duration);

            return true;
        }

        private void CalendarScrollViewer_PointerWheelChanged(
            object sender,
            PointerRoutedEventArgs e)
        {
            if (CalendarScrollViewer == null)
                return;

            var delta =
                e.GetCurrentPoint(CalendarCanvas)
                    .Properties
                    .MouseWheelDelta;

            if (delta == 0)
                return;

            if (IsCalendarControlDown())
            {
                // Se acumulan varios pulsos y se redibuja una sola vez.
                // Esto evita reconstruir cientos de controles por cada
                // pequeña señal de la rueda.
                QueueCalendarWheelZoom(
                    delta > 0
                        ? 0.10
                        : -0.10);

                e.Handled = true;
                return;
            }

            if (!IsCalendarShiftDown())
                return;

            var verticalBefore =
                CalendarScrollViewer.VerticalOffset;

            var step =
                Math.Max(
                    42,
                    CalendarScrollViewer.ViewportWidth * 0.055);

            var nextHorizontal =
                Math.Clamp(
                    CalendarScrollViewer.HorizontalOffset -
                    Math.Sign(delta) * step,
                    0,
                    CalendarScrollViewer.ScrollableWidth);

            // Movimiento horizontal corto para evitar brincos.
            CalendarScrollViewer.ChangeView(
                nextHorizontal,
                verticalBefore,
                null,
                disableAnimation: false);

            _calendarStableVerticalOffset =
                verticalBefore;

            UpdateCalendarStickyElements();
            e.Handled = true;
        }

        private void CalendarScrollViewer_ViewChanged(
            object sender,
            ScrollViewerViewChangedEventArgs e)
        {
            if (CalendarScrollViewer == null)
                return;

            if (!IsCalendarShiftDown())
            {
                _calendarStableVerticalOffset =
                    CalendarScrollViewer.VerticalOffset;
            }

            UpdateCalendarStickyElements();
        }

        private void UpdateCalendarStickyElements()
        {
            if (CalendarScrollViewer == null)
                return;

            var horizontal =
                CalendarScrollViewer.HorizontalOffset;

            var vertical =
                CalendarScrollViewer.VerticalOffset;

            foreach (var header in _calendarStickyHeaders)
                Canvas.SetTop(header, vertical + 2);

            foreach (var hour in _calendarStickyHours)
            {
                var baseLeft =
                    hour.Tag is CalendarStickyPosition position
                        ? position.Left
                        : 8;

                Canvas.SetLeft(hour, horizontal + baseLeft);
            }

            if (_calendarStickyCorner != null)
            {
                Canvas.SetLeft(
                    _calendarStickyCorner,
                    horizontal + 10);

                Canvas.SetTop(
                    _calendarStickyCorner,
                    vertical + 17 * _calendarZoom);
            }
        }

        private sealed record CalendarStickyPosition(
            double Left,
            double Top);

        private void LoadCalendarPreferences()
        {
            if (_calendarPreferencesLoaded)
                return;

            _calendarPreferencesLoaded = true;

            var values =
                ApplicationData.Current.LocalSettings.Values;

            if (values.TryGetValue(
                    LS_CalendarZoom,
                    out var zoomRaw) &&
                double.TryParse(
                    zoomRaw?.ToString(),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out var zoom))
            {
                _calendarZoom =
                    Math.Clamp(zoom, 0.70, 1.40);
            }

            var savedSelectionVersion =
                values.TryGetValue(
                    LS_CalendarPeopleSelectionVersion,
                    out var selectionVersionRaw) &&
                int.TryParse(
                    selectionVersionRaw?.ToString(),
                    out var selectionVersion)
                    ? selectionVersion
                    : 0;

            if (savedSelectionVersion < CalendarPeopleSelectionVersion)
            {
                _calendarSelectedPeople.Clear();

                foreach (var person in ActiveCalendarPeople)
                    _calendarSelectedPeople.Add(person);

                values[LS_CalendarPeopleSelectionVersion] =
                    CalendarPeopleSelectionVersion;

                values[LS_CalendarPeople] =
                    string.Join("|", ActiveCalendarPeople);
            }

            var selected =
                values[LS_CalendarPeople] as string;

            if (!string.IsNullOrWhiteSpace(selected))
            {
                _calendarSelectedPeople.Clear();

                foreach (var person in selected.Split('|'))
                {
                    if (ActiveCalendarPeople.Contains(
                            person,
                            StringComparer.OrdinalIgnoreCase))
                    {
                        _calendarSelectedPeople.Add(person);
                    }
                }

                // Las personas/columnas agregadas en versiones nuevas no deben
                // quedar ocultas por preferencias antiguas.
                foreach (var person in ActiveCalendarPeople)
                {
                    if (!_calendarSelectedPeople.Contains(person) &&
                        string.Equals(
                            person,
                            "Sin asignar",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        _calendarSelectedPeople.Add(person);
                    }
                }
            }

            var savedWidths =
                values[LS_CalendarColumnWidths] as string;

            if (!string.IsNullOrWhiteSpace(savedWidths))
            {
                foreach (var entry in savedWidths.Split('|'))
                {
                    var parts = entry.Split('=');

                    if (parts.Length != 2)
                        continue;

                    var person = parts[0].Trim();

                    if (!ActiveCalendarPeople.Contains(
                            person,
                            StringComparer.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    if (double.TryParse(
                            parts[1],
                            NumberStyles.Float,
                            CultureInfo.InvariantCulture,
                            out var width))
                    {
                        _calendarColumnWidths[person] =
                            Math.Clamp(
                                width,
                                CalendarMinPersonColumnWidth,
                                CalendarMaxPersonColumnWidth);
                    }
                }
            }

            var order =
                values[LS_CalendarOrder] as string;

            if (!string.IsNullOrWhiteSpace(order))
            {
                var saved = order
                    .Split('|')
                    .Where(person =>
                        ActiveCalendarPeople.Contains(
                            person,
                            StringComparer.OrdinalIgnoreCase))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();

                foreach (var person in ActiveCalendarPeople)
                {
                    if (!saved.Contains(
                            person,
                            StringComparer.OrdinalIgnoreCase))
                    {
                        saved.Add(person);
                    }
                }

                _calendarPeopleOrder.Clear();
                _calendarPeopleOrder.AddRange(saved);
            }
        }

        private void SaveCalendarPreferences()
        {
            var values =
                ApplicationData.Current.LocalSettings.Values;

            values[LS_CalendarZoom] =
                _calendarZoom.ToString(
                    CultureInfo.InvariantCulture);

            values[LS_CalendarPeopleSelectionVersion] =
                CalendarPeopleSelectionVersion;

            values[LS_CalendarPeople] =
                string.Join(
                    "|",
                    _calendarPeopleOrder.Where(person =>
                        _calendarSelectedPeople.Contains(person)));

            values[LS_CalendarOrder] =
                string.Join("|", _calendarPeopleOrder);

            values[LS_CalendarColumnWidths] =
                string.Join(
                    "|",
                    _calendarPeopleOrder.Select(person =>
                        $"{person}={GetStoredCalendarColumnWidth(person).ToString(CultureInfo.InvariantCulture)}"));
        }

        private void ResolveCalendarColumnLayout(
            IReadOnlyList<string> persons,
            double viewportWidth)
        {
            _calendarResolvedColumnWidths.Clear();
            _calendarResolvedColumnLefts.Clear();
            _calendarCobroRailWidth = 0;
            _calendarCobroRailLeft = CalendarTimeColumnWidth;

            if (persons.Count == 0)
                return;

            var available =
                Math.Max(
                    0,
                    viewportWidth -
                    CalendarTimeColumnWidth);

            var responsiveMaxBase =
                persons.Count <= 4
                    ? 460d
                    : persons.Count <= 6
                        ? 400d
                        : 360d;

            var minResolvedWidth =
                CalendarMinPersonColumnWidth *
                _calendarZoom;

            var maxResolvedWidth =
                Math.Max(
                    minResolvedWidth,
                    responsiveMaxBase *
                    _calendarZoom);

            var widths =
                persons
                    .Select(person =>
                        Math.Clamp(
                            GetStoredCalendarColumnWidth(
                                person) *
                            _calendarZoom,
                            minResolvedWidth,
                            maxResolvedWidth))
                    .ToList();

            var hasCobros =
                _calendarShowCobros &&
                GetCalendarCobroItems(
                    _calendarSelectedDate).Count > 0;

            if (hasCobros)
            {
                _calendarCobroRailWidth =
                    Math.Clamp(
                        190d * _calendarZoom,
                        160d,
                        240d);
            }

            var total = widths.Sum();
            // El carril de Cobros se SUMA al calendario; no reduce las
            // columnas que ya estaban visibles. Si hace falta, aparece scroll
            // horizontal en lugar de comprimir actividades.
            var activityAvailable = available;

            if (activityAvailable > total + 0.5)
            {
                var remaining = activityAvailable - total;

                while (remaining > 0.5)
                {
                    var expandable =
                        Enumerable.Range(0, widths.Count)
                            .Where(index =>
                                widths[index] <
                                maxResolvedWidth - 0.5)
                            .ToList();

                    if (expandable.Count == 0)
                        break;

                    var share = remaining / expandable.Count;
                    var consumed = 0d;

                    foreach (var index in expandable)
                    {
                        var room = maxResolvedWidth - widths[index];
                        var add = Math.Min(room, share);
                        widths[index] += add;
                        consumed += add;
                    }

                    if (consumed <= 0.5)
                        break;

                    remaining -= consumed;
                }
            }
            else if (activityAvailable > 0 &&
                     total > activityAvailable + 0.5)
            {
                var required = total - activityAvailable;

                while (required > 0.5)
                {
                    var shrinkable =
                        Enumerable.Range(0, widths.Count)
                            .Where(index =>
                                widths[index] >
                                minResolvedWidth + 0.5)
                            .ToList();

                    if (shrinkable.Count == 0)
                        break;

                    var share = required / shrinkable.Count;
                    var reduced = 0d;

                    foreach (var index in shrinkable)
                    {
                        var room = widths[index] - minResolvedWidth;
                        var take = Math.Min(room, share);
                        widths[index] -= take;
                        reduced += take;
                    }

                    if (reduced <= 0.5)
                        break;

                    required -= reduced;
                }
            }

            var resolvedSlot =
                Math.Clamp(
                    _calendarCobroColumnSlot,
                    0,
                    persons.Count);

            var currentLeft = CalendarTimeColumnWidth;

            for (var index = 0; index < persons.Count; index++)
            {
                if (_calendarCobroRailWidth > 0 &&
                    index == resolvedSlot)
                {
                    _calendarCobroRailLeft = currentLeft;
                    currentLeft += _calendarCobroRailWidth;
                }

                var person = persons[index];
                var resolvedWidth = widths[index];

                _calendarResolvedColumnLefts[person] = currentLeft;
                _calendarResolvedColumnWidths[person] = resolvedWidth;
                currentLeft += resolvedWidth;
            }

            if (_calendarCobroRailWidth > 0 &&
                resolvedSlot == persons.Count)
            {
                _calendarCobroRailLeft = currentLeft;
            }
        }

        private double GetStoredCalendarColumnWidth(
            string person)
        {
            return _calendarColumnWidths.TryGetValue(
                    person,
                    out var width)
                ? Math.Clamp(
                    width,
                    CalendarMinPersonColumnWidth,
                    CalendarMaxPersonColumnWidth)
                : CalendarBasePersonColumnWidth;
        }

        private double GetResolvedCalendarColumnWidth(
            string person)
        {
            return _calendarResolvedColumnWidths.TryGetValue(
                    person,
                    out var width)
                ? width
                : CalendarDefaultPersonColumnWidth;
        }

        private double GetResolvedCalendarColumnLeft(
            string person)
        {
            return _calendarResolvedColumnLefts.TryGetValue(
                    person,
                    out var left)
                ? left
                : CalendarTimeColumnWidth;
        }

        private double GetResolvedCalendarCobroRailWidth()
        {
            return Math.Max(0, _calendarCobroRailWidth);
        }

        private double GetResolvedCalendarCobroRailLeft()
        {
            return _calendarCobroRailLeft;
        }

        private bool TryGetCalendarProjectCachedContent(
            string pageId,
            out IReadOnlyList<NotionPreviewBlock> blocks)
        {
            blocks =
                Array.Empty<NotionPreviewBlock>();

            var clean =
                (pageId ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(clean))
                return false;

            if (!_calendarProjectContentCache.TryGetValue(
                    clean,
                    out var cached))
            {
                return false;
            }

            if (DateTimeOffset.UtcNow - cached.StoredAt >
                CalendarProjectContentCacheLifetime)
            {
                _calendarProjectContentCache.Remove(clean);
                return false;
            }

            blocks = cached.Blocks;
            return true;
        }

        private void SaveCalendarProjectCachedContent(
            string pageId,
            IReadOnlyList<NotionPreviewBlock> blocks)
        {
            var clean =
                (pageId ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(clean))
                return;

            _calendarProjectContentCache[clean] =
                new CalendarProjectContentCacheEntry(
                    DateTimeOffset.UtcNow,
                    blocks ?? Array.Empty<NotionPreviewBlock>());

            _calendarProjectContentLoadFailures.Remove(clean);

            // Límite defensivo para que una sesión muy larga no conserve
            // cientos de bodies completos en memoria.
            if (_calendarProjectContentCache.Count <= 80)
                return;

            foreach (var oldKey in
                     _calendarProjectContentCache
                         .OrderBy(item => item.Value.StoredAt)
                         .Take(
                             _calendarProjectContentCache.Count - 80)
                         .Select(item => item.Key)
                         .ToList())
            {
                _calendarProjectContentCache.Remove(oldKey);
            }
        }

        private int GetCalendarProjectLoadedContentCount(
            IEnumerable<NotionCalendarActivity> activities)
        {
            return (activities ??
                    Enumerable.Empty<NotionCalendarActivity>())
                .Where(activity =>
                    activity != null &&
                    !string.IsNullOrWhiteSpace(activity.PageId))
                .GroupBy(
                    activity => activity.PageId,
                    StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .Count(activity =>
                    TryGetCalendarProjectCachedContent(
                        activity.PageId,
                        out _));
        }

        private async Task PreloadCalendarProjectContentAsync(
            IReadOnlyList<NotionCalendarActivity> activities,
            string token,
            CancellationToken cancellationToken)
        {
            var unique =
                (activities ??
                 Array.Empty<NotionCalendarActivity>())
                    .Where(activity =>
                        activity != null &&
                        !activity.IsReviewMirror &&
                        !string.IsNullOrWhiteSpace(
                            activity.PageId))
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();

            if (unique.Count == 0 ||
                string.IsNullOrWhiteSpace(token))
            {
                return;
            }

            _calendarProjectContentPreloadRunning = true;
            _calendarProjectContentPreloadCompleted =
                GetCalendarProjectLoadedContentCount(unique);
            _calendarProjectContentPreloadTotal =
                unique.Count;

            try
            {
                for (var index = 0;
                     index < unique.Count;
                     index++)
                {
                    cancellationToken.ThrowIfCancellationRequested();

                    var activity =
                        unique[index];

                    if (TryGetCalendarProjectCachedContent(
                            activity.PageId,
                            out _))
                    {
                        _calendarProjectContentPreloadCompleted =
                            Math.Min(
                                _calendarProjectContentPreloadTotal,
                                _calendarProjectContentPreloadCompleted + 1);

                        continue;
                    }

                    StatusText.Text =
                        $"Estado: Checklist listo ✅ · " +
                        $"precargando contenido {index + 1} de {unique.Count}…";

                    if (_calendarProjectPreviewActive &&
                        CalendarPersonPreviewSummary != null)
                    {
                        var currentStats =
                            GetCalendarProjectChecklistStats(
                                unique);

                        CalendarPersonPreviewSummary.Text =
                            $"{unique.Count} actividad(es) · " +
                            $"☑ {currentStats.Completed}/{currentStats.Total} · " +
                            $"{GetChecklistPercentage(currentStats)}% global · " +
                            $"contenido {_calendarProjectContentPreloadCompleted}/{unique.Count}";
                    }

                    try
                    {
                        using var itemCts =
                            CancellationTokenSource
                                .CreateLinkedTokenSource(
                                    cancellationToken);

                        itemCts.CancelAfter(
                            TimeSpan.FromMinutes(3));

                        var blocks =
                            await _notionPreviewService
                                .GetPagePreviewAsync(
                                    token,
                                    activity.PageId,
                                    itemCts.Token);

                        SaveCalendarProjectCachedContent(
                            activity.PageId,
                            blocks);
                    }
                    catch (OperationCanceledException)
                    {
                        cancellationToken.ThrowIfCancellationRequested();

                        _calendarProjectContentLoadFailures.Add(
                            activity.PageId);
                    }
                    catch (Exception ex)
                    {
                        _calendarProjectContentLoadFailures.Add(
                            activity.PageId);

                        Debug.WriteLine(
                            $"[PROJECT_CONTENT_PRELOAD] " +
                            $"{activity.PageId}: {ex.Message}");
                    }

                    _calendarProjectContentPreloadCompleted =
                        GetCalendarProjectLoadedContentCount(unique);

                    if (_calendarProjectPreviewActive &&
                        CalendarPersonPreviewSummary != null)
                    {
                        var currentStats =
                            GetCalendarProjectChecklistStats(
                                unique);

                        CalendarPersonPreviewSummary.Text =
                            $"{unique.Count} actividad(es) · " +
                            $"☑ {currentStats.Completed}/{currentStats.Total} · " +
                            $"{GetChecklistPercentage(currentStats)}% global · " +
                            $"contenido {_calendarProjectContentPreloadCompleted}/{unique.Count}";
                    }
                }
            }
            finally
            {
                _calendarProjectContentPreloadRunning = false;
                _calendarProjectContentPreloadCompleted =
                    GetCalendarProjectLoadedContentCount(unique);
                _calendarProjectContentPreloadTotal =
                    unique.Count;
            }
        }

        private async Task WarmCalendarProjectPanelChecklistAsync(
            CalendarProjectGroupCriteria criteria,
            IReadOnlyList<NotionCalendarActivity> activities,
            CancellationToken cancellationToken)
        {
            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token) ||
                activities == null ||
                activities.Count == 0)
            {
                return;
            }

            try
            {
                await _notionCalendarService
                    .WarmChecklistStatsForActivitiesAsync(
                        token,
                        activities,
                        cancellationToken);

                cancellationToken.ThrowIfCancellationRequested();

                SaveCalendarProjectActivitiesToMemory(
                    criteria,
                    activities);

                if (_calendarProjectPreviewActive &&
                    _calendarProjectPreviewCriteria != null &&
                    string.Equals(
                        _calendarProjectPreviewCriteria.Key,
                        criteria.Key,
                        StringComparison.OrdinalIgnoreCase))
                {
                    RenderCalendarProjectPreviewItems();

                    var stats =
                        GetCalendarProjectChecklistStats(
                            activities);

                    StatusText.Text =
                        stats.Total > 0
                            ? $"Estado: Proyecto precargado ✅ · " +
                              $"{stats.Completed}/{stats.Total} · " +
                              $"{GetChecklistPercentage(stats)}%"
                            : "Estado: Proyecto precargado ✅ · sin checklist activo";
                }
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                Debug.WriteLine(
                    $"[PROJECT_PANEL_CHECKLIST_WARM] {ex.Message}");
            }
        }

        private async Task ShowCalendarProjectPreviewAsync(
            NotionCalendarActivity sourceActivity)
        {
            if (sourceActivity == null ||
                CalendarPersonPreviewPanel == null ||
                CalendarPersonPreviewItems == null)
            {
                return;
            }

            if (!TryBuildCalendarProjectGroupCriteria(
                    sourceActivity,
                    out var criteria))
            {
                // Para tarjetas que todavía no tienen tipo/dominio/persona
                // suficientes, conserva el comportamiento útil del panel.
                var fallbackPerson =
                    SplitPersons(sourceActivity.Person)
                        .Select(NormalizeCalendarPerson)
                        .FirstOrDefault() ??
                    "Sin asignar";

                StatusText.Text =
                    "Estado: Esta actividad todavía no tiene tipo + dominio + persona + mes suficientes para agruparla.";

                ShowCalendarPersonPreview(
                    fallbackPerson);

                return;
            }

            try
            {
                _calendarPersonPreviewCts?.Cancel();
                _calendarPersonPreviewCts?.Dispose();
            }
            catch
            {
            }

            _calendarPersonPreviewCts =
                new CancellationTokenSource();

            var cancellationToken =
                _calendarPersonPreviewCts.Token;

            _calendarProjectPreviewActive = true;
            EnsureCalendarProjectCardZoomLoaded();

            _calendarProjectPreviewCriteria = criteria;
            _calendarProjectPreviewActivities =
                Array.Empty<NotionCalendarActivity>();
            _calendarProjectPreviewSourcePageId =
                sourceActivity.PageId;
            _calendarPersonPreviewPerson =
                criteria.Person;

            CalendarPersonPreviewPanel.Visibility =
                Visibility.Visible;

            CalendarPersonPreviewTitle.Text =
                $"{criteria.ProjectLabel} · {criteria.Domain}";

            CalendarPersonPreviewDate.Text =
                $"{criteria.MonthTag} · " +
                GetCalendarProjectMonthLabel(criteria);

            CalendarPersonPreviewSummary.Text =
                "Buscando actividades relacionadas…";

            CalendarPersonPreviewItems.Children.Clear();

            CalendarPersonPreviewItems.Children.Add(
                BuildCalendarPersonPreviewMessage(
                    "Buscando en Revisiones por tipo de proyecto, dominio, persona y mes…",
                    isError: false));

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                CalendarPersonPreviewSummary.Text =
                    "Configura primero el token de Notion.";

                CalendarPersonPreviewItems.Children.Clear();
                CalendarPersonPreviewItems.Children.Add(
                    BuildCalendarPersonPreviewMessage(
                        "No hay un token de Notion configurado.",
                        isError: true));

                return;
            }

            try
            {
                StatusText.Text =
                    $"Estado: Buscando proyecto {criteria.ProjectLabel} · " +
                    $"{criteria.Domain} · {criteria.Person}…";

                using var timeoutCts =
                    CancellationTokenSource
                        .CreateLinkedTokenSource(
                            cancellationToken);

                timeoutCts.CancelAfter(
                    TimeSpan.FromMinutes(5));

                var related =
                    await GetCalendarProjectRelatedActivitiesAsync(
                        sourceActivity,
                        criteria,
                        token,
                        timeoutCts.Token,
                        forceRefresh: false);

                timeoutCts.Token.ThrowIfCancellationRequested();

                _calendarProjectPreviewActivities =
                    related;

                // Render inmediato con lo que ya exista en cache. Los bodies
                // faltantes se completan en background y el panel se repinta
                // una sola vez al terminar.
                RenderCalendarProjectPreviewItems();

                _ = WarmCalendarProjectPanelChecklistAsync(
                    criteria,
                    related,
                    cancellationToken);

                var globalStats =
                    GetCalendarProjectChecklistStats(
                        related);

                var scannedActivities =
                    related.Count(activity =>
                        activity != null &&
                        activity.ChecklistScanned);

                var allChecklistScanned =
                    related.Count == 0 ||
                    scannedActivities >= related.Count;

                StatusText.Text =
                    allChecklistScanned
                        ? globalStats.Total > 0
                            ? $"Estado: Proyecto listo ✅ · " +
                              $"{related.Count} actividad(es) · " +
                              $"☑ {globalStats.Completed}/{globalStats.Total} · " +
                              $"{GetChecklistPercentage(globalStats)}% · " +
                              $"{FormatCalendarWorkMinutes(GetCalendarProjectTotalMinutes(related))}"
                            : $"Estado: Proyecto listo ✅ · " +
                              $"{related.Count} actividad(es) · sin checklist activo · " +
                              $"{FormatCalendarWorkMinutes(GetCalendarProjectTotalMinutes(related))}"
                        : $"Estado: Proyecto visible ✅ · " +
                          $"precargando checklist {scannedActivities}/{related.Count} en segundo plano";
            }
            catch (OperationCanceledException)
            {
                if (_calendarProjectPreviewActive)
                {
                    CalendarPersonPreviewSummary.Text =
                        "La búsqueda del proyecto se canceló.";
                }
            }
            catch (Exception ex)
            {
                if (!_calendarProjectPreviewActive)
                    return;

                CalendarPersonPreviewSummary.Text =
                    "No se pudo completar la búsqueda del proyecto.";

                CalendarPersonPreviewItems.Children.Clear();
                CalendarPersonPreviewItems.Children.Add(
                    BuildCalendarPersonPreviewMessage(
                        $"No se pudieron obtener las actividades relacionadas.\n{ex.Message}",
                        isError: true));

                StatusText.Text =
                    $"Estado: Error al agrupar proyecto → {ex.Message}";
            }
        }

        private NotionChecklistStats GetCalendarProjectChecklistStats(
            IEnumerable<NotionCalendarActivity> activities)
        {
            var unique =
                (activities ??
                 Enumerable.Empty<NotionCalendarActivity>())
                    .Where(activity =>
                        activity != null &&
                        !activity.IsReviewMirror &&
                        !string.IsNullOrWhiteSpace(
                            activity.PageId))
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();

            // Porcentaje REAL solicitado: suma todos los to_do de los bodies.
            // Una actividad sin checklist aporta 0/0; una actividad aun no
            // precargada tampoco altera artificialmente el porcentaje.
            var total =
                unique
                    .Where(activity => activity.ChecklistScanned)
                    .Sum(activity => Math.Max(0, activity.ChecklistTotal));

            var completed =
                unique
                    .Where(activity => activity.ChecklistScanned)
                    .Sum(activity =>
                        Math.Clamp(
                            activity.ChecklistCompleted,
                            0,
                            Math.Max(0, activity.ChecklistTotal)));

            return new NotionChecklistStats(
                total,
                completed);
        }

        private static int GetCalendarProjectTotalMinutes(
            IEnumerable<NotionCalendarActivity> activities)
        {
            return (activities ??
                    Enumerable.Empty<NotionCalendarActivity>())
                .Where(activity =>
                    activity != null &&
                    !activity.IsReviewMirror &&
                    !string.IsNullOrWhiteSpace(
                        activity.PageId))
                .GroupBy(
                    activity => activity.PageId,
                    StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .Sum(activity =>
                {
                    if (activity.End <= activity.Start)
                        return 0;

                    return Math.Max(
                        0,
                        (int)Math.Round(
                            (activity.End -
                             activity.Start)
                            .TotalMinutes));
                });
        }

        private void EnsureCalendarProjectCardZoomLoaded()
        {
            if (_calendarProjectCardZoomLoaded)
                return;

            _calendarProjectCardZoomLoaded = true;

            try
            {
                var values =
                    ApplicationData.Current.LocalSettings.Values;

                if (!values.TryGetValue(
                        LS_CalendarProjectCardZoom,
                        out var raw) ||
                    raw == null)
                {
                    _calendarProjectCardZoom =
                        CalendarProjectCardZoomDefault;
                    return;
                }

                var parsed = raw switch
                {
                    double value => value,
                    float value => value,
                    int value => value / 100d,
                    string value when double.TryParse(
                        value,
                        NumberStyles.Float,
                        CultureInfo.InvariantCulture,
                        out var number) => number,
                    _ => CalendarProjectCardZoomDefault
                };

                _calendarProjectCardZoom =
                    Math.Clamp(
                        parsed,
                        CalendarProjectCardZoomMin,
                        CalendarProjectCardZoomMax);
            }
            catch
            {
                _calendarProjectCardZoom =
                    CalendarProjectCardZoomDefault;
            }
        }

        private double GetCalendarProjectCardScale()
        {
            if (!_calendarProjectPreviewActive)
                return 1.0;

            EnsureCalendarProjectCardZoomLoaded();

            return Math.Clamp(
                _calendarProjectCardZoom,
                CalendarProjectCardZoomMin,
                CalendarProjectCardZoomMax);
        }

        private double ScaleCalendarProjectCard(
            double value,
            double minimum = 0)
        {
            return Math.Max(
                minimum,
                value * GetCalendarProjectCardScale());
        }

        private void ChangeCalendarProjectCardZoom(
            double delta)
        {
            EnsureCalendarProjectCardZoomLoaded();

            var next =
                Math.Clamp(
                    _calendarProjectCardZoom + delta,
                    CalendarProjectCardZoomMin,
                    CalendarProjectCardZoomMax);

            next =
                Math.Round(
                    next,
                    2,
                    MidpointRounding.AwayFromZero);

            if (Math.Abs(
                    next -
                    _calendarProjectCardZoom) < 0.001)
            {
                return;
            }

            _calendarProjectCardZoom = next;

            ApplicationData.Current.LocalSettings.Values[
                LS_CalendarProjectCardZoom] =
                _calendarProjectCardZoom;

            if (_calendarProjectPreviewActive)
                RenderCalendarProjectPreviewItems();
        }

        private FrameworkElement BuildCalendarProjectZoomControl()
        {
            EnsureCalendarProjectCardZoomLoaded();

            var root =
                new Grid
                {
                    Margin = new Thickness(
                        0,
                        0,
                        0,
                        5),
                    ColumnSpacing = 6,
                    HorizontalAlignment =
                        HorizontalAlignment.Right
                };

            root.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            root.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            root.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            Button BuildZoomButton(
                string content,
                string tooltip)
            {
                var button =
                    new Button
                    {
                        Content = content,
                        Width = 28,
                        Height = 26,
                        Padding = new Thickness(0),
                        HorizontalContentAlignment =
                            HorizontalAlignment.Center,
                        VerticalContentAlignment =
                            VerticalAlignment.Center,
                        FontSize = 12,
                        CornerRadius =
                            new CornerRadius(6),
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    36,
                                    255,
                                    255,
                                    255)),
                        BorderBrush =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    74,
                                    148,
                                    163,
                                    184)),
                        BorderThickness =
                            new Thickness(1)
                    };

                ToolTipService.SetToolTip(
                    button,
                    tooltip);

                return button;
            }

            var zoomOut =
                BuildZoomButton(
                    "−",
                    "Hacer más pequeñas las cards del proyecto");

            zoomOut.IsEnabled =
                _calendarProjectCardZoom >
                CalendarProjectCardZoomMin + 0.001;

            zoomOut.Click +=
                (_, __) =>
                    ChangeCalendarProjectCardZoom(
                        -CalendarProjectCardZoomStep);

            var zoomLabel =
                new Border
                {
                    MinWidth = 52,
                    Height = 26,
                    Padding =
                        new Thickness(
                            8,
                            0,
                            8,
                            0),
                    CornerRadius =
                        new CornerRadius(6),
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                30,
                                56,
                                189,
                                248)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                90,
                                56,
                                189,
                                248)),
                    BorderThickness =
                        new Thickness(1),
                    Child =
                        new TextBlock
                        {
                            Text =
                                $"{Math.Round(_calendarProjectCardZoom * 100):0}%",
                            FontSize = 10.5,
                            FontWeight =
                                Microsoft.UI.Text.FontWeights.SemiBold,
                            HorizontalAlignment =
                                HorizontalAlignment.Center,
                            VerticalAlignment =
                                VerticalAlignment.Center
                        }
                };

            ToolTipService.SetToolTip(
                zoomLabel,
                "Zoom exclusivo de las cards del proyecto");

            var zoomIn =
                BuildZoomButton(
                    "+",
                    "Hacer más grandes las cards del proyecto");

            zoomIn.IsEnabled =
                _calendarProjectCardZoom <
                CalendarProjectCardZoomMax - 0.001;

            zoomIn.Click +=
                (_, __) =>
                    ChangeCalendarProjectCardZoom(
                        CalendarProjectCardZoomStep);

            Grid.SetColumn(zoomOut, 0);
            Grid.SetColumn(zoomLabel, 1);
            Grid.SetColumn(zoomIn, 2);

            root.Children.Add(zoomOut);
            root.Children.Add(zoomLabel);
            root.Children.Add(zoomIn);

            return root;
        }

        private FrameworkElement BuildCalendarProjectSummaryCard(
            CalendarProjectGroupCriteria criteria,
            IReadOnlyList<NotionCalendarActivity> activities)
        {
            var stats =
                GetCalendarProjectChecklistStats(
                    activities);

            var percentage =
                GetChecklistPercentage(stats);

            var scannedActivities =
                activities.Count(activity =>
                    activity != null &&
                    activity.ChecklistScanned);

            var allChecklistScanned =
                activities.Count == 0 ||
                scannedActivities >= activities.Count;

            var cardScale =
                GetCalendarProjectCardScale();

            var content =
                new StackPanel
                {
                    Spacing =
                        Math.Max(
                            3,
                            7 * cardScale)
                };

            content.Children.Add(
                new TextBlock
                {
                    Text =
                        "RESUMEN GENERAL DEL PROYECTO",
                    FontSize =
                        Math.Max(
                            8,
                            10 * cardScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.Bold,
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255,
                                125,
                                211,
                                252)),
                    CharacterSpacing =
                        (int)Math.Round(
                            40 * cardScale)
                });

            var top =
                new Grid
                {
                    ColumnSpacing =
                        Math.Max(
                            5,
                            10 * cardScale)
                };

            top.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            top.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            var identity =
                new StackPanel
                {
                    Spacing =
                        Math.Max(
                            1,
                            2 * cardScale)
                };

            identity.Children.Add(
                new TextBlock
                {
                    Text =
                        $"{criteria.ProjectLabel} · " +
                        $"{criteria.Domain}",
                    FontSize =
                        Math.Max(
                            10.5,
                            14 * cardScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    TextWrapping =
                        TextWrapping.Wrap
                });

            identity.Children.Add(
                new TextBlock
                {
                    Text =
                        $"{criteria.MonthTag} · " +
                        $"{activities.Count} actividad(es) · " +
                        $"{FormatCalendarWorkMinutes(GetCalendarProjectTotalMinutes(activities))}",
                    FontSize =
                        Math.Max(
                            8.5,
                            10.5 * cardScale),
                    Opacity = 0.72,
                    TextWrapping =
                        TextWrapping.Wrap
                });

            Grid.SetColumn(identity, 0);
            top.Children.Add(identity);

            var percentText =
                new TextBlock
                {
                    Text =
                        stats.Total > 0
                            ? $"{percentage}%"
                            : allChecklistScanned
                                ? "0%"
                                : "…",
                    FontSize =
                        Math.Max(
                            17,
                            24 * cardScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.Bold,
                    Foreground =
                        new SolidColorBrush(
                            stats.Total > 0
                                ? Color.FromArgb(
                                    255,
                                    74,
                                    222,
                                    128)
                                : Color.FromArgb(
                                    220,
                                    203,
                                    213,
                                    225)),
                    VerticalAlignment =
                        VerticalAlignment.Center
                };

            Grid.SetColumn(percentText, 1);
            top.Children.Add(percentText);

            content.Children.Add(top);

            content.Children.Add(
                new ProgressBar
                {
                    Minimum = 0,
                    Maximum = 100,
                    Value =
                        stats.Total > 0
                            ? percentage
                            : 0,
                    Height =
                        Math.Max(
                            4,
                            7 * cardScale),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                });

            content.Children.Add(
                new TextBlock
                {
                    Text =
                        stats.Total > 0
                            ? $"☑ {stats.Completed}/{stats.Total} completados · " +
                              $"{stats.Pending} pendientes" +
                              (allChecklistScanned
                                  ? string.Empty
                                  : $" · precargando {scannedActivities}/{activities.Count}")
                            : allChecklistScanned
                                ? "Sin checklist activo en las actividades."
                                : $"Precargando checklist {scannedActivities}/{activities.Count}…",
                    FontSize =
                        Math.Max(
                            8.5,
                            10.5 * cardScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    Opacity = 0.84
                });

            return new Border
            {
                Margin = new Thickness(
                    0,
                    0,
                    0,
                    4),
                Padding =
                    new Thickness(
                        Math.Max(
                            7,
                            12 * cardScale)),
                CornerRadius =
                    new CornerRadius(
                        Math.Max(
                            7,
                            10 * cardScale)),
                Background =
                    new SolidColorBrush(
                        Color.FromArgb(
                            82,
                            8,
                            47,
                            73)),
                BorderBrush =
                    new SolidColorBrush(
                        Color.FromArgb(
                            210,
                            56,
                            189,
                            248)),
                BorderThickness =
                    new Thickness(1.25),
                Child = content
            };
        }

        private void RenderCalendarProjectPreviewItems()
        {
            if (!_calendarProjectPreviewActive ||
                _calendarProjectPreviewCriteria == null ||
                CalendarPersonPreviewItems == null ||
                CalendarPersonPreviewPanel?.Visibility !=
                    Visibility.Visible)
            {
                return;
            }

            var criteria =
                _calendarProjectPreviewCriteria;

            var activities =
                _calendarProjectPreviewActivities
                    .Where(activity =>
                        activity != null)
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .OrderBy(activity => activity.Start)
                    .ThenBy(activity => activity.Title)
                    .ToList();

            CalendarPersonPreviewTitle.Text =
                $"{criteria.ProjectLabel} · {criteria.Domain}";

            CalendarPersonPreviewDate.Text =
                $"{criteria.MonthTag} · " +
                GetCalendarProjectMonthLabel(criteria);

            var stats =
                GetCalendarProjectChecklistStats(
                    activities);

            var scannedActivities =
                activities.Count(activity =>
                    activity.ChecklistScanned);

            var allChecklistScanned =
                activities.Count == 0 ||
                scannedActivities >= activities.Count;

            var loadedContent =
                GetCalendarProjectLoadedContentCount(
                    activities);

            var contentProgress =
                activities.Count == 0
                    ? string.Empty
                    : loadedContent >= activities.Count
                        ? " · contenido listo ✅"
                        : _calendarProjectContentPreloadRunning
                            ? $" · contenido {loadedContent}/{activities.Count}"
                            : loadedContent > 0
                                ? $" · contenido {loadedContent}/{activities.Count}"
                                : string.Empty;

            CalendarPersonPreviewSummary.Text =
                activities.Count == 0
                    ? "No se encontraron actividades relacionadas."
                    : stats.Total > 0
                        ? $"{activities.Count} actividad(es) · " +
                          $"☑ {stats.Completed}/{stats.Total} · " +
                          $"{GetChecklistPercentage(stats)}% global" +
                          (allChecklistScanned
                              ? string.Empty
                              : $" · checklist {scannedActivities}/{activities.Count}") +
                          contentProgress
                        : allChecklistScanned
                            ? $"{activities.Count} actividad(es) · sin checklist activo" +
                              contentProgress
                            : $"{activities.Count} actividad(es) · " +
                              $"precargando checklist {scannedActivities}/{activities.Count}" +
                              contentProgress;

            CalendarPersonPreviewItems.Children.Clear();

            if (activities.Count == 0)
            {
                CalendarPersonPreviewItems.Children.Add(
                    BuildCalendarPersonPreviewMessage(
                        "No se encontraron actividades que coincidan con tipo + dominio + persona + mes.",
                        isError: false));

                return;
            }

            // Zoom independiente del calendario principal.
            CalendarPersonPreviewItems.Children.Add(
                BuildCalendarProjectZoomControl());

            CalendarPersonPreviewItems.Children.Add(
                BuildCalendarProjectSummaryCard(
                    criteria,
                    activities));

            foreach (var activity in activities)
            {
                CalendarPersonPreviewItems.Children.Add(
                    BuildCalendarPersonPreviewCard(
                        activity));
            }
        }

        private async void CalendarPersonPreview_Click(
            object sender,
            RoutedEventArgs e)
        {
            if (sender is not FrameworkElement element)
                return;

            var person =
                (element.Tag?.ToString() ??
                 string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(person))
                return;

            ShowCalendarPersonPreview(person);

            var activities =
                GetCalendarPersonPreviewActivities(person);

            await HydrateCalendarChecklistStatsAsync(
                activities,
                $"Cargando avance de {person}",
                forceRefresh: false);

            if (CalendarPersonPreviewPanel?.Visibility ==
                    Visibility.Visible &&
                string.Equals(
                    _calendarPersonPreviewPerson,
                    person,
                    StringComparison.OrdinalIgnoreCase))
            {
                RenderCalendarPersonPreviewItems(person);
                UpdateCalendarChecklistVisuals(
                    activities.Select(
                        activity => activity.PageId));
            }
        }

        private void CalendarPersonPreviewClose_Click(
            object sender,
            RoutedEventArgs e)
        {
            CloseCalendarPersonPreviewPanel();
        }

        private void ShowCalendarPersonPreview(
            string person)
        {
            _calendarProjectPreviewActive = false;
            _calendarProjectPreviewCriteria = null;
            _calendarProjectPreviewActivities =
                Array.Empty<NotionCalendarActivity>();
            _calendarProjectPreviewSourcePageId =
                string.Empty;

            if (CalendarPersonPreviewPanel == null ||
                CalendarPersonPreviewItems == null)
            {
                return;
            }

            person =
                NormalizeCalendarPerson(person);

            if (string.IsNullOrWhiteSpace(person))
                return;

            var personChanged =
                !string.Equals(
                    _calendarPersonPreviewPerson,
                    person,
                    StringComparison.OrdinalIgnoreCase);

            if (personChanged ||
                _calendarPersonPreviewCts == null ||
                _calendarPersonPreviewCts.IsCancellationRequested)
            {
                try
                {
                    _calendarPersonPreviewCts?.Cancel();
                    _calendarPersonPreviewCts?.Dispose();
                }
                catch
                {
                }

                _calendarPersonPreviewCts =
                    new CancellationTokenSource();
            }

            _calendarPersonPreviewPerson = person;

            CalendarPersonPreviewPanel.Visibility =
                Visibility.Visible;

            CalendarPersonPreviewTitle.Text =
                $"Actividades de {person}";

            CalendarPersonPreviewDate.Text =
                FormatCalendarDate(_calendarSelectedDate);

            RenderCalendarPersonPreviewItems(person);

            DispatcherQueue.TryEnqueue(() =>
            {
                if (_calendarViewActive)
                    DrawCalendar(_calendarActivities);
            });
        }

        private IReadOnlyList<NotionCalendarActivity>
            GetCalendarPersonPreviewActivities(
                string person)
        {
            var expanded =
                ExpandCalendarReviewActivities(
                    _calendarActivities);

            var phaseFiltered =
                string.IsNullOrWhiteSpace(
                    _calendarPhaseFilter)
                    ? expanded
                    : expanded
                        .Where(activity =>
                            ContainsExactCalendarPart(
                                BuildCalendarActivitySearchableText(
                                    activity),
                                _calendarPhaseFilter))
                        .ToList();

            var visible =
                FilterCalendarActivities(
                    phaseFiltered,
                    _calendarSearchQuery);

            return visible
                .Where(activity =>
                    SplitPersons(activity.Person)
                        .Select(NormalizeCalendarPerson)
                        .Any(candidate =>
                            string.Equals(
                                candidate,
                                person,
                                StringComparison.OrdinalIgnoreCase)))
                .GroupBy(activity =>
                    string.Join(
                        "|",
                        activity.PageId,
                        activity.Person,
                        activity.IsReviewMirror,
                        activity.Start.ToString("O")),
                    StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .OrderBy(activity => activity.Start)
                .ThenBy(activity => activity.End)
                .ThenBy(activity => activity.Title)
                .ToList();
        }

        private NotionChecklistStats GetCalendarChecklistStats(
            NotionCalendarActivity activity)
        {
            if (activity == null)
                return new NotionChecklistStats(0, 0);

            if (!string.IsNullOrWhiteSpace(activity.PageId) &&
                _oneClickChecklistStats.TryGetValue(
                    activity.PageId,
                    out var cached))
            {
                return cached;
            }

            return new NotionChecklistStats(
                activity.ChecklistTotal,
                activity.ChecklistCompleted);
        }

        private static int GetChecklistPercentage(
            NotionChecklistStats stats)
        {
            return stats.Total <= 0
                ? 0
                : Math.Clamp(
                    (int)Math.Round(
                        stats.Completed * 100d / stats.Total),
                    0,
                    100);
        }

        private static string FormatCalendarChecklistLabel(
            NotionCalendarActivity activity,
            NotionChecklistStats stats)
        {
            if (activity == null ||
                !activity.ChecklistScanned)
            {
                return "Pendiente de cargar";
            }

            return stats.HasChecklist
                ? $"{stats.Completed}/{stats.Total} · {GetChecklistPercentage(stats)}% · {stats.Pending} pendiente(s)"
                : "Sin checklist nativo en el contenido de Notion";
        }

        private async Task HydrateCalendarChecklistStatsAsync(
            IReadOnlyList<NotionCalendarActivity> activities,
            string stage,
            bool forceRefresh,
            CancellationToken cancellationToken = default,
            Action<NotionCalendarActivity, int, int>?
                itemCompleted = null)
        {
            var unique =
                (activities ?? Array.Empty<NotionCalendarActivity>())
                    .Where(activity =>
                        activity != null &&
                        !activity.IsReviewMirror &&
                        !string.IsNullOrWhiteSpace(activity.PageId))
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();

            if (unique.Count == 0)
                return;

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
                return;

            var nextIndex = -1;
            var completedCount = 0;
            var workerCount = Math.Min(2, unique.Count);

            async Task WorkerAsync()
            {
                while (true)
                {
                    cancellationToken.ThrowIfCancellationRequested();

                    var index = Interlocked.Increment(ref nextIndex);

                    if (index >= unique.Count)
                        return;

                    var activity = unique[index];

                    if (!forceRefresh &&
                        activity.ChecklistScanned)
                    {
                        _oneClickChecklistStats[activity.PageId] =
                            new NotionChecklistStats(
                                activity.ChecklistTotal,
                                activity.ChecklistCompleted);

                        var ready =
                            Interlocked.Increment(
                                ref completedCount);

                        itemCompleted?.Invoke(
                            activity,
                            ready,
                            unique.Count);

                        continue;
                    }

                    try
                    {
                        using var cts =
                            CancellationTokenSource
                                .CreateLinkedTokenSource(
                                    cancellationToken);

                        cts.CancelAfter(
                            TimeSpan.FromMinutes(2));

                        var stats =
                            await _notionCalendarService
                                .GetChecklistStatsAsync(
                                    token,
                                    activity.PageId,
                                    cts.Token,
                                    forceRefresh);

                        activity.ChecklistScanned = true;
                        activity.ChecklistTotal = stats.Total;
                        activity.ChecklistCompleted = stats.Completed;
                        _oneClickChecklistStats[activity.PageId] = stats;
                    }
                    catch (OperationCanceledException)
                    {
                        cancellationToken.ThrowIfCancellationRequested();

                        activity.ChecklistScanned = false;
                        activity.ChecklistTotal = 0;
                        activity.ChecklistCompleted = 0;
                        _oneClickChecklistStats.TryRemove(
                            activity.PageId,
                            out _);
                    }
                    catch
                    {
                        // Un error temporal no se interpreta como "sin checklist".
                        // Se deja pendiente para permitir un nuevo intento.
                        activity.ChecklistScanned = false;
                        activity.ChecklistTotal = 0;
                        activity.ChecklistCompleted = 0;
                        _oneClickChecklistStats.TryRemove(
                            activity.PageId,
                            out _);
                    }

                    var current =
                        Interlocked.Increment(
                            ref completedCount);

                    itemCompleted?.Invoke(
                        activity,
                        current,
                        unique.Count);
                }
            }

            // Dos workers como maximo: mejora claramente el primer escaneo sin
            // lanzar decenas de peticiones a la vez. El servicio ademas comparte
            // lecturas duplicadas y tiene su propio gate de red.
            await Task.WhenAll(
                Enumerable.Range(0, workerCount)
                    .Select(_ => WorkerAsync()));
        }

        private void StartCalendarIncrementalChecklistRefresh(
            IEnumerable<string> pageIds,
            DateTime requestedDate,
            long loadVersion)
        {
            var ids =
                (pageIds ?? Array.Empty<string>())
                    .Where(id => !string.IsNullOrWhiteSpace(id))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);

            if (ids.Count == 0)
                return;

            // Se consultan únicamente los PageId que Notion reportó como
            // modificados y que siguen visibles en este día. Esto también
            // cubre páginas nuevas (por ejemplo, una actividad duplicada).
            var snapshot =
                _calendarActivities
                    .Where(activity =>
                        activity != null &&
                        !activity.IsReviewMirror &&
                        !string.IsNullOrWhiteSpace(activity.PageId) &&
                        ids.Contains(activity.PageId))
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();

            if (snapshot.Count == 0)
                return;

            try
            {
                _calendarIncrementalChecklistCts?.Cancel();
                _calendarIncrementalChecklistCts?.Dispose();
            }
            catch
            {
            }

            var cts = new CancellationTokenSource();
            _calendarIncrementalChecklistCts = cts;

            _ = RefreshCalendarChecklistForChangedPagesAsync(
                snapshot,
                requestedDate.Date,
                loadVersion,
                cts.Token);
        }

        private async Task RefreshCalendarChecklistForChangedPagesAsync(
            IReadOnlyList<NotionCalendarActivity> activities,
            DateTime requestedDate,
            long loadVersion,
            CancellationToken cancellationToken)
        {
            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token) ||
                activities == null || activities.Count == 0)
            {
                return;
            }

            var changedCount = 0;

            try
            {
                for (var index = 0; index < activities.Count; index++)
                {
                    cancellationToken.ThrowIfCancellationRequested();

                    // Si otra ruta activó rate-limit, el checklist incremental
                    // espera en segundo plano sin bloquear la UI ni perder el
                    // porcentaje que ya estaba en caché.
                    if (NotionRequestCoordinator.IsCoolingDown)
                    {
                        var remaining =
                            NotionRequestCoordinator.CooldownRemaining;

                        if (remaining < TimeSpan.Zero)
                            remaining = TimeSpan.Zero;

                        DispatcherQueue.TryEnqueue(() =>
                        {
                            if (_calendarViewActive &&
                                requestedDate == _calendarSelectedDate.Date &&
                                loadVersion == _calendarLoadVersion)
                            {
                                StatusText.Text =
                                    $"Estado: Checklist conserva caché · " +
                                    $"Notion reintenta en " +
                                    $"{Math.Max(1, (int)Math.Ceiling(remaining.TotalSeconds))}s";
                            }
                        });

                        await Task.Delay(
                            remaining + TimeSpan.FromSeconds(2),
                            cancellationToken);
                    }

                    var activity = activities[index];
                    var previous = new NotionChecklistStats(
                        activity.ChecklistTotal,
                        activity.ChecklistCompleted);

                    try
                    {
                        using var itemCts =
                            CancellationTokenSource.CreateLinkedTokenSource(
                                cancellationToken);
                        itemCts.CancelAfter(TimeSpan.FromMinutes(2));

                        var stats =
                            await _notionCalendarService.GetChecklistStatsAsync(
                                token,
                                activity.PageId,
                                itemCts.Token,
                                forceRefresh: true);

                        foreach (var instance in _calendarActivities.Where(item =>
                                     string.Equals(
                                         item.PageId,
                                         activity.PageId,
                                         StringComparison.OrdinalIgnoreCase)))
                        {
                            instance.ChecklistScanned = true;
                            instance.ChecklistTotal = stats.Total;
                            instance.ChecklistCompleted = stats.Completed;
                        }

                        _oneClickChecklistStats[activity.PageId] = stats;

                        if (previous.Total != stats.Total ||
                            previous.Completed != stats.Completed)
                        {
                            changedCount++;
                        }

                        // Las lecturas de body son las llamadas más caras del
                        // calendario. Un pequeño espacio entre actividades evita
                        // una ráfaga cuando Notion reporta decenas de cambios.
                        if (index + 1 < activities.Count)
                        {
                            await Task.Delay(
                                TimeSpan.FromMilliseconds(650),
                                cancellationToken);
                        }
                    }
                    catch (OperationCanceledException)
                    {
                        cancellationToken.ThrowIfCancellationRequested();
                    }
                    catch (Exception ex)
                    {
                        Debug.WriteLine(
                            $"[CHECKLIST_INCREMENTAL] {activity.PageId}: {ex.Message}");
                    }
                }

                cancellationToken.ThrowIfCancellationRequested();

                if (!_calendarViewActive ||
                    requestedDate != _calendarSelectedDate.Date ||
                    loadVersion != _calendarLoadVersion)
                {
                    return;
                }

                DispatcherQueue.TryEnqueue(() =>
                {
                    if (!_calendarViewActive ||
                        requestedDate != _calendarSelectedDate.Date ||
                        loadVersion != _calendarLoadVersion)
                    {
                        return;
                    }

                    if (changedCount > 0)
                    {
                        UpdateCalendarChecklistVisuals(
                            activities.Select(
                                activity => activity.PageId));
                    }

                    StatusText.Text =
                        activities.Count == 1
                            ? changedCount > 0
                                ? "Estado: ACT actualizado ✅ · 1 actividad cambió checklist"
                                : "Estado: ACT comprobado ✅ · sin cambio de checklist"
                            : changedCount > 0
                                ? $"Estado: ACT actualizado ✅ · {changedCount} de {activities.Count} página(s) cambiaron checklist"
                                : $"Estado: ACT comprobado ✅ · {activities.Count} página(s) revisadas · checklist sin cambio";
                });
            }
            catch (OperationCanceledException)
            {
            }
        }

        private void StartCalendarChecklistHydration(
            DateTime requestedDate,
            long loadVersion)
        {
            try
            {
                _calendarChecklistHydrationCts?.Cancel();
                _calendarChecklistHydrationCts?.Dispose();
            }
            catch
            {
            }

            var cts = new CancellationTokenSource();
            _calendarChecklistHydrationCts = cts;

            var unique =
                _calendarActivities
                    .Where(activity =>
                        activity != null &&
                        !activity.IsReviewMirror &&
                        !string.IsNullOrWhiteSpace(activity.PageId))
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();

            // Lo ya persistido en caché no vuelve a recorrer el pipeline.
            // Solo alimenta One Click desde memoria. La lectura completa se
            // reserva para páginas que todavía nunca han sido escaneadas.
            foreach (var activity in unique.Where(item => item.ChecklistScanned))
            {
                _oneClickChecklistStats[activity.PageId] =
                    new NotionChecklistStats(
                        activity.ChecklistTotal,
                        activity.ChecklistCompleted);
            }

            // Baseline de HOY/DÍA: solo archivo local, cero requests de Notion.
            _ =
                RefreshCalendarCardTodayBaselinesAsync(
                    requestedDate,
                    loadVersion,
                    cts.Token);

            // CARGA EN ETAPAS:
            // 1) HOY/DÍA se obtiene del tracking local.
            // 2) ACT termina/restaura checklist del día visible.
            // 3) SOLO DESPUÉS comienza PROY.
            //
            // Antes ACT y PROY competían desde el primer momento. Aunque el
            // servicio limita bodies a 2, el usuario veía varios procesos
            // mezclados y Notion podía tardar más en completar los porcentajes.
            var snapshot =
                unique
                    .Where(activity => !activity.ChecklistScanned)
                    .ToList();

            if (snapshot.Count == 0)
            {
                StatusText.Text =
                    "Estado: ACT listo desde caché ✅ · preparando PROY…";

                StartCalendarProjectChecklistWarmup(
                    requestedDate,
                    loadVersion);

                return;
            }

            if (NotionRequestCoordinator.IsCoolingDown)
            {
                var remaining =
                    NotionRequestCoordinator.CooldownRemaining;

                if (remaining < TimeSpan.Zero)
                    remaining = TimeSpan.Zero;

                StatusText.Text =
                    $"Estado: ACT conserva caché · " +
                    $"{snapshot.Count} pendiente(s) · Notion reintenta en " +
                    $"{Math.Max(1, (int)Math.Ceiling(remaining.TotalSeconds))}s · " +
                    $"PROY espera su turno";

                _ = ResumeCalendarChecklistHydrationAfterCooldownAsync(
                    snapshot,
                    requestedDate.Date,
                    loadVersion,
                    cts);

                return;
            }

            StatusText.Text =
                $"Estado: ACT · preparando checklist del día · " +
                $"0/{snapshot.Count} · PROY espera su turno";

            _ = HydrateCalendarChecklistForCardsAsync(
                snapshot,
                requestedDate.Date,
                loadVersion,
                cts.Token);
        }

        private async Task ResumeCalendarChecklistHydrationAfterCooldownAsync(
            IReadOnlyList<NotionCalendarActivity> activities,
            DateTime requestedDate,
            long loadVersion,
            CancellationTokenSource owner)
        {
            try
            {
                var remaining =
                    NotionRequestCoordinator.CooldownRemaining;

                if (remaining < TimeSpan.Zero)
                    remaining = TimeSpan.Zero;

                await Task.Delay(
                    remaining + TimeSpan.FromSeconds(2),
                    owner.Token);

                if (owner.IsCancellationRequested ||
                    !_calendarViewActive ||
                    requestedDate != _calendarSelectedDate.Date ||
                    loadVersion != _calendarLoadVersion)
                {
                    return;
                }

                DispatcherQueue.TryEnqueue(() =>
                {
                    StatusText.Text =
                        $"Estado: ACT · reanudando checklist · " +
                        $"0/{activities.Count} · PROY espera su turno";
                });

                await HydrateCalendarChecklistForCardsAsync(
                    activities,
                    requestedDate,
                    loadVersion,
                    owner.Token);
            }
            catch (OperationCanceledException)
            {
            }
        }

        private async Task HydrateCalendarChecklistForCardsAsync(
            IReadOnlyList<NotionCalendarActivity> activities,
            DateTime requestedDate,
            long loadVersion,
            CancellationToken cancellationToken)
        {
            try
            {
                await HydrateCalendarChecklistStatsAsync(
                    activities,
                    "Analizando checklist",
                    forceRefresh: false,
                    cancellationToken: cancellationToken,
                    itemCompleted: (activity, current, total) =>
                    {
                        DispatcherQueue.TryEnqueue(() =>
                        {
                            if (!_calendarViewActive ||
                                requestedDate !=
                                    _calendarSelectedDate.Date ||
                                loadVersion !=
                                    _calendarLoadVersion)
                            {
                                return;
                            }

                            UpdateCalendarChecklistVisuals(
                                new[] { activity.PageId });

                            // Un solo aviso general; no llenamos las cards
                            // con badges de "Calculando".
                            StatusText.Text =
                                $"Estado: ACT · checklist {current}/{total} · " +
                                $"PROY espera su turno";
                        });
                    });

                cancellationToken.ThrowIfCancellationRequested();

                if (!_calendarViewActive ||
                    requestedDate != _calendarSelectedDate.Date ||
                    loadVersion != _calendarLoadVersion)
                {
                    return;
                }

                DispatcherQueue.TryEnqueue(() =>
                {
                    if (_calendarViewActive &&
                        requestedDate == _calendarSelectedDate.Date &&
                        loadVersion == _calendarLoadVersion)
                    {
                        UpdateCalendarChecklistVisuals(
                            activities.Select(
                                activity => activity.PageId));

                        StatusText.Text =
                            $"Estado: ACT listo ✅ ({activities.Count}) · preparando PROY…";

                        StartCalendarProjectChecklistWarmup(
                            requestedDate,
                            loadVersion);
                    }
                });
            }
            catch (OperationCanceledException)
            {
            }
        }

        private static string BuildCalendarActivitySpeechText(
            NotionCalendarActivity activity,
            IReadOnlyList<NotionPreviewBlock>? blocks = null)
        {
            if (activity == null)
                return string.Empty;

            var parts = new List<string>();

            var duration =
                activity.End > activity.Start
                    ? activity.End - activity.Start
                    : TimeSpan.FromHours(1);

            var durationText =
                duration.TotalMinutes < 60
                    ? $"Duración aproximada: {Math.Max(1, (int)Math.Round(duration.TotalMinutes))} minutos"
                    : duration.TotalMinutes % 60 < 1
                        ? $"Duración aproximada: {Math.Max(1, (int)Math.Round(duration.TotalHours))} horas"
                        : $"Duración aproximada: {(int)duration.TotalHours} horas y {duration.Minutes} minutos";

            parts.Add(
                $"Horario: {activity.Start:HH:mm} a {activity.End:HH:mm}. {durationText}");

            var title = CleanSpeechText(activity.Title);
            if (!string.IsNullOrWhiteSpace(title))
                parts.Add($"Actividad: {title}");

            var status = CleanSpeechText(activity.Status);
            if (!string.IsNullOrWhiteSpace(status))
                parts.Add($"Estado: {status}");

            var update = CleanSpeechText(activity.UpdateText);
            if (!string.IsNullOrWhiteSpace(update))
                parts.Add($"Última actualización: {update}");

            var description = CleanSpeechText(activity.Description);
            if (!string.IsNullOrWhiteSpace(description))
                parts.Add($"Resumen: {description}");

            foreach (var block in
                     (blocks ?? Array.Empty<NotionPreviewBlock>())
                     .Where(block =>
                         !block.IsStrikethrough &&
                         !(block.Kind == NotionPreviewBlockKind.ToDo && block.IsChecked) &&
                         block.Kind != NotionPreviewBlockKind.Divider &&
                         block.Kind != NotionPreviewBlockKind.Image &&
                         block.Kind != NotionPreviewBlockKind.Pdf &&
                         block.Kind != NotionPreviewBlockKind.File &&
                         block.Kind != NotionPreviewBlockKind.Audio &&
                         block.Kind != NotionPreviewBlockKind.Video &&
                         block.Kind != NotionPreviewBlockKind.Embed)
                     .Take(12))
            {
                var text = CleanSpeechText(block.Text);
                if (!string.IsNullOrWhiteSpace(text))
                    parts.Add(text);
            }

            return string.Join(
                ". ",
                parts
                    .Where(value =>
                        !string.IsNullOrWhiteSpace(value))
                    .Distinct(StringComparer.OrdinalIgnoreCase));
        }

        private async Task StartCalendarActivitySpeechAsync(
            NotionCalendarActivity activity,
            IReadOnlyList<NotionPreviewBlock>? blocks,
            Button readButton,
            Button stopButton)
        {
            var speechText =
                BuildCalendarActivitySpeechText(
                    activity,
                    blocks);

            if (string.IsNullOrWhiteSpace(speechText))
            {
                StatusText.Text =
                    "Estado: Esta actividad no tiene contenido para leer.";
                return;
            }

            try
            {
                StopNotionPreviewSpeech();

                readButton.Content = "🔊 Leyendo...";
                readButton.IsEnabled = false;
                stopButton.IsEnabled = true;

                var stream =
                    await _previewSpeechSynth
                        .SynthesizeTextToStreamAsync(
                            speechText);

                var player = new MediaPlayer
                {
                    Source =
                        MediaSource.CreateFromStream(
                            stream,
                            stream.ContentType)
                };

                _previewSpeechPlayer = player;
                _previewSpeechPlaying = true;

                void ResetButtons()
                {
                    if (ReferenceEquals(
                            _previewSpeechPlayer,
                            player))
                    {
                        StopNotionPreviewSpeech();
                    }

                    readButton.Content = "▶ Leer resumen";
                    readButton.IsEnabled = true;
                    stopButton.IsEnabled = false;
                }

                player.MediaEnded +=
                    (_, __) =>
                        DispatcherQueue.TryEnqueue(
                            ResetButtons);

                player.MediaFailed +=
                    (_, __) =>
                        DispatcherQueue.TryEnqueue(
                            ResetButtons);

                StatusText.Text =
                    "Estado: Leyendo resumen de la actividad...";

                player.Play();
            }
            catch (Exception ex)
            {
                StopNotionPreviewSpeech();
                readButton.Content = "▶ Leer resumen";
                readButton.IsEnabled = true;
                stopButton.IsEnabled = false;
                StatusText.Text =
                    $"Estado: No se pudo leer la actividad → {ex.Message}";
            }
        }

