                    ? GetCalendarProjectPreviewTitle(
                        activity,
                        out projectOrderToken)
                    : GetCalendarCompactActivityTitle(
                        activity);

            var heading = new Grid
            {
                ColumnSpacing =
                    Math.Max(
                        4,
                        8 * cardScale)
            };

            if (projectListMode)
            {
                // Orden destacado + título limpio + horario discreto.
