                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                heading.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(
                            1,
                            GridUnitType.Star)
                    });

                heading.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                if (!string.IsNullOrWhiteSpace(
                        projectOrderToken))
                {
                    var orderBadge = new Border
                    {
                        MinWidth =
                            Math.Max(
                                42,
                                54 * cardScale),
                        Padding =
                            new Thickness(
                                Math.Max(5, 7 * cardScale),
                                Math.Max(2, 3 * cardScale),
                                Math.Max(5, 7 * cardScale),
                                Math.Max(2, 3 * cardScale)),
                        CornerRadius =
                            new CornerRadius(
                                Math.Max(5, 7 * cardScale)),
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    42,
                                    56,
                                    189,
                                    248)),
                        BorderBrush =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    170,
                                    56,
                                    189,
                                    248)),
                        BorderThickness =
                            new Thickness(1),
                        VerticalAlignment =
                            VerticalAlignment.Center,
                        Child = new TextBlock
                        {
                            Text = projectOrderToken,
                            FontSize =
                                Math.Max(
                                    8.8,
                                    10.8 * cardScale),
                            FontWeight =
                                Microsoft.UI.Text.FontWeights.Bold,
                            HorizontalAlignment =
                                HorizontalAlignment.Center,
                            Foreground =
                                new SolidColorBrush(
                                    Color.FromArgb(
                                        255,
                                        125,
                                        211,
                                        252))
                        }
                    };

                    Grid.SetColumn(orderBadge, 0);
                    heading.Children.Add(orderBadge);
                }

                var title = new TextBlock
                {
                    Text = projectTitle,
                    FontSize =
                        Math.Max(
                            9.7,
                            12.8 * cardScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    // John pidió que el listado no "grite": el nombre real
                    // sigue siendo el dato principal, pero en un blanco/gris
                    // suave en lugar del blanco fuerte predeterminado.
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(
                                235,
                                218,
                                224,
                                231)),
                    TextWrapping = TextWrapping.NoWrap,
                    TextTrimming =
                        TextTrimming.CharacterEllipsis,
                    MaxLines = 1,
                    VerticalAlignment =
                        VerticalAlignment.Center
                };

                // El título técnico/completo sigue disponible sin ocupar
                // espacio visual en la lista.
                ToolTipService.SetToolTip(
                    title,
                    activity.Title);

                Grid.SetColumn(title, 1);
                heading.Children.Add(title);

                var time = new TextBlock
                {
                    Text = activity.TimeLabel,
                    FontSize =
                        Math.Max(
                            8.2,
                            10.3 * cardScale),
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    Opacity = 0.58,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    HorizontalAlignment =
                        HorizontalAlignment.Right
                };

                Grid.SetColumn(time, 2);
                heading.Children.Add(time);
            }
            else
            {
                // Vista por persona: conserva el diseño anterior.
                heading.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                heading.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(
                            1,
                            GridUnitType.Star)
                    });

                var time = new TextBlock
                {
                    Text = activity.TimeLabel,
                    MinWidth =
