            root.Children.Add(heading);

            void AddSummary(
                string label,
                string value)
            {
                if (string.IsNullOrWhiteSpace(value))
                    return;

                root.Children.Add(
                    new TextBlock
                    {
                        Text = $"{label}: {value}",
                        FontSize =
                            projectListMode
                                ? Math.Max(
                                    8.0,
                                    9.8 * cardScale)
                                : Math.Max(
                                    8.3,
                                    10.5 * cardScale),
                        TextWrapping =
                            projectListMode
                                ? TextWrapping.NoWrap
                                : TextWrapping.Wrap,
                        TextTrimming =
                            projectListMode
                                ? TextTrimming.CharacterEllipsis
                                : TextTrimming.None,
                        MaxLines =
                            projectListMode
                                ? 1
                                : 0,
                        Opacity =
                            projectListMode
                                ? 0.56
                                : 0.76
                    });
            }

            AddSummary("Estado", activity.Status);
            AddSummary(
                "Última actualización",
                activity.UpdateText);

            var previewChecklist =
                GetCalendarChecklistStats(activity);

            AddSummary(
                "Checklist",
                FormatCalendarChecklistLabel(
                    activity,
                    previewChecklist));

            if (IsCalendarWorkTimerFor(activity))
            {
                AddSummary(
                    _calendarWorkTimerState?.IsRunning == true
                        ? "Cronómetro activo"
                        : "Cronómetro pausado",
                    FormatCalendarWorkTimer(
                        GetCalendarWorkTimerElapsedSeconds()));
            }

            var workedTodayInPreview =
                GetCalendarWorkedMinutesForDay(
                    activity,
                    _calendarSelectedDate.Date);

            if (workedTodayInPreview > 0)
            {
                AddSummary(
                    "Tiempo real hoy",
                    FormatCalendarWorkMinutes(
                        workedTodayInPreview));
            }

            if (activity.HasWorkLog &&
                activity.WorkedMinutes > 0)
            {
                AddSummary(
                    "Tiempo acumulado",
                    FormatCalendarWorkMinutes(
                        activity.WorkedMinutes));
            }

            if (activity.HasActivityDayRange)
            {
                AddSummary(
                    "Tiempo de actividad",
                    activity.IsActivityOverdue
                        ? $"Día {activity.ActivityElapsedDays} de {activity.ActivityBudgetDays} · vencida +{activity.ActivityElapsedDays - activity.ActivityBudgetDays} día(s)"
                        : $"Día {activity.ActivityElapsedDays} de {activity.ActivityBudgetDays}");
            }

            if (activity.IsAutomationLocked)
            {
                root.Children.Add(
                    new TextBlock
                    {
                        Text =
                            "🔒 Bloqueada para automatizaciones",
                        FontSize =
                            Math.Max(
                                8.3,
                                10.5 * cardScale),
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(255, 216, 180, 254)),
                        TextWrapping = TextWrapping.Wrap
                    });
            }

            if (activity.IsReviewMirror)
            {
                root.Children.Add(
                    new TextBlock
                    {
                        Text =
                            "Copia visual de seguimiento",
                        FontSize =
                            Math.Max(
                                8,
                                10 * cardScale),
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Opacity = 0.70
                    });
            }

            var contentHost = new ContentControl
            {
                HorizontalContentAlignment =
                    HorizontalAlignment.Stretch,
                Visibility = Visibility.Collapsed
            };

            var actions = new VariableSizedWrapGrid
            {
                Orientation = Orientation.Horizontal,
                MaximumRowsOrColumns = 3,
                ItemWidth =
                    Math.Max(
                        88,
                        116 * cardScale),
                ItemHeight =
                    Math.Max(
                        27,
                        36 * cardScale),
                Width =
                    Math.Max(
                        285,
                        370 * cardScale)
            };

            Button BuildCardActionButton(
                string text)
            {
                return new Button
                {
                    Content = text,
                    Width =
                        Math.Max(
                            84,
                            110 * cardScale),
                    Height =
                        Math.Max(
                            25,
                            32 * cardScale),
                    Margin =
                        new Thickness(
                            0,
                            0,
                            Math.Max(
                                3,
                                6 * cardScale),
                            Math.Max(
                                2,
                                4 * cardScale)),
                    Padding =
                        new Thickness(
                            Math.Max(
                                5,
                                8 * cardScale),
                            Math.Max(
                                2,
                                4 * cardScale),
                            Math.Max(
                                5,
                                8 * cardScale),
                            Math.Max(
                                2,
                                4 * cardScale)),
                    FontSize =
                        Math.Max(
                            9,
                            11 * cardScale),
                    CornerRadius =
                        new CornerRadius(
                            Math.Max(
                                4,
                                6 * cardScale)),
                    Tag = activity
                };
            }

            var contentIsReady =
                TryGetCalendarProjectCachedContent(
                    activity.PageId,
                    out _);

            if (_calendarProjectPreviewActive)
            {
                AddSummary(
                    "Contenido",
                    contentIsReady
                        ? "Precargado ✅"
                        : _calendarProjectContentLoadFailures.Contains(
                            activity.PageId)
                            ? "Pendiente de reintento"
                            : _calendarProjectContentPreloadRunning
                                ? "Precargando…"
                                : "Se cargará al abrir");
            }

            var previewButton =
                BuildCardActionButton(
                    contentIsReady
                        ? "Ver contenido ✓"
                        : "Ver contenido");

            previewButton.Click +=
                async (_, __) =>
                {
                    await ToggleCalendarPersonActivityContentAsync(
                        activity,
                        previewButton,
                        contentHost);
                };

            var messageButton =
                BuildCardActionButton(
                    "Mensaje");

            messageButton.Click +=
                async (_, __) =>
                {
                    await ShowCalendarMessageComposerAsync(
                        activity,
                        _calendarPersonPreviewPerson);
                };

            ToolTipService.SetToolTip(
                messageButton,
                "Enviar mensaje con los datos de esta actividad");

            var openButton =
                BuildCardActionButton(
                    "Abrir");

            openButton.Click +=
                async (_, __) =>
                {
                    await OpenCalendarActivityAsync(activity);
                };

            var lockButton =
                BuildCardActionButton(
                    activity.IsAutomationLocked
                        ? "🔓 Desbloquear"
                        : "🔒 Bloquear");

            lockButton.IsEnabled =
                !activity.IsReviewMirror;

            lockButton.Click +=
                async (_, __) =>
                {
                    if (await ToggleCalendarActivityAutomationLockAsync(
                            activity))
                    {
                        lockButton.Content =
                            activity.IsAutomationLocked
                                ? "🔓 Desbloquear"
                                : "🔒 Bloquear";

                        RenderCalendarPersonPreviewItems(
                            _calendarPersonPreviewPerson);
                    }
                };

            var timerButton =
                BuildCardActionButton(
                    IsCalendarWorkTimerFor(activity)
                        ? _calendarWorkTimerState?.IsRunning == true
                            ? "⏸ Pausar"
                            : "▶ Continuar"
                        : "▶ Cronómetro");

            timerButton.IsEnabled =
                !activity.IsReviewMirror;

            timerButton.Click +=
                async (_, __) =>
                {
                    if (IsCalendarWorkTimerFor(activity) &&
                        _calendarWorkTimerState?.IsRunning == true)
                    {
                        PauseCalendarWorkTimer(
                            activity);
                    }
                    else
                    {
                        await StartCalendarWorkTimerAsync(
                            activity);
                    }

                    DrawCalendarPreservingView(
                        _calendarActivities,
                        force: true);
                };

            var finishTimerButton =
                BuildCardActionButton(
                    "■ Guardar tiempo");

            finishTimerButton.IsEnabled =
                !activity.IsReviewMirror &&
                IsCalendarWorkTimerFor(activity);

            finishTimerButton.Click +=
                async (_, __) =>
                {
                    await FinishCalendarWorkTimerAsync(
                        activity);
                };

            var readButton =
                BuildCardActionButton(
                    "▶ Leer resumen");

            var stopSpeechButton =
                BuildCardActionButton(
                    "■ Detener");

            stopSpeechButton.IsEnabled = false;

            readButton.Click +=
                async (_, __) =>
                {
                    await StartCalendarActivitySpeechAsync(
                        activity,
                        blocks: null,
                        readButton,
                        stopSpeechButton);
                };

            stopSpeechButton.Click +=
                (_, __) =>
                {
                    StopNotionPreviewSpeech();
                    readButton.Content = "▶ Leer resumen";
                    readButton.IsEnabled = true;
                    stopSpeechButton.IsEnabled = false;
                };

            actions.Children.Add(previewButton);
            actions.Children.Add(messageButton);
            actions.Children.Add(openButton);
            actions.Children.Add(lockButton);
            actions.Children.Add(timerButton);
            actions.Children.Add(finishTimerButton);
            actions.Children.Add(readButton);
            actions.Children.Add(stopSpeechButton);

            root.Children.Add(actions);
            root.Children.Add(contentHost);

            return new Border
            {
                Padding =
                    new Thickness(
                        Math.Max(
                            7,
                            11 * cardScale)),
                CornerRadius =
                    new CornerRadius(
                        Math.Max(
                            6,
                            9 * cardScale)),
                Background =
                    new SolidColorBrush(
                        Color.FromArgb(
                            46,
                            255,
                            255,
                            255)),
                BorderBrush =
                    GetActivityBrush(
                        activity.Status,
                        activity.StatusColor),
                BorderThickness = new Thickness(1),
                Child = root
            };
        }

        private async Task ToggleCalendarPersonActivityContentAsync(
            NotionCalendarActivity activity,
            Button previewButton,
            ContentControl contentHost,
            string collapsedLabel = "Ver contenido",
            string expandedLabel = "Ocultar contenido")
        {
            if (contentHost.Visibility == Visibility.Visible)
            {
                contentHost.Visibility = Visibility.Collapsed;
                previewButton.Content = collapsedLabel;
                return;
            }

            contentHost.Visibility = Visibility.Visible;
            previewButton.Content = expandedLabel;

            // Si la precarga automática ya terminó para esta actividad,
            // se dibuja inmediatamente sin otra petición a Notion.
            if (TryGetCalendarProjectCachedContent(
                    activity.PageId,
                    out var cachedBlocks))
            {
                contentHost.Content =
                    BuildCalendarPersonActivityContent(
                        activity,
                        cachedBlocks);

                return;
            }

            var loading = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 8,
                Margin = new Thickness(0, 4, 0, 2)
            };

            loading.Children.Add(
                new ProgressRing
                {
                    Width = 18,
                    Height = 18,
                    IsActive = true
                });

            loading.Children.Add(
                new TextBlock
                {
                    Text =
                        "Cargando únicamente esta actividad...",
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    FontSize = 10.5,
                    Opacity = 0.72
                });

            contentHost.Content = loading;

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                contentHost.Content =
                    BuildCalendarPersonPreviewMessage(
                        "Configura primero el token de Notion.",
                        isError: true);
                return;
            }

            var panelToken =
                _calendarPersonPreviewCts?.Token ??
                CancellationToken.None;

            using var cts =
                CancellationTokenSource.CreateLinkedTokenSource(
                    panelToken);

            cts.CancelAfter(
                TimeSpan.FromMinutes(3));

            previewButton.IsEnabled = false;

            try
            {
                var blocks =
                    await _notionPreviewService
                        .GetPagePreviewAsync(
                            token,
                            activity.PageId,
                            cts.Token);

                cts.Token.ThrowIfCancellationRequested();

                SaveCalendarProjectCachedContent(
                    activity.PageId,
                    blocks);

                contentHost.Content =
                    BuildCalendarPersonActivityContent(
                        activity,
                        blocks);
            }
            catch (OperationCanceledException)
            {
                contentHost.Content =
                    BuildCalendarPersonPreviewMessage(
                        "La carga se canceló.",
                        isError: false);
            }
            catch (Exception ex)
            {
                contentHost.Content =
                    BuildCalendarPersonPreviewMessage(
                        $"No se pudo cargar el contenido.\n{ex.Message}",
                        isError: true);
            }
            finally
            {
                previewButton.IsEnabled = true;
            }
        }

        private FrameworkElement BuildCalendarPersonActivityContent(
            NotionCalendarActivity activity,
            IReadOnlyList<NotionPreviewBlock> blocks)
        {
            var cardScale =
                GetCalendarProjectCardScale();

            var content = new StackPanel
            {
                Spacing =
                    Math.Max(
                        3,
                        6 * cardScale),
                Margin =
                    new Thickness(
                        0,
                        Math.Max(
                            3,
                            5 * cardScale),
                        0,
                        0)
            };

            if (!string.IsNullOrWhiteSpace(
                    activity.Description))
            {
                content.Children.Add(
                    CreateSectionLabel(
                        "DESCRIPCIÓN"));

                content.Children.Add(
                    CreatePreviewText(
                        activity.Description,
                        Math.Max(
                            8.5,
                            10.5 * cardScale),
                        Microsoft.UI.Text.FontWeights.Normal,
                        0.86,
                        0));
            }

            var visibleBlocks = blocks
                .Where(block =>
                    (block.Kind ==
                        NotionPreviewBlockKind.Divider ||
                     !string.IsNullOrWhiteSpace(
                         block.Text) ||
                     !string.IsNullOrWhiteSpace(
                         block.Url)) &&
                    !(block.Text ?? string.Empty).Contains(
                        "[ANFETA_",
                        StringComparison.OrdinalIgnoreCase) &&
                    !(block.Text ?? string.Empty).Contains(
                        "Datos internos de ANFETA",
                        StringComparison.OrdinalIgnoreCase))
                .Take(120)
                .ToList();

            if (visibleBlocks.Count > 0)
            {
                content.Children.Add(
                    CreateSectionLabel(
                        "CONTENIDO DE LA ACTIVIDAD"));
            }

            var number = 0;

            foreach (var block in visibleBlocks)
            {
                if (block.Kind ==
                    NotionPreviewBlockKind.NumberedListItem)
                {
                    number++;
                }
                else
                {
                    number = 0;
                }

                var element =
                    CreateBlockElement(
                        block,
                        number);

                if (element == null)
                    continue;

                ConstrainCalendarPreviewElement(
                    element,
                    350);

                content.Children.Add(element);
            }

            if (visibleBlocks.Count == 0 &&
                string.IsNullOrWhiteSpace(
                    activity.Description))
            {
                content.Children.Add(
                    CreatePreviewText(
                        "La actividad no contiene bloques visibles.",
                        Math.Max(
                            8.5,
                            10.5 * cardScale),
                        Microsoft.UI.Text.FontWeights.Normal,
                        0.64,
                        0));
            }

            return new Border
            {
                Padding =
                    new Thickness(
                        Math.Max(
                            6,
                            9 * cardScale)),
                CornerRadius =
                    new CornerRadius(
                        Math.Max(
                            5,
                            7 * cardScale)),
                Background =
                    new SolidColorBrush(
                        Color.FromArgb(
                            30,
                            255,
                            255,
                            255)),
                Child = content
            };
        }

        private static FrameworkElement
            BuildCalendarPersonPreviewMessage(
                string message,
                bool isError)
        {
            return new Border
            {
                Margin = new Thickness(0, 5, 0, 0),
                Padding = new Thickness(9),
                CornerRadius = new CornerRadius(7),
                Background =
                    new SolidColorBrush(
                        isError
                            ? Color.FromArgb(
                                34,
                                248,
                                113,
                                113)
                            : Color.FromArgb(
                                30,
                                255,
                                255,
                                255)),
                Child = new TextBlock
                {
                    Text = message,
                    FontSize = 10.5,
                    TextWrapping = TextWrapping.Wrap,
                    Opacity = 0.78
                }
            };
        }

        private void RefreshCalendarPersonPreviewIfOpen()
        {
            if (_calendarProjectPreviewActive)
            {
                if (CalendarPersonPreviewPanel?.Visibility ==
                    Visibility.Visible)
                {
                    DispatcherQueue.TryEnqueue(
                        RenderCalendarProjectPreviewItems);
                }

                return;
            }

            if (CalendarPersonPreviewPanel?.Visibility !=
                    Visibility.Visible ||
                string.IsNullOrWhiteSpace(
                    _calendarPersonPreviewPerson))
            {
                return;
            }

            // Solo se reconstruye el listado si el panel no está siendo creado
            // por esta misma llamada de DrawCalendar. La actualización diferida
            // evita modificar el árbol visual mientras se recorre el calendario.
            var person =
                _calendarPersonPreviewPerson;

            DispatcherQueue.TryEnqueue(() =>
            {
                if (_calendarViewActive &&
                    CalendarPersonPreviewPanel?.Visibility ==
                        Visibility.Visible &&
                    string.Equals(
                        person,
                        _calendarPersonPreviewPerson,
                        StringComparison.OrdinalIgnoreCase))
                {
                    RenderCalendarPersonPreviewItems(person);
                }
            });
        }

        private void RenderCalendarPersonPreviewItems(
            string person)
        {
            if (_calendarProjectPreviewActive)
            {
                RenderCalendarProjectPreviewItems();
                return;
            }

            if (CalendarPersonPreviewItems == null ||
                CalendarPersonPreviewPanel?.Visibility !=
                    Visibility.Visible)
            {
                return;
            }

            CalendarPersonPreviewTitle.Text =
                $"Actividades de {person}";

            CalendarPersonPreviewDate.Text =
                FormatCalendarDate(_calendarSelectedDate);

            var activities =
                GetCalendarPersonPreviewActivities(person);

            CalendarPersonPreviewSummary.Text =
                activities.Count == 0
                    ? "No hay actividades visibles para esta persona en el día y filtros actuales."
                    : activities.Count == 1
                        ? "1 actividad · el contenido de Notion se carga solo al solicitarlo."
                        : $"{activities.Count} actividades · el contenido de Notion se carga solo al solicitarlo.";

            CalendarPersonPreviewItems.Children.Clear();

            if (activities.Count == 0)
            {
                CalendarPersonPreviewItems.Children.Add(
                    BuildCalendarPersonPreviewMessage(
                        "No se encontraron actividades para mostrar.",
                        isError: false));
                return;
            }

            foreach (var activity in activities)
            {
                CalendarPersonPreviewItems.Children.Add(
                    BuildCalendarPersonPreviewCard(
                        activity));
            }
        }

        private void CloseCalendarPersonPreviewPanel(
            bool redrawCalendar = true)
        {
            StopNotionPreviewSpeech();
            try
            {
                _calendarPersonPreviewCts?.Cancel();
                _calendarPersonPreviewCts?.Dispose();
            }
            catch
            {
            }

            _calendarPersonPreviewCts = null;
            _calendarPersonPreviewPerson = string.Empty;

            _calendarProjectPreviewActive = false;
            _calendarProjectPreviewCriteria = null;
            _calendarProjectPreviewActivities =
                Array.Empty<NotionCalendarActivity>();
            _calendarProjectPreviewSourcePageId =
                string.Empty;

            _calendarProjectContentPreloadRunning = false;
            _calendarProjectContentPreloadCompleted = 0;
            _calendarProjectContentPreloadTotal = 0;

            if (CalendarPersonPreviewItems != null)
                CalendarPersonPreviewItems.Children.Clear();

            if (CalendarPersonPreviewPanel != null)
            {
                CalendarPersonPreviewPanel.Visibility =
                    Visibility.Collapsed;
            }

            if (redrawCalendar)
            {
                DispatcherQueue.TryEnqueue(() =>
                {
                    if (_calendarViewActive)
                        DrawCalendar(_calendarActivities);
                });
            }
        }


        private enum OneClickPriorityLevel
        {
            Urgent = 0,
            Today = 1,
            ThisWeek = 2,
            Normal = 3,
            Waiting = 4,
            Closed = 5,
            Undefined = 6
        }

        private sealed class OneClickPriorityInfo
        {
            public OneClickPriorityLevel Level { get; init; }
            public string Label { get; init; } = string.Empty;
            public string Reason { get; init; } = string.Empty;
            public Color Color { get; init; }
            public bool IsMissing { get; init; }
            public bool IsQuickWinReview { get; init; }
            public NotionChecklistStats Checklist { get; init; } =
                new(0, 0);
        }

        private sealed class OneClickSchedulePreviewItem
        {
            public NotionCalendarActivity Activity { get; init; } = new();
            public DateTime Start { get; init; }
            public DateTime End { get; init; }
            public int DurationMinutes { get; init; }
            public bool IsOverflow { get; init; }
            public bool IsOvertime { get; init; }

            // sprtuzREVISION: carril lógico separado al final del día.
            // No cuenta como cobertura normal.
            public bool IsSuspended { get; init; }

            public int OvertimeMinutes { get; init; }
            public string Note { get; init; } = string.Empty;

            public bool HasScheduleChange =>
                !IsOverflow &&
                (Math.Abs(
                     (Activity.Start - Start).TotalMinutes) >= 0.5 ||
                 Math.Abs(
                     (Activity.End - End).TotalMinutes) >= 0.5);
        }

        private sealed class OneClickSchedulePreviewResult
        {
            public string Person { get; init; } = string.Empty;
            public DateTime Day { get; init; }
            public DateTime EffectiveStart { get; init; }
            public DateTime EffectiveEnd { get; init; }
            public DateTime StandardEnd { get; init; }
            public DateTime AbsoluteEnd { get; init; }
            public bool IsToday { get; init; }
            public bool IsLateStart { get; init; }
            public IReadOnlyList<OneClickSchedulePreviewItem> Scheduled { get; init; } =
                Array.Empty<OneClickSchedulePreviewItem>();
            public IReadOnlyList<OneClickSchedulePreviewItem> Overflow { get; init; } =
                Array.Empty<OneClickSchedulePreviewItem>();

            public IReadOnlyList<OneClickSchedulePreviewItem> SuspendedScheduled { get; init; } =
                Array.Empty<OneClickSchedulePreviewItem>();

            public IReadOnlyList<OneClickSchedulePreviewItem> SuspendedOverflow { get; init; } =
                Array.Empty<OneClickSchedulePreviewItem>();

            public IReadOnlyList<NotionCalendarActivity> DeferredToTomorrow { get; init; } =
                Array.Empty<NotionCalendarActivity>();
            public IReadOnlyList<NotionCalendarActivity> InProgressUnchanged { get; init; } =
                Array.Empty<NotionCalendarActivity>();
            public int AvailableMinutes { get; init; }
            public int ScheduledMinutes { get; init; }
            public int NormalChangedCount =>
                Scheduled.Count(item => item.HasScheduleChange);

            public int SuspendedChangedCount =>
                SuspendedScheduled.Count(item => item.HasScheduleChange);

            public int ChangedCount =>
                NormalChangedCount + SuspendedChangedCount;

            public int DeferredCount =>
                DeferredToTomorrow.Count;

            public int TotalActionCount =>
                ChangedCount + DeferredCount;

            public int SuspendedMinutes =>
                SuspendedScheduled.Sum(item => item.DurationMinutes);
            public int OvertimeCount =>
                Scheduled.Count(item => item.IsOvertime);
            public int OvertimeMinutes =>
                Scheduled.Count == 0
                    ? 0
                    : Math.Max(
                        0,
                        (int)Math.Ceiling(
                            (Scheduled.Max(item => item.End) -
                             StandardEnd).TotalMinutes));
            public double CoveragePercentage =>
                AvailableMinutes <= 0
                    ? 0
                    : ScheduledMinutes * 100d / AvailableMinutes;
        }

        private sealed class OneClickSchedulePreviewUiState
        {
            public string Person { get; init; } = string.Empty;
            public List<NotionCalendarActivity> OrderedActivities { get; } = new();
            public OneClickSchedulePreviewResult Result { get; set; } = new();
            public ContentControl? Host { get; set; }
            public ContentDialog? Dialog { get; set; }
            public Popup? Popup { get; set; }
            public Button? ConfirmButton { get; set; }
            public TimeSpan RequestedStart { get; set; } =
                TimeSpan.FromHours(6);
            public string DraggedPageId { get; set; } = string.Empty;
        }

        private static bool IsOneClickPm(string person)
        {
            person = NormalizeCalendarPerson(person);

            return string.Equals(
                       person,
                       "John",
                       StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(
                       person,
                       "Genaro",
                       StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(
                       person,
                       "Isaias",
                       StringComparison.OrdinalIgnoreCase);
        }

        private static bool ContainsOneClickToken(
            string text,
            string token)
        {
            return Regex.IsMatch(
                text ?? string.Empty,
                $@"(?<![\p{{L}}\p{{Nd}}_]){Regex.Escape(token)}(?![\p{{L}}\p{{Nd}}_])",
                RegexOptions.IgnoreCase |
                RegexOptions.CultureInvariant);
        }

        private OneClickPriorityInfo GetOneClickPriorityInfo(
            NotionCalendarActivity activity,
            string person)
        {
            var title = activity?.Title ?? string.Empty;
            var searchable = NormalizeCalendarSearchText(
                string.Join(
                    " ",
                    title,
                    activity?.Status ?? string.Empty,
                    activity?.Description ?? string.Empty));

            var checklist =
                GetCalendarChecklistStats(activity);

            OneClickPriorityInfo Build(
                OneClickPriorityLevel level,
                string label,
                string reason,
                Color color,
                bool missing = false,
                bool quickWin = false)
            {
                return new OneClickPriorityInfo
                {
                    Level = level,
                    Label = label,
                    Reason = reason,
                    Color = color,
                    IsMissing = missing,
                    IsQuickWinReview = quickWin,
                    Checklist = checklist
                };
            }

            if (searchable.Contains("espera", StringComparison.OrdinalIgnoreCase) ||
                searchable.Contains("depende", StringComparison.OrdinalIgnoreCase))
            {
                return Build(
                    OneClickPriorityLevel.Waiting,
                    "En espera",
                    "Depende de otra persona o condición",
                    Color.FromArgb(255, 96, 165, 250));
            }

            if (searchable.Contains("urgente", StringComparison.OrdinalIgnoreCase))
            {
                return Build(
                    OneClickPriorityLevel.Urgent,
                    "Urgente",
                    "Marcada como urgente",
                    Color.FromArgb(255, 248, 113, 113));
            }

            if (IsOneClickPm(person) &&
                HasExactCalendarPhase(activity, "rtuzREVISION"))
            {
                var reason = checklist.HasChecklist
                    ? $"RTUZ · {checklist.Pending} pendiente(s) de {checklist.Total}"
                    : "RTUZ · sin checklist visible";

                return Build(
                    OneClickPriorityLevel.Urgent,
                    "RTUZ primero",
                    reason,
                    Color.FromArgb(255, 248, 113, 113),
                    quickWin: true);
            }

            var activeProjectType =
                new[]
                {
                    "wwebs", "sseo", "aads",
                    "aapli", "pprog"
                }
                .FirstOrDefault(token =>
                    ContainsOneClickToken(title, token));

            if (HasExactCalendarPhase(activity, "prtuzREVISION") &&
                !string.IsNullOrWhiteSpace(activeProjectType))
            {
                return Build(
                    OneClickPriorityLevel.Today,
                    "Alta · hoy",
                    $"Proyecto activo {activeProjectType.ToUpperInvariant()}",
                    Color.FromArgb(255, 251, 146, 60));
            }

            if (searchable.Contains("hoy", StringComparison.OrdinalIgnoreCase) ||
                searchable.Contains("muy importante", StringComparison.OrdinalIgnoreCase))
            {
                return Build(
                    OneClickPriorityLevel.Today,
                    "Muy importante",
                    "Debe realizarse hoy",
                    Color.FromArgb(255, 251, 146, 60));
            }

            if (HasExactCalendarPhase(activity, "prtuzREVISION"))
            {
                return Build(
                    OneClickPriorityLevel.ThisWeek,
                    "Importante",
                    "Actividad por hacer",
                    Color.FromArgb(255, 250, 204, 21));
            }

            var generalType =
                new[]
                {
                    "wwebs", "sseo", "aads", "aapli",
                    "pprog", "ddise", "rrede"
                }
                .FirstOrDefault(token =>
                    ContainsOneClickToken(title, token));

            if (!string.IsNullOrWhiteSpace(generalType))
            {
                return Build(
                    OneClickPriorityLevel.ThisWeek,
                    "Importante",
                    $"Actividad {generalType.ToUpperInvariant()}",
                    Color.FromArgb(255, 250, 204, 21));
            }

            var duration =
                activity == null
                    ? 60
                    : RoundOneClickDurationMinutes(activity);

            if (duration <= 30 ||
                Regex.IsMatch(
                    title,
                    @"(?<![\p{L}\p{Nd}_])[a-z]{4,5}00(?![\p{L}\p{Nd}_])",
                    RegexOptions.IgnoreCase |
                    RegexOptions.CultureInvariant))
            {
                return Build(
                    OneClickPriorityLevel.Normal,
                    "Rápida / delegable",
                    "Ajuste corto de 15 a 30 minutos",
                    Color.FromArgb(255, 74, 222, 128));
            }

            return Build(
                OneClickPriorityLevel.Undefined,
                "Sin prioridad",
                "ANFETA no encontró una regla de prioridad",
                Color.FromArgb(255, 148, 163, 184),
                missing: true);
        }

        private IReadOnlyList<NotionCalendarActivity>
            PrepareOneClickPriorityOrder(
                string person,
                IReadOnlyList<NotionCalendarActivity> activities)
        {
            var list =
                (activities ?? Array.Empty<NotionCalendarActivity>())
                    .ToList();

            if (list.Count == 0)
                return list;

            // One Click NO dispara ni espera la lectura de checklist.
            // El calendario ya hidrata esos datos automáticamente en segundo
            // plano. Si una actividad todavía no termina de analizarse, se
            // usa la información disponible y el desempate cae en duración
            // y horario, permitiendo abrir el preview inmediatamente.
            return list
                .Select(activity =>
                {
                    var priority =
                        GetOneClickPriorityInfo(
                            activity,
                            person);

                    var pendingChecklist =
                        priority.IsQuickWinReview
                            ? priority.Checklist.HasChecklist
                                ? priority.Checklist.Pending
                                : int.MaxValue
                            : 0;

                    return new
                    {
                        Activity = activity,
                        Priority = priority,
                        PendingChecklist = pendingChecklist,
                        Duration =
                            RoundOneClickDurationMinutes(activity)
                    };
                })
                .OrderBy(item => (int)item.Priority.Level)
                .ThenBy(item => item.PendingChecklist)
                .ThenBy(item => item.Duration)
                .ThenBy(item => item.Activity.Start)
                .ThenBy(item => item.Activity.Title)
                .Select(item => item.Activity)
                .ToList();
        }

        private IReadOnlyList<string> BuildOneClickScheduleWarnings(
            OneClickSchedulePreviewUiState state)
        {
            var warnings = new List<string>();

            var allNormal =
                state.Result.Scheduled
                    .Concat(state.Result.Overflow)
                    .ToList();

            if (state.Result.DeferredToTomorrow.Count > 0)
            {
                warnings.Add(
                    $"{state.Result.DeferredToTomorrow.Count} actividad(es) cuyo horario ya terminó se pasarán a mañana al confirmar.");
            }

            if (state.Result.InProgressUnchanged.Count > 0)
            {
                warnings.Add(
                    $"{state.Result.InProgressUnchanged.Count} actividad(es) en curso se conservarán sin cambios.");
            }

            if (state.Result.SuspendedScheduled.Count > 0)
            {
                warnings.Add(
                    $"{state.Result.SuspendedScheduled.Count} suspendida(s) se reservaron al final del día en bloques de 30 min, desde las {state.Result.AbsoluteEnd:h:mm tt} hacia atrás. No cuentan como cobertura normal.");
            }

            if (state.Result.SuspendedOverflow.Count > 0)
            {
                warnings.Add(
                    $"{state.Result.SuspendedOverflow.Count} suspendida(s) no caben en el tramo final disponible; permanecerán sin cambios.");
            }

            var missingPriority =
                allNormal.Count(item =>
                    GetOneClickPriorityInfo(
                        item.Activity,
                        state.Person)
                        .IsMissing);

            if (missingPriority > 0)
            {
                warnings.Add(
                    $"{missingPriority} actividad(es) sin una prioridad reconocida.");
            }

            if (IsOneClickPm(state.Person))
            {
                var rtuzChecklistPending =
                    allNormal.Count(item =>
                    {
                        var priority =
                            GetOneClickPriorityInfo(
                                item.Activity,
                                state.Person);

                        return priority.IsQuickWinReview &&
                               !item.Activity.ChecklistScanned;
                    });

                var rtuzWithoutChecklist =
                    allNormal.Count(item =>
                    {
                        var priority =
                            GetOneClickPriorityInfo(
                                item.Activity,
                                state.Person);

                        return priority.IsQuickWinReview &&
                               item.Activity.ChecklistScanned &&
                               !priority.Checklist.HasChecklist;
                    });

                if (rtuzChecklistPending > 0)
                {
                    warnings.Add(
                        $"{rtuzChecklistPending} revisión(es) RTUZ todavía están calculando checklist en segundo plano; el preview abrió sin esperar y usa duración/horario como desempate temporal.");
                }

                if (rtuzWithoutChecklist > 0)
                {
                    warnings.Add(
                        $"{rtuzWithoutChecklist} revisión(es) RTUZ no tienen checklist nativo visible; se ordenaron por duración y horario.");
                }
            }

            if (state.Result.OvertimeCount > 0)
            {
                warnings.Add(
                    $"{state.Result.OvertimeCount} actividad(es) normales se acomodaron con tiempo extra. " +
                    $"No invaden el tramo reservado para suspendidas ni pasan de las {state.Result.AbsoluteEnd:h:mm tt}.");
            }

            if (state.Result.Overflow.Count > 0)
            {
                warnings.Add(
                    $"{state.Result.Overflow.Count} actividad(es) normales no caben en el tramo disponible.");
            }

            return warnings;
        }

        private static bool IsOneClickSuspendedActivity(
            NotionCalendarActivity activity)
        {
            return activity != null &&
                   HasExactCalendarPhase(
                       activity,
                       "sprtuzREVISION");
        }

        private static bool IsOneClickScheduleBaseExcluded(
            NotionCalendarActivity activity)
        {
            if (activity == null ||
                activity.IsReviewMirror ||
                activity.IsAutomationLocked ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return true;
            }

            if (HasExactCalendarPhase(
                    activity,
                    "zREVISION"))
            {
                return true;
            }

            if (Regex.IsMatch(
                    activity.Title ?? string.Empty,
                    @"(?<![\p{L}\p{Nd}_])F{1,2}TF(?![\p{L}\p{Nd}_])",
                    RegexOptions.IgnoreCase |
                    RegexOptions.CultureInvariant))
            {
                return true;
            }

            var status =
                NormalizeCalendarSearchText(
                    activity.Status);

            return status.Contains(
                       "terminad",
                       StringComparison.OrdinalIgnoreCase) ||
                   status.Contains(
                       "completad",
                       StringComparison.OrdinalIgnoreCase) ||
                   status.Contains(
                       "cancelad",
                       StringComparison.OrdinalIgnoreCase) ||
                   status.Contains(
                       "archivad",
                       StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsOneClickScheduleExcluded(
            NotionCalendarActivity activity)
        {
            // Suspendida ya no desaparece: se procesa por separado al final.
            return IsOneClickScheduleBaseExcluded(activity) ||
                   IsOneClickSuspendedActivity(activity);
        }

        private IReadOnlyList<NotionCalendarActivity>
            GetOneClickScheduleActivities(
                string person)
        {
            person =
                NormalizeCalendarPerson(person);

            return ExpandCalendarReviewActivities(
                    _calendarActivities)
                .Where(activity =>
                    activity != null &&
                    !IsOneClickScheduleExcluded(activity) &&
                    SplitPersons(activity.Person)
                        .Select(NormalizeCalendarPerson)
                        .Any(candidate =>
                            string.Equals(
                                candidate,
                                person,
                                StringComparison.OrdinalIgnoreCase)))
                .GroupBy(
                    activity => activity.PageId,
                    StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .OrderBy(activity => activity.Start)
                .ThenBy(activity => activity.End)
                .ThenBy(activity => activity.Title)
                .ToList();
        }

        private IReadOnlyList<NotionCalendarActivity>
            GetOneClickSuspendedActivities(
                string person)
        {
            person =
                NormalizeCalendarPerson(person);

            return ExpandCalendarReviewActivities(
                    _calendarActivities)
                .Where(activity =>
                    activity != null &&
                    !IsOneClickScheduleBaseExcluded(activity) &&
                    IsOneClickSuspendedActivity(activity) &&
                    SplitPersons(activity.Person)
                        .Select(NormalizeCalendarPerson)
                        .Any(candidate =>
                            string.Equals(
                                candidate,
                                person,
                                StringComparison.OrdinalIgnoreCase)))
                .GroupBy(
                    activity => activity.PageId,
                    StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .OrderByDescending(activity => activity.Start)
                .ThenByDescending(activity => activity.End)
                .ThenBy(activity => activity.Title)
                .ToList();
        }

        private static int RoundOneClickDurationMinutes(
            NotionCalendarActivity activity)
        {
            // La duración sale del rango que la persona ya configuró en
            // “Fecha POR Hacer”. One Click Schedule puede cambiar la hora de
            // inicio, pero no debe recalcular el tiempo por WEB, SEO, ADS u
            // otro tipo de proyecto. Solo se aplica el mínimo operativo de
            // 15 minutos cuando el rango es menor o inválido.
            var rawMinutes =
                activity.End > activity.Start
                    ? (activity.End - activity.Start).TotalMinutes
                    : 60;

            if (!double.IsFinite(rawMinutes) || rawMinutes <= 0)
                rawMinutes = 60;

            var assignedMinutes =
                (int)Math.Ceiling(rawMinutes);

            return Math.Max(15, assignedMinutes);
        }

        private static DateTime RoundOneClickStartUpToQuarterHour(
            DateTime value)
        {
            var clean = new DateTime(
                value.Year,
                value.Month,
                value.Day,
                value.Hour,
                value.Minute,
                0,
                value.Kind);

            var remainder = clean.Minute % 15;
            var hasPartialMinute =
                value.Second > 0 || value.Millisecond > 0;

            if (remainder == 0 && !hasPartialMinute)
                return clean;

            return clean.AddMinutes(
                remainder == 0
                    ? 15
                    : 15 - remainder);
        }

        private static int CalculateOneClickAvailableMinutes(
            DateTime start,
            DateTime end)
        {
            if (end <= start)
                return 0;

            return Math.Max(
                0,
                (int)Math.Round(
                    (end - start).TotalMinutes));
        }

        private static bool TryFindOneClickScheduleSlot(
            DateTime cursor,
            TimeSpan duration,
            DateTime workEnd,
            out DateTime start,
            out DateTime end)
        {
            start = cursor;
            end = start.Add(duration);

            // Reunión 20/08: One Click ya no reserva automáticamente
            // 1:00–2:00 PM. Las actividades se compactan de forma continua
            // desde la hora elegida hasta el límite disponible.
            return end <= workEnd;
        }

        private OneClickSchedulePreviewResult
            BuildOneClickSchedulePreview(
                string person,
                IReadOnlyList<NotionCalendarActivity>? orderedActivities = null,
                DateTime? requestedStart = null)
        {
            var day =
                _calendarSelectedDate.Date;

            // Reunión 20/08: One Click considera toda la jornada operativa
            // desde las 6:00 AM y puede acomodar hasta las 10:00 PM.
            // Las 6:00 PM se conservan únicamente como referencia para marcar
            // tiempo extra; ya NO existe una pausa fija de 1:00–2:00 PM.
            var standardStart =
                day.AddHours(6);

            var standardEnd =
                day.AddHours(18);

            var absoluteEnd =
                day.AddHours(22);

            var today =
                DateTime.Today;

            var isToday =
                day == today;

            var desiredStart =
                requestedStart.HasValue
                    ? day.Add(requestedStart.Value.TimeOfDay)
                    : standardStart;

            var effectiveStart =
                RoundOneClickStartUpToQuarterHour(
                    desiredStart);

            if (effectiveStart < standardStart)
                effectiveStart = standardStart;

            if (effectiveStart > absoluteEnd)
                effectiveStart = absoluteEnd;

            // La hora final disponible siempre es 10:00 PM. El usuario decide
            // desde qué hora comenzar; One Click compacta desde ahí sin huecos.
            var effectiveEnd =
                absoluteEnd;

            // ------------------------------------------------------------
            // SUSPENDIDAS — Genaro 19/08
            // ------------------------------------------------------------
            // sprtuzREVISION != Bloqueada_ANFETA.
            // El candado sigue excluyendo la actividad de toda automatización.
            var suspendedScheduled =
                new List<OneClickSchedulePreviewItem>();

            var suspendedOverflow =
                new List<OneClickSchedulePreviewItem>();

            var suspendedLowerBound =
                effectiveStart > standardEnd
                    ? effectiveStart
                    : standardEnd;

            var suspendedCursor =
                absoluteEnd;

            foreach (var activity in
                     GetOneClickSuspendedActivities(
                         person))
            {
                const int suspendedBlockMinutes = 30;

                var suspendedEnd =
                    suspendedCursor;

                var suspendedStart =
                    suspendedEnd.AddMinutes(
                        -suspendedBlockMinutes);

                if (suspendedStart <
                    suspendedLowerBound)
                {
                    suspendedOverflow.Add(
                        new OneClickSchedulePreviewItem
                        {
                            Activity = activity,
                            DurationMinutes =
                                suspendedBlockMinutes,
                            IsOverflow = true,
                            IsSuspended = true,
                            Note =
                                $"Suspendida sin espacio en el tramo final " +
                                $"{suspendedLowerBound:h:mm tt}–{absoluteEnd:h:mm tt}."
                        });

                    continue;
                }

                suspendedScheduled.Add(
                    new OneClickSchedulePreviewItem
                    {
                        Activity = activity,
                        Start = suspendedStart,
                        End = suspendedEnd,
                        DurationMinutes =
                            suspendedBlockMinutes,
                        IsOverflow = false,
                        IsOvertime = false,
                        IsSuspended = true,
                        OvertimeMinutes = 0,
                        Note =
                            "Suspendida · bloque de 30 min reservado al final del día."
                    });

                suspendedCursor =
                    suspendedStart;
            }

            var normalAbsoluteEnd =
                suspendedScheduled.Count > 0
                    ? suspendedScheduled
                        .Min(item => item.Start)
                    : absoluteEnd;

            if (normalAbsoluteEnd < effectiveStart)
                normalAbsoluteEnd = effectiveStart;

            var availableMinutes =
                CalculateOneClickAvailableMinutes(
                    effectiveStart,
                    normalAbsoluteEnd);

            // ------------------------------------------------------------
            // NORMALES
            // ------------------------------------------------------------
            var scheduled =
                new List<OneClickSchedulePreviewItem>();

            var overflow =
                new List<OneClickSchedulePreviewItem>();

            var cursor =
                effectiveStart;

            var activitiesToSchedule =
                (orderedActivities ??
                 GetOneClickScheduleActivities(
                     person))
                    // Regla 20/08: tomar TODAS las actividades del día que
                    // pertenezcan al tramo operativo 06:00–22:00, aunque su
                    // horario original ya haya pasado. La hora inicial elegida
                    // define desde dónde se reconstruye el acomodo.
                    .Where(activity =>
                        activity != null &&
                        activity.End > standardStart &&
                        activity.Start < absoluteEnd)
                    .ToList();

            var deferredToTomorrow =
                new List<NotionCalendarActivity>();

            var inProgressUnchanged =
                new List<NotionCalendarActivity>();

            foreach (var activity in activitiesToSchedule)
            {
                var durationMinutes =
                    RoundOneClickDurationMinutes(
                        activity);

                var duration =
                    TimeSpan.FromMinutes(
                        durationMinutes);

                if (!TryFindOneClickScheduleSlot(
                        cursor,
                        duration,
                        normalAbsoluteEnd,
                        out var start,
                        out var end))
                {
                    overflow.Add(
                        new OneClickSchedulePreviewItem
                        {
                            Activity = activity,
                            DurationMinutes =
                                durationMinutes,
                            IsOverflow = true,
                            IsSuspended = false,
                            Note =
                                suspendedScheduled.Count > 0
                                    ? $"No cabe antes de las {normalAbsoluteEnd:h:mm tt}; " +
                                      $"el tramo posterior está reservado para " +
                                      $"{suspendedScheduled.Count} suspendida(s)."
                                    : effectiveStart >= absoluteEnd
                                        ? "La hora inicial ya alcanzó el límite absoluto de las 10:00 PM."
                                        : $"No cabe antes de las {absoluteEnd:h:mm tt}."
                        });

                    continue;
                }

                var overtimeStart =
                    start > standardEnd
                        ? start
                        : standardEnd;

                var overtimeMinutes =
                    end > standardEnd
                        ? Math.Max(
                            0,
                            (int)Math.Ceiling(
                                (end - overtimeStart)
                                .TotalMinutes))
                        : 0;

                scheduled.Add(
                    new OneClickSchedulePreviewItem
                    {
                        Activity = activity,
                        Start = start,
                        End = end,
                        DurationMinutes =
                            durationMinutes,
                        IsOverflow = false,
                        IsOvertime =
                            overtimeMinutes > 0,
                        IsSuspended = false,
                        OvertimeMinutes =
                            overtimeMinutes,
                        Note =
                            overtimeMinutes > 0
                                ? $"ANFETA la acomodó usando " +
                                  $"{FormatOneClickDuration(overtimeMinutes)} " +
                                  $"de tiempo extra. Límite disponible: " +
                                  $"{normalAbsoluteEnd:h:mm tt}."
                                : string.Empty
                    });

                // Sin hueco automático entre una actividad y la siguiente.
                cursor =
                    end;
            }

            return new OneClickSchedulePreviewResult
            {
                Person =
                    NormalizeCalendarPerson(
                        person),
                Day = day,
                EffectiveStart =
                    effectiveStart,
                EffectiveEnd =
                    effectiveEnd,
                StandardEnd =
                    standardEnd,
                AbsoluteEnd =
                    absoluteEnd,
                IsToday =
                    isToday,
                IsLateStart =
                    effectiveStart >
                        day.AddHours(12),
                Scheduled =
                    scheduled,
                Overflow =
                    overflow,
                SuspendedScheduled =
                    suspendedScheduled,
                SuspendedOverflow =
                    suspendedOverflow,
                DeferredToTomorrow =
                    deferredToTomorrow,
                InProgressUnchanged =
                    inProgressUnchanged,
                AvailableMinutes =
                    availableMinutes,
                // Las suspendidas no inflan cobertura.
                ScheduledMinutes =
                    scheduled.Sum(item =>
                        item.DurationMinutes)
            };
        }

        private double CalculateCurrentCalendarCoverage(string person)
        {
            var day = _calendarSelectedDate.Date;
            var windows = new[]
            {
                (Start: day.AddHours(10), End: day.AddHours(13)),
                (Start: day.AddHours(14), End: day.AddHours(18))
            };

            var intervals =
                new List<(DateTime Start, DateTime End)>();

            foreach (var activity in
                     GetOneClickScheduleActivities(person))
            {
                foreach (var window in windows)
                {
                    var start =
                        activity.Start > window.Start
                            ? activity.Start
                            : window.Start;

                    var end =
                        activity.End < window.End
                            ? activity.End
                            : window.End;

                    if (end > start)
                        intervals.Add((start, end));
                }
            }

            if (intervals.Count == 0)
                return 0;

            var ordered =
                intervals
                    .OrderBy(item => item.Start)
                    .ThenBy(item => item.End)
                    .ToList();

            var coveredMinutes = 0d;
            var currentStart = ordered[0].Start;
            var currentEnd = ordered[0].End;

            foreach (var interval in ordered.Skip(1))
            {
                if (interval.Start <= currentEnd)
                {
                    if (interval.End > currentEnd)
                        currentEnd = interval.End;
                }
                else
                {
                    coveredMinutes +=
                        (currentEnd - currentStart).TotalMinutes;

                    currentStart = interval.Start;
                    currentEnd = interval.End;
                }
            }

            coveredMinutes +=
                (currentEnd - currentStart).TotalMinutes;

            return Math.Clamp(
                coveredMinutes * 100d / (7 * 60d),
                0,
                999);
        }

        private static SolidColorBrush GetOneClickCoverageBrush(
            double percentage)
        {
            var color = percentage switch
            {
                < 50 => Color.FromArgb(255, 248, 113, 113),
                < 80 => Color.FromArgb(255, 250, 204, 21),
                <= 100 => Color.FromArgb(255, 74, 222, 128),
                _ => Color.FromArgb(255, 192, 132, 252)
            };

            return new SolidColorBrush(color);
        }

        private static string FormatOneClickDuration(int minutes)
        {
            if (minutes < 60)
                return $"{minutes} min";

            var hours = minutes / 60;
            var remainder = minutes % 60;

            return remainder == 0
                ? hours == 1 ? "1 hora" : $"{hours} horas"
                : $"{hours} h {remainder} min";
        }

        private FrameworkElement BuildOneClickPreviewCard(
            OneClickSchedulePreviewItem item,
            bool overflow,
            OneClickSchedulePreviewUiState? state = null)
        {
            var priority =
                GetOneClickPriorityInfo(
                    item.Activity,
                    state?.Person ?? item.Activity.Person);

            var suspendedAccent =
                Color.FromArgb(
                    255,
                    168,
                    85,
                    247);

            var displayAccent =
                item.IsSuspended
                    ? suspendedAccent
                    : priority.Color;

            var displayPriorityLabel =
                item.IsSuspended
                    ? "SUSPENDIDA · FINAL"
                    : priority.Label;

            var displayPriorityReason =
                item.IsSuspended
                    ? "sprtuzREVISION · bloque de 30 min reservado al final del día"
                    : priority.Reason;

            var contentGrid = new Grid
            {
                ColumnSpacing = 9
            };

            contentGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(78)
                });

            contentGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });

            var timeText = new TextBlock
            {
                Text = overflow
                    ? "Excedente"
                    : $"{item.Start:h:mm tt}\n{item.End:h:mm tt}",
                FontSize = 10.5,
                FontWeight =
                    Microsoft.UI.Text.FontWeights.SemiBold,
                Foreground = overflow
                    ? new SolidColorBrush(
                        Color.FromArgb(255, 248, 113, 113))
                    : item.IsSuspended
                        ? new SolidColorBrush(
                            Color.FromArgb(255, 216, 180, 254))
                        : item.IsOvertime
                            ? new SolidColorBrush(
                                Color.FromArgb(255, 192, 132, 252))
                            : new SolidColorBrush(
                                Color.FromArgb(255, 125, 211, 252)),
                TextWrapping = TextWrapping.Wrap,
                VerticalAlignment = VerticalAlignment.Top
            };

            Grid.SetColumn(timeText, 0);
            contentGrid.Children.Add(timeText);

            var details = new StackPanel
            {
                Spacing = 2
            };

            var priorityRow = new Grid();
            priorityRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });
            priorityRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            var priorityBrightness =
                displayAccent.R * 0.299 +
                displayAccent.G * 0.587 +
                displayAccent.B * 0.114;

            var priorityBadge = new Border
            {
                HorizontalAlignment = HorizontalAlignment.Left,
                Padding = new Thickness(8, 3, 8, 3),
                CornerRadius = new CornerRadius(10),
                Background =
                    new SolidColorBrush(
                        Color.FromArgb(
                            225,
                            displayAccent.R,
                            displayAccent.G,
                            displayAccent.B)),
                Child = new TextBlock
                {
                    Text = displayPriorityLabel,
                    FontSize = 9.3,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.Bold,
                    Foreground =
                        new SolidColorBrush(
                            priorityBrightness >= 145
                                ? Colors.Black
                                : Colors.White),
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    MaxLines = 1
                }
            };

            ToolTipService.SetToolTip(
                priorityBadge,
                string.IsNullOrWhiteSpace(displayPriorityReason)
                    ? displayPriorityLabel
                    : $"{displayPriorityLabel}: {displayPriorityReason}");

            Grid.SetColumn(priorityBadge, 0);
            priorityRow.Children.Add(priorityBadge);

            if (!overflow && state != null && !item.IsSuspended)
            {
                var dragIcon = new TextBlock
                {
                    Text = "☰",
                    Margin = new Thickness(6, 0, 0, 0),
                    FontSize = 12,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(210, 125, 211, 252)),
                    VerticalAlignment = VerticalAlignment.Center
                };

                ToolTipService.SetToolTip(
                    dragIcon,
                    "Arrastra esta tarjeta sobre otra para cambiar el orden.");

                Grid.SetColumn(dragIcon, 1);
                priorityRow.Children.Add(dragIcon);
            }

            details.Children.Add(priorityRow);

            details.Children.Add(
                new TextBlock
                {
                    Text = item.Activity.Title,
                    FontSize = 12,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    TextWrapping = TextWrapping.Wrap,
                    MaxLines = 2,
                    TextTrimming = TextTrimming.CharacterEllipsis
                });

            var statusText =
                string.IsNullOrWhiteSpace(item.Activity.Status)
                    ? string.Empty
                    : $" · {item.Activity.Status}";

            details.Children.Add(
                new TextBlock
                {
                    Text =
                        $"{FormatOneClickDuration(item.DurationMinutes)}{statusText}",
                    FontSize = 10,
                    Opacity = 0.78,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    MaxLines = 1
                });

            if (item.IsSuspended)
            {
                details.Children.Add(
                    new TextBlock
                    {
                        Text =
                            "💤 Final del día · 30 min · fuera de cobertura normal",
                        FontSize = 9.7,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(255, 216, 180, 254)),
                        TextWrapping = TextWrapping.Wrap,
                        MaxLines = 2
                    });
            }

            var checklist =
                GetCalendarChecklistStats(item.Activity);

            details.Children.Add(
                new TextBlock
                {
                    Text = item.Activity.ChecklistScanned
                        ? checklist.HasChecklist
                            ? $"☑ Checklist {checklist.Completed}/{checklist.Total} · {GetChecklistPercentage(checklist)}% · {checklist.Pending} pendiente(s)"
                            : "☑ Sin checklist nativo en Notion"
                        : "☑ Checklist pendiente de cargar",
                    FontSize = 9.7,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    Foreground =
                        new SolidColorBrush(
                            checklist.HasChecklist
                                ? Color.FromArgb(255, 125, 211, 252)
                                : Color.FromArgb(255, 148, 163, 184)),
                    TextWrapping = TextWrapping.Wrap,
                    MaxLines = 2
                });

            if (!overflow && item.IsOvertime)
            {
                details.Children.Add(
                    new Border
                    {
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 2, 0, 0),
                        Padding = new Thickness(7, 3, 7, 3),
                        CornerRadius = new CornerRadius(8),
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(50, 192, 132, 252)),
                        BorderBrush =
                            new SolidColorBrush(
                                Color.FromArgb(150, 192, 132, 252)),
                        BorderThickness = new Thickness(1),
                        Child = new TextBlock
                        {
                            Text =
                                $"⏱ Tiempo extra +{FormatOneClickDuration(item.OvertimeMinutes)} · límite 10:00 PM",
                            FontSize = 9.4,
                            FontWeight =
                                Microsoft.UI.Text.FontWeights.SemiBold,
                            Foreground =
                                new SolidColorBrush(
                                    Color.FromArgb(255, 216, 180, 254)),
                            TextWrapping = TextWrapping.Wrap,
                            MaxLines = 2
                        }
                    });
            }

            if (!overflow && item.HasScheduleChange)
            {
                details.Children.Add(
                    new TextBlock
                    {
                        Text =
                            $"Actual {item.Activity.Start:h:mm tt}–{item.Activity.End:h:mm tt} → se actualizará",
                        FontSize = 9.7,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(255, 74, 222, 128)),
                        TextTrimming = TextTrimming.CharacterEllipsis,
                        MaxLines = 1
                    });
            }

            if (overflow &&
                !string.IsNullOrWhiteSpace(item.Note))
            {
                details.Children.Add(
                    new TextBlock
                    {
                        Text = item.Note,
                        FontSize = 9.7,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(255, 251, 146, 60)),
                        TextWrapping = TextWrapping.Wrap,
                        MaxLines = 2,
                        TextTrimming = TextTrimming.CharacterEllipsis
                    });
            }

            Grid.SetColumn(details, 1);
            contentGrid.Children.Add(details);

            var cardContent = new Grid
            {
                ColumnSpacing = 8
            };

            cardContent.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(5)
                });

            cardContent.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });

            var priorityStripe = new Border
            {
                Background =
                    new SolidColorBrush(displayAccent),
                CornerRadius = new CornerRadius(3)
            };

            Grid.SetColumn(priorityStripe, 0);
            cardContent.Children.Add(priorityStripe);

            Grid.SetColumn(contentGrid, 1);
            cardContent.Children.Add(contentGrid);

            var card = new Border
            {
                Padding = new Thickness(7, 7, 10, 7),
                CornerRadius = new CornerRadius(7),
                Background =
                    new SolidColorBrush(
                        overflow
                            ? Color.FromArgb(42, 248, 113, 113)
                            : item.IsSuspended
                                ? Color.FromArgb(46, 168, 85, 247)
                                : item.IsOvertime
                                    ? Color.FromArgb(42, 192, 132, 252)
                                    : Color.FromArgb(34, 255, 255, 255)),
                BorderBrush =
                    new SolidColorBrush(
                        overflow
                            ? Color.FromArgb(150, 248, 113, 113)
                            : item.IsSuspended
                                ? Color.FromArgb(175, 168, 85, 247)
                                : item.IsOvertime
                                    ? Color.FromArgb(165, 192, 132, 252)
                                    : Color.FromArgb(70, 255, 255, 255)),
                BorderThickness = new Thickness(1),
                Child = cardContent,
                Tag = item.Activity.PageId
            };

            ToolTipService.SetToolTip(
                card,
                string.Join(
                    "\n",
                    new[]
                    {
                        displayPriorityReason,
                        item.IsOvertime
                            ? item.Note
                            : overflow
                                ? item.Note
                                : item.IsSuspended
                                    ? "Suspendida reservada al final del día; no participa en el orden normal."
                                    : "Arrastra sobre otra actividad para cambiar el orden."
                    }.Where(value =>
                        !string.IsNullOrWhiteSpace(value))));

            if (!overflow && state != null)
            {
                card.CanDrag = true;
                card.AllowDrop = true;

                card.DragStarting += (_, args) =>
                {
                    state.DraggedPageId =
                        item.Activity.PageId ?? string.Empty;

                    args.Data.RequestedOperation =
                        Windows.ApplicationModel.DataTransfer
                            .DataPackageOperation.Move;

                    args.Data.SetText(
                        state.DraggedPageId);
                };

                card.DragOver += (_, args) =>
                {
                    args.AcceptedOperation =
                        Windows.ApplicationModel.DataTransfer
                            .DataPackageOperation.Move;

                    args.DragUIOverride.Caption =
                        "Cambiar orden y compactar horarios";
                    args.Handled = true;
                };

                card.Drop += async (_, args) =>
                {
                    var sourcePageId =
                        state.DraggedPageId;

                    try
                    {
                        if (args.DataView.Contains(
                                Windows.ApplicationModel.DataTransfer
                                    .StandardDataFormats.Text))
                        {
                            sourcePageId =
                                await args.DataView.GetTextAsync();
                        }
                    }
                    catch
                    {
                    }

                    var point = args.GetPosition(card);
                    var insertAfter =
                        point.Y >= card.ActualHeight / 2d;

                    ReorderOneClickSchedulePreview(
                        state,
                        sourcePageId,
                        item.Activity.PageId,
                        insertAfter);

                    args.Handled = true;
                };
            }

            return card;
        }


        private FrameworkElement BuildOneClickSchedulePreviewContent(
            OneClickSchedulePreviewUiState state)
        {
            var host = new ContentControl
            {
                HorizontalContentAlignment =
                    HorizontalAlignment.Stretch
            };

            state.Host = host;
            host.Content =
                BuildOneClickSchedulePreviewVisual(state);

            var startPicker = new TimePicker
            {
                Header = "Hora de inicio",
                ClockIdentifier = "24HourClock",
                MinuteIncrement = 15,
                Time = state.RequestedStart,
                Width = 165,
                HorizontalAlignment =
                    HorizontalAlignment.Left
            };

            var rangeText = new TextBlock
            {
                Text =
                    "One Click toma todas las actividades del día entre 06:00 y 22:00. " +
                    "Ya no reserva automáticamente 13:00–14:00.",
                FontSize = 10.2,
                Opacity = 0.74,
                TextWrapping = TextWrapping.Wrap,
                VerticalAlignment = VerticalAlignment.Center
            };

            var selectorGrid = new Grid
            {
                ColumnSpacing = 12,
                Padding = new Thickness(10, 8, 10, 8),
                Background =
                    new SolidColorBrush(
                        Color.FromArgb(26, 56, 189, 248))
            };

            selectorGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            selectorGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });

            Grid.SetColumn(startPicker, 0);
            Grid.SetColumn(rangeText, 1);
            selectorGrid.Children.Add(startPicker);
            selectorGrid.Children.Add(rangeText);

            startPicker.TimeChanged +=
                (_, __) =>
                {
                    var selected =
                        startPicker.Time;

                    var minimum =
                        TimeSpan.FromHours(6);

                    var maximum =
                        TimeSpan.FromHours(21) +
                        TimeSpan.FromMinutes(45);

                    var clamped =
                        selected < minimum
                            ? minimum
                            : selected > maximum
                                ? maximum
                                : selected;

                    if (clamped != selected)
                    {
                        startPicker.Time = clamped;
                        return;
                    }

                    state.RequestedStart =
                        clamped;

                    state.Result =
                        BuildOneClickSchedulePreview(
                            state.Person,
                            state.OrderedActivities,
                            _calendarSelectedDate.Date.Add(
                                state.RequestedStart));

                    host.Content =
                        BuildOneClickSchedulePreviewVisual(
                            state);

                    if (state.ConfirmButton != null)
                    {
                        state.ConfirmButton.IsEnabled =
                            state.Result.TotalActionCount > 0;
                    }

                    if (state.Dialog != null)
                    {
                        state.Dialog.IsPrimaryButtonEnabled =
                            state.Result.TotalActionCount > 0;
                    }

                    StatusText.Text =
                        $"Estado: One Click {state.Person} · inicio " +
                        $"{state.Result.EffectiveStart:h:mm tt} · " +
                        $"{state.Result.Scheduled.Count} actividad(es) acomodadas.";
                };

            return new StackPanel
            {
                Spacing = 8,
                Children =
                {
                    selectorGrid,
                    host
                }
            };
        }

        private FrameworkElement BuildOneClickSchedulePreviewVisual(
