            Button BuildCompactInfoButton(
                string icon,
                string title,
                string detail,
                Color accent,
                double width = 34)
            {
                var button = new Button
                {
                    Content = icon,
                    Width = width,
                    Height = 30,
                    Padding = new Thickness(4, 1, 4, 1),
                    HorizontalContentAlignment =
                        HorizontalAlignment.Center,
                    VerticalContentAlignment =
                        VerticalAlignment.Center,
                    FontSize = 11,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    CornerRadius = new CornerRadius(6),
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                28,
                                accent.R,
                                accent.G,
                                accent.B)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                95,
                                accent.R,
                                accent.G,
                                accent.B)),
                    BorderThickness = new Thickness(1)
                };

                ToolTipService.SetToolTip(
                    button,
                    title);

                button.Flyout = new Flyout
                {
                    Content = new Border
                    {
                        Width = 330,
                        MaxWidth = 330,
                        Padding = new Thickness(12),
                        CornerRadius = new CornerRadius(8),
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(255, 42, 42, 42)),
                        BorderBrush =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    120,
                                    accent.R,
                                    accent.G,
                                    accent.B)),
                        BorderThickness = new Thickness(1),
                        Child = new StackPanel
                        {
                            Spacing = 6,
                            Children =
                            {
                                new TextBlock
                                {
                                    Text = title,
                                    FontSize = 12.5,
                                    FontWeight =
                                        Microsoft.UI.Text.FontWeights.SemiBold,
                                    Foreground =
                                        new SolidColorBrush(accent)
                                },
                                new TextBlock
                                {
                                    Text = detail,
                                    FontSize = 10.5,
                                    TextWrapping = TextWrapping.Wrap,
                                    MaxWidth = 300
