        private async Task WarmOpenCalendarProjectChecklistAsync(
            NotionCalendarActivity sourceActivity,
            CalendarProjectGroupCriteria criteria,
            IReadOnlyList<NotionCalendarActivity> activities,
            string highlightPageId,
            CancellationToken cancellationToken)
        {
            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token) ||
                activities == null ||
                activities.Count == 0)
            {
                return;
            }

            try
            {
                await _notionCalendarService
                    .WarmChecklistStatsForActivitiesAsync(
                        token,
                        activities,
                        cancellationToken);

                cancellationToken.ThrowIfCancellationRequested();

                SaveCalendarProjectActivitiesToMemory(
                    criteria,
                    activities);

                if (_calendarActivityPreviewPopup?.IsOpen != true ||
                    _calendarActivityPreviewHost == null)
                {
                    return;
                }

                var visiblePageId =
                    _calendarActivityPreviewPinned
                        ? _calendarActivityPreviewPinnedPageId
                        : (_calendarHoveredActivityButton?.Tag as
                            NotionCalendarActivity)?.PageId ??
                          string.Empty;

                if (!string.Equals(
                        visiblePageId,
                        highlightPageId,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                var selected =
                    activities.FirstOrDefault(activity =>
                        string.Equals(
                            activity.PageId,
                            highlightPageId,
                            StringComparison.OrdinalIgnoreCase))
                    ?? sourceActivity;

                UpdateCalendarActivityPreviewContent(
                    BuildCalendarProjectHoverChecklist(
                        selected,
                        criteria,
                        activities));
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                Debug.WriteLine(
                    $"[PROJECT_CHECKLIST_WARM] {ex.Message}");
            }
        }

        private async Task RefreshPinnedCalendarProjectChecklistAsync(
            NotionCalendarActivity sourceActivity,
            CalendarProjectGroupCriteria criteria,
            string highlightPageId)
        {
            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
                return;

            try
            {
                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(2));

                var related =
                    await GetCalendarProjectRelatedActivitiesAsync(
                        sourceActivity,
                        criteria,
                        token,
                        cts.Token,
                        forceRefresh: false);

                var highlighted =
                    related.FirstOrDefault(activity =>
                        string.Equals(
                            activity.PageId,
                            highlightPageId,
                            StringComparison.OrdinalIgnoreCase))
                    ?? sourceActivity;

                if (_calendarActivityPreviewPopup?.IsOpen == true &&
                    _calendarActivityPreviewHost != null)
                {
                    UpdateCalendarActivityPreviewContent(
                        BuildCalendarProjectHoverChecklist(
                            highlighted,
                            criteria,
                            related));
                }
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: Se guardó el cambio, pero no se pudo refrescar la checklist → {ex.Message}";
            }
        }

        private async Task RefreshCalendarDayAfterProjectActionAsync()
        {
            try
            {
                var cached =
                    await _notionCalendarService
                        .TryGetCachedDayAsync(
                            _calendarSelectedDate);

                if (cached == null)
                    return;

                _calendarActivities =
                    cached;

                ApplyCachedCalendarReviewFlow(
                    _calendarActivities);

                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);
            }
            catch
            {
                // La acción principal ya quedó guardada en Notion.
                // Un fallo visual de refresco no debe presentarse como fallo de guardado.
            }
        }

        private async Task<bool> CompleteCalendarProjectActivityAsync(
            NotionCalendarActivity activity)
        {
            if (activity == null ||
                activity.IsReviewMirror)
            {
                return false;
            }

            if (HasExactCalendarPhase(
                    activity,
                    "zREVISION"))
            {
                StatusText.Text =
                    "Estado: La actividad ya está terminada.";
                return true;
            }

            var dialog =
                new ContentDialog
                {
                    XamlRoot = XamlRoot,
                    Title = "Terminar actividad",
                    Content =
                        new TextBlock
                        {
                            Text =
                                "La actividad pasará a zREVISION. ¿Deseas continuar?",
                            TextWrapping =
                                TextWrapping.Wrap
                        },
                    PrimaryButtonText = "Terminar",
                    CloseButtonText = "Cancelar",
                    DefaultButton =
                        ContentDialogButton.Primary
                };

            if (await dialog.ShowAsync() !=
                ContentDialogResult.Primary)
            {
                return false;
            }

            // Si está en revisión pendiente, conserva el flujo existente y
            // registra la revisión como aprobada en lugar de saltarse metadata.
            if (HasExactCalendarPhase(
                    activity,
                    "rtuzREVISION") &&
                activity.IsPendingReview)
            {
                if (!CanCurrentUserResolveReview(activity))
                {
                    StatusText.Text =
                        $"Estado: Solo {activity.ReviewAssignee} puede terminar/aprobar esta revisión.";
                    return false;
                }

                _calendarReviewFlowCache.TryGetValue(
                    activity.PageId,
                    out var previousMetadata);

                var reviewer =
                    NormalizeCalendarPerson(
                        !string.IsNullOrWhiteSpace(
                            previousMetadata?.ReviewAssignee)
                            ? previousMetadata.ReviewAssignee
                            : activity.ReviewAssignee);

                var original =
                    ResolveOriginalReviewPersonForCompletion(
                        activity,
                        reviewer,
                        previousMetadata);

                var approvedMetadata =
                    new ReviewFlowMetadata
                    {
                        OriginalPerson = original,
                        ReviewAssignee = reviewer,
                        State = "approved",
                        SubmittedAt =
                            activity.ReviewSubmittedAt ??
                            previousMetadata?.SubmittedAt ??
                            DateTimeOffset.Now,
                        UpdatedAt = DateTimeOffset.Now,
                        UpdatedBy =
                            GetCurrentCalendarUserName(),
                        Note =
                            "Actividad terminada desde la checklist de proyecto.",
                        AlertPageId =
                            previousMetadata?.AlertPageId ??
                            string.Empty,
                        AlertPageUrl =
                            previousMetadata?.AlertPageUrl ??
                            string.Empty
                    };

                var reviewSaved =
                    await SaveCalendarReviewFlowAsync(
                        activity,
                        approvedMetadata,
                        "Actividad terminada");

                return reviewSaved &&
                       HasExactCalendarPhase(
                           activity,
                           "zREVISION");
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return false;
            }

            try
            {
                ShowLoadingState(
                    "Estado: Terminando actividad…",
                    activity.Title);

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(2));

                var updatedTitle =
                    ReplaceCalendarReviewPhase(
                        activity.Title,
                        "zREVISION");

                await _notionCalendarService
                    .UpdateActivityTitleAsync(
                        token,
                        activity.PageId,
                        updatedTitle,
                        cts.Token);

                activity.Title =
                    updatedTitle;

                foreach (var item in
                         _calendarActivities.Where(item =>
                             string.Equals(
                                 item.PageId,
                                 activity.PageId,
                                 StringComparison.OrdinalIgnoreCase)))
                {
                    item.Title =
                        updatedTitle;
                }

                StatusText.Text =
                    "Estado: Actividad terminada ✅";

                return true;
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo terminar la actividad → {ex.Message}";

                return false;
            }
            finally
            {
                HideLoadingState();
            }
        }

        private async Task<bool> ChangeCalendarProjectActivityDateAsync(
            NotionCalendarActivity activity,
            CalendarProjectGroupCriteria? projectCriteria = null)
        {
            if (activity == null ||
                activity.IsReviewMirror)
            {
                return false;
            }

            if (activity.IsAutomationLocked)
            {
                StatusText.Text =
                    "Estado: La actividad está bloqueada para automatizaciones.";
                return false;
            }

            if (projectCriteria == null &&
                TryBuildCalendarProjectGroupCriteria(
                    activity,
                    out var resolvedCriteria))
            {
                projectCriteria =
                    resolvedCriteria;
            }

            var allowedYear =
                projectCriteria?.Year ??
                activity.Start.Year;

            var allowedMonth =
                projectCriteria?.Month ??
                activity.Start.Month;

            var monthStart =
                new DateTime(
                    allowedYear,
                    allowedMonth,
                    1);

            var monthEnd =
                monthStart
                    .AddMonths(1)
                    .AddDays(-1);

            var minDate =
                new DateTimeOffset(
                    monthStart.Year,
                    monthStart.Month,
                    monthStart.Day,
                    0,
                    0,
                    0,
                    DateTimeOffset.Now.Offset);

            var maxDate =
                new DateTimeOffset(
                    monthEnd.Year,
                    monthEnd.Month,
                    monthEnd.Day,
                    23,
                    59,
                    59,
                    DateTimeOffset.Now.Offset);

            var currentIsInsideMonth =
                activity.Start.Date >=
                    monthStart.Date &&
                activity.Start.Date <=
                    monthEnd.Date;

            var datePicker =
                new CalendarDatePicker
                {
                    Header = "Fecha POR Hacer",
                    Date =
                        currentIsInsideMonth
                            ? new DateTimeOffset(
                                activity.Start.Year,
                                activity.Start.Month,
                                activity.Start.Day,
                                0,
                                0,
                                0,
                                DateTimeOffset.Now.Offset)
                            : null,
                    MinDate = minDate,
                    MaxDate = maxDate,
                    PlaceholderText =
                        $"Selecciona una fecha de " +
                        $"{monthStart.ToString("MMMM yyyy", new CultureInfo("es-MX"))}",
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            var current =
                new TextBlock
                {
                    Text =
                        $"Se conservará el horario actual: " +
                        $"{activity.Start:HH:mm}–{activity.End:HH:mm} · " +
                        $"{activity.EstimatedDurationLabel}",
                    FontSize = 10.5,
                    Opacity = 0.72,
                    TextWrapping =
                        TextWrapping.Wrap
                };

            var monthRule =
                new TextBlock
                {
                    Text =
                        projectCriteria != null
                            ? $"Proyecto {projectCriteria.MonthTag} · " +
                              $"solo se permiten fechas del " +
                              $"{monthStart:dd/MM/yyyy} al {monthEnd:dd/MM/yyyy}."
                            : $"Solo se permiten fechas del mes " +
                              $"{monthStart:MMMM yyyy}.",
                    FontSize = 10.5,
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255,
                                125,
                                211,
                                252)),
                    Opacity = 0.86,
                    TextWrapping =
                        TextWrapping.Wrap
                };

            var panel =
                new StackPanel
                {
                    Width = 390,
                    Spacing = 10,
                    Children =
                    {
                        current,
                        monthRule,
                        datePicker
                    }
                };

            var dialog =
                new ContentDialog
                {
                    XamlRoot = XamlRoot,
                    Title = "📅 Cambiar fecha de actividad",
                    Content = panel,
                    PrimaryButtonText = "Guardar fecha",
                    CloseButtonText = "Cancelar",
                    DefaultButton =
                        ContentDialogButton.Primary
                };

            if (await dialog.ShowAsync() !=
                    ContentDialogResult.Primary ||
                !datePicker.Date.HasValue)
            {
                return false;
            }

            var selected =
                datePicker.Date.Value.LocalDateTime.Date;

            var newStart =
                selected.Add(
                    activity.Start.TimeOfDay);

            var duration =
                activity.End > activity.Start
                    ? activity.End - activity.Start
                    : TimeSpan.FromMinutes(15);

            var newEnd =
                newStart.Add(duration);

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return false;
            }

            try
            {
                ShowLoadingState(
                    "Estado: Cambiando Fecha POR Hacer…",
                    activity.Title);

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(2));

                var result =
                    await _notionCalendarService
                        .UpdateActivityScheduleWithAuditAsync(
                            token,
                            activity,
                            newStart,
                            newEnd,
                            $"ANFETA · checklist proyecto · cambio de fecha · " +
                            $"{DateTime.Now:yyyy-MM-dd HH:mm}",
                            cts.Token);

                activity.Start =
                    result.Activity.Start;

                activity.End =
                    result.Activity.End;

                activity.DatePropertyName =
                    result.Activity.DatePropertyName;

                StatusText.Text =
                    $"Estado: Fecha actualizada ✅ · {activity.Start:dd/MM/yyyy}";

                return true;
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo cambiar la fecha → {ex.Message}";

                return false;
            }
            finally
            {
                HideLoadingState();
            }
        }

        private async Task<bool> AdjustCalendarProjectActivityDurationAsync(
            NotionCalendarActivity activity,
            int deltaMinutes,
            IReadOnlyList<NotionCalendarActivity>? projectActivities = null,
            CalendarProjectGroupCriteria? criteria = null)
        {
            if (activity == null ||
                activity.IsReviewMirror ||
                deltaMinutes == 0)
            {
                return false;
            }

            if (activity.IsAutomationLocked)
            {
                StatusText.Text =
                    "Estado: La actividad está bloqueada para automatizaciones.";
                return false;
            }

            var currentMinutes =
                activity.End > activity.Start
                    ? Math.Max(
                        15,
                        (int)Math.Round(
                            (activity.End -
                             activity.Start)
                            .TotalMinutes))
                    : 15;

            var nextMinutes =
                Math.Max(
                    15,
                    currentMinutes + deltaMinutes);

            if (nextMinutes == currentMinutes)
            {
                StatusText.Text =
                    "Estado: La duración mínima es de 15 minutos.";
                return false;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return false;
            }

            var day =
                activity.Start.Date;

            var owner =
                GetCalendarProjectPrimaryPerson(
                    activity);

            var newEnd =
                activity.Start.AddMinutes(
                    nextMinutes);

            var dayLimit =
                day.AddHours(
                    CalendarEndHour);

            if (newEnd.Date != day ||
                newEnd > dayLimit)
            {
                StatusText.Text =
                    $"Estado: La nueva duración terminaría después de " +
                    $"{CalendarEndHour:00}:00. No se aplicaron cambios.";
                return false;
            }

            var plans =
                new List<CalendarProjectSchedulePlan>
                {
                    new(
                        activity,
                        activity.Start,
                        newEnd)
                };

            // +15 inteligente:
            // si el nuevo final alcanza a la siguiente actividad de la MISMA
            // persona, se recorre esa actividad conservando su duración y se
            // continúa en cadena únicamente mientras exista empalme.
            // -15 solo libera espacio; nunca arrastra lo posterior hacia atrás.
            if (deltaMinutes > 0)
            {
                IReadOnlyList<NotionCalendarActivity>? dayActivities =
                    null;

                try
                {
                    using var dayCts =
                        new CancellationTokenSource(
                            TimeSpan.FromMinutes(2));

                    if (day == _calendarSelectedDate.Date &&
                        _calendarActivities.Count > 0)
                    {
                        dayActivities =
                            _calendarActivities;
                    }
                    else
                    {
                        dayActivities =
                            await _notionCalendarService
                                .TryGetCachedDayAsync(
                                    day,
                                    dayCts.Token);

                        dayActivities ??=
                            await _notionCalendarService
                                .GetDayAsync(
                                    token,
                                    day,
                                    progress: null,
                                    cancellationToken:
                                        dayCts.Token,
                                    forceRefresh: false);
                    }
                }
                catch (OperationCanceledException)
                {
                    StatusText.Text =
                        "Estado: No se pudo verificar el horario del día a tiempo. " +
                        "No se aplicaron cambios.";
                    return false;
                }
                catch (Exception ex)
                {
                    StatusText.Text =
                        $"Estado: No se pudo verificar el horario del día → {ex.Message}";
                    return false;
                }

                var subsequent =
                    (dayActivities ??
                     Array.Empty<NotionCalendarActivity>())
                        .Where(other =>
                            other != null &&
                            !other.IsReviewMirror &&
                            !string.IsNullOrWhiteSpace(
                                other.PageId) &&
                            !string.Equals(
                                other.PageId,
                                activity.PageId,
                                StringComparison.OrdinalIgnoreCase) &&
                            other.Start.Date == day &&
                            other.Start >= activity.Start &&
                            string.Equals(
                                GetCalendarProjectPrimaryPerson(
                                    other),
                                owner,
                                StringComparison.OrdinalIgnoreCase))
                        .GroupBy(
                            other => other.PageId,
                            StringComparer.OrdinalIgnoreCase)
                        .Select(group => group.First())
                        .OrderBy(other => other.Start)
                        .ThenBy(other => other.End)
                        .ThenBy(other => other.Title)
                        .ToList();

                var cursor =
                    newEnd;

                foreach (var other in subsequent)
                {
                    // Al encontrar un hueco suficiente, las actividades que
                    // siguen ya no necesitan moverse.
                    if (other.Start >= cursor)
                        break;

                    if (other.IsAutomationLocked)
                    {
                        StatusText.Text =
                            $"Estado: +15 necesita recorrer una actividad bloqueada de " +
                            $"{owner}: {other.Start:HH:mm}–{other.End:HH:mm} · " +
                            $"{other.Title}. Desbloquéala primero.";
                        return false;
                    }

                    var duration =
                        other.End > other.Start
                            ? other.End - other.Start
                            : TimeSpan.FromMinutes(15);

                    if (duration <
                        TimeSpan.FromMinutes(15))
                    {
                        duration =
                            TimeSpan.FromMinutes(15);
                    }

                    var shiftedStart =
                        cursor;

                    var shiftedEnd =
                        shiftedStart.Add(
                            duration);

                    if (shiftedStart.Date != day ||
                        shiftedEnd.Date != day ||
                        shiftedEnd > dayLimit)
                    {
                        StatusText.Text =
                            $"Estado: El ajuste encadenado no cabe antes de " +
                            $"{CalendarEndHour:00}:00. No se aplicaron cambios.";
                        return false;
                    }

                    plans.Add(
                        new CalendarProjectSchedulePlan(
                            other,
                            shiftedStart,
                            shiftedEnd));

                    cursor =
                        shiftedEnd;
                }
            }

            var snapshots =
                plans
                    .Select(plan => plan.Activity)
                    .GroupBy(
                        item => item.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToDictionary(
                        item => item.PageId,
                        item =>
                            new CalendarProjectScheduleSnapshot(
                                item.PageId,
                                item.Start,
                                item.End,
                                item.DatePropertyName ??
                                string.Empty),
                        StringComparer.OrdinalIgnoreCase);

            var shiftedCount =
                Math.Max(
                    0,
                    plans.Count - 1);

            var applied =
                new List<NotionCalendarActivity>();

            // Feedback visual inmediato. Si una escritura falla, se restaura
            // tanto Notion como la copia local mediante rollback.
            foreach (var plan in plans)
            {
                ApplyCalendarProjectScheduleLocally(
                    plan.Activity,
                    plan.NewStart,
                    plan.NewEnd,
                    plan.Activity.DatePropertyName);
            }

            if (criteria != null &&
                projectActivities != null)
            {
                SaveCalendarProjectActivitiesToMemory(
                    criteria,
                    projectActivities);

                if (_calendarActivityPreviewPopup?.IsOpen == true &&
                    _calendarActivityPreviewHost != null)
                {
                    UpdateCalendarActivityPreviewContent(
                        BuildCalendarProjectHoverChecklist(
                            activity,
                            criteria,
                            projectActivities));
                }
            }

            try
            {
                ShowLoadingState(
                    shiftedCount > 0
                        ? "Estado: Ajustando duración y recorriendo actividades…"
                        : "Estado: Ajustando duración…",
                    shiftedCount > 0
                        ? $"{owner} · {shiftedCount + 1} cambios"
                        : $"{activity.Start:HH:mm}–{newEnd:HH:mm}");

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(5));

                for (var index = 0;
                     index < plans.Count;
                     index++)
                {
                    cts.Token.ThrowIfCancellationRequested();

                    var plan =
                        plans[index];

                    var isTarget =
                        string.Equals(
                            plan.Activity.PageId,
                            activity.PageId,
                            StringComparison.OrdinalIgnoreCase);

                    UpdateLoadingState(
                        shiftedCount > 0
                            ? "Estado: Ajustando duración y recorriendo actividades…"
                            : "Estado: Ajustando duración…",
                        $"{index + 1}/{plans.Count} · " +
                        $"{plan.NewStart:HH:mm}–{plan.NewEnd:HH:mm} · " +
                        plan.Activity.Title);

                    var audit =
                        isTarget
                            ? $"ANFETA · checklist proyecto · duración " +
                              $"{currentMinutes}m → {nextMinutes}m · " +
                              $"{DateTime.Now:yyyy-MM-dd HH:mm}"
                            : $"ANFETA · checklist proyecto · ajuste encadenado " +
                              $"+{deltaMinutes}m · " +
                              $"{DateTime.Now:yyyy-MM-dd HH:mm}";

                    var result =
                        await _notionCalendarService
                            .UpdateActivityScheduleWithAuditAsync(
                                token,
                                plan.Activity,
                                plan.NewStart,
                                plan.NewEnd,
                                audit,
                                cts.Token);

                    ApplyCalendarProjectScheduleLocally(
                        plan.Activity,
                        result.Activity.Start,
                        result.Activity.End,
                        result.Activity.DatePropertyName);

                    applied.Add(
                        plan.Activity);
                }

                if (criteria != null &&
                    projectActivities != null)
                {
                    SaveCalendarProjectActivitiesToMemory(
                        criteria,
                        projectActivities);

                    if (_calendarActivityPreviewPopup?.IsOpen == true &&
                        _calendarActivityPreviewHost != null)
                    {
                        UpdateCalendarActivityPreviewContent(
                            BuildCalendarProjectHoverChecklist(
                                activity,
                                criteria,
                                projectActivities));
                    }
                }

                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);

                StatusText.Text =
                    shiftedCount > 0
                        ? $"Estado: Duración actualizada ✅ · " +
                          $"{FormatCalendarWorkMinutes(nextMinutes)} · " +
                          $"{shiftedCount} actividad(es) posterior(es) recorrida(s)"
                        : $"Estado: Duración actualizada ✅ · " +
                          $"{FormatCalendarWorkMinutes(nextMinutes)}";

                return true;
            }
            catch (Exception ex)
            {
                var rollbackFailures =
                    new List<string>();

                try
                {
                    using var rollbackCts =
                        new CancellationTokenSource(
                            TimeSpan.FromMinutes(5));

                    foreach (var appliedActivity in
                             applied.AsEnumerable().Reverse())
                    {
                        if (!snapshots.TryGetValue(
                                appliedActivity.PageId,
                                out var snapshot))
                        {
                            continue;
                        }

                        try
                        {
                            var rollback =
                                await _notionCalendarService
                                    .UpdateActivityScheduleWithAuditAsync(
                                        token,
                                        appliedActivity,
                                        snapshot.Start,
                                        snapshot.End,
                                        $"ANFETA · rollback ajuste duración · " +
                                        $"{DateTime.Now:yyyy-MM-dd HH:mm}",
                                        rollbackCts.Token);

                            ApplyCalendarProjectScheduleLocally(
                                appliedActivity,
                                rollback.Activity.Start,
                                rollback.Activity.End,
                                rollback.Activity.DatePropertyName);
                        }
                        catch
                        {
                            rollbackFailures.Add(
                                appliedActivity.Title);
                        }
                    }
                }
                catch
                {
                    // El estado local se restaura abajo aun cuando una petición
                    // de rollback no haya podido completarse.
                }

                foreach (var snapshot in snapshots.Values)
                {
                    var localActivity =
                        plans
                            .Select(plan =>
                                plan.Activity)
                            .FirstOrDefault(candidate =>
                                string.Equals(
                                    candidate.PageId,
                                    snapshot.PageId,
                                    StringComparison.OrdinalIgnoreCase));

                    if (localActivity == null)
                        continue;

                    ApplyCalendarProjectScheduleLocally(
                        localActivity,
                        snapshot.Start,
                        snapshot.End,
                        snapshot.DatePropertyName);
                }

                if (criteria != null &&
                    projectActivities != null)
                {
                    SaveCalendarProjectActivitiesToMemory(
                        criteria,
                        projectActivities);

                    if (_calendarActivityPreviewPopup?.IsOpen == true &&
                        _calendarActivityPreviewHost != null)
                    {
                        UpdateCalendarActivityPreviewContent(
                            BuildCalendarProjectHoverChecklist(
                                activity,
                                criteria,
                                projectActivities));
                    }
                }

                try
                {
                    DrawCalendarPreservingView(
                        _calendarActivities,
                        force: true);
                }
                catch
                {
                }

                StatusText.Text =
                    rollbackFailures.Count == 0
                        ? $"Estado: Falló el ajuste y se revirtieron los cambios → {ex.Message}"
                        : $"Estado: Falló el ajuste y el rollback quedó incompleto " +
                          $"({rollbackFailures.Count}) → {ex.Message}";

                return false;
            }
            finally
            {
                HideLoadingState();
            }
        }


        private sealed record CalendarProjectScheduleSnapshot(
            string PageId,
            DateTime Start,
            DateTime End,
            string DatePropertyName);

        private sealed record CalendarProjectSchedulePlan(
            NotionCalendarActivity Activity,
            DateTime NewStart,
            DateTime NewEnd);

        private static string GetCalendarProjectPrimaryPerson(
            NotionCalendarActivity activity)
        {
            if (activity == null)
                return "Sin asignar";

            foreach (var raw in
                     SplitPersons(
                         activity.Person ??
                         string.Empty))
            {
                var normalized =
                    NormalizeCalendarPerson(raw);

                if (!string.IsNullOrWhiteSpace(normalized) &&
                    !string.Equals(
                        normalized,
                        "Sin asignar",
                        StringComparison.OrdinalIgnoreCase))
                {
                    return normalized;
                }
            }

            foreach (var raw in
                     SplitPersons(
                         activity.OriginalPerson ??
                         string.Empty))
            {
                var normalized =
                    NormalizeCalendarPerson(raw);

                if (!string.IsNullOrWhiteSpace(normalized) &&
                    !string.Equals(
                        normalized,
                        "Sin asignar",
                        StringComparison.OrdinalIgnoreCase))
                {
                    return normalized;
                }
            }

            var titlePerson =
                GetActiveCalendarPersonFromTitle(
                    activity.Title);

            if (!string.IsNullOrWhiteSpace(titlePerson))
                return titlePerson;

            return "Sin asignar";
        }

        private static bool CalendarProjectIntervalsOverlap(
            DateTime firstStart,
            DateTime firstEnd,
            DateTime secondStart,
            DateTime secondEnd)
        {
            return
                firstStart < secondEnd &&
                secondStart < firstEnd;
        }

        private void ApplyCalendarProjectScheduleLocally(
            NotionCalendarActivity activity,
            DateTime start,
            DateTime end,
            string? datePropertyName = null)
        {
            if (activity == null)
                return;

            activity.Start = start;
            activity.End = end;

            if (!string.IsNullOrWhiteSpace(datePropertyName))
            {
                activity.DatePropertyName =
                    datePropertyName;
            }

            void ApplyToList(
                IEnumerable<NotionCalendarActivity>? source)
            {
                if (source == null)
                    return;

                foreach (var local in
                         source.Where(item =>
                             item != null &&
                             string.Equals(
                                 item.PageId,
                                 activity.PageId,
                                 StringComparison.OrdinalIgnoreCase)))
                {
                    local.Start = start;
                    local.End = end;

                    if (!string.IsNullOrWhiteSpace(
                            datePropertyName))
                    {
                        local.DatePropertyName =
                            datePropertyName;
                    }
                }
            }

            ApplyToList(
                _calendarActivities);

            ApplyToList(
                _calendarActivityPreviewLastProjectActivities);

            ApplyToList(
                _calendarProjectPreviewActivities);
        }

        private async Task<bool> ReorderCalendarProjectActivitiesAsync(
            IReadOnlyList<NotionCalendarActivity> projectActivities,
            string draggedPageId,
            NotionCalendarActivity targetActivity,
            bool insertAfter,
            CalendarProjectGroupCriteria criteria)
        {
            if (!_calendarActivityPreviewPinned)
            {
                StatusText.Text =
                    "Estado: Fija primero la checklist con clic para reordenar actividades.";
                return false;
            }

            var dragged =
                (projectActivities ??
                 Array.Empty<NotionCalendarActivity>())
                    .FirstOrDefault(activity =>
                        string.Equals(
                            activity.PageId,
                            draggedPageId,
                            StringComparison.OrdinalIgnoreCase));

            if (dragged == null ||
                targetActivity == null ||
                string.Equals(
                    dragged.PageId,
                    targetActivity.PageId,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            if (!CanCurrentUserReorderCalendarActivity(
                    dragged))
            {
                StatusText.Text =
                    GetCalendarReorderAccessMessage(
                        dragged);
                return false;
            }

            if (!CanCurrentUserReorderCalendarActivity(
                    targetActivity))
            {
                StatusText.Text =
                    GetCalendarReorderAccessMessage(
                        targetActivity);
                return false;
            }

            var draggedPhase =
                GetCalendarProjectPhaseInfo(
                    dragged)?.Token ??
                string.Empty;

            var targetPhase =
                GetCalendarProjectPhaseInfo(
                    targetActivity)?.Token ??
                string.Empty;

            var currentUser =
                GetCurrentCalendarUserName();

            // Coordinadores operan sobre el calendario del responsable de la
            // actividad, no sobre su propio nombre. Usuarios normales siguen
            // trabajando únicamente dentro de su calendario personal.
            var draggedPerson =
                CanCurrentUserReorderAnyCalendarActivity()
                    ? GetCalendarProjectPrimaryPerson(dragged)
                    : currentUser;

            if (string.IsNullOrWhiteSpace(draggedPerson) ||
                string.Equals(
                    draggedPerson,
                    "Sin asignar",
                    StringComparison.OrdinalIgnoreCase))
            {
                StatusText.Text =
                    "Estado: No se pudo identificar el responsable del bloque a reordenar.";
                return false;
            }

            if (dragged.Start.Date !=
                targetActivity.Start.Date)
            {
                StatusText.Text =
                    "Estado: Solo puedes reordenar actividades del mismo día.";
                return false;
            }

            // Origen y destino SIEMPRE deben pertenecer al mismo calendario
            // de persona. John/Genaro/Isaias pueden operar calendarios ajenos,
            // pero tampoco mezclan responsables dentro de un mismo reorder.
            if (!IsCalendarActivityAssignedToPerson(
                    dragged,
                    draggedPerson) ||
                !IsCalendarActivityAssignedToPerson(
                    targetActivity,
                    draggedPerson))
            {
                StatusText.Text =
                    CanCurrentUserReorderAnyCalendarActivity()
                        ? $"Estado: Para reordenar deben pertenecer al mismo calendario · {draggedPerson}."
                        : "Estado: Solo puedes reordenar actividades asignadas a tu usuario.";
                return false;
            }

            // Como la UI está agrupada por estado, cruzar estados no tendría
            // una posición visual estable. El orden se modifica dentro del
            // mismo estado + día + persona.
            if (!string.Equals(
                    draggedPhase,
                    targetPhase,
                    StringComparison.OrdinalIgnoreCase))
            {
                StatusText.Text =
                    "Estado: Solo puedes reordenar actividades dentro del mismo estado.";
                return false;
            }

            var day =
                dragged.Start.Date;

            var cohort =
                (projectActivities ??
                 Array.Empty<NotionCalendarActivity>())
                    .Where(activity =>
                        activity != null &&
                        !activity.IsReviewMirror &&
                        activity.Start.Date == day &&
                        IsCalendarActivityAssignedToPerson(
                            activity,
                            draggedPerson) &&
                        string.Equals(
                            GetCalendarProjectPhaseInfo(activity)?.Token ??
                            string.Empty,
                            draggedPhase,
                            StringComparison.OrdinalIgnoreCase))
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .OrderBy(activity => activity.Start)
                    .ThenBy(activity => activity.Title)
                    .ToList();

            if (cohort.Count < 2)
                return false;

            if (cohort.Any(activity =>
                    activity.IsAutomationLocked))
            {
                StatusText.Text =
                    "Estado: Hay una actividad bloqueada en este bloque. " +
                    "Desbloquéala antes de reordenar.";
                return false;
            }

            var originalOrder =
                cohort
                    .Select(activity => activity.PageId)
                    .ToList();

            var reordered =
                cohort.ToList();

            reordered.RemoveAll(activity =>
                string.Equals(
                    activity.PageId,
                    dragged.PageId,
                    StringComparison.OrdinalIgnoreCase));

            var targetIndex =
                reordered.FindIndex(activity =>
                    string.Equals(
                        activity.PageId,
                        targetActivity.PageId,
                        StringComparison.OrdinalIgnoreCase));

            if (targetIndex < 0)
                return false;

            if (insertAfter)
                targetIndex++;

            targetIndex =
                Math.Clamp(
                    targetIndex,
                    0,
                    reordered.Count);

            reordered.Insert(
                targetIndex,
                dragged);

            var nextOrder =
                reordered
                    .Select(activity => activity.PageId)
                    .ToList();

            if (originalOrder.SequenceEqual(
                    nextOrder,
                    StringComparer.OrdinalIgnoreCase))
            {
                StatusText.Text =
                    "Estado: La actividad ya está en esa posición.";
                return false;
            }

            // La primera hora del bloque se conserva como ancla.
            // Solo cambia el orden; cada actividad conserva su duración.
            var cursor =
                cohort
                    .Min(activity => activity.Start);

            var plans =
                new List<CalendarProjectSchedulePlan>();

            foreach (var activity in reordered)
            {
                var duration =
                    activity.End > activity.Start
                        ? activity.End - activity.Start
                        : TimeSpan.FromMinutes(15);

                if (duration <
                    TimeSpan.FromMinutes(15))
                {
                    duration =
                        TimeSpan.FromMinutes(15);
                }

                var newStart = cursor;
                var newEnd =
                    newStart.Add(duration);

                // El reordenamiento solicitado es dentro del mismo día.
                // No dejamos que una cadena salte a mañana por accidente.
                if (newStart.Date != day ||
                    newEnd.Date != day)
                {
                    StatusText.Text =
                        "Estado: El bloque completo no cabe dentro del mismo día. " +
                        "No se aplicaron cambios.";
                    return false;
                }

                plans.Add(
                    new CalendarProjectSchedulePlan(
                        activity,
                        newStart,
                        newEnd));

                cursor = newEnd;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return false;
            }

            try
            {
                // Verificar colisiones sin descargar otra vez el día visible.
                using var conflictCts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(2));

                IReadOnlyList<NotionCalendarActivity>? dayActivities =
                    null;

                if (day == _calendarSelectedDate.Date &&
                    _calendarActivities.Count > 0)
                {
                    dayActivities =
                        _calendarActivities;
                }
                else
                {
                    dayActivities =
                        await _notionCalendarService
                            .TryGetCachedDayAsync(
                                day,
                                conflictCts.Token);

                    dayActivities ??=
                        await _notionCalendarService
                            .GetDayAsync(
                                token,
                                day,
                                progress: null,
                                cancellationToken:
                                    conflictCts.Token,
                                forceRefresh: false);
                }

                var cohortIds =
                    new HashSet<string>(
                        cohort.Select(activity =>
                            activity.PageId),
                        StringComparer.OrdinalIgnoreCase);

                var external =
                    dayActivities
                        .Where(activity =>
                            activity != null &&
                            !activity.IsReviewMirror &&
                            !cohortIds.Contains(
                                activity.PageId) &&
                            IsCalendarActivityAssignedToPerson(
                                activity,
                                draggedPerson))
                        .ToList();

                foreach (var plan in plans)
                {
                    var collision =
                        external.FirstOrDefault(other =>
                            CalendarProjectIntervalsOverlap(
                                plan.NewStart,
                                plan.NewEnd,
                                other.Start,
                                other.End));

                    if (collision != null)
                    {
                        StatusText.Text =
                            $"Estado: No se puede reordenar porque el nuevo horario " +
                            $"se cruza con otra actividad de {draggedPerson}: " +
                            $"{collision.Start:HH:mm}–{collision.End:HH:mm} · " +
                            $"{collision.Title}";
                        return false;
                    }
                }
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: No se pudo verificar superposiciones a tiempo. " +
                    "No se aplicaron cambios.";
                return false;
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo verificar el horario del día → {ex.Message}";
                return false;
            }

            var snapshots =
                cohort.ToDictionary(
                    activity => activity.PageId,
                    activity =>
                        new CalendarProjectScheduleSnapshot(
                            activity.PageId,
                            activity.Start,
                            activity.End,
                            activity.DatePropertyName ??
                            string.Empty),
                    StringComparer.OrdinalIgnoreCase);

            var applied =
                new List<NotionCalendarActivity>();

            // Feedback local inmediato.
            foreach (var plan in plans)
            {
                ApplyCalendarProjectScheduleLocally(
                    plan.Activity,
                    plan.NewStart,
                    plan.NewEnd,
                    plan.Activity.DatePropertyName);
            }

            SaveCalendarProjectActivitiesToMemory(
                criteria,
                projectActivities);

            if (_calendarActivityPreviewPopup?.IsOpen == true &&
                _calendarActivityPreviewHost != null)
            {
                UpdateCalendarActivityPreviewContent(
                    BuildCalendarProjectHoverChecklist(
                        dragged,
                        criteria,
                        projectActivities));
            }

            try
            {
                ShowLoadingState(
                    "Estado: Reordenando actividades…",
                    $"{draggedPerson} · {day:dd/MM/yyyy}");

                using var updateCts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(5));

                var changedPlans =
                    plans
                        .Where(plan =>
                            snapshots.TryGetValue(
                                plan.Activity.PageId,
                                out var original) &&
                            (original.Start != plan.NewStart ||
                             original.End != plan.NewEnd))
                        .ToList();

                for (var index = 0;
                     index < changedPlans.Count;
                     index++)
                {
                    updateCts.Token.ThrowIfCancellationRequested();

                    var plan =
                        changedPlans[index];

                    UpdateLoadingState(
                        "Estado: Reordenando actividades…",
                        $"{index + 1}/{changedPlans.Count} · " +
                        $"{plan.NewStart:HH:mm}–{plan.NewEnd:HH:mm} · " +
                        plan.Activity.Title);

                    var result =
                        await _notionCalendarService
                            .UpdateActivityScheduleWithAuditAsync(
                                token,
                                plan.Activity,
                                plan.NewStart,
                                plan.NewEnd,
                                $"ANFETA · checklist proyecto · reordenar · " +
                                $"posición {index + 1}/{changedPlans.Count} · " +
                                $"{DateTime.Now:yyyy-MM-dd HH:mm}",
                                updateCts.Token);

                    ApplyCalendarProjectScheduleLocally(
                        plan.Activity,
                        result.Activity.Start,
                        result.Activity.End,
                        result.Activity.DatePropertyName);

                    applied.Add(
                        plan.Activity);
                }

                SaveCalendarProjectActivitiesToMemory(
                    criteria,
                    projectActivities);

                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);

                if (_calendarActivityPreviewPopup?.IsOpen == true &&
                    _calendarActivityPreviewHost != null)
                {
                    UpdateCalendarActivityPreviewContent(
                        BuildCalendarProjectHoverChecklist(
                            dragged,
                            criteria,
                            projectActivities));
                }

                StatusText.Text =
                    $"Estado: Orden actualizado ✅ · " +
                    $"{reordered.Count} actividad(es) · " +
                    $"{reordered.First().Start:HH:mm}–{reordered.Last().End:HH:mm}";

                return true;
            }
            catch (Exception ex)
            {
                // Rollback únicamente de las páginas que ya alcanzaron a
                // guardarse correctamente antes del fallo.
                var rollbackFailures =
                    new List<string>();

                try
                {
                    using var rollbackCts =
                        new CancellationTokenSource(
                            TimeSpan.FromMinutes(5));

                    foreach (var activity in
                             applied.AsEnumerable().Reverse())
                    {
                        if (!snapshots.TryGetValue(
                                activity.PageId,
                                out var snapshot))
                        {
                            continue;
                        }

                        try
                        {
                            var rollback =
                                await _notionCalendarService
                                    .UpdateActivityScheduleWithAuditAsync(
                                        token,
                                        activity,
                                        snapshot.Start,
                                        snapshot.End,
                                        $"ANFETA · rollback reordenamiento · " +
                                        $"{DateTime.Now:yyyy-MM-dd HH:mm}",
                                        rollbackCts.Token);

                            ApplyCalendarProjectScheduleLocally(
                                activity,
                                rollback.Activity.Start,
                                rollback.Activity.End,
                                rollback.Activity.DatePropertyName);
                        }
                        catch
                        {
                            rollbackFailures.Add(
                                activity.Title);
                        }
                    }
                }
                catch
                {
                    // Se reporta abajo como rollback incompleto.
                }

                foreach (var item in snapshots)
                {
                    var activity =
                        projectActivities.FirstOrDefault(candidate =>
                            string.Equals(
                                candidate.PageId,
                                item.Key,
                                StringComparison.OrdinalIgnoreCase));

                    if (activity == null)
                        continue;

                    ApplyCalendarProjectScheduleLocally(
                        activity,
                        item.Value.Start,
                        item.Value.End,
                        item.Value.DatePropertyName);
                }

                SaveCalendarProjectActivitiesToMemory(
                    criteria,
                    projectActivities);

                try
                {
                    DrawCalendarPreservingView(
                        _calendarActivities,
                        force: true);

                    if (_calendarActivityPreviewPopup?.IsOpen == true &&
                        _calendarActivityPreviewHost != null)
                    {
                        UpdateCalendarActivityPreviewContent(
                            BuildCalendarProjectHoverChecklist(
                                dragged,
                                criteria,
                                projectActivities));
                    }
                }
                catch
                {
                }

                StatusText.Text =
                    rollbackFailures.Count == 0
                        ? $"Estado: Falló el reordenamiento y se revirtieron " +
                          $"los cambios aplicados → {ex.Message}"
                        : $"Estado: Falló el reordenamiento y el rollback quedó " +
                          $"incompleto ({rollbackFailures.Count}) → {ex.Message}";

                return false;
            }
            finally
            {
                HideLoadingState();
            }
        }

        private Button BuildCalendarProjectMiniActionButton(
            string content,
            string tooltip,
            NotionCalendarActivity activity,
            double width = 28)
        {
            var button =
                new Button
                {
                    Content = content,
                    Width = width,
                    Height = 24,
                    Margin =
                        new Thickness(
                            0, 0, 3, 0),
                    Padding =
                        new Thickness(0),
                    CornerRadius =
                        new CornerRadius(5),
                    HorizontalContentAlignment =
                        HorizontalAlignment.Center,
                    VerticalContentAlignment =
                        VerticalAlignment.Center,
                    FontSize = 9.5,
                    Tag = activity,
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                22,
                                255,
                                255,
                                255)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                50,
                                255,
                                255,
                                255)),
                    BorderThickness =
                        new Thickness(1)
                };

            ToolTipService.SetToolTip(
                button,
                tooltip);

            return button;
        }

        private Dictionary<string, CalendarProjectViewMapping>
            GetCalendarProjectViewMappings()
        {
            if (_calendarProjectViewMappings != null)
                return _calendarProjectViewMappings;

            _calendarProjectViewMappings =
                new Dictionary<string, CalendarProjectViewMapping>(
                    StringComparer.OrdinalIgnoreCase);

            try
            {
                var raw =
                    ApplicationData.Current.LocalSettings.Values[
                        LS_CalendarProjectViewMappings] as string;

                if (string.IsNullOrWhiteSpace(raw))
                    return _calendarProjectViewMappings;

                var parsed =
                    JsonSerializer.Deserialize<
                        Dictionary<
                            string,
                            CalendarProjectViewMapping>>(
                        raw);

                if (parsed != null)
                {
                    _calendarProjectViewMappings =
                        new Dictionary<
                            string,
                            CalendarProjectViewMapping>(
                            parsed,
                            StringComparer.OrdinalIgnoreCase);
                }
            }
            catch
            {
                // Un mapping antiguo/corrupto no debe romper el calendario.
                _calendarProjectViewMappings =
                    new Dictionary<
                        string,
                        CalendarProjectViewMapping>(
                        StringComparer.OrdinalIgnoreCase);
            }

            return _calendarProjectViewMappings;
        }

        private void SaveCalendarProjectViewMappings()
        {
            try
            {
                var mappings =
                    GetCalendarProjectViewMappings();

                ApplicationData.Current.LocalSettings.Values[
                    LS_CalendarProjectViewMappings] =
                    JsonSerializer.Serialize(
                        mappings);
            }
            catch
            {
                // La selección sigue siendo utilizable durante la sesión.
            }
        }

        private static string GetCalendarProjectViewMappingKey(
            CalendarProjectGroupCriteria criteria)
        {
            // La vista principal de Notion corresponde al DOMINIO completo.
            // No depende del tipo (SEO/ADS/WEB) ni del mes.
            return
                NormalizeCalendarProjectDomain(
                    criteria.Domain);
        }

        private static bool IsExactCalendarProjectDomainView(
            NotionProjectViewInfo view,
            CalendarProjectGroupCriteria criteria)
        {
            var domain =
                NormalizeCalendarProjectDomain(
                    criteria.Domain);

            var viewName =
                NormalizeCalendarProjectDomain(
                    view?.Name ??
                    string.Empty);

            return
                !string.IsNullOrWhiteSpace(domain) &&
                string.Equals(
                    viewName,
                    domain,
                    StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsNearCalendarProjectDomainView(
            NotionProjectViewInfo view,
            CalendarProjectGroupCriteria criteria)
        {
            var domain =
                NormalizeCalendarProjectDomain(
                    criteria.Domain);

            if (string.IsNullOrWhiteSpace(domain))
                return false;

            var domainBase =
                domain
                    .Split(
                        '.',
                        StringSplitOptions.RemoveEmptyEntries)
                    .FirstOrDefault() ??
                domain;

            var name =
                (view?.Name ??
                 string.Empty)
                    .Trim()
                    .ToLowerInvariant();

            return
                name.Contains(
                    domain,
                    StringComparison.OrdinalIgnoreCase) ||
                (domainBase.Length >= 4 &&
                 name.Contains(
                     domainBase,
                     StringComparison.OrdinalIgnoreCase));
        }

        private static string NormalizeCalendarProjectViewText(
            string value)
        {
            return Regex.Replace(
                    (value ?? string.Empty)
                        .Trim()
                        .ToLowerInvariant(),
                    @"[\s_\-:/\\.?&=]+",
                    " ")
                .Trim();
        }

        private static int ScoreCalendarProjectNotionView(
            NotionProjectViewInfo view,
            CalendarProjectGroupCriteria criteria)
        {
            var domain =
                NormalizeCalendarProjectDomain(
                    criteria.Domain);

            var domainBase =
                domain
                    .Split(
                        '.',
                        StringSplitOptions.RemoveEmptyEntries)
                    .FirstOrDefault() ??
                domain;

            var projectToken =
                (criteria.ProjectType ??
                 string.Empty)
                    .Trim()
                    .ToLowerInvariant();

            var projectLabel =
                (criteria.ProjectLabel ??
                 string.Empty)
                    .Trim()
                    .ToLowerInvariant();

            var name =
                NormalizeCalendarProjectViewText(
                    view.Name);

            var filter =
                NormalizeCalendarProjectViewText(
                    view.FilterJson);

            var score = 0;

            if (!string.IsNullOrWhiteSpace(domain))
            {
                if (name.Contains(
                        domain,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 140;
                }

                if (filter.Contains(
                        domain,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 110;
                }
            }

            if (domainBase.Length >= 4)
            {
                if (name.Contains(
                        domainBase,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 70;
                }

                if (filter.Contains(
                        domainBase,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 45;
                }
            }

            if (!string.IsNullOrWhiteSpace(projectToken))
            {
                if (name.Contains(
                        projectToken,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 40;
                }

                if (filter.Contains(
                        projectToken,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 30;
                }
            }

            if (!string.IsNullOrWhiteSpace(projectLabel) &&
                projectLabel.Length >= 3)
            {
                if (name.Contains(
                        projectLabel,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 20;
                }

                if (filter.Contains(
                        projectLabel,
                        StringComparison.OrdinalIgnoreCase))
                {
                    score += 15;
                }
            }

            if (name.Contains(
                    "principal",
                    StringComparison.OrdinalIgnoreCase))
            {
                score += 25;
            }

            if (name.Contains(
                    "general",
                    StringComparison.OrdinalIgnoreCase))
            {
                score += 18;
            }

            if (name.Contains(
                    "actividad",
                    StringComparison.OrdinalIgnoreCase))
            {
                score += 12;
            }

            if (name.Contains(
                    "revision",
                    StringComparison.OrdinalIgnoreCase))
            {
                score += 6;
            }

            if (view.Type is "table" or "list" or "board")
                score += 2;

            return score;
        }

        private async Task OpenCalendarProjectNotionViewAsync(
            CalendarProjectGroupCriteria criteria,
            bool forceReselect = false)
        {
            if (criteria == null)
                return;

            var key =
                GetCalendarProjectViewMappingKey(
                    criteria);

            var mappings =
                GetCalendarProjectViewMappings();

            if (!forceReselect &&
                mappings.TryGetValue(
                    key,
                    out var saved) &&
                !string.IsNullOrWhiteSpace(
                    saved.ViewUrl))
            {
                await OpenNotionPageWithFallbackAsync(
                    saved.ViewUrl,
                    desktopSuccessStatus:
                        $"Vista del proyecto abierta · {saved.ViewName}",
                    browserSuccessStatus:
                        $"Vista del proyecto abierta en navegador · {saved.ViewName}",
                    failureStatus:
                        "No se pudo abrir la vista del proyecto",
                    invalidUrlStatus:
                        "La vista guardada del proyecto no tiene una URL válida");

                return;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return;
            }

            try
            {
                ShowLoadingState(
                    "Estado: Buscando vista del dominio en VS zPROYECTOS…",
                    criteria.Domain);

                // La búsqueda queda restringida al database/container REAL
                // del selector de vistas de VS zPROYECTOS. No se intenta leer
                // el PageId 37fab... como bloques porque esa página privada no
                // es el database que aparece en el enlace de cada vista.
                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(4));

                var progress =
                    new Progress<string>(
                        message =>
                        {
                            UpdateLoadingState(
                                "Estado: Buscando vista del dominio en VS zPROYECTOS…",
                                message);

                            StatusText.Text =
                                $"Estado: {message}";
                        });

                var selected =
                    await _notionProjectViewService
                        .FindExactViewByDatabaseIdAsync(
                            token,
                            CalendarProjectsViewDatabaseId,
                            criteria.Domain,
                            cts.Token,
                            forceRefresh:
                                forceReselect,
                            progress:
                                progress);

                if (selected == null)
                {
                    StatusText.Text =
                        $"Estado: No se encontró la vista del dominio " +
                        $"{criteria.Domain} dentro de VS zPROYECTOS.";
                    return;
                }

                mappings[key] =
                    new CalendarProjectViewMapping
                    {
                        ViewId =
                            selected.Id,
                        ViewName =
                            selected.Name,
                        ViewUrl =
                            selected.Url,
                        ViewType =
                            selected.Type,
                        SavedAt =
                            DateTimeOffset.Now
                    };

                SaveCalendarProjectViewMappings();

                StatusText.Text =
                    $"Estado: Vista de proyecto encontrada ✅ · {selected.Name}";

                await OpenNotionPageWithFallbackAsync(
                    selected.Url,
                    desktopSuccessStatus:
                        $"Vista del proyecto abierta · {selected.Name}",
                    browserSuccessStatus:
                        $"Vista del proyecto abierta en navegador · {selected.Name}",
                    failureStatus:
                        "No se pudo abrir la vista del proyecto",
                    invalidUrlStatus:
                        "Notion no devolvió una URL válida para la vista encontrada");
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: La búsqueda de la vista del dominio fue cancelada o agotó el tiempo.";
            }
            catch (Exception ex)
            {
                StatusText.Text =
                    $"Estado: No se pudo resolver la vista del dominio → {ex.Message}";
            }
            finally
            {
                HideLoadingState();
            }
        }

        private async Task HighlightCalendarActivityFromChecklistAsync(
            NotionCalendarActivity activity)
        {
            if (activity == null ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                return;
            }

            var targetDate = activity.Start.Date;
            var targetPerson =
                GetCalendarProjectPrimaryPerson(
                    activity);

            // Resaltar significa encontrar la ubicación REAL de esa PageId.
            // Si está en otro día, ANFETA navega primero al día correcto.
            if (_calendarSelectedDate.Date != targetDate)
            {
                StatusText.Text =
                    $"Estado: 🎯 Abriendo {targetDate:dd/MM/yyyy} para localizar la actividad...";

                await NavigateCalendarToDateAsync(
                    targetDate);
            }

            // Si la persona estaba oculta por el filtro de Personas, se muestra
            // automáticamente para que el botón nunca termine en "no encontrada"
            // únicamente por una preferencia visual.
            if (!string.IsNullOrWhiteSpace(targetPerson) &&
                !string.Equals(
                    targetPerson,
                    "Sin asignar",
                    StringComparison.OrdinalIgnoreCase) &&
                !_calendarSelectedPeople.Contains(targetPerson))
            {
                _calendarSelectedPeople.Add(targetPerson);
                DrawCalendar(_calendarActivities);
            }

            // Un filtro de texto/fase puede ocultar la actividad que acabamos
            // de pedir. Solo se limpian si realmente impiden localizarla.
            if (!_calendarActivityVisuals.TryGetValue(
                    activity.PageId,
                    out var visuals) ||
                visuals.Count == 0)
            {
                _calendarSearchQuery = string.Empty;

                if (SearchBox != null)
                {
                    SearchBox.Text = string.Empty;
                    SearchBox.IsSuggestionListOpen = false;
                }

                _calendarPhaseFilter = string.Empty;

                if (CalendarPhaseFilterControl != null &&
                    CalendarPhaseFilterControl.Items.Count > 0)
                {
                    var allIndex = 0;

                    for (var index = 0;
                         index < CalendarPhaseFilterControl.Items.Count;
                         index++)
                    {
                        if (CalendarPhaseFilterControl.Items[index] is
                                ComboBoxItem item &&
                            string.IsNullOrWhiteSpace(
                                item.Tag?.ToString()))
                        {
                            allIndex = index;
                            break;
                        }
                    }

                    CalendarPhaseFilterControl.SelectedIndex = allIndex;
                }

                DrawCalendar(_calendarActivities);

                _calendarActivityVisuals.TryGetValue(
                    activity.PageId,
                    out visuals);
            }

            var visual =
                visuals?.FirstOrDefault();

            if (visual?.Button == null)
            {
                StatusText.Text =
                    $"Estado: No se pudo dibujar la actividad para {targetDate:dd/MM/yyyy}. " +
                    "Pulsa Actualizar y vuelve a intentar.";
                return;
            }

            var button = visual.Button;

            var left = Math.Max(
                0,
                Canvas.GetLeft(button));

            var top = Math.Max(
                0,
                Canvas.GetTop(button));

            var viewportWidth =
                Math.Max(
                    1,
                    CalendarScrollViewer?.ViewportWidth ??
                    CalendarHost.ActualWidth);

            var viewportHeight =
                Math.Max(
                    1,
                    CalendarScrollViewer?.ViewportHeight ??
                    CalendarHost.ActualHeight);

            var targetHorizontal =
                Math.Max(
                    0,
                    left - viewportWidth * 0.28);

            var targetVertical =
                Math.Max(
                    0,
                    top - CalendarHeaderHeight -
                    viewportHeight * 0.22);

            CalendarScrollViewer?.ChangeView(
                targetHorizontal,
                targetVertical,
                null,
                disableAnimation: false);

            // En empalmes deja esta tarjeta arriba para que el usuario sepa
            // exactamente cuál de 1/3, 2/3, etc. fue localizada.
            if (_calendarPinnedOverlapActivityButton != null &&
                !ReferenceEquals(
                    _calendarPinnedOverlapActivityButton,
                    button) &&
                _calendarActivityBaseZIndexes.TryGetValue(
                    _calendarPinnedOverlapActivityButton,
                    out var previousPinnedZ))
            {
                Canvas.SetZIndex(
                    _calendarPinnedOverlapActivityButton,
                    previousPinnedZ);
            }

            _calendarPinnedOverlapActivityButton = button;

            var previousBorderBrush = button.BorderBrush;
            var previousBorderThickness = button.BorderThickness;
            var previousZ = Canvas.GetZIndex(button);

            button.BorderBrush =
                new SolidColorBrush(
                    Color.FromArgb(
                        255,
                        34,
                        211,
                        238));

            button.BorderThickness =
                new Thickness(5, 2, 2, 2);

            Canvas.SetZIndex(
                button,
                2200);

            button.Focus(
                FocusState.Programmatic);

            // Reubica la checklist al lado de la actividad localizada cuando
            // hay espacio. Así el modal fijado no tapa justo lo que queremos ver.
            _calendarHoveredActivityButton = button;
            PositionCalendarActivityPreviewPopup(button);

            var orderedTitle =
                GetCalendarOrderedCompactActivityTitle(
                    activity);

            StatusText.Text =
                $"Estado: 🎯 {orderedTitle} · {targetPerson} · " +
                $"{activity.Start:HH:mm}–{activity.End:HH:mm} resaltada ✅";

            try
            {
                // El pulso dura suficiente para localizarla incluso después
                // del scroll animado y sin obligar a cerrar la checklist.
                await Task.Delay(
                    TimeSpan.FromSeconds(4));
            }
            catch
            {
            }

            if (CalendarCanvas?.Children.Contains(button) == true)
            {
                button.BorderBrush = previousBorderBrush;
                button.BorderThickness = previousBorderThickness;

                Canvas.SetZIndex(
                    button,
                    ReferenceEquals(
                        _calendarPinnedOverlapActivityButton,
                        button)
                        ? 1400
                        : previousZ);
            }
        }

        private FrameworkElement
            BuildCalendarProjectHoverChecklist(
                NotionCalendarActivity hoveredActivity,
                CalendarProjectGroupCriteria criteria,
                IReadOnlyList<NotionCalendarActivity> activities)
        {
            var unique =
                (activities ??
                 Array.Empty<NotionCalendarActivity>())
                    .Where(activity =>
                        activity != null &&
                        !activity.IsReviewMirror &&
                        !string.IsNullOrWhiteSpace(
                            activity.PageId))
                    .GroupBy(
                        activity => activity.PageId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();

            // Guarda el proyecto ya resuelto por el hover.
            // Al hacer clic se reutiliza para reconstruir la MISMA
            // checklist en modo fijado con el detalle completo arriba.
            _calendarActivityPreviewLastCriteria =
                criteria;

            _calendarActivityPreviewLastProjectActivities =
                unique;

            _calendarActivityPreviewLastSelectedPageId =
                hoveredActivity.PageId ?? string.Empty;

            var projectChecklist =
                GetCalendarProjectChecklistStats(
                    unique);

            var percentage =
                GetChecklistPercentage(
                    projectChecklist);

            var scannedActivities =
                unique.Count(activity =>
                    activity.ChecklistScanned);

            var allChecklistScanned =
                unique.Count == 0 ||
                scannedActivities >= unique.Count;

            var percentageLabel =
                projectChecklist.Total > 0
                    ? $"{percentage}%"
                    : allChecklistScanned
                        ? "0%"
                        : "…";

            var totalMinutes =
                GetCalendarProjectTotalMinutes(
                    unique);

            var root =
                new StackPanel
                {
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch,
                    Spacing = 8,
                    Padding =
                        new Thickness(12)
                };

            // Hover conserva la información de consulta.
