            var listRoot =
                new StackPanel
                {
                    Spacing = 6,
                    Margin =
                        new Thickness(
                            0, 3, 0, 0),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            FrameworkElement BuildActivitiesHeader(
                bool includeCount)
            {
                var header =
                    new Grid
                    {
                        ColumnSpacing = 8,
                        Margin =
                            new Thickness(
                                0, 1, 0, 2),
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch
                    };

                header.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            new GridLength(
                                1,
                                GridUnitType.Star)
                    });

                header.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                if (includeCount)
                {
                    header.ColumnDefinitions.Add(
                        new ColumnDefinition
                        {
                            Width = GridLength.Auto
                        });
                }

                var title =
                    new TextBlock
                    {
                        Text = "ACTIVIDADES DEL PROYECTO",
                        FontSize = 10.5,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.Bold,
                        Foreground =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    255,
                                    125,
                                    211,
                                    252)),
                        CharacterSpacing = 30,
                        VerticalAlignment =
                            VerticalAlignment.Center
                    };

                Grid.SetColumn(
                    title,
                    0);

                header.Children.Add(
                    title);

                var scope =
                    BuildProjectScopeButton();

                Grid.SetColumn(
                    scope,
                    1);

                header.Children.Add(
                    scope);

                if (includeCount)
                {
                    var count =
                        new Border
                        {
                            Padding =
                                new Thickness(
                                    8, 3, 8, 3),
                            CornerRadius =
                                new CornerRadius(10),
                            Background =
                                new SolidColorBrush(
                                    Color.FromArgb(
                                        38,
                                        255,
                                        255,
                                        255)),
                            Child =
                                new TextBlock
                                {
                                    Text =
                                        unique.Count.ToString(
                                            CultureInfo.InvariantCulture),
                                    FontSize = 10,
                                    FontWeight =
                                        Microsoft.UI.Text.FontWeights.Bold
                                }
                        };

                    Grid.SetColumn(
                        count,
                        2);

                    header.Children.Add(
                        count);
                }

                return header;
            }

            var phaseGroups =
                unique
                    .Select(activity =>
                        new
                        {
                            Activity = activity,
                            Phase =
                                GetCalendarProjectPhaseInfo(
                                    activity)
                        })
                    .Where(item =>
                        item.Phase != null)
                    .GroupBy(item =>
                        item.Phase!.Token,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group =>
                        new
                        {
                            Phase =
                                group.First().Phase!,
                            Activities =
                                group
                                    .Select(item =>
                                        item.Activity)
                                    .OrderBy(GetCalendarProjectOrderPresenceKey)
                                    .ThenBy(GetCalendarProjectOrderMajorKey)
                                    .ThenBy(GetCalendarProjectOrderMinorKey)
                                    .ThenBy(activity =>
                                        activity.Start)
                                    .ThenBy(activity =>
                                        activity.Title)
                                    .ToList()
                        })
                    .OrderBy(group =>
                        group.Phase.Order)
                    .ToList();

            var hoveredPhase =
                GetCalendarProjectPhaseInfo(
                    hoveredActivity)?.Token ??
                string.Empty;

            foreach (var phaseGroup in phaseGroups)
            {
                var phaseContent =
                    new StackPanel
                    {
                        // Las actividades se leen como una secuencia continua,
                        // no como tarjetas separadas.
                        Spacing = 1,
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch
                    };

                var phaseHasNumberedActivities =
                    phaseGroup.Activities.Any(activity =>
                        TryGetCalendarProjectOrderNumber(
                            activity,
                            out _));

                // Si el plan trae 1.00 / 2.03 / etc. se construye UNA sola
                // secuencia para toda la fase, aunque las actividades estén en
                // días distintos. La fecha sigue visible dentro de cada renglón.
                // Sin numeración se conserva la agrupación histórica por día.
                var dayGroups =
                    phaseHasNumberedActivities
                        ? phaseGroup.Activities
                            .GroupBy(_ => DateTime.MinValue)
                        : phaseGroup.Activities
                            .GroupBy(activity =>
                                activity.Start.Date);

                IEnumerable<IGrouping<DateTime, NotionCalendarActivity>>
                    orderedDayGroups;

                if (phaseHasNumberedActivities)
                {
                    orderedDayGroups = dayGroups;
                }
                else
                {
                    orderedDayGroups =
                        string.Equals(
                            phaseGroup.Phase.Token,
                            "zREVISION",
                            StringComparison.OrdinalIgnoreCase)
                            ? dayGroups.OrderByDescending(
                                group => group.Key)
                            : dayGroups.OrderBy(
                                group => group.Key);
                }

                foreach (var dayGroup in orderedDayGroups)
                {
                    if (!phaseHasNumberedActivities)
                    {
                        phaseContent.Children.Add(
                            new TextBlock
                            {
                                Text =
                                    FormatCalendarProjectDayHeader(
                                        dayGroup.Key),
                                Margin =
                                    new Thickness(
                                        3, 3, 0, 1),
                                FontSize = 10,
                                FontWeight =
                                    Microsoft.UI.Text.FontWeights.SemiBold,
                                Opacity = 0.72
                            });
                    }

                    // Cuando el título trae 1.0 / 2.03 / 5.01, ese orden
                    // manda dentro del día. Las páginas antiguas sin número
                    // conservan el criterio de fecha/hora que ya funcionaba.
                    var numberedFirst =
                        dayGroup
                            .OrderBy(GetCalendarProjectOrderPresenceKey)
                            .ThenBy(GetCalendarProjectOrderMajorKey)
                            .ThenBy(GetCalendarProjectOrderMinorKey);

                    var orderedActivities =
                        string.Equals(
                            phaseGroup.Phase.Token,
                            "zREVISION",
                            StringComparison.OrdinalIgnoreCase)
                            ? numberedFirst
                                .ThenByDescending(item =>
                                    item.Start)
                                .ThenBy(item =>
                                    item.Title)
                            : numberedFirst
                                .ThenBy(item =>
                                    item.Start)
                                .ThenBy(item =>
                                    item.Title);

                    foreach (var activity in
                             orderedActivities)
                    {
                        var isCurrent =
                            string.Equals(
                                activity.PageId,
                                hoveredActivity.PageId,
                                StringComparison.OrdinalIgnoreCase);

                        var row =
                            new Grid
                            {
                                ColumnSpacing = 6,
                                HorizontalAlignment =
                                    HorizontalAlignment.Stretch
                            };

                        row.ColumnDefinitions.Add(
                            new ColumnDefinition
                            {
                                Width = GridLength.Auto
                            });

                        row.ColumnDefinitions.Add(
                            new ColumnDefinition
                            {
                                Width =
                                    new GridLength(
                                        1,
                                        GridUnitType.Star)
                            });

                        row.ColumnDefinitions.Add(
                            new ColumnDefinition
                            {
                                Width = GridLength.Auto
                            });

                        var checks =
                            new StackPanel
                            {
                                Orientation =
                                    Orientation.Horizontal,
                                Spacing = 2,
                                VerticalAlignment =
                                    VerticalAlignment.Top
                            };

                        var reviewDone =
                            HasExactCalendarPhase(
                                activity,
                                "rtuzREVISION") ||
                            HasExactCalendarPhase(
                                activity,
                                "zREVISION");

                        var finishDone =
                            HasExactCalendarPhase(
                                activity,
                                "zREVISION");

                        var reviewButton =
                            BuildCalendarProjectMiniActionButton(
                                reviewDone
                                    ? "R✓"
                                    : "R",
                                reviewDone
                                    ? "R = La actividad ya pasó a revisión."
                                    : "R = Pasar actividad a rtuzREVISION.",
                                activity,
                                width: 30);

                        reviewButton.Foreground =
                            new SolidColorBrush(
                                reviewDone
                                    ? Color.FromArgb(
                                        255,
                                        134,
                                        239,
                                        172)
                                    : phaseGroup.Phase.Accent);

                        reviewButton.IsEnabled =
                            !reviewDone &&
                            CanSendCalendarActivityToReview(
                                activity);

                        reviewButton.Click +=
                            async (_, __) =>
                            {
                                var changed =
                                    await PromptAndSendCalendarActivityToReviewAsync(
                                        activity);

                                if (!changed)
                                    return;

                                await RefreshCalendarDayAfterProjectActionAsync();

                                await RefreshPinnedCalendarProjectChecklistAsync(
                                    activity,
                                    criteria,
                                    hoveredActivity.PageId);
                            };

                        var finishButton =
                            BuildCalendarProjectMiniActionButton(
                                finishDone
                                    ? "F✓"
                                    : "F",
                                finishDone
                                    ? "F = La actividad ya está terminada."
                                    : "F = Terminar actividad y pasarla a zREVISION.",
                                activity,
                                width: 30);

                        finishButton.Foreground =
                            new SolidColorBrush(
                                finishDone
                                    ? Color.FromArgb(
                                        255,
                                        134,
                                        239,
                                        172)
                                    : phaseGroup.Phase.Accent);

                        finishButton.IsEnabled =
                            !finishDone &&
                            !activity.IsReviewMirror;

                        finishButton.Click +=
                            async (_, __) =>
                            {
                                var changed =
                                    await CompleteCalendarProjectActivityAsync(
                                        activity);

                                if (!changed)
                                    return;

                                await RefreshCalendarDayAfterProjectActionAsync();

                                await RefreshPinnedCalendarProjectChecklistAsync(
                                    activity,
                                    criteria,
                                    hoveredActivity.PageId);
                            };

                        checks.Children.Add(
                            reviewButton);

                        checks.Children.Add(
                            finishButton);

                        // Columna izquierda = secuencia. El número del plan
                        // queda fijo para comparar 1.00 → 1.10 → 2.03 de un vistazo.
                        var orderLabel =
                            TryGetCalendarProjectOrderNumber(
                                activity,
                                out var activityOrder)
                                ? activityOrder.Label
                                : "—";

                        var leftInfo =
                            new StackPanel
                            {
                                Spacing = 2,
                                MinWidth = 54,
                                VerticalAlignment =
                                    VerticalAlignment.Top
                            };

                        leftInfo.Children.Add(
                            new Border
                            {
                                MinWidth = 44,
                                Height = 22,
                                Padding =
                                    new Thickness(
                                        5, 0, 5, 0),
                                CornerRadius =
                                    new CornerRadius(6),
                                HorizontalAlignment =
                                    HorizontalAlignment.Center,
                                Background =
                                    new SolidColorBrush(
                                        Color.FromArgb(
                                            30,
                                            56,
                                            189,
                                            248)),
                                Child =
                                    new TextBlock
                                    {
                                        Text = orderLabel,
                                        FontSize = 9,
                                        FontWeight =
                                            Microsoft.UI.Text.FontWeights.Bold,
                                        HorizontalAlignment =
                                            HorizontalAlignment.Center,
                                        VerticalAlignment =
                                            VerticalAlignment.Center
                                    }
                            });

                        leftInfo.Children.Add(
                            new TextBlock
                            {
                                Text =
                                    $"{activity.Start:HH:mm}–{activity.End:HH:mm}",
                                FontSize = 8.6,
                                FontWeight =
                                    Microsoft.UI.Text.FontWeights.SemiBold,
                                Opacity = 0.72,
                                HorizontalAlignment =
                                    HorizontalAlignment.Center,
                                MaxLines = 1
                            });

                        leftInfo.Children.Add(
                            new TextBlock
                            {
                                Text =
                                    activity.EstimatedDurationLabel,
                                FontSize = 8.2,
                                Opacity = 0.60,
                                HorizontalAlignment =
                                    HorizontalAlignment.Center,
                                MaxLines = 1
                            });

                        Grid.SetColumn(
                            leftInfo,
                            0);

                        row.Children.Add(
                            leftInfo);

                        var textStack =
                            new StackPanel
                            {
                                Spacing = 1,
                                HorizontalAlignment =
                                    HorizontalAlignment.Stretch
                            };

                        // La lista interna del popup usa la misma limpieza que
                        // "Proyecto relacionado": 1.00/1.10/2.03 queda en su
                        // columna, y prtuz/rtuz + tipo + mes + dominio/persona
                        // dejan de competir visualmente con el nombre real.
                        var cleanProjectTitle =
                            GetCalendarProjectPreviewTitle(
                                activity,
                                out _);

                        var titleText =
                            new TextBlock
                            {
                                Text =
                                    string.IsNullOrWhiteSpace(cleanProjectTitle)
                                        ? "Actividad sin título"
                                        : cleanProjectTitle,
                                FontSize = 10.5,
                                FontWeight =
                                    isCurrent
                                        ? Microsoft.UI.Text.FontWeights.SemiBold
                                        : Microsoft.UI.Text.FontWeights.Normal,
                                Foreground =
                                    new SolidColorBrush(
                                        isCurrent
                                            ? Color.FromArgb(
                                                255,
                                                255,
                                                255,
                                                255)
                                            : Color.FromArgb(
                                                245,
                                                255,
                                                255,
                                                255)),
                                TextWrapping =
                                    TextWrapping.NoWrap,
                                MaxLines = 1,
                                TextTrimming =
                                    TextTrimming.CharacterEllipsis
                            };

                        // El título ORIGINAL sigue disponible al pasar el mouse;
                        // no se modifica nada en Notion.
                        ToolTipService.SetToolTip(
                            titleText,
                            activity.Title);

                        textStack.Children.Add(
                            titleText);

                        var person =
                            string.IsNullOrWhiteSpace(
                                activity.Person)
                                ? "Sin asignar"
                                : activity.Person;

                        var technicalPhase =
                            GetCalendarProjectPhaseInfo(activity)?.Token ??
                            string.Empty;

                        // Esto corresponde a la petición de John: la
                        // nomenclatura técnica (revisión / tipo / mes...) queda
                        // en un tono cercano al fondo para que la vista se lea
                        // como un listado limpio a simple vista.
                        textStack.Children.Add(
                            new TextBlock
                            {
                                Text =
                                    string.Join(
                                        " · ",
                                        new[]
                                        {
                                            technicalPhase,
                                            criteria.ProjectLabel,
                                            criteria.MonthTag,
                                            activity.Start.ToString(
                                                "dd/MM",
                                                CultureInfo.InvariantCulture),
                                            person
                                        }.Where(value =>
                                            !string.IsNullOrWhiteSpace(value))),
                                FontSize = 8.7,
                                Foreground =
                                    new SolidColorBrush(
                                        Color.FromArgb(
                                            255,
                                            255,
                                            255,
                                            255)),
                                // Sigue siendo secundaria por tamaño/opacidad,
                                // pero ya no se pierde contra tarjetas oscuras.
                                Opacity = 0.78,
                                TextWrapping =
                                    TextWrapping.NoWrap,
                                MaxLines = 1,
                                TextTrimming =
                                    TextTrimming.CharacterEllipsis
                            });

                        Grid.SetColumn(
                            textStack,
                            1);

                        row.Children.Add(
                            textStack);

                        var rowChecklistStats =
                            GetCalendarChecklistStats(
                                activity);

                        var rowChecklistText =
                            !activity.ChecklistScanned
                                ? "…"
                                : rowChecklistStats.HasChecklist
                                    ? $"{rowChecklistStats.Completed}/{rowChecklistStats.Total}"
                                    : "0/0";

                        var rowChecklistBadge =
                            new Border
                            {
                                MinWidth = 42,
                                Height = 22,
                                Margin =
                                    new Thickness(
                                        4, 0, 0, 0),
                                Padding =
                                    new Thickness(
                                        5, 0, 5, 0),
                                CornerRadius =
                                    new CornerRadius(8),
                                HorizontalAlignment =
                                    HorizontalAlignment.Right,
                                VerticalAlignment =
                                    VerticalAlignment.Top,
                                Background =
                                    new SolidColorBrush(
                                        !activity.ChecklistScanned
                                            ? Color.FromArgb(
                                                205,
                                                15,
                                                31,
                                                45)
                                            : rowChecklistStats.HasChecklist
                                                ? Color.FromArgb(
                                                    205,
                                                    11,
                                                    38,
                                                    31)
                                                : Color.FromArgb(
                                                    95,
                                                    51,
                                                    65,
                                                    85)),
                                BorderBrush =
                                    new SolidColorBrush(
                                        !activity.ChecklistScanned
                                            ? Color.FromArgb(
                                                255,
                                                125,
                                                211,
                                                252)
                                            : rowChecklistStats.HasChecklist
                                                ? Color.FromArgb(
                                                    255,
                                                    74,
                                                    222,
                                                    128)
                                                : Color.FromArgb(
                                                    150,
                                                    148,
                                                    163,
                                                    184)),
                                BorderThickness =
                                    new Thickness(1),
                                Child =
                                    new TextBlock
                                    {
                                        Text = rowChecklistText,
                                        FontSize = 9,
                                        FontWeight =
                                            Microsoft.UI.Text.FontWeights.Bold,
                                        Foreground =
                                            new SolidColorBrush(
                                                !activity.ChecklistScanned
                                                    ? Color.FromArgb(
                                                        255,
                                                        186,
                                                        230,
                                                        253)
                                                    : rowChecklistStats.HasChecklist
                                                        ? Color.FromArgb(
                                                            255,
                                                            134,
                                                            239,
                                                            172)
                                                        : Color.FromArgb(
                                                            220,
                                                            203,
                                                            213,
                                                            225)),
                                        HorizontalAlignment =
                                            HorizontalAlignment.Center,
                                        VerticalAlignment =
                                            VerticalAlignment.Center
                                    }
                            };

                        ToolTipService.SetToolTip(
                            rowChecklistBadge,
                            !activity.ChecklistScanned
                                ? "Checklist pendiente de precarga."
                                : rowChecklistStats.HasChecklist
                                    ? $"Checklist: {rowChecklistStats.Completed}/{rowChecklistStats.Total} · {GetChecklistPercentage(rowChecklistStats)}%"
                                    : "Checklist revisado · sin tareas activas.");

                        var rightInfo =
                            new StackPanel
                            {
                                Spacing = 3,
                                HorizontalAlignment =
                                    HorizontalAlignment.Right,
                                VerticalAlignment =
                                    VerticalAlignment.Top
                            };

                        rightInfo.Children.Add(
                            rowChecklistBadge);

                        checks.HorizontalAlignment =
                            HorizontalAlignment.Right;

                        rightInfo.Children.Add(
                            checks);

                        Grid.SetColumn(
                            rightInfo,
                            2);

                        row.Children.Add(
                            rightInfo);

                        // Body bajo demanda por actividad. Se mantiene fuera de
                        // la carga inicial: solo se consulta cuando el usuario
                        // lo despliega y reutiliza el cache de contenido si ya
                        // estaba disponible.
                        var activityContentHost =
                            new ContentControl
                            {
                                HorizontalContentAlignment =
                                    HorizontalAlignment.Stretch,
                                Visibility =
                                    Visibility.Collapsed,
                                Margin =
                                    new Thickness(
                                        0, 3, 0, 0)
                            };

                        var actionBar =
                            new StackPanel
                            {
                                Orientation =
                                    Orientation.Horizontal,
                                Spacing = 1,
                                Margin =
                                    new Thickness(
                                        0, 4, 0, 0),
                                Visibility =
                                    Visibility.Collapsed
                            };

                        var canCurrentUserDragActivity =
                            _calendarActivityPreviewPinned &&
                            CanCurrentUserReorderCalendarActivity(
                                activity);

                        var dragHandle =
                            new Border
                            {
                                Width = 28,
                                Height = 24,
                                Margin =
                                    new Thickness(
                                        0, 0, 3, 0),
                                CornerRadius =
                                    new CornerRadius(5),
                                Background =
                                    new SolidColorBrush(
                                        Color.FromArgb(
                                            30,
                                            56,
                                            189,
                                            248)),
                                BorderBrush =
                                    new SolidColorBrush(
                                        Color.FromArgb(
                                            80,
                                            56,
                                            189,
                                            248)),
                                BorderThickness =
                                    new Thickness(1),
                                Opacity =
                                    canCurrentUserDragActivity
                                        ? 1.0
                                        : 0.30,
                                CanDrag =
                                    canCurrentUserDragActivity,
                                Child =
                                    new TextBlock
                                    {
                                        Text = "↕",
                                        FontSize = 13,
                                        FontWeight =
                                            Microsoft.UI.Text.FontWeights.Bold,
                                        HorizontalAlignment =
                                            HorizontalAlignment.Center,
                                        VerticalAlignment =
                                            VerticalAlignment.Center
                                    }
                            };

                        ToolTipService.SetToolTip(
                            dragHandle,
                            !_calendarActivityPreviewPinned
                                ? "Haz clic en la tarjeta para fijar la checklist y poder reordenar."
                                : canCurrentUserDragActivity
                                    ? "Arrastra esta actividad sobre otra del mismo estado, día y persona."
                                    : GetCalendarReorderAccessMessage(
                                        activity)
                                        .Replace(
                                            "Estado: ",
                                            string.Empty));

                        dragHandle.DragStarting +=
                            (_, args) =>
                            {
                                if (!CanCurrentUserReorderCalendarActivity(
                                        activity))
                                {
                                    return;
                                }

                                args.Data.SetText(
                                    activity.PageId);

                                args.Data.RequestedOperation =
                                    Windows.ApplicationModel.DataTransfer
                                        .DataPackageOperation.Move;
                            };

                        var highlightButton =
                            BuildCalendarProjectMiniActionButton(
                                "🎯",
                                "Localizar y resaltar esta actividad en su día, persona y horario dentro del calendario.",
                                activity,
                                width: 32);

                        highlightButton.IsEnabled =
                            !activity.IsReviewMirror;

                        highlightButton.Click +=
                            async (_, __) =>
                            {
                                await HighlightCalendarActivityFromChecklistAsync(
                                    activity);
                            };

                        var dateButton =
                            BuildCalendarProjectMiniActionButton(
                                "📅",
                                "Cambiar Fecha POR Hacer conservando la hora y duración.",
                                activity);

                        dateButton.IsEnabled =
                            !activity.IsAutomationLocked &&
                            !activity.IsReviewMirror;

                        dateButton.Click +=
                            async (_, __) =>
                            {
                                var changed =
                                    await ChangeCalendarProjectActivityDateAsync(
                                        activity,
                                        criteria);

                                if (!changed)
                                    return;

                                await RefreshCalendarDayAfterProjectActionAsync();

                                await RefreshPinnedCalendarProjectChecklistAsync(
                                    activity,
                                    criteria,
                                    hoveredActivity.PageId);
                            };

                        var alarmButton =
                            BuildCalendarProjectMiniActionButton(
                                "🔔",
                                "Crear recordatorio/notificación ANFETA para esta actividad.",
                                activity);

                        alarmButton.IsEnabled =
                            !activity.IsReviewMirror;

                        alarmButton.Click +=
                            async (_, __) =>
                            {
                                // El popup fijado permanece abierto mientras
                                // se crea el recordatorio. La notificación usa
                                // el mismo sistema de Mensajes/Recordatorios.
                                await ShowCalendarActivityReminderDialogAsync(
                                    activity);
                            };

                        var notionButton =
                            BuildCalendarProjectMiniActionButton(
                                "N",
                                "Abrir esta actividad directamente en Notion.",
                                activity,
                                width: 32);

                        notionButton.Click +=
                            async (_, __) =>
                            {
                                await OpenCalendarActivityAsync(
                                    activity);
                            };

                        var contentButton =
                            BuildCalendarProjectMiniActionButton(
                                "▾",
                                "Ver u ocultar el contenido de esta actividad. El body se carga solo al abrirlo.",
                                activity,
                                width: 30);

                        contentButton.Click +=
                            async (_, __) =>
                            {
                                await ToggleCalendarPersonActivityContentAsync(
                                    activity,
                                    contentButton,
                                    activityContentHost,
                                    collapsedLabel: "▾",
                                    expandedLabel: "▴");
                            };

                        var minusButton =
                            BuildCalendarProjectMiniActionButton(
                                "−15",
                                "Reducir 15 minutos la duración asignada.",
                                activity,
                                width: 36);

                        minusButton.IsEnabled =
                            !activity.IsAutomationLocked &&
                            !activity.IsReviewMirror &&
                            activity.EstimatedDuration.TotalMinutes > 15;

                        minusButton.Click +=
                            async (_, __) =>
                            {
                                var changed =
                                    await AdjustCalendarProjectActivityDurationAsync(
                                        activity,
                                        -15,
                                        unique,
                                        criteria);

                                if (!changed)
                                    return;

                                await RefreshCalendarDayAfterProjectActionAsync();

                                await RefreshPinnedCalendarProjectChecklistAsync(
                                    activity,
                                    criteria,
                                    hoveredActivity.PageId);
                            };

                        var durationLabel =
                            new Border
                            {
                                MinWidth = 44,
                                Height = 24,
                                Margin =
                                    new Thickness(
                                        0, 0, 3, 0),
                                Padding =
                                    new Thickness(
                                        4, 0, 4, 0),
                                CornerRadius =
                                    new CornerRadius(5),
                                Background =
                                    new SolidColorBrush(
                                        Color.FromArgb(
                                            18,
                                            255,
                                            255,
                                            255)),
                                Child =
                                    new TextBlock
                                    {
                                        Text =
                                            FormatCalendarWorkMinutes(
                                                Math.Max(
                                                    15,
                                                    (int)Math.Round(
                                                        activity.EstimatedDuration.TotalMinutes))),
                                        FontSize = 9,
                                        FontWeight =
                                            Microsoft.UI.Text.FontWeights.SemiBold,
                                        VerticalAlignment =
                                            VerticalAlignment.Center,
                                        HorizontalAlignment =
                                            HorizontalAlignment.Center
                                    }
                            };

                        ToolTipService.SetToolTip(
                            durationLabel,
                            "Duración actual asignada.");

                        var plusButton =
                            BuildCalendarProjectMiniActionButton(
                                "+15",
                                "Aumentar 15 minutos la duración asignada.",
                                activity,
                                width: 36);

                        plusButton.IsEnabled =
                            !activity.IsAutomationLocked &&
                            !activity.IsReviewMirror;

                        plusButton.Click +=
                            async (_, __) =>
                            {
                                var changed =
                                    await AdjustCalendarProjectActivityDurationAsync(
                                        activity,
                                        15,
                                        unique,
                                        criteria);

                                if (!changed)
                                    return;

                                await RefreshCalendarDayAfterProjectActionAsync();

                                await RefreshPinnedCalendarProjectChecklistAsync(
                                    activity,
                                    criteria,
                                    hoveredActivity.PageId);
                            };

                        actionBar.Children.Add(
                            dragHandle);

                        actionBar.Children.Add(
                            highlightButton);

                        actionBar.Children.Add(
                            dateButton);

                        actionBar.Children.Add(
                            alarmButton);

                        actionBar.Children.Add(
                            notionButton);

                        actionBar.Children.Add(
                            contentButton);

                        actionBar.Children.Add(
                            minusButton);

                        actionBar.Children.Add(
                            durationLabel);

                        actionBar.Children.Add(
                            plusButton);

                        textStack.Children.Add(
                            actionBar);

                        var activityCardBody =
                            new StackPanel
                            {
                                Spacing = 2,
                                HorizontalAlignment =
                                    HorizontalAlignment.Stretch
                            };

                        activityCardBody.Children.Add(row);
                        activityCardBody.Children.Add(activityContentHost);

                        var isRtuzProjectActivity =
                            HasExactCalendarPhase(
                                activity,
                                "rtuzREVISION");

                        var activityCard =
                            new Border
                            {
                                HorizontalAlignment =
                                    HorizontalAlignment.Stretch,
                                Padding =
                                    new Thickness(
                                        7, 4, 7, 4),
                                CornerRadius =
                                    new CornerRadius(3),
                                Background =
                                    new SolidColorBrush(
                                        isCurrent
                                            ? Color.FromArgb(
                                                145,
                                                20,
                                                83,
                                                45)
                                            : isRtuzProjectActivity
                                                ? Color.FromArgb(
                                                    100,
                                                    20,
                                                    83,
                                                    45)
                                                : Color.FromArgb(
                                                    20,
                                                    255,
                                                    255,
                                                    255)),
                                // rtuzREVISION conserva el FONDO verde, pero
                                // ya no dibuja un rectángulo verde alrededor.
                                // Solo queda un separador neutro entre renglones.
                                BorderBrush =
                                    new SolidColorBrush(
                                        isCurrent
                                            ? Color.FromArgb(
                                                95,
                                                125,
                                                211,
                                                252)
                                            : Color.FromArgb(
                                                34,
                                                255,
                                                255,
                                                255)),
                                BorderThickness =
                                    new Thickness(
                                        0, 0, 0, 1),
                                AllowDrop =
                                    _calendarActivityPreviewPinned &&
                                    CanCurrentUserReorderCalendarActivity(
                                        activity),
                                Child = activityCardBody
                            };

                        // Las acciones secundarias no interrumpen la lectura de
                        // la secuencia. Se revelan únicamente al apuntar a la
                        // actividad, como se pidió en Meet.
                        activityCard.PointerEntered +=
                            (_, __) =>
                            {
                                actionBar.Visibility =
                                    Visibility.Visible;
                            };

                        activityCard.PointerExited +=
                            (_, __) =>
                            {
                                if (activityContentHost.Visibility !=
                                    Visibility.Visible)
                                {
                                    actionBar.Visibility =
                                        Visibility.Collapsed;
                                }
                            };

                        activityCard.DragOver +=
                            (_, args) =>
                            {
                                if (!_calendarActivityPreviewPinned ||
                                    !CanCurrentUserReorderCalendarActivity(
                                        activity))
                                {
                                    return;
                                }

                                args.AcceptedOperation =
                                    Windows.ApplicationModel.DataTransfer
                                        .DataPackageOperation.Move;
                            };

                        activityCard.Drop +=
                            async (_, args) =>
                            {
                                if (!_calendarActivityPreviewPinned ||
                                    !CanCurrentUserReorderCalendarActivity(
                                        activity) ||
                                    !args.DataView.Contains(
                                        Windows.ApplicationModel.DataTransfer
                                            .StandardDataFormats.Text))
                                {
                                    return;
                                }

                                var draggedPageId =
                                    await args.DataView.GetTextAsync();

                                if (string.IsNullOrWhiteSpace(
                                        draggedPageId))
                                {
                                    return;
                                }

                                var pointer =
                                    args.GetPosition(
                                        activityCard);

                                var insertAfter =
                                    pointer.Y >=
                                    (activityCard.ActualHeight / 2d);

                                args.AcceptedOperation =
                                    Windows.ApplicationModel.DataTransfer
                                        .DataPackageOperation.Move;

                                await ReorderCalendarProjectActivitiesAsync(
                                    unique,
                                    draggedPageId,
                                    activity,
                                    insertAfter,
                                    criteria);
                            };

                        phaseContent.Children.Add(
                            activityCard);
                    }
                }

                var header =
                    new Grid
                    {
                        ColumnSpacing = 8
                    };

                header.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            new GridLength(
                                1,
                                GridUnitType.Star)
                    });

                header.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                var phaseLabel =
                    new TextBlock
                    {
                        Text =
                            phaseGroup.Phase.Label,
                        FontSize = 11.5,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.Bold,
                        Foreground =
                            new SolidColorBrush(
                                phaseGroup.Phase.Accent)
                    };

                Grid.SetColumn(
                    phaseLabel,
                    0);

                header.Children.Add(
                    phaseLabel);

                var count =
                    new Border
                    {
                        MinWidth = 30,
                        Padding =
                            new Thickness(
                                6, 1, 6, 1),
                        CornerRadius =
                            new CornerRadius(9),
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    30,
                                    phaseGroup.Phase.Accent.R,
                                    phaseGroup.Phase.Accent.G,
                                    phaseGroup.Phase.Accent.B)),
                        Child =
                            new TextBlock
                            {
                                Text =
                                    phaseGroup.Activities.Count
                                        .ToString(
                                            CultureInfo.InvariantCulture),
                                FontSize = 9.5,
                                FontWeight =
                                    Microsoft.UI.Text.FontWeights.Bold,
                                HorizontalAlignment =
                                    HorizontalAlignment.Center
                            }
                    };

                Grid.SetColumn(
                    count,
                    1);

                header.Children.Add(
                    count);

                listRoot.Children.Add(
                    new Expander
                    {
                        Header = header,
                        Content = phaseContent,
                        IsExpanded =
                            string.Equals(
                                phaseGroup.Phase.Token,
                                hoveredPhase,
                                StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(
                                phaseGroup.Phase.Token,
                                "prtuzREVISION",
                                StringComparison.OrdinalIgnoreCase),
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch,
                        HorizontalContentAlignment =
                            HorizontalAlignment.Stretch
                    });
            }

            if (phaseGroups.Count == 0)
            {
                listRoot.Children.Add(
                    new TextBlock
                    {
                        Text =
                            "No se encontraron actividades asociadas para este proyecto.",
                        FontSize = 11,
                        TextWrapping =
                            TextWrapping.Wrap,
                        Opacity = 0.68
                    });
            }

            // En pantallas normales se conserva el layout vertical aprobado.
            // Cuando la checklist está fijada y dispone de ancho real, el detalle
            // seleccionado queda a la izquierda y TODA la lista comparativa pasa
            // a la derecha. Así John/monitores grandes pueden comparar 1.00, 2.03,
            // 3.00, etc. sin convertir el modal en una columna interminable.
            var previewSizeMode =
                _calendarActivityPreviewPinned
                    ? GetCalendarActivityPreviewSizeMode()
                    : "hover";

            var useWideLayout =
                _calendarActivityPreviewPinned &&
                (string.Equals(
                     previewSizeMode,
                     "large",
                     StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(
                     previewSizeMode,
                     "xlarge",
                     StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(
                     previewSizeMode,
                     "max",
                     StringComparison.OrdinalIgnoreCase) ||
                 (string.Equals(
                      previewSizeMode,
                      "auto",
                      StringComparison.OrdinalIgnoreCase) &&
                  (RootLayout?.ActualWidth ?? 0) >= 1250));

            if (!useWideLayout)
            {
                root.Children.Add(
                    BuildActivitiesHeader(
                        includeCount: true));

                root.Children.Add(
                    new TextBlock
                    {
                        Text = criteria.IncludeAllProjectTypes
                            ? $"Todas las áreas · {criteria.Domain} · {criteria.MonthTag}"
                            : $"{criteria.ProjectLabel} · {criteria.Domain} · {criteria.MonthTag}",
                        FontSize = 9.5,
                        Opacity = 0.64,
                        Margin =
                            new Thickness(
                                1, 0, 0, 1)
                    });

                root.Children.Add(
                    listRoot);

                return root;
            }

            var wideRoot =
                new Grid
                {
                    ColumnSpacing = 14,
                    Padding = new Thickness(0),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            wideRoot.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            0.36,
                            GridUnitType.Star)
                });

            wideRoot.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            0.64,
                            GridUnitType.Star)
                });

            Grid.SetColumn(
                root,
                0);

            wideRoot.Children.Add(
                root);

            var rightPanel =
                new StackPanel
                {
                    Spacing = 8,
                    Padding =
                        new Thickness(
                            4, 12, 12, 12),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            rightPanel.Children.Add(
                BuildActivitiesHeader(
                    includeCount: true));

            rightPanel.Children.Add(
                new TextBlock
                {
                    Text = criteria.IncludeAllProjectTypes
                        ? $"Todas las áreas · {criteria.Domain} · {criteria.MonthTag}"
                        : $"{criteria.ProjectLabel} · {criteria.Domain} · {criteria.MonthTag}",
                    FontSize = 10,
                    Opacity = 0.68,
                    TextWrapping =
                        TextWrapping.Wrap
                });

            var rightScrollHeightCap =
                string.Equals(
                    previewSizeMode,
                    "max",
                    StringComparison.OrdinalIgnoreCase)
                    ? 1900d
                    : string.Equals(
                        previewSizeMode,
                        "xlarge",
                        StringComparison.OrdinalIgnoreCase)
                        ? 1500d
                        : 1040d;

            var rightScroll =
                new ScrollViewer
                {
                    Content = listRoot,
                    VerticalScrollMode =
                        ScrollMode.Auto,
                    VerticalScrollBarVisibility =
                        ScrollBarVisibility.Auto,
                    HorizontalScrollMode =
                        ScrollMode.Disabled,
                    HorizontalScrollBarVisibility =
                        ScrollBarVisibility.Disabled,
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch,
                    HorizontalContentAlignment =
                        HorizontalAlignment.Stretch,
                    MaxHeight =
                        Math.Max(
                            420,
                            Math.Min(
                                rightScrollHeightCap,
                                (RootLayout?.ActualHeight ?? 900) - 150))
                };

            rightPanel.Children.Add(
                rightScroll);

            var rightBorder =
                new Border
                {
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                42,
                                255,
                                255,
                                255)),
                    BorderThickness =
                        new Thickness(1, 0, 0, 0),
                    Child = rightPanel
                };

            Grid.SetColumn(
                rightBorder,
                1);

            wideRoot.Children.Add(
                rightBorder);

            return wideRoot;
        }

        private void SetCalendarActivityPreviewPinned(
            string pageId,
            bool pinned)
        {
            var wasPinned =
                _calendarActivityPreviewPinned;

            _calendarActivityPreviewPinned =
                pinned;

            _calendarActivityPreviewPinnedPageId =
                pinned
                    ? (pageId ?? string.Empty).Trim()
                    : string.Empty;

            // Cada nueva fijación vuelve a iniciar junto a la card. Después
            // de que el usuario la arrastre, PositionCalendarActivityPreviewPopup
            // conserva esa posición en lugar de regresarla al ancla.
            if (!pinned || !wasPinned)
            {
                _calendarActivityPreviewUserMoved = false;
                _calendarActivityPreviewDragActive = false;
            }

            if (_calendarActivityPreviewPinBar != null)
            {
                _calendarActivityPreviewPinBar.Visibility =
                    pinned
                        ? Visibility.Visible
                        : Visibility.Collapsed;
            }

            if (pinned)
            {
                StopCalendarPreviewCloseTimer();

                StatusText.Text =
                    "Estado: Checklist del proyecto fijada 📌";
            }
        }

        private async Task PinCalendarActivityProjectPreviewAsync(
            Button button,
            NotionCalendarActivity activity)
        {
            if (button == null ||
                activity == null)
            {
                return;
            }

            _calendarActivityHoverTimer?.Stop();

            _calendarPointerOverActivity = true;
            _calendarHoveredActivityButton =
                button;

            SetCalendarActivityPreviewPinned(
                activity.PageId,
                true);

            // Si el hover ya dejó abierto el popup para esta misma tarjeta,
            // reutilizamos los datos ya resueltos y reconstruimos ESA MISMA
            // interfaz en modo fijado. En este modo aparece arriba el detalle
            // completo con los campos/botones históricos de ANFETA.
            if (_calendarActivityPreviewPopup?.IsOpen == true &&
                _calendarActivityPreviewHost != null)
            {
                if (_calendarActivityPreviewLastCriteria != null &&
                    _calendarActivityPreviewLastProjectActivities.Count > 0)
                {
                    var selected =
                        _calendarActivityPreviewLastProjectActivities
                            .FirstOrDefault(item =>
                                string.Equals(
                                    item.PageId,
                                    activity.PageId,
                                    StringComparison.OrdinalIgnoreCase))
                        ?? activity;

                    UpdateCalendarActivityPreviewContent(
                        BuildCalendarProjectHoverChecklist(
                            selected,
                            _calendarActivityPreviewLastCriteria,
                            _calendarActivityPreviewLastProjectActivities));
                }

                PositionCalendarActivityPreviewPopup(
                    button);

                return;
            }

            if (!TryBuildCalendarProjectGroupCriteria(
                    activity,
                    out var criteria))
            {
                ShowCalendarActivityPreviewFlyout(
                    button,
                    BuildCalendarActivitySummary(
                        activity));

                SetCalendarActivityPreviewPinned(
                    activity.PageId,
                    true);

                return;
            }

            ShowCalendarActivityPreviewFlyout(
                button,
                BuildCalendarProjectHoverLoading(
                    activity,
                    criteria));

            SetCalendarActivityPreviewPinned(
                activity.PageId,
                true);

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                UpdateCalendarActivityPreviewContent(
                    BuildCalendarActivityErrorPreview(
                        activity,
                        "Configura primero el token de Notion."));

                return;
            }

            try
            {
                _calendarHoverPreviewCts?.Cancel();
                _calendarHoverPreviewCts?.Dispose();
            }
            catch
            {
            }

            _calendarHoverPreviewCts =
                new CancellationTokenSource(
                    TimeSpan.FromSeconds(90));

            var localCts =
                _calendarHoverPreviewCts;

            try
            {
                var related =
                    await GetCalendarProjectRelatedActivitiesAsync(
                        activity,
                        criteria,
                        token,
                        localCts.Token);

                if (localCts.IsCancellationRequested ||
                    !_calendarActivityPreviewPinned ||
                    !string.Equals(
                        _calendarActivityPreviewPinnedPageId,
                        activity.PageId,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                UpdateCalendarActivityPreviewContent(
                    BuildCalendarProjectHoverChecklist(
                        activity,
                        criteria,
                        related));

                _ = WarmOpenCalendarProjectChecklistAsync(
                    activity,
                    criteria,
                    related,
                    activity.PageId,
                    localCts.Token);
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                if (!_calendarActivityPreviewPinned ||
                    !string.Equals(
                        _calendarActivityPreviewPinnedPageId,
                        activity.PageId,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                UpdateCalendarActivityPreviewContent(
                    BuildCalendarActivityErrorPreview(
                        activity,
                        ex.Message));
            }
        }

        private void CalendarActivityPreviewClose_Click(
            object sender,
            RoutedEventArgs e)
        {
            HideCalendarActivityPreviewFlyout();
        }

        private void CalendarActivity_PointerEntered(
            object sender,
            PointerRoutedEventArgs e)
        {
            if (sender is not Button button ||
                button.Tag is not NotionCalendarActivity)
            {
                return;
            }

            // Una checklist fijada no cambia solo por pasar el mouse sobre
            // otra tarjeta. Primero debe cerrarse con X.
            if (_calendarActivityPreviewPinned)
                return;

            _calendarPointerOverActivity = true;
            _calendarPendingActivityButton = button;

            StopCalendarPreviewCloseTimer();

            if (_calendarActivityHoverTimer == null)
            {
                _calendarActivityHoverTimer =
                    new DispatcherTimer
                    {
                        // Debe mantenerse sobre una actividad antes de
                        // abrir/cambiar la checklist del proyecto.
                        Interval =
                            TimeSpan.FromMilliseconds(650)
                    };

                _calendarActivityHoverTimer.Tick +=
                    CalendarActivityHoverTimer_Tick;
            }

            _calendarActivityHoverTimer.Stop();
            _calendarActivityHoverTimer.Start();
        }

        private async void CalendarActivityHoverTimer_Tick(
            object? sender,
            object e)
        {
            _calendarActivityHoverTimer?.Stop();

            var button =
                _calendarPendingActivityButton;

            if (!_calendarPointerOverActivity ||
                button == null ||
                button.Tag is not NotionCalendarActivity activity)
            {
                return;
            }

            _calendarHoveredActivityButton = button;

            try
            {
                _calendarHoverPreviewCts?.Cancel();
                _calendarHoverPreviewCts?.Dispose();
            }
            catch
            {
            }

            _calendarHoverPreviewCts =
                new CancellationTokenSource(
                    TimeSpan.FromSeconds(90));

            var localCts =
                _calendarHoverPreviewCts;

            if (!TryBuildCalendarProjectGroupCriteria(
                    activity,
                    out var criteria))
            {
                ShowCalendarActivityPreviewFlyout(
                    button,
                    BuildCalendarActivitySummary(
                        activity));

                return;
            }

            ShowCalendarActivityPreviewFlyout(
                button,
                BuildCalendarProjectHoverLoading(
                    activity,
                    criteria));

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                UpdateCalendarActivityPreviewContent(
                    BuildCalendarActivityErrorPreview(
                        activity,
                        "Configura primero el token de Notion."));

                return;
            }

            try
            {
                var related =
                    await GetCalendarProjectRelatedActivitiesAsync(
                        activity,
                        criteria,
                        token,
                        localCts.Token);

                if (localCts.IsCancellationRequested ||
                    _calendarHoveredActivityButton != button)
                {
                    return;
                }

                UpdateCalendarActivityPreviewContent(
                    BuildCalendarProjectHoverChecklist(
                        activity,
                        criteria,
                        related));

                _ = WarmOpenCalendarProjectChecklistAsync(
                    activity,
                    criteria,
                    related,
                    activity.PageId,
                    localCts.Token);
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                if (_calendarHoveredActivityButton != button)
                    return;

                UpdateCalendarActivityPreviewContent(
                    BuildCalendarActivityErrorPreview(
                        activity,
                        ex.Message));
            }
        }

        private void CalendarActivity_PointerExited(
            object sender,
            PointerRoutedEventArgs e)
        {
            _calendarPointerOverActivity = false;

            if (_calendarPendingActivityButton == sender)
                _calendarPendingActivityButton = null;

            _calendarActivityHoverTimer?.Stop();

            if (!_calendarActivityPreviewPinned)
                StartCalendarPreviewCloseTimer();
        }

        // Escala visual exclusiva del popup/checklist fijado.
        // En Extra grande y Máximo no solo crece la caja: también crecen
        // textos, controles, badges y espacios para aprovechar monitores
        // grandes sin modificar el calendario ni la lógica de Notion.
        private double GetCalendarActivityPreviewUiScale()
        {
            if (!_calendarActivityPreviewPinned)
                return 1d;

            var mode =
                GetCalendarActivityPreviewSizeMode();

            var rootWidth =
                Math.Max(
                    1,
                    RootLayout?.ActualWidth ??
                    XamlRoot?.Size.Width ??
                    1200d);

            var rootHeight =
                Math.Max(
                    1,
                    RootLayout?.ActualHeight ??
                    XamlRoot?.Size.Height ??
                    800d);

            var veryLargeScreen =
                rootWidth >= 3000d ||
                rootHeight >= 1600d;

            return mode switch
            {
                "large" => 1.08d,

                // Pantallas grandes: además del modal ancho, la tipografía
                // y los controles aumentan de forma perceptible.
                "xlarge" =>
                    veryLargeScreen
                        ? 1.30d
                        : 1.22d,

                // Máximo está pensado para las pantallas muy grandes de John.
                // El contenido escala más, pero mantiene scroll interno.
                "max" =>
                    veryLargeScreen
                        ? 1.52d
                        : 1.38d,

                // Automático conserva el aspecto normal, salvo en monitores
                // realmente grandes donde aplica una ayuda ligera de lectura.
                "auto" =>
                    rootWidth >= 3000d
                        ? 1.12d
                        : 1d,

                _ => 1d
            };
        }

        private static Thickness ScaleCalendarActivityPreviewThickness(
            Thickness value,
            double scale)
        {
            return new Thickness(
                value.Left * scale,
                value.Top * scale,
                value.Right * scale,
                value.Bottom * scale);
        }

        private CalendarActivityPreviewVisualBaseline
            CaptureCalendarActivityPreviewVisualBaseline(
                DependencyObject node)
        {
            double? fontSize = null;
            double? lineHeight = null;

            if (node is TextBlock textBlock)
            {
                if (!double.IsNaN(textBlock.FontSize) &&
                    textBlock.FontSize > 0)
                {
                    fontSize = textBlock.FontSize;
                }

                if (textBlock.LineHeight > 0)
                    lineHeight = textBlock.LineHeight;
            }
            else if (node is Control control &&
                     !double.IsNaN(control.FontSize) &&
                     control.FontSize > 0)
            {
                fontSize = control.FontSize;
            }

            var width = double.NaN;
            var height = double.NaN;
            var minWidth = 0d;
            var minHeight = 0d;
            var margin = new Thickness(0);

            if (node is FrameworkElement element)
            {
                width = element.Width;
                height = element.Height;
                minWidth = element.MinWidth;
                minHeight = element.MinHeight;
                margin = element.Margin;
            }

            var padding = new Thickness(0);

            if (node is Border border)
                padding = border.Padding;

            return new CalendarActivityPreviewVisualBaseline
            {
                FontSize = fontSize,
                LineHeight = lineHeight,
                Width = width,
                Height = height,
                MinWidth = minWidth,
                MinHeight = minHeight,
                Margin = margin,
                Padding = padding,
                StackSpacing =
                    node is StackPanel stackPanel
                        ? stackPanel.Spacing
                        : 0d,
                GridColumnSpacing =
                    node is Grid grid
                        ? grid.ColumnSpacing
                        : 0d,
                GridRowSpacing =
                    node is Grid rowGrid
                        ? rowGrid.RowSpacing
                        : 0d
            };
        }

        private void ScaleCalendarActivityPreviewVisualTree(
            DependencyObject node,
            double scale)
        {
            if (node == null)
                return;

            scale =
                Math.Clamp(
                    scale,
                    0.75d,
                    1.75d);

            // IMPORTANTE: GetValue conserva el estado BASE la primera vez.
            // Cada cambio posterior (Máximo -> Normal, etc.) vuelve a calcular
            // desde estas medidas originales, nunca desde el resultado anterior.
            var baseline =
                _calendarActivityPreviewVisualBaselines.GetValue(
                    node,
                    CaptureCalendarActivityPreviewVisualBaseline);

            if (node is TextBlock textBlock)
            {
                if (baseline.FontSize.HasValue)
                {
                    textBlock.FontSize =
                        Math.Clamp(
                            baseline.FontSize.Value * scale,
                            8d,
                            36d);
                }

                if (baseline.LineHeight.HasValue)
                {
                    textBlock.LineHeight =
                        Math.Clamp(
                            baseline.LineHeight.Value * scale,
                            8d,
                            48d);
                }
            }
            else if (node is Control control &&
                     baseline.FontSize.HasValue)
            {
                control.FontSize =
                    Math.Clamp(
                        baseline.FontSize.Value * scale,
                        9d,
                        36d);
            }

            if (node is FrameworkElement element)
            {
                if (!double.IsNaN(baseline.Height) &&
                    baseline.Height > 0 &&
                    baseline.Height <= 100d)
                {
                    element.Height =
                        baseline.Height * scale;
                }

                if (baseline.MinHeight > 0 &&
                    baseline.MinHeight <= 100d)
                {
                    element.MinHeight =
                        baseline.MinHeight * scale;
                }

                if (!double.IsNaN(baseline.Width) &&
                    baseline.Width > 0 &&
                    baseline.Width <= 190d)
                {
                    element.Width =
                        baseline.Width * scale;
                }

                if (baseline.MinWidth > 0 &&
                    baseline.MinWidth <= 190d)
                {
                    element.MinWidth =
                        baseline.MinWidth * scale;
                }

                element.Margin =
                    ScaleCalendarActivityPreviewThickness(
                        baseline.Margin,
                        Math.Min(
                            scale,
                            1.30d));
            }

            if (node is Border border)
            {
                border.Padding =
                    ScaleCalendarActivityPreviewThickness(
                        baseline.Padding,
                        Math.Min(
                            scale,
                            1.32d));
            }

            if (node is StackPanel stackPanel)
            {
                stackPanel.Spacing =
                    baseline.StackSpacing *
                    Math.Min(
                        scale,
                        1.28d);
            }

            if (node is Grid grid)
            {
                grid.ColumnSpacing =
                    baseline.GridColumnSpacing *
                    Math.Min(
                        scale,
                        1.28d);

                grid.RowSpacing =
                    baseline.GridRowSpacing *
                    Math.Min(
                        scale,
                        1.28d);
            }

            if (node is Panel panel)
            {
                foreach (var child in panel.Children)
                {
                    ScaleCalendarActivityPreviewVisualTree(
                        child,
                        scale);
                }

                return;
            }

            if (node is Border childBorder &&
                childBorder.Child != null)
            {
                ScaleCalendarActivityPreviewVisualTree(
                    childBorder.Child,
                    scale);

                return;
            }

            if (node is ScrollViewer scrollViewer &&
                scrollViewer.Content is DependencyObject scrollContent)
            {
                ScaleCalendarActivityPreviewVisualTree(
                    scrollContent,
                    scale);

                return;
            }

            if (node is Expander expander)
            {
                if (expander.Header is DependencyObject header)
                {
                    ScaleCalendarActivityPreviewVisualTree(
                        header,
                        scale);
                }

                if (expander.Content is DependencyObject expanderContent)
                {
                    ScaleCalendarActivityPreviewVisualTree(
                        expanderContent,
                        scale);
                }

                return;
            }

            if (node is ContentControl contentControl &&
                contentControl.Content is DependencyObject content)
            {
                ScaleCalendarActivityPreviewVisualTree(
                    content,
                    scale);
            }
        }

        private void ApplyCalendarActivityPreviewUiScale(
            FrameworkElement content)
        {
            if (!_calendarActivityPreviewPinned ||
                content == null)
            {
                return;
            }

            // Incluso escala 1.0 debe recorrer el árbol: esa es justamente la
            // operación que RESTAURA Normal después de Extra grande/Máximo.
            var scale =
                GetCalendarActivityPreviewUiScale();

            ScaleCalendarActivityPreviewVisualTree(
                content,
                scale);

            content.InvalidateMeasure();
            content.InvalidateArrange();
        }

        private string GetCalendarActivityPreviewSizeMode()
        {
            var raw =
                (ApplicationData.Current.LocalSettings.Values[
                    LS_CalendarActivityPreviewSizeMode] as string ??
                 "auto")
                .Trim()
                .ToLowerInvariant();

            return raw switch
            {
                "normal" => "normal",
                "large" => "large",
                "xlarge" => "xlarge",
                "max" => "max",
                _ => "auto"
            };
        }

        private static string GetCalendarActivityPreviewSizeModeLabel(
            string mode)
        {
            return (mode ?? string.Empty).Trim().ToLowerInvariant() switch
            {
                "normal" => "Normal",
                "large" => "Grande",
                "xlarge" => "Extra grande",
                "max" => "Máximo",
                _ => "Automático"
            };
        }

        private void CalendarActivityPreviewSizeMode_Click(
            object sender,
            RoutedEventArgs e)
        {
            if (sender is not MenuFlyoutItem item)
                return;

            var mode =
                (item.Tag?.ToString() ?? "auto")
                .Trim()
                .ToLowerInvariant();

            mode = mode switch
            {
                "normal" => "normal",
                "large" => "large",
                "xlarge" => "xlarge",
                "max" => "max",
                _ => "auto"
            };

            ApplicationData.Current.LocalSettings.Values[
                LS_CalendarActivityPreviewSizeMode] = mode;

            if (_calendarActivityPreviewPopup?.IsOpen == true &&
                _calendarHoveredActivityButton != null)
            {
                // El tamaño ahora también cambia la ESTRUCTURA del modal
                // (vertical ↔ dos columnas). Por eso no basta con redimensionar
                // el Popup: reconstruye el contenido ya resuelto sin tocar Notion.
                if (_calendarActivityPreviewPinned &&
                    _calendarActivityPreviewLastCriteria != null &&
                    _calendarActivityPreviewLastProjectActivities.Count > 0)
                {
                    var selected =
                        _calendarActivityPreviewLastProjectActivities
                            .FirstOrDefault(activity =>
                                string.Equals(
                                    activity.PageId,
                                    _calendarActivityPreviewLastSelectedPageId,
                                    StringComparison.OrdinalIgnoreCase))
                        ?? _calendarActivityPreviewLastProjectActivities.First();

                    UpdateCalendarActivityPreviewContent(
                        BuildCalendarProjectHoverChecklist(
                            selected,
                            _calendarActivityPreviewLastCriteria,
                            _calendarActivityPreviewLastProjectActivities));
                }

                PositionCalendarActivityPreviewPopup(
                    _calendarHoveredActivityButton);
            }

            StatusText.Text =
                $"Estado: Tamaño de checklist → " +
                $"{GetCalendarActivityPreviewSizeModeLabel(mode)} ✅";
        }

        private MenuFlyout BuildCalendarActivityPreviewSizeFlyout()
        {
            var flyout = new MenuFlyout();

            var options = new[]
            {
                (Mode: "auto", Label: "Automático (según pantalla)"),
                (Mode: "normal", Label: "Normal"),
                (Mode: "large", Label: "Grande"),
                (Mode: "xlarge", Label: "Extra grande · pantalla grande"),
                (Mode: "max", Label: "Máximo · pantalla muy grande")
            };

            foreach (var option in options)
            {
                var item = new MenuFlyoutItem
                {
                    Text = option.Label,
                    Tag = option.Mode
                };

                item.Click +=
                    CalendarActivityPreviewSizeMode_Click;

                flyout.Items.Add(item);
            }

            return flyout;
        }

        private void ShowCalendarActivityPreviewFlyout(
            Button anchor,
            FrameworkElement content)
        {
            StopCalendarPreviewCloseTimer();

            _calendarHoveredActivityButton = anchor;

            ApplyCalendarActivityPreviewUiScale(
                content);

            if (_calendarActivityPreviewPopup?.IsOpen == true &&
                _calendarActivityPreviewHost != null)
            {
                _calendarActivityPreviewHost.Content =
                    content;

                if (_calendarActivityPreviewPinBar != null)
                {
                    _calendarActivityPreviewPinBar.Visibility =
                        _calendarActivityPreviewPinned
                            ? Visibility.Visible
                            : Visibility.Collapsed;
                }

                PositionCalendarActivityPreviewPopup(
                    anchor);

                return;
            }

            var host = new ContentControl
            {
                Content = content,
                IsTabStop = true,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                HorizontalContentAlignment = HorizontalAlignment.Stretch,
                VerticalContentAlignment = VerticalAlignment.Top
            };

            host.PointerEntered +=
                CalendarPreviewContent_PointerEntered;

            host.PointerExited +=
                CalendarPreviewContent_PointerExited;

            var popupScroll =
                new ScrollViewer
                {
                    Content = host,
                    HorizontalScrollMode =
                        ScrollMode.Disabled,
                    HorizontalScrollBarVisibility =
                        ScrollBarVisibility.Disabled,
                    VerticalScrollMode =
                        ScrollMode.Auto,
                    VerticalScrollBarVisibility =
                        ScrollBarVisibility.Auto,
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    HorizontalContentAlignment = HorizontalAlignment.Stretch,
                    IsTabStop = true
                };

            popupScroll.PointerEntered +=
                CalendarPreviewContent_PointerEntered;

            popupScroll.PointerExited +=
                CalendarPreviewContent_PointerExited;

            var pinHeader =
                new Grid
                {
                    Height = 36,
                    Padding =
                        new Thickness(
                            10,
                            0,
                            6,
                            0),
                    ColumnSpacing = 8
                };

            var pinHeaderBorder =
                new Border
                {
                    Child = pinHeader,
                    Visibility =
                        _calendarActivityPreviewPinned
                            ? Visibility.Visible
                            : Visibility.Collapsed,
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                24,
                                74,
                                222,
                                128)),
                    BorderBrush =
                        new SolidColorBrush(
                            Color.FromArgb(
                                80,
                                74,
                                222,
                                128)),
                    BorderThickness =
                        new Thickness(
                            0,
                            0,
                            0,
                            1)
                };

            pinHeader.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            pinHeader.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            pinHeader.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            var pinLabel =
                new TextBlock
                {
                    Text =
                        "📌 Actividad fijada · Editor",
                    FontSize = 10.5,
                    FontWeight =
                        Microsoft.UI.Text.FontWeights.SemiBold,
                    Foreground =
                        new SolidColorBrush(
                            Color.FromArgb(
                                255,
                                134,
                                239,
                                172)),
                    VerticalAlignment =
                        VerticalAlignment.Center
                };

            var pinDragArea =
                new Grid
                {
                    Background =
                        new SolidColorBrush(
                            Colors.Transparent),
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch,
                    VerticalAlignment =
                        VerticalAlignment.Stretch
                };

            pinDragArea.Children.Add(
                pinLabel);

            Grid.SetColumn(
                pinDragArea,
                0);

            pinHeader.Children.Add(
                pinDragArea);

            ToolTipService.SetToolTip(
                pinDragArea,
                "Arrastra esta zona para mover la actividad fijada");

            var resizeButton =
                new Button
                {
                    Content = "⛶",
                    Width = 30,
                    Height = 26,
                    Padding =
                        new Thickness(0),
                    HorizontalContentAlignment =
                        HorizontalAlignment.Center,
                    VerticalContentAlignment =
                        VerticalAlignment.Center,
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                24,
                                255,
                                255,
                                255)),
                    BorderThickness =
                        new Thickness(0),
                    CornerRadius =
                        new CornerRadius(6),
                    FontSize = 12,
                    VerticalAlignment =
                        VerticalAlignment.Center,
                    Flyout =
                        BuildCalendarActivityPreviewSizeFlyout()
                };

            ToolTipService.SetToolTip(
                resizeButton,
                "Ajustar tamaño de la checklist fijada");

            Grid.SetColumn(
                resizeButton,
                1);

            pinHeader.Children.Add(
                resizeButton);

            var closeButton =
                new Button
                {
                    Content = "✕",
                    Width = 28,
                    Height = 26,
                    Padding =
                        new Thickness(0),
                    HorizontalContentAlignment =
                        HorizontalAlignment.Center,
                    VerticalContentAlignment =
                        VerticalAlignment.Center,
                    Background =
                        new SolidColorBrush(
                            Color.FromArgb(
                                24,
                                255,
                                255,
                                255)),
                    BorderThickness =
                        new Thickness(0),
                    CornerRadius =
                        new CornerRadius(6),
                    FontSize = 11,
                    VerticalAlignment =
                        VerticalAlignment.Center
                };

            ToolTipService.SetToolTip(
                closeButton,
                "Cerrar checklist fijada");

            closeButton.Click +=
                CalendarActivityPreviewClose_Click;

            Grid.SetColumn(
                closeButton,
                2);

            pinHeader.Children.Add(
                closeButton);

            var popupLayout =
                new Grid
                {
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    VerticalAlignment = VerticalAlignment.Stretch
                };

            popupLayout.RowDefinitions.Add(
                new RowDefinition
                {
                    Height = GridLength.Auto
                });

            popupLayout.RowDefinitions.Add(
                new RowDefinition
                {
                    Height =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            Grid.SetRow(
                pinHeaderBorder,
                0);

            popupLayout.Children.Add(
                pinHeaderBorder);

            Grid.SetRow(
                popupScroll,
                1);

            popupLayout.Children.Add(
                popupScroll);

            var card = new Border
            {
                Child = popupLayout,
                Padding = new Thickness(0),
                CornerRadius = new CornerRadius(10),
                Background =
                    new SolidColorBrush(
                        Color.FromArgb(
                            255,
                            42,
                            42,
                            42)),
                BorderBrush =
                    new SolidColorBrush(
                        Color.FromArgb(
                            70,
                            255,
                            255,
                            255)),
                BorderThickness =
                    new Thickness(1),
                Shadow =
                    new Microsoft.UI.Xaml.Media.ThemeShadow()
            };

            card.PointerEntered +=
                CalendarPreviewContent_PointerEntered;

            card.PointerExited +=
                CalendarPreviewContent_PointerExited;

            // Esta checklist es grande y contiene mucho texto. Con
            // RenderTransform el texto se vuelve a rasterizar mientras el
            // panel viaja y en algunos equipos se percibe como "temblor".
            // Aquí movemos el Popup por offsets REALES, siempre en píxeles
            // enteros, y congelamos los repintados de contenido hasta soltar.
            card.UseLayoutRounding = true;
            popupLayout.UseLayoutRounding = true;
            popupScroll.UseLayoutRounding = true;

            var popup = new Popup
            {
                Child = card,
                IsLightDismissEnabled = false,

                // El panel fijado puede bajar parcialmente fuera del cuerpo
                // de ANFETA mientras la cabecera permanezca accesible. El hover
                // se limita manualmente en PositionCalendarActivityPreviewPopup.
                ShouldConstrainToRootBounds = false,
                XamlRoot = anchor.XamlRoot
            };

            var isDragging = false;
            uint dragPointerId = 0;
            var dragStart =
                new Windows.Foundation.Point();
            var dragStartLeft = 0d;
            var dragStartTop = 0d;

            double ClampPreviewDragLeft(
                double value)
            {
                var rootWidth =
                    Math.Max(
                        1,
                        RootLayout?.ActualWidth ??
                        XamlRoot?.Size.Width ??
                        900d);

                var width =
                    card.Width > 0
                        ? card.Width
                        : 560d;

                const double edge = 10d;
                const double minimumVisibleHeader = 150d;

                var minLeft =
                    Math.Min(
                        edge,
                        -(Math.Max(
                            0d,
                            width -
                            minimumVisibleHeader)));

                var maxLeft =
                    Math.Max(
                        edge,
                        rootWidth -
                        minimumVisibleHeader);

                return Math.Clamp(
                    value,
                    minLeft,
                    maxLeft);
            }

            double ClampPreviewDragTop(
                double value)
            {
                var rootHeight =
                    Math.Max(
                        1,
                        RootLayout?.ActualHeight ??
                        XamlRoot?.Size.Height ??
                        700d);

                const double edge = 10d;
                const double headerHeight = 36d;

                // El cuerpo puede salir por abajo, pero la barra verde siempre
                // queda visible para poder recuperar la ventana.
                var maxTop =
                    Math.Max(
                        edge,
                        rootHeight -
                        headerHeight -
                        edge);

                return Math.Clamp(
                    value,
                    edge,
                    maxTop);
            }

            void CommitPreviewDrag()
            {
                isDragging = false;
                _calendarActivityPreviewDragActive = false;

                // Si checklist/Notion terminó un repintado mientras se movía
                // la ventana, se aplica AHORA. Así el layout nunca cambia a
                // mitad del gesto y desaparece otra fuente de vibración.
                if (_calendarActivityPreviewPendingContent != null &&
                    _calendarActivityPreviewHost != null)
                {
                    var pending =
                        _calendarActivityPreviewPendingContent;

                    _calendarActivityPreviewPendingContent =
                        null;

                    _calendarActivityPreviewHost.Content =
                        pending;
                }
            }

            pinDragArea.PointerPressed +=
                (_, args) =>
                {
                    if (!_calendarActivityPreviewPinned)
                        return;

                    var currentPoint =
                        args.GetCurrentPoint(null);

                    if (!currentPoint.Properties.IsLeftButtonPressed)
                        return;

                    isDragging = true;
                    _calendarActivityPreviewDragActive = true;
                    dragPointerId =
                        args.Pointer.PointerId;
                    dragStart =
                        currentPoint.Position;
                    dragStartLeft =
                        popup.HorizontalOffset;
                    dragStartTop =
                        popup.VerticalOffset;

                    // El punto inicial y los offsets del popup son la
                    // única referencia del gesto. No transformamos el contenido.
                    pinDragArea.CapturePointer(
                        args.Pointer);

                    args.Handled = true;
                };

            pinDragArea.PointerMoved +=
                (_, args) =>
                {
                    if (!isDragging ||
                        args.Pointer.PointerId !=
                        dragPointerId)
                    {
                        return;
                    }

                    var currentPoint =
                        args.GetCurrentPoint(null);

                    if (!currentPoint.Properties.IsLeftButtonPressed)
                    {
                        CommitPreviewDrag();
                        pinDragArea.ReleasePointerCapture(
                            args.Pointer);
                        return;
                    }

                    var deltaX =
                        currentPoint.Position.X -
                        dragStart.X;

                    var deltaY =
                        currentPoint.Position.Y -
                        dragStart.Y;

                    // Mueve el Popup completo en coordenadas reales.
                    // Math.Round evita posiciones sub-píxel y, al no aplicar
                    // RenderTransform al árbol de texto, la checklist deja de
                    // re-rasterizarse/"vibrar" durante el arrastre.
                    var targetLeft =
                        Math.Round(
                            ClampPreviewDragLeft(
                                dragStartLeft +
                                deltaX),
                            MidpointRounding.AwayFromZero);

                    var targetTop =
                        Math.Round(
                            ClampPreviewDragTop(
                                dragStartTop +
                                deltaY),
                            MidpointRounding.AwayFromZero);

                    if (Math.Abs(
                            popup.HorizontalOffset -
                            targetLeft) >= 1d)
                    {
                        popup.HorizontalOffset =
                            targetLeft;
                    }

                    if (Math.Abs(
                            popup.VerticalOffset -
                            targetTop) >= 1d)
                    {
                        popup.VerticalOffset =
                            targetTop;
                    }

                    if (Math.Abs(deltaX) > 1 ||
                        Math.Abs(deltaY) > 1)
                    {
                        _calendarActivityPreviewUserMoved =
                            true;
                    }

                    args.Handled = true;
                };

            pinDragArea.PointerReleased +=
                (_, args) =>
                {
                    if (!isDragging ||
                        args.Pointer.PointerId !=
                        dragPointerId)
                    {
                        return;
                    }

                    CommitPreviewDrag();
                    pinDragArea.ReleasePointerCapture(
                        args.Pointer);
                    args.Handled = true;
                };

            pinDragArea.PointerCanceled +=
                (_, args) =>
                {
                    if (args.Pointer.PointerId !=
                        dragPointerId)
                    {
                        return;
                    }

                    CommitPreviewDrag();
                    pinDragArea.ReleasePointerCapture(
                        args.Pointer);
                };

            pinDragArea.PointerCaptureLost +=
                (_, __) =>
                {
                    CommitPreviewDrag();
                };

            _calendarActivityPreviewHost = host;
            _calendarActivityPreviewScrollViewer =
                popupScroll;
            _calendarActivityPreviewPopupCard = card;
            _calendarActivityPreviewPopup = popup;
            _calendarActivityPreviewPinBar =
                pinHeaderBorder;

            popup.IsOpen = true;

            PositionCalendarActivityPreviewPopup(
                anchor);
        }

        private void PositionCalendarActivityPreviewPopup(
            Button anchor)
        {
            var popup =
                _calendarActivityPreviewPopup;

            if (popup == null ||
                !popup.IsOpen ||
                RootLayout == null)
            {
                return;
            }

            // Mientras el usuario arrastra la ventana fijada NO recalculamos
            // ancho, alto, measure/arrange ni posición automática. Antes esas
            // recalculaciones podían competir con el RenderTransform y causar
            // el pequeño "temblor" visual de la checklist al moverla.
            if (_calendarActivityPreviewPinned &&
                _calendarActivityPreviewDragActive)
            {
                return;
            }

            try
            {
                var transform =
                    anchor.TransformToVisual(
                        RootLayout);

                var point =
                    transform.TransformPoint(
                        new Windows.Foundation.Point(
                            0,
                            0));

                const double edge = 12;

                var rootWidth =
                    Math.Max(
                        1,
                        RootLayout.ActualWidth);

                var rootHeight =
                    Math.Max(
                        1,
                        RootLayout.ActualHeight);

                var usableWidth =
                    Math.Max(
                        1,
                        rootWidth - (edge * 2));

                var availableHeight =
                    Math.Max(
                        1,
                        rootHeight - (edge * 2));

                // Hover = vistazo compacto.
                // Clic/fijado = editor completo.
                var sizeMode =
                    _calendarActivityPreviewPinned
                        ? GetCalendarActivityPreviewSizeMode()
                        : "hover";

                // Reaplica SIEMPRE la escala al contenido ya visible. Como las
                // medidas se calculan desde baseline, también reduce fuentes,
                // botones y espacios al volver de Máximo/Extra grande.
                if (_calendarActivityPreviewPinned &&
                    _calendarActivityPreviewHost?.Content is
                        FrameworkElement currentPreviewContent)
                {
                    ApplyCalendarActivityPreviewUiScale(
                        currentPreviewContent);
                }

                double preferredWidth;
                double preferredHeight;

                if (string.Equals(
                        sizeMode,
                        "normal",
                        StringComparison.OrdinalIgnoreCase))
                {
                    preferredWidth = 600d;
                    preferredHeight = 760d;
                }
                else if (string.Equals(
                             sizeMode,
                             "large",
                             StringComparison.OrdinalIgnoreCase))
                {
                    preferredWidth = 760d;
                    preferredHeight = 900d;
                }
                else if (string.Equals(
                             sizeMode,
                             "xlarge",
                             StringComparison.OrdinalIgnoreCase))
                {
                    // Extra grande: deja de ser un 900x1040 fijo.
                    // Crece con ANFETA y aprovecha monitores 2K/4K.
                    preferredWidth =
                        Math.Clamp(
                            usableWidth * 0.66,
                            980d,
                            1900d);

                    preferredHeight =
                        Math.Clamp(
                            availableHeight * 0.90,
                            760d,
                            1500d);
                }
                else if (string.Equals(
                             sizeMode,
                             "max",
                             StringComparison.OrdinalIgnoreCase))
                {
                    // Máximo: modo accesible para pantallas muy grandes.
                    // Puede ocupar casi toda ANFETA pero conserva margen,
                    // cabecera de arrastre y scroll interno.
                    preferredWidth =
                        Math.Clamp(
                            usableWidth * 0.90,
                            1200d,
                            3000d);

                    preferredHeight =
                        availableHeight * 0.96;
                }
                else if (_calendarActivityPreviewPinned)
                {
                    // AUTO: editor amplio y responsive. La posición se
                    // resuelve después junto a la actividad seleccionada.
                    preferredWidth =
                        Math.Clamp(
                            usableWidth * 0.48,
                            560d,
                            820d);

                    preferredHeight =
                        Math.Clamp(
                            availableHeight * 0.88,
                            640d,
                            980d);
                }
                else
                {
                    // Hover temporal más discreto que antes.
                    preferredWidth =
                        rootWidth >= 3000
                            ? 600d
                            : rootWidth >= 2200
                                ? 520d
                                : 460d;

                    preferredHeight =
                        rootHeight >= 1400
                            ? 860d
                            : rootHeight >= 1000
                                ? 760d
                                : 680d;
                }

                var previewWidth =
                    Math.Min(
                        preferredWidth,
                        usableWidth);

                if (previewWidth < 320 &&
                    usableWidth >= 320)
                {
                    previewWidth = 320;
                }

                var maxPopupHeight =
                    Math.Min(
                        preferredHeight,
                        availableHeight);

                if (_calendarActivityPreviewScrollViewer != null)
                {
                    _calendarActivityPreviewScrollViewer.Width =
                        previewWidth;

                    _calendarActivityPreviewScrollViewer
                        .HorizontalAlignment =
                            HorizontalAlignment.Stretch;

                    _calendarActivityPreviewScrollViewer
                        .HorizontalContentAlignment =
                            HorizontalAlignment.Stretch;

                    var previewUiScale =
                        GetCalendarActivityPreviewUiScale();

                    var headerScale =
                        _calendarActivityPreviewPinned
                            ? Math.Clamp(
                                previewUiScale,
                                1d,
                                1.52d)
                            : 1d;

                    var pinHeight =
                        _calendarActivityPreviewPinned
                            ? 36d * headerScale
                            : 0d;

                    if (_calendarActivityPreviewPinned &&
                        _calendarActivityPreviewPinBar?.Child is Grid pinGrid)
                    {
                        pinGrid.Height =
                            pinHeight;

                        pinGrid.Padding =
                            new Thickness(
                                10d * headerScale,
                                0,
                                6d * headerScale,
                                0);

                        pinGrid.ColumnSpacing =
                            8d * headerScale;

                        if (pinGrid.Children.Count > 0 &&
                            pinGrid.Children[0] is Grid dragArea &&
                            dragArea.Children.Count > 0 &&
                            dragArea.Children[0] is TextBlock pinText)
                        {
                            pinText.FontSize =
                                10.5d * headerScale;
                        }

                        if (pinGrid.Children.Count > 1 &&
                            pinGrid.Children[1] is Button sizeButton)
                        {
                            sizeButton.Width =
                                30d * headerScale;
                            sizeButton.Height =
                                26d * headerScale;
                            sizeButton.FontSize =
                                12d * headerScale;
                        }

                        if (pinGrid.Children.Count > 2 &&
                            pinGrid.Children[2] is Button closePreviewButton)
                        {
                            closePreviewButton.Width =
                                28d * headerScale;
                            closePreviewButton.Height =
                                26d * headerScale;
                            closePreviewButton.FontSize =
                                11d * headerScale;
                        }
                    }

                    _calendarActivityPreviewScrollViewer.MaxHeight =
                        Math.Max(
                            120,
                            maxPopupHeight -
                            pinHeight -
                            2);
                }

                if (_calendarActivityPreviewPopupCard != null)
                {
                    _calendarActivityPreviewPopupCard.MaxHeight =
                        maxPopupHeight;

                    _calendarActivityPreviewPopupCard.Width =
                        previewWidth;

                    _calendarActivityPreviewPopupCard.MaxWidth =
                        previewWidth;
                }

                if (_calendarActivityPreviewHost != null)
                {
                    var innerWidth =
                        Math.Max(
                            280,
                            previewWidth - 26);

                    _calendarActivityPreviewHost.Width =
                        innerWidth;

                    _calendarActivityPreviewHost.MaxWidth =
                        innerWidth;

                    _calendarActivityPreviewHost
                        .HorizontalAlignment =
                            HorizontalAlignment.Stretch;

                    _calendarActivityPreviewHost
                        .HorizontalContentAlignment =
                            HorizontalAlignment.Stretch;

                    _calendarActivityPreviewHost.InvalidateMeasure();
                    _calendarActivityPreviewHost.InvalidateArrange();
                }

                // Si la checklist fijada ya fue movida por el usuario, las
                // actualizaciones de contenido/tamaño NO la regresan a la card.
                // Solo se limita lo mínimo necesario para conservar parte de
                // la cabecera accesible.
                if (_calendarActivityPreviewPinned &&
                    _calendarActivityPreviewUserMoved)
                {
                    if (_calendarActivityPreviewDragActive)
                        return;

                    const double minimumVisibleHeader = 150d;
                    const double draggableHeaderHeight = 36d;

                    var minLeft =
                        Math.Min(
                            edge,
                            -(Math.Max(
                                0d,
                                previewWidth -
                                minimumVisibleHeader)));

                    var maxLeft =
                        Math.Max(
                            edge,
                            rootWidth -
                            minimumVisibleHeader);

                    var maxTop =
                        Math.Max(
                            edge,
                            rootHeight -
                            draggableHeaderHeight -
                            edge);

                    popup.HorizontalOffset =
                        Math.Clamp(
                            popup.HorizontalOffset,
                            minLeft,
                            maxLeft);

                    popup.VerticalOffset =
                        Math.Clamp(
                            popup.VerticalOffset,
                            edge,
                            maxTop);

                    return;
                }

                // Apertura inicial: hover y editor fijado nacen JUNTO a la
                // actividad, no en el extremo contrario de la aplicación.
                // Primero intenta derecha, luego izquierda; si ninguna cabe
                // completa utiliza el lado con más espacio y clamplea.
                var anchorLeft =
                    point.X;

                var anchorRight =
                    point.X +
                    Math.Max(
                        1,
                        anchor.ActualWidth);

                const double anchorGap = 16d;

                var rightCandidate =
                    anchorRight +
                    anchorGap;

                var leftCandidate =
                    anchorLeft -
                    previewWidth -
                    anchorGap;

                var rightFits =
                    rightCandidate +
                    previewWidth <=
                    rootWidth -
                    edge;

                var leftFits =
                    leftCandidate >=
                    edge;

                double left;

                if (rightFits)
                {
                    left =
                        rightCandidate;
                }
                else if (leftFits)
                {
                    left =
                        leftCandidate;
                }
                else
                {
                    var rightSpace =
                        Math.Max(
                            0,
                            rootWidth -
                            edge -
                            anchorRight);

                    var leftSpace =
                        Math.Max(
                            0,
                            anchorLeft -
                            edge);

                    left =
                        rightSpace >= leftSpace
                            ? rightCandidate
                            : leftCandidate;
                }

                left =
                    Math.Clamp(
                        left,
                        edge,
                        Math.Max(
                            edge,
                            rootWidth -
                            previewWidth -
                            edge));

                // Verticalmente nace a la altura de la actividad. Si no
                // cabe hacia abajo, sube solo lo necesario; nunca salta a una
                // zona lejana del calendario.
                var top =
                    _calendarActivityPreviewPinned
                        ? point.Y - 18d
                        : point.Y;

                if (top + maxPopupHeight >
                    rootHeight - edge)
                {
                    top =
                        rootHeight -
                        maxPopupHeight -
                        edge;
                }

                top =
                    Math.Clamp(
                        top,
                        edge,
                        Math.Max(
                            edge,
                            rootHeight -
                            maxPopupHeight -
                            edge));

                popup.HorizontalOffset =
                    left;

                popup.VerticalOffset =
                    top;
            }
            catch
            {
                var width =
                    _calendarActivityPreviewPopupCard?.Width > 0
                        ? _calendarActivityPreviewPopupCard.Width
                        : 560d;

                var fallbackRootWidth =
                    RootLayout?.ActualWidth ??
                    900d;

                // Fallback seguro y cercano al contenido visible. No
                // vuelve a mandar la actividad fijada al extremo derecho.
                popup.HorizontalOffset =
                    Math.Clamp(
                        popup.HorizontalOffset,
                        12,
                        Math.Max(
                            12,
                            fallbackRootWidth -
                            width -
                            12));

                popup.VerticalOffset =
                    Math.Max(
                        12,
                        popup.VerticalOffset);
            }
        }

        private void UpdateCalendarActivityPreviewContent(
            FrameworkElement content)
        {
            if (_calendarActivityPreviewPopup?.IsOpen != true ||
                _calendarActivityPreviewHost == null)
            {
                return;
            }

            ApplyCalendarActivityPreviewUiScale(
                content);

            // No cambies el árbol visual en pleno drag. Una actualización de
            // checklist puede llegar desde background justo mientras se mueve
            // el popup y provocar un salto/temblor aunque la posición sea fija.
            if (_calendarActivityPreviewDragActive)
            {
                _calendarActivityPreviewPendingContent =
                    content;
                return;
            }

            _calendarActivityPreviewPendingContent =
                null;

            _calendarActivityPreviewHost.Content =
                content;

            _calendarActivityPreviewScrollViewer?
                .ChangeView(
                    horizontalOffset: null,
                    verticalOffset: 0,
                    zoomFactor: null,
                    disableAnimation: true);

            if (!_calendarActivityPreviewDragActive &&
                _calendarHoveredActivityButton != null)
            {
                DispatcherQueue.TryEnqueue(
                    () =>
                    {
                        if (!_calendarActivityPreviewDragActive)
                        {
                            PositionCalendarActivityPreviewPopup(
                                _calendarHoveredActivityButton);
                        }
                    });
            }
        }

        private void CalendarPreviewContent_PointerEntered(
            object sender,
            PointerRoutedEventArgs e)
        {
            _calendarPointerOverPreview = true;
            _calendarPointerOverActivity = false;
            _calendarPendingActivityButton = null;
            _calendarActivityHoverTimer?.Stop();

            StopCalendarPreviewCloseTimer();
        }

        private void CalendarPreviewContent_PointerExited(
            object sender,
            PointerRoutedEventArgs e)
        {
            _calendarPointerOverPreview = false;

            if (!_calendarActivityPreviewPinned)
                StartCalendarPreviewCloseTimer();
        }

        private void StartCalendarPreviewCloseTimer()
        {
            if (_calendarPreviewCloseTimer == null)
            {
                _calendarPreviewCloseTimer =
                    new DispatcherTimer
                    {
                        Interval =
                            TimeSpan.FromMilliseconds(320)
                    };

                _calendarPreviewCloseTimer.Tick +=
                    (_, __) =>
                    {
                        _calendarPreviewCloseTimer.Stop();

                        if (!_calendarActivityPreviewPinned &&
                            !_calendarPointerOverActivity &&
                            !_calendarPointerOverPreview)
                        {
                            HideCalendarActivityPreviewFlyout();
                        }
                    };
            }

            _calendarPreviewCloseTimer.Stop();
            _calendarPreviewCloseTimer.Start();
        }

        private void StopCalendarPreviewCloseTimer()
        {
            _calendarPreviewCloseTimer?.Stop();
        }

        private void HideCalendarActivityPreviewFlyout()
        {
            StopCalendarPreviewCloseTimer();
            StopNotionPreviewSpeech();

            try
            {
                _calendarHoverPreviewCts?.Cancel();
            }
            catch
            {
            }

            if (_calendarActivityPreviewPopup != null)
                _calendarActivityPreviewPopup.IsOpen = false;

            _calendarActivityPreviewPopup = null;
            _calendarActivityPreviewPopupCard = null;
            _calendarActivityPreviewHost = null;
            _calendarActivityPreviewPendingContent = null;
            _calendarActivityPreviewPinBar = null;
            _calendarActivityPreviewScrollViewer = null;

            _calendarActivityPreviewPinned = false;
            _calendarActivityPreviewPinnedPageId =
                string.Empty;
            _calendarActivityPreviewUserMoved = false;
            _calendarActivityPreviewDragActive = false;

            _calendarActivityPreviewLastCriteria = null;
            _calendarActivityPreviewLastProjectActivities =
                Array.Empty<NotionCalendarActivity>();
            _calendarActivityPreviewLastSelectedPageId =
                string.Empty;

            _calendarHoveredActivityButton = null;
            _calendarPendingActivityButton = null;
            _calendarActivityHoverTimer?.Stop();
            _calendarPointerOverActivity = false;
            _calendarPointerOverPreview = false;
        }

