        private FrameworkElement BuildCalendarActivityPagePreview(
            NotionCalendarActivity activity,
            IReadOnlyList<NotionPreviewBlock> blocks)
        {
            var content = new StackPanel
            {
                Spacing = 7
            };

            if (!string.IsNullOrWhiteSpace(
                    activity.Description))
            {
                content.Children.Add(
                    CreateSectionLabel(
                        "DESCRIPCIÓN"));

                content.Children.Add(
                    CreatePreviewText(
                        activity.Description,
                        11,
                        Microsoft.UI.Text.FontWeights.Normal,
                        0.88,
                        0));
            }

            var visibleBlocks = blocks
                .Where(block =>
                    block.Kind ==
                        NotionPreviewBlockKind.Divider ||
                    !string.IsNullOrWhiteSpace(
                        block.Text) ||
                    !string.IsNullOrWhiteSpace(
                        block.Url))
                .ToList();

            if (visibleBlocks.Count > 0)
            {
                content.Children.Add(
                    CreateSectionLabel(
                        "CONTENIDO DE LA PÁGINA"));
            }

            var number = 0;

            foreach (var block in visibleBlocks)
            {
                if (block.Kind ==
                    NotionPreviewBlockKind.NumberedListItem)
                {
                    number++;
                }
                else
                {
                    number = 0;
                }

                var element =
                    CreateBlockElement(
                        block,
                        number);

                if (element != null)
                {
                    ConstrainCalendarPreviewElement(
                        element,
                        Math.Clamp(
                            (RootLayout?.ActualWidth ?? 700) * 0.72,
                            450,
                            1280));

                    content.Children.Add(element);
                }
            }

            if (visibleBlocks.Count == 0 &&
                string.IsNullOrWhiteSpace(
                    activity.Description))
            {
                content.Children.Add(
                    CreatePreviewText(
                        "La página no contiene bloques visibles.",
                        11,
                        Microsoft.UI.Text.FontWeights.Normal,
                        0.64,
                        0));
            }

            return BuildCalendarActivityPreviewShell(
                activity,
                content,
                statusText:
                    "Clic en la actividad para abrir la página en Notion.",
                speechBlocks: blocks);
        }

        private static void ConstrainCalendarPreviewElement(
            UIElement element,
            double availableWidth)
        {
            if (element is FrameworkElement framework)
            {
                framework.MaxWidth =
                    Math.Max(
                        120,
                        availableWidth);
            }

            switch (element)
            {
                case TextBlock text:
                    text.TextWrapping =
                        TextWrapping.Wrap;

                    text.TextTrimming =
                        TextTrimming.None;

                    text.MaxLines = 0;

                    text.MaxWidth =
                        Math.Max(
                            100,
                            availableWidth);
                    break;

                case CheckBox checkBox:
                    // El cuadro conserva su tamaño y el texto recibe el resto.
                    checkBox.MaxWidth = 34;
                    break;

                case Border border
                    when border.Child is UIElement child:
                    ConstrainCalendarPreviewElement(
                        child,
                        Math.Max(
                            100,
                            availableWidth - 18));
                    break;

                case ContentControl contentControl
                    when contentControl.Content is UIElement child:
                    ConstrainCalendarPreviewElement(
                        child,
                        availableWidth);
                    break;

                case Panel panel:
                    var childWidth =
                        panel is StackPanel stack &&
                        stack.Orientation ==
                            Orientation.Horizontal
                            ? Math.Max(
                                100,
                                availableWidth - 48)
                            : availableWidth;

                    foreach (var child in panel.Children)
                    {
                        ConstrainCalendarPreviewElement(
                            child,
                            childWidth);
                    }
                    break;

                case Expander expander:
                    if (expander.Header is UIElement header)
                    {
                        ConstrainCalendarPreviewElement(
                            header,
                            Math.Max(
                                100,
                                availableWidth - 30));
                    }

                    if (expander.Content is UIElement expanderContent)
                    {
                        ConstrainCalendarPreviewElement(
                            expanderContent,
                            Math.Max(
                                100,
                                availableWidth - 18));
                    }
                    break;
            }
        }

        private FrameworkElement BuildCalendarActivityErrorPreview(
