                    Opacity = 0.82
                }
            };

            return BuildCalendarActivityPreviewShell(
                activity,
                content,
                statusText:
                    "Clic en la actividad para abrir la página en Notion.");
        }


        private async Task<bool> SaveCalendarActivityEditorAsync(
            NotionCalendarActivity activity,
            string requestedTitle,
            DateTime requestedStart,
            DateTime requestedEnd)
        {
            if (activity == null ||
                activity.IsReviewMirror ||
                string.IsNullOrWhiteSpace(activity.PageId))
            {
                StatusText.Text =
                    "Estado: La copia visual no se puede editar.";
                return false;
            }

            requestedTitle =
                (requestedTitle ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(requestedTitle))
            {
                StatusText.Text =
                    "Estado: El título no puede quedar vacío.";
                return false;
            }

            if (requestedEnd <= requestedStart)
            {
                StatusText.Text =
                    "Estado: La duración debe ser mayor a cero.";
                return false;
            }

            var token =
                ApplicationData.Current.LocalSettings.Values[
                    "Notion.Token"] as string;

            if (string.IsNullOrWhiteSpace(token))
            {
                StatusText.Text =
                    "Estado: Configura primero el token de Notion.";
                return false;
            }

            var originalTitle =
                activity.Title ?? string.Empty;

            var originalStart =
                activity.Start;

            var originalEnd =
                activity.End;

            var titleChanged =
                !string.Equals(
                    originalTitle.Trim(),
                    requestedTitle,
                    StringComparison.Ordinal);

            var scheduleChanged =
                Math.Abs(
                    (requestedStart -
                     originalStart)
                    .TotalSeconds) >= 30 ||
                Math.Abs(
                    (requestedEnd -
                     originalEnd)
                    .TotalSeconds) >= 30;

            if (!titleChanged &&
                !scheduleChanged)
            {
                StatusText.Text =
                    "Estado: No hay cambios que guardar.";
                return false;
            }

            if (scheduleChanged &&
                activity.IsAutomationLocked)
            {
                StatusText.Text =
                    "Estado: La actividad está bloqueada. " +
                    "El título sí puede editarse, pero desbloquéala " +
                    "para cambiar fecha u horario.";

                // Si además cambió título sí permitimos guardar esa parte.
                if (!titleChanged)
                    return false;

                scheduleChanged = false;
            }

            var titleSaved = false;
            var scheduleSaved = false;

            try
            {
                ShowLoadingState(
                    "Estado: Guardando actividad…",
                    requestedTitle);

                using var cts =
                    new CancellationTokenSource(
                        TimeSpan.FromMinutes(2));

                if (titleChanged)
                {
                    var savedTitle =
                        await _notionCalendarService
                            .UpdateActivityTitleAsync(
                                token,
                                activity.PageId,
                                requestedTitle,
                                cts.Token);

                    activity.Title =
                        savedTitle;

                    foreach (var item in
                             _calendarActivities.Where(item =>
                                 string.Equals(
                                     item.PageId,
                                     activity.PageId,
                                     StringComparison.OrdinalIgnoreCase)))
                    {
                        item.Title =
                            savedTitle;
                    }

                    foreach (var item in
                             _calendarActivityPreviewLastProjectActivities
                                 .Where(item =>
                                     string.Equals(
                                         item.PageId,
                                         activity.PageId,
                                         StringComparison.OrdinalIgnoreCase)))
                    {
                        item.Title =
                            savedTitle;
                    }

                    titleSaved = true;
                }

                if (scheduleChanged)
                {
                    var audit =
                        $"ANFETA · Editor actividad · " +
                        $"{DateTime.Now:dd/MM/yyyy HH:mm} · " +
                        $"{originalStart:dd/MM HH:mm}–{originalEnd:HH:mm} → " +
                        $"{requestedStart:dd/MM HH:mm}–{requestedEnd:HH:mm}";

                    var update =
                        await _notionCalendarService
                            .UpdateActivityScheduleWithAuditAsync(
                                token,
                                activity,
                                requestedStart,
                                requestedEnd,
                                audit,
                                cts.Token);

                    var updated =
                        update.Activity;

                    activity.Start =
                        updated.Start;

                    activity.End =
                        updated.End;

                    activity.DatePropertyName =
                        updated.DatePropertyName;

                    foreach (var item in
                             _calendarActivityPreviewLastProjectActivities
                                 .Where(item =>
                                     string.Equals(
                                         item.PageId,
                                         activity.PageId,
                                         StringComparison.OrdinalIgnoreCase)))
                    {
                        item.Start =
                            updated.Start;

                        item.End =
                            updated.End;

                        item.DatePropertyName =
                            updated.DatePropertyName;
                    }

                    if (requestedStart.Date !=
                        originalStart.Date)
                    {
                        RegisterCalendarDayMovement(
                            activity,
                            originalStart.Date,
                            requestedStart.Date,
                            "Editor de actividad");
                    }

                    scheduleSaved = true;
                }

                // El servicio ya actualizó DayCache. Cerramos el popup antes
                // de repintar para no conservar un anchor destruido.
                HideCalendarActivityPreviewFlyout();

                var currentDay =
                    await _notionCalendarService
                        .TryGetCachedDayAsync(
                            _calendarSelectedDate,
                            cts.Token);

                _calendarActivities =
                    currentDay ??
                    Array.Empty<NotionCalendarActivity>();

                ApplyCachedCalendarReviewFlow(
                    _calendarActivities);

                DrawCalendarPreservingView(
                    _calendarActivities,
                    force: true);

                var savedParts =
                    new List<string>();

                if (titleSaved)
                    savedParts.Add("título");

                if (scheduleSaved)
                    savedParts.Add("fecha/horario");

                StatusText.Text =
                    $"Estado: Actividad actualizada ✅ · " +
                    $"{string.Join(" + ", savedParts)}";

                return true;
            }
            catch (OperationCanceledException)
            {
                StatusText.Text =
                    "Estado: Notion tardó demasiado en guardar los cambios.";
                return false;
            }
            catch (Exception ex)
            {
                var partial =
                    titleSaved
                        ? " · el título sí alcanzó a guardarse"
                        : string.Empty;

                StatusText.Text =
                    $"Estado: No se pudieron guardar todos los cambios{partial} → " +
                    $"{ex.Message}";

                return false;
            }
            finally
            {
                HideLoadingState();
            }
        }

        private FrameworkElement BuildCalendarActivityPreviewShell(
            NotionCalendarActivity activity,
            UIElement? content,
            string statusText,
            IReadOnlyList<NotionPreviewBlock>? speechBlocks = null,
            bool compactMeta = false)
        {
            var root = new StackPanel
            {
                HorizontalAlignment =
                    HorizontalAlignment.Stretch,
                Spacing = 8,
                Padding = new Thickness(10)
            };

            var pinnedEditorMode =
                _calendarActivityPreviewPinned &&
                !activity.IsReviewMirror;

            TextBox? titleEditor =
                null;

            var titleRow =
                new Grid
                {
                    ColumnSpacing = 8,
                    HorizontalAlignment =
                        HorizontalAlignment.Stretch
                };

            titleRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            titleRow.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        GridLength.Auto
                });

            if (pinnedEditorMode)
            {
                titleEditor =
                    new TextBox
                    {
                        Text =
                            activity.Title ?? string.Empty,
                        PlaceholderText =
                            "Título de la actividad",
                        FontSize = 13,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        TextWrapping =
                            TextWrapping.Wrap,
                        AcceptsReturn = false,
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch,
                        MinHeight = 34
                    };

                ToolTipService.SetToolTip(
                    titleEditor,
                    "Edita el título original de Notion. " +
                    "Se guarda con el botón Guardar cambios.");

                Grid.SetColumn(
                    titleEditor,
                    0);

                titleRow.Children.Add(
                    titleEditor);
            }
            else
            {
                var titleText =
                    new TextBlock
                    {
                        Text = compactMeta
                            ? GetCalendarOrderedCompactActivityTitle(
                                activity)
                            : activity.Title,
                        FontSize = 14,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        TextWrapping =
                            TextWrapping.Wrap,
                        VerticalAlignment =
                            VerticalAlignment.Center
                    };

                Grid.SetColumn(
                    titleText,
                    0);

                titleRow.Children.Add(
                    titleText);
            }

            if (pinnedEditorMode)
            {
                var lockButton =
                    new Button
                    {
                        Content =
                            activity.IsAutomationLocked
                                ? "🔒"
                                : "🔓",
                        Width = 34,
                        Height = 32,
                        Padding =
                            new Thickness(0),
                        HorizontalContentAlignment =
                            HorizontalAlignment.Center,
                        VerticalContentAlignment =
                            VerticalAlignment.Center,
                        CornerRadius =
                            new CornerRadius(7),
                        FontSize = 14,
                        Background =
                            new SolidColorBrush(
                                activity.IsAutomationLocked
                                    ? Color.FromArgb(
                                        42, 248, 113, 113)
                                    : Color.FromArgb(
                                        34, 74, 222, 128)),
                        BorderBrush =
                            new SolidColorBrush(
                                activity.IsAutomationLocked
                                    ? Color.FromArgb(
                                        130, 248, 113, 113)
                                    : Color.FromArgb(
                                        110, 74, 222, 128)),
                        BorderThickness =
                            new Thickness(1),
                        Tag = activity
                    };

                ToolTipService.SetToolTip(
                    lockButton,
                    activity.IsAutomationLocked
                        ? "Automatización bloqueada · clic para desbloquear"
                        : "Automatización permitida · clic para bloquear");

                lockButton.Click +=
                    async (_, __) =>
                    {
                        lockButton.IsEnabled = false;

                        try
                        {
                            await ToggleCalendarActivityAutomationLockAsync(
                                activity);
                        }
                        finally
                        {
                            lockButton.IsEnabled = true;
                        }
                    };

                Grid.SetColumn(
                    lockButton,
                    1);

                titleRow.Children.Add(
                    lockButton);
            }

            root.Children.Add(
                titleRow);

            DatePicker? editorDate =
                null;

            TimePicker? editorStart =
                null;

            ComboBox? editorDuration =
                null;

            TextBlock? editorStatus =
                null;

            Button? editorSave =
                null;

            if (pinnedEditorMode)
            {
                var currentDuration =
                    Math.Max(
                        15,
                        (int)Math.Round(
                            (activity.End > activity.Start
                                ? activity.End - activity.Start
                                : TimeSpan.FromHours(1))
                            .TotalMinutes));

                editorDate =
                    new DatePicker
                    {
                        Header = "Fecha",
                        Date =
                            new DateTimeOffset(
                                DateTime.SpecifyKind(
                                    activity.Start.Date,
                                    DateTimeKind.Local)),
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch,
                        IsEnabled =
                            !activity.IsAutomationLocked
                    };

                editorStart =
                    new TimePicker
                    {
                        Header = "Hora",
                        ClockIdentifier =
                            "24HourClock",
                        MinuteIncrement = 15,
                        Time =
                            new TimeSpan(
                                activity.Start.Hour,
                                activity.Start.Minute,
                                0),
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch,
                        IsEnabled =
                            !activity.IsAutomationLocked
                    };

                editorDuration =
                    new ComboBox
                    {
                        Header = "Duración",
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch,
                        IsEnabled =
                            !activity.IsAutomationLocked
                    };

                var durationOptions =
                    new[]
                    {
                        15, 30, 45, 60, 90, 120, 180, 240
                    }
                    .Append(currentDuration)
                    .Distinct()
                    .OrderBy(minutes => minutes)
                    .ToList();

                foreach (var minutes in durationOptions)
                {
                    var durationItem =
                        new ComboBoxItem
                        {
                            Content =
                                minutes < 60
                                    ? $"{minutes} min"
                                    : minutes % 60 == 0
                                        ? $"{minutes / 60} h"
                                        : $"{minutes / 60} h {minutes % 60} min",
                            Tag = minutes
                        };

                    editorDuration.Items.Add(
                        durationItem);

                    if (minutes == currentDuration)
                    {
                        editorDuration.SelectedItem =
                            durationItem;
                    }
                }

                if (editorDuration.SelectedIndex < 0 &&
                    editorDuration.Items.Count > 0)
                {
                    editorDuration.SelectedIndex = 0;
                }

                var scheduleGrid =
                    new Grid
                    {
                        ColumnSpacing = 8,
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch
                    };

                scheduleGrid.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            new GridLength(
                                1.20,
                                GridUnitType.Star)
                    });

                scheduleGrid.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            new GridLength(
                                0.85,
                                GridUnitType.Star)
                    });

                scheduleGrid.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            new GridLength(
                                0.85,
                                GridUnitType.Star)
                    });

                Grid.SetColumn(
                    editorDate,
                    0);

                Grid.SetColumn(
                    editorStart,
                    1);

                Grid.SetColumn(
                    editorDuration,
                    2);

                scheduleGrid.Children.Add(
                    editorDate);

                scheduleGrid.Children.Add(
                    editorStart);

                scheduleGrid.Children.Add(
                    editorDuration);

                editorSave =
                    new Button
                    {
                        Content = "💾 Guardar cambios",
                        Height = 31,
                        Padding =
                            new Thickness(
                                12, 2, 12, 2),
                        HorizontalAlignment =
                            HorizontalAlignment.Left,
                        CornerRadius =
                            new CornerRadius(7)
                    };

                editorStatus =
                    new TextBlock
                    {
                        Text =
                            activity.IsAutomationLocked
                                ? "🔒 Fecha y horario bloqueados; el título sigue siendo editable."
                                : "Edita título, fecha, hora o duración y guarda.",
                        FontSize = 10,
                        Opacity = 0.68,
                        VerticalAlignment =
                            VerticalAlignment.Center,
                        TextWrapping =
                            TextWrapping.Wrap
                    };

                var saveRow =
                    new Grid
                    {
                        ColumnSpacing = 10
                    };

                saveRow.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            GridLength.Auto
                    });

                saveRow.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width =
                            new GridLength(
                                1,
                                GridUnitType.Star)
                    });

                Grid.SetColumn(
                    editorSave,
                    0);

                Grid.SetColumn(
                    editorStatus,
                    1);

                saveRow.Children.Add(
                    editorSave);

                saveRow.Children.Add(
                    editorStatus);

                var editorPanel =
                    new StackPanel
                    {
                        Spacing = 7,
                        HorizontalAlignment =
                            HorizontalAlignment.Stretch
                    };

                editorPanel.Children.Add(
                    scheduleGrid);

                editorPanel.Children.Add(
                    saveRow);

                root.Children.Add(
                    new Border
                    {
                        Padding =
                            new Thickness(
                                9, 7, 9, 7),
                        CornerRadius =
                            new CornerRadius(7),
                        Background =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    22,
                                    56,
                                    189,
                                    248)),
                        BorderBrush =
                            new SolidColorBrush(
                                Color.FromArgb(
                                    60,
                                    56,
                                    189,
                                    248)),
                        BorderThickness =
                            new Thickness(1),
                        Child =
                            editorPanel
                    });

                editorSave.Click +=
                    async (_, __) =>
                    {
                        if (titleEditor == null ||
                            editorDate == null ||
                            editorStart == null ||
                            editorDuration == null ||
                            editorStatus == null)
                        {
                            return;
                        }

                        var selectedDate =
                            editorDate.Date
                                .LocalDateTime
                                .Date;

                        var selectedTime =
                            editorStart.Time;

                        var start =
                            selectedDate.Add(
                                new TimeSpan(
                                    selectedTime.Hours,
                                    selectedTime.Minutes,
                                    0));

                        var minutes =
                            editorDuration.SelectedItem is
                                ComboBoxItem selectedDuration &&
                            selectedDuration.Tag is int taggedMinutes
                                ? taggedMinutes
                                : currentDuration;

                        var end =
                            start.AddMinutes(
                                Math.Max(
                                    15,
                                    minutes));

                        editorSave.IsEnabled = false;

                        editorStatus.Text =
                            "Guardando en Notion…";

                        try
                        {
                            var saved =
                                await SaveCalendarActivityEditorAsync(
                                    activity,
                                    titleEditor.Text,
                                    start,
                                    end);

                            if (!saved &&
                                _calendarActivityPreviewPopup?.IsOpen == true)
                            {
                                editorStatus.Text =
                                    StatusText.Text
                                        .Replace(
                                            "Estado:",
                                            string.Empty,
                                            StringComparison.OrdinalIgnoreCase)
                                        .Trim();

                                editorSave.IsEnabled = true;
                            }
                        }
                        catch (Exception ex)
                        {
                            editorStatus.Text =
                                ex.Message;

                            editorSave.IsEnabled = true;
                        }
                    };
            }
            else
            {
                root.Children.Add(
                    new TextBlock
                    {
                        Text = activity.TimeLabel,
                        FontSize = 11.5,
                        Opacity = 0.78
                    });
            }

            void AddMeta(
                string label,
                string value)
            {
                if (string.IsNullOrWhiteSpace(value))
                    return;

                var row = new Grid
                {
                    ColumnSpacing = 8,
                    HorizontalAlignment = HorizontalAlignment.Stretch
                };

                row.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                row.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(
                            1,
                            GridUnitType.Star)
                    });

                var labelText =
                    new TextBlock
                    {
                        Text = $"{label}:",
                        FontSize = 10.5,
                        FontWeight =
                            Microsoft.UI.Text.FontWeights.SemiBold,
                        Opacity = 0.62
                    };

                var valueText =
                    new TextBlock
                    {
                        Text = value,
                        HorizontalAlignment = HorizontalAlignment.Stretch,
                        FontSize = 10.5,
                        TextWrapping =
                            TextWrapping.Wrap,
                        Opacity = 0.90
                    };

                Grid.SetColumn(labelText, 0);
                Grid.SetColumn(valueText, 1);

                row.Children.Add(labelText);
                row.Children.Add(valueText);
                root.Children.Add(row);
            }

            AddMeta("Persona actual", activity.Person);

            if (!compactMeta)
            {
                AddMeta(
                    "Calendario de origen",
                    GetCalendarOrigin(activity));
                AddMeta("Proyecto", activity.Project);
            }

            AddMeta("Estado", activity.Status);
            AddMeta(
                "Última actualización",
                activity.UpdateText);

            var shellChecklist =
                GetCalendarChecklistStats(activity);

            AddMeta(
                "Checklist",
                FormatCalendarChecklistLabel(
                    activity,
                    shellChecklist));

            // En modo fijado el estado vive en el candado compacto superior.
            // En hover conservamos texto únicamente si está bloqueada.
            if (!pinnedEditorMode &&
                activity.IsAutomationLocked)
            {
                AddMeta(
                    "Automatización",
                    "Bloqueada");
            }

            AddMeta(
                "Movimiento ANFETA",
                GetCalendarDayMovementDetail(activity));

            var actionsPanel = new VariableSizedWrapGrid
            {
                Orientation = Orientation.Horizontal,
                // Sin ancho fijo: al agrandar la checklist el panel usa el
                // espacio nuevo y acomoda más acciones por fila. En tamaños
                // pequeños mantiene los botones compactos existentes.
                ItemWidth = 198,
                ItemHeight = 35,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                Margin = new Thickness(0, 4, 0, 2)
            };

            if (!activity.IsReviewMirror &&
                HasExactCalendarPhase(
                    activity,
                    "rtuzREVISION") &&
                activity.IsPendingReview &&
                CanCurrentUserResolveReview(activity))
            {
                Button AddReviewerButton(
                    string text,
                    RoutedEventHandler handler)
                {
                    var button = new Button
                    {
                        Content = text,
                        Width = 190,
                        Height = 30,
                        Margin = new Thickness(0, 0, 8, 6),
                        Padding = new Thickness(10, 0, 10, 0),
                        CornerRadius = new CornerRadius(6),
                        Tag = activity
                    };

                    button.Click += handler;
                    actionsPanel.Children.Add(button);
                    return button;
                }

                AddReviewerButton(
                    "Aprobar revisión",
                    CalendarContextApproveReview_Click);

                AddReviewerButton(
                    "Regresar con correcciones…",
                    CalendarContextReturnReview_Click);
            }
            else if (CanSendCalendarActivityToReview(activity))
            {
                var reviewButton =
                    new Button
                    {
                        Content = "Enviar a revisión…",
                        Width = 190,
                        Height = 30,
                        Margin = new Thickness(0, 0, 8, 6),
                        Padding = new Thickness(10, 0, 10, 0),
                        CornerRadius = new CornerRadius(6),
                        Tag = activity
                    };

                reviewButton.Click +=
                    async (_, __) =>
                    {
                        reviewButton.IsEnabled = false;

                        try
                        {
                            var sent =
                                await PromptAndSendCalendarActivityToReviewAsync(
                                    activity);

                            if (sent)
                            {
                                reviewButton.Content =
                                    "Enviada a revisión ✅";
                            }
                        }
                        finally
                        {
                            await Task.Delay(900);
                            reviewButton.IsEnabled = true;
                            reviewButton.Content =
                                "Enviar a revisión…";
                        }
                    };

                actionsPanel.Children.Add(
                    reviewButton);
            }

            if (!activity.IsReviewMirror &&
                HasExactCalendarPhase(
                    activity,
                    "zREVISION"))
            {
                var reassignButton = new Button
                {
                    Content =
                        "Reasignar → prtuzREVISION",
                    Width = 190,
                    Height = 30,
                    Margin =
                        new Thickness(0, 0, 8, 6),
                    Padding =
                        new Thickness(10, 0, 10, 0),
                    CornerRadius =
                        new CornerRadius(6),
                    Tag = activity
                };

                reassignButton.Click +=
                    CalendarContextReassignApproved_Click;

                actionsPanel.Children.Add(
                    reassignButton);
            }

            var messageButton =
                new Button
                {
                    Content = "Enviar mensaje…",
                    Width = 190,
                    Height = 30,
                    Margin = new Thickness(0, 0, 8, 6),
                    Padding = new Thickness(10, 0, 10, 0),
                    CornerRadius = new CornerRadius(6),
                    Tag = activity
                };

            messageButton.Click +=
                async (_, __) =>
                {
                    HideCalendarActivityPreviewFlyout();

                    await ShowCalendarMessageComposerAsync(
                        activity);
                };

            ToolTipService.SetToolTip(
                messageButton,
                "Crear un mensaje relacionado con esta actividad");

            actionsPanel.Children.Add(messageButton);

